import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import Modal from '../ui/Modal';
import Avatar from '../shared/Avatar';
import Button from '../ui/Button';
import Icon from '../ui/Icon';
import Input from '../ui/Input';
import InfiniteScroll from 'react-infinite-scroll-component';
import LoadingSkeleton from '../shared/LoadingSkeleton';
import { useFollowing } from '../../hooks/useFollowing';
import { useFollow } from '../../hooks/useFollow';
import styles from './FollowingModal.module.css';

const FollowingModal = ({ isOpen, onClose, userId }) => {
    const navigate = useNavigate();
    const { following, loading, hasMore, searchQuery, setSearchQuery, loadMore, updateFollowingStatus, unfollowUser } = useFollowing(userId, isOpen);
    const { toggleFollow } = useFollow();
    const [actionLoading, setActionLoading] = useState({});

    const handleUnfollow = async (user) => {
        setActionLoading(prev => ({ ...prev, [user.id]: true }));
        await unfollowUser(user.id);
        setActionLoading(prev => ({ ...prev, [user.id]: false }));
    };

    const handleUserClick = (username) => {
        onClose();
        navigate(`/profile/${username}`);
    };

    return (
        <Modal isOpen={isOpen} onClose={onClose} title="Following" className={styles.modal}>
            <div className={styles.searchContainer}>
                <Input
                    type="text"
                    placeholder="Search following..."
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    icon={<Icon name="Search" size={18} />}
                />
            </div>

            <div className={styles.list} id="following-scroll">
                {loading && following.length === 0 ? (
                    <LoadingSkeleton type="list" count={10} />
                ) : following.length === 0 ? (
                    <div className={styles.emptyState}>
                        <Icon name="Users" size={48} />
                        <p>Not following anyone yet</p>
                        {searchQuery && <p className={styles.emptyHint}>Try a different search term</p>}
                    </div>
                ) : (
                    <InfiniteScroll
                        dataLength={following.length}
                        next={loadMore}
                        hasMore={hasMore}
                        loader={<LoadingSkeleton type="list" count={3} />}
                        scrollableTarget="following-scroll"
                    >
                        {following.map((user) => (
                            <div key={user.id} className={styles.item}>
                                <div className={styles.userInfo} onClick={() => handleUserClick(user.username)} style={{ cursor: 'pointer', display: 'flex', alignItems: 'center', flex: 1 }}>
                                    <Avatar src={user.avatar_url} alt={user.username} size="md" />
                                    <div className={styles.info}>
                                        <div className={styles.username}>
                                            {user.username}
                                            {user.verified && <Icon name="BadgeCheck" size={14} className={styles.verified} />}
                                        </div>
                                        <div className={styles.fullName}>{user.full_name}</div>
                                        {user.isMutual && <span className={styles.mutualBadge}>Mutual</span>}
                                    </div>
                                </div>
                                <div className={styles.actions}>
                                    <Button
                                        variant="outline"
                                        size="sm"
                                        onClick={() => handleUnfollow(user)}
                                        loading={actionLoading[user.id]}
                                    >
                                        Following
                                    </Button>
                                </div>
                            </div>
                        ))}
                    </InfiniteScroll>
                )}
            </div>
        </Modal>
    );
};

export default FollowingModal;

import React, { useState, useEffect, useRef } from 'react';
import { useSwipeable } from 'react-swipeable';
import Modal from '../ui/Modal';
import Avatar from '../shared/Avatar';
import Icon from '../ui/Icon';
import { formatTimeAgo } from '../../utils/formatTimeAgo';
import styles from './HighlightsViewerModal.module.css';

const HighlightsViewerModal = ({ isOpen, onClose, highlight, allHighlights = [], onHighlightChange }) => {
    const [currentHighlightIndex, setCurrentHighlightIndex] = useState(0);
    const [currentStoryIndex, setCurrentStoryIndex] = useState(0);
    const [progress, setProgress] = useState(0);
    const [isPaused, setIsPaused] = useState(false);
    const [isMuted, setIsMuted] = useState(false);
    const videoRef = useRef(null);
    const progressIntervalRef = useRef(null);

    const currentHighlight = allHighlights[currentHighlightIndex] || highlight;
    const stories = currentHighlight?.stories || [];
    const currentStory = stories[currentStoryIndex];
    const storyDuration = currentStory?.duration || 5000; // Default 5 seconds

    useEffect(() => {
        if (highlight && allHighlights.length > 0) {
            const index = allHighlights.findIndex(h => h.id === highlight.id);
            if (index !== -1) {
                setCurrentHighlightIndex(index);
            }
        }
    }, [highlight, allHighlights]);

    useEffect(() => {
        if (isOpen && !isPaused) {
            startProgress();
        } else {
            stopProgress();
        }

        return () => stopProgress();
    }, [isOpen, currentStoryIndex, isPaused]);

    const startProgress = () => {
        stopProgress();
        setProgress(0);

        const interval = 50; // Update every 50ms
        const increment = (interval / storyDuration) * 100;

        progressIntervalRef.current = setInterval(() => {
            setProgress(prev => {
                if (prev >= 100) {
                    handleNext();
                    return 0;
                }
                return prev + increment;
            });
        }, interval);
    };

    const stopProgress = () => {
        if (progressIntervalRef.current) {
            clearInterval(progressIntervalRef.current);
            progressIntervalRef.current = null;
        }
    };

    const handleNext = () => {
        if (currentStoryIndex < stories.length - 1) {
            // Next story in current highlight
            setCurrentStoryIndex(currentStoryIndex + 1);
            setProgress(0);
        } else if (currentHighlightIndex < allHighlights.length - 1) {
            // Next highlight
            setCurrentHighlightIndex(currentHighlightIndex + 1);
            setCurrentStoryIndex(0);
            setProgress(0);
            if (onHighlightChange) {
                onHighlightChange(allHighlights[currentHighlightIndex + 1]);
            }
        } else {
            // End of all highlights
            onClose();
        }
    };

    const handlePrevious = () => {
        if (currentStoryIndex > 0) {
            // Previous story in current highlight
            setCurrentStoryIndex(currentStoryIndex - 1);
            setProgress(0);
        } else if (currentHighlightIndex > 0) {
            // Previous highlight
            const prevHighlight = allHighlights[currentHighlightIndex - 1];
            setCurrentHighlightIndex(currentHighlightIndex - 1);
            setCurrentStoryIndex(prevHighlight.stories.length - 1);
            setProgress(0);
            if (onHighlightChange) {
                onHighlightChange(prevHighlight);
            }
        }
    };

    const handleTap = (e) => {
        const rect = e.currentTarget.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const width = rect.width;

        if (x < width / 3) {
            handlePrevious();
        } else if (x > (width * 2) / 3) {
            handleNext();
        } else {
            setIsPaused(!isPaused);
        }
    };

    const handleMuteToggle = () => {
        if (videoRef.current) {
            videoRef.current.muted = !isMuted;
            setIsMuted(!isMuted);
        }
    };

    const swipeHandlers = useSwipeable({
        onSwipedLeft: handleNext,
        onSwipedRight: handlePrevious,
        onSwipedDown: onClose,
        preventScrollOnSwipe: true,
        trackMouse: false
    });

    if (!currentHighlight || !currentStory) {
        return null;
    }

    const isVideo = currentStory.media_type === 'video';

    return (
        <Modal isOpen={isOpen} onClose={onClose} className={styles.modal}>
            <div className={styles.content} {...swipeHandlers}>
                {/* Progress Bars */}
                <div className={styles.progressBars}>
                    {stories.map((_, index) => (
                        <div key={index} className={styles.progressBarContainer}>
                            <div
                                className={styles.progressBar}
                                style={{
                                    width: index < currentStoryIndex
                                        ? '100%'
                                        : index === currentStoryIndex
                                            ? `${progress}%`
                                            : '0%'
                                }}
                            />
                        </div>
                    ))}
                </div>

                {/* Header */}
                <div className={styles.header}>
                    <div className={styles.userInfo}>
                        <Avatar
                            src={currentHighlight.user?.avatar_url}
                            alt={currentHighlight.user?.username}
                            size="sm"
                        />
                        <div className={styles.userDetails}>
                            <div className={styles.username}>
                                {currentHighlight.user?.username}
                            </div>
                            <div className={styles.timestamp}>
                                {formatTimeAgo(currentStory.created_at)}
                            </div>
                        </div>
                    </div>

                    <div className={styles.headerActions}>
                        {isVideo && (
                            <button
                                className={styles.headerBtn}
                                onClick={handleMuteToggle}
                                aria-label={isMuted ? 'Unmute' : 'Mute'}
                            >
                                <Icon name={isMuted ? 'VolumeX' : 'Volume2'} size={20} />
                            </button>
                        )}
                        <button
                            className={styles.headerBtn}
                            onClick={onClose}
                            aria-label="Close"
                        >
                            <Icon name="X" size={20} />
                        </button>
                    </div>
                </div>

                {/* Story Content */}
                <div className={styles.storyContainer} onClick={handleTap}>
                    {isVideo ? (
                        <video
                            ref={videoRef}
                            src={currentStory.media_url}
                            className={styles.media}
                            autoPlay
                            loop={false}
                            playsInline
                            muted={isMuted}
                            onEnded={handleNext}
                        />
                    ) : (
                        <img
                            src={currentStory.media_url}
                            alt="Story"
                            className={styles.media}
                        />
                    )}

                    {/* Pause Indicator */}
                    {isPaused && (
                        <div className={styles.pauseIndicator}>
                            <Icon name="Pause" size={48} />
                        </div>
                    )}

                    {/* Tap Zones (visual feedback) */}
                    <div className={styles.tapZones}>
                        <div className={styles.tapZone} />
                        <div className={styles.tapZone} />
                        <div className={styles.tapZone} />
                    </div>
                </div>

                {/* Navigation Hints */}
                <div className={styles.navHints}>
                    <div className={styles.navHint}>
                        <Icon name="ChevronLeft" size={16} />
                        <span>Tap left</span>
                    </div>
                    <div className={styles.navHint}>
                        <Icon name="ChevronDown" size={16} />
                        <span>Swipe down to close</span>
                    </div>
                    <div className={styles.navHint}>
                        <span>Tap right</span>
                        <Icon name="ChevronRight" size={16} />
                    </div>
                </div>

                {/* Story Info */}
                {currentStory.caption && (
                    <div className={styles.caption}>
                        {currentStory.caption}
                    </div>
                )}

                {/* Highlight Title */}
                <div className={styles.highlightTitle}>
                    {currentHighlight.title}
                </div>
            </div>
        </Modal>
    );
};

export default HighlightsViewerModal;

import React from 'react';
import PropTypes from 'prop-types';
import { formatDateAwarded } from '../../utils/badgeFormatter';
import styles from './BadgeAuditLog.module.css';

/**
 * BadgeAuditLog Component
 * Audit log viewer for all badge-related actions
 */
const BadgeAuditLog = ({ auditLog, onRefresh }) => {
    const getActionColor = (action) => {
        switch (action) {
            case 'awarded':
                return 'var(--success)';
            case 'revoked':
                return 'var(--error)';
            case 'applied':
                return 'var(--primary)';
            default:
                return 'var(--text-secondary)';
        }
    };

    return (
        <div className={styles.auditLog}>
            <div className={styles.header}>
                <h3>Audit Log</h3>
                <button className={styles.refreshButton} onClick={onRefresh}>
                    Refresh
                </button>
            </div>

            <div className={styles.logList}>
                {auditLog.map(entry => (
                    <div key={entry.id} className={styles.logEntry}>
                        <div className={styles.timestamp}>
                            {new Date(entry.timestamp).toLocaleString()}
                        </div>
                        <div className={styles.action} style={{ color: getActionColor(entry.action) }}>
                            {entry.action.toUpperCase()}
                        </div>
                        <div className={styles.details}>
                            <span className={styles.badgeName}>{entry.badge?.name}</span>
                            <span className={styles.separator}>ΓÇó</span>
                            <span className={styles.userEmail}>{entry.user?.email}</span>
                            {entry.actor?.email && entry.actor.email !== entry.user?.email && (
                                <>
                                    <span className={styles.separator}>ΓÇó</span>
                                    <span className={styles.actor}>by {entry.actor.email}</span>
                                </>
                            )}
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
};

BadgeAuditLog.propTypes = {
    auditLog: PropTypes.arrayOf(PropTypes.object).isRequired,
    onRefresh: PropTypes.func.isRequired
};

export default BadgeAuditLog;

import React, { useEffect, useState } from 'react';
import { Navigate } from 'react-router-dom';
import { useAuth } from '../../hooks/useAuth';
import { supabase } from '../../lib/supabase';

const AdminRoute = ({ children }) => {
    const { user, loading: authLoading } = useAuth();
    const [isAdmin, setIsAdmin] = useState(false);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const checkAdmin = async () => {
            if (!user) {
                setLoading(false);
                return;
            }

            // Check metadata first (fastest)
            if (user.user_metadata?.role === 'admin') {
                setIsAdmin(true);
                setLoading(false);
                return;
            }

            // Check profiles table
            try {
                const { data, error } = await supabase
                    .from('profiles')
                    .select('role')
                    .eq('id', user.id)
                    .single();

                if (data && data.role === 'admin') {
                    setIsAdmin(true);
                }
            } catch (error) {
                console.error('Error checking admin status:', error);
            }

            setLoading(false);
        };

        if (!authLoading) {
            checkAdmin();
        }
    }, [user, authLoading]);

    if (authLoading || loading) {
        return (
            <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '100vh' }}>
                Loading...
            </div>
        );
    }

    if (!user || !isAdmin) {
        return <Navigate to="/" replace />;
    }

    return children;
};

export default AdminRoute;

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import Input from '../shared/Input';
import Button from '../shared/Button';
import Checkbox from '../shared/Checkbox';
import Toast from '../shared/Toast';
import UsernameCheck from './UsernameCheck';
import PasswordStrength from './PasswordStrength';
import useFormValidation from '../../hooks/useFormValidation';
import usePasswordStrength from '../../hooks/usePasswordStrength';
import { validateEmail } from '../../utils/validateEmail';
import { validatePassword } from '../../utils/validatePassword';
import { signUpWithEmail, createUserProfile, createUserSettings, createUserPresence } from '../../utils/supabaseAuth';
import { calculateAge, isAgeValid, isTeen, formatDOB, validateDOB, getAgeValidationMessage } from '../../utils/ageValidation';
import styles from './SignupForm.module.css';
import { FaEnvelope, FaLock, FaEye, FaEyeSlash, FaCalendar } from 'react-icons/fa';

const SignupForm = () => {
    const navigate = useNavigate();
    const [showPassword, setShowPassword] = useState(false);
    const [toast, setToast] = useState(null);
    const [isUsernameValid, setIsUsernameValid] = useState(false);
    const [dob, setDob] = useState({ month: '', day: '', year: '' });
    const [dobError, setDobError] = useState(null);
    const [ageMessage, setAgeMessage] = useState(null);

    const validate = (values) => {
        const errors = {};
        if (!values.email) {
            errors.email = 'Email is required';
        } else if (!validateEmail(values.email)) {
            errors.email = 'Invalid email format';
        }

        const pwCheck = validatePassword(values.password);
        if (!pwCheck.isValid) {
            errors.password = pwCheck.errors[0];
        }

        if (values.password !== values.confirmPassword) {
            errors.confirmPassword = 'Passwords do not match';
        }

        if (!values.terms) {
            errors.terms = 'You must agree to the Terms & Privacy Policy';
        }

        return errors;
    };

    const {
        values,
        errors,
        isSubmitting,
        handleChange,
        handleBlur,
        handleSubmit,
        setValues
    } = useFormValidation({
        username: '',
        email: '',
        password: '',
        confirmPassword: '',
        terms: false
    }, validate);

    const { strength, score } = usePasswordStrength(values.password);

    // Handle DOB change and validate
    const handleDobChange = (field, value) => {
        const newDob = { ...dob, [field]: value };
        setDob(newDob);

        // Validate if all fields are filled
        if (newDob.month && newDob.day && newDob.year) {
            const validation = validateDOB(newDob.month, newDob.day, newDob.year);

            if (!validation.isValid) {
                setDobError(validation.error);
                setAgeMessage(null);
            } else {
                setDobError(null);

                // Calculate age and show message
                const dobString = formatDOB(newDob.month, newDob.day, newDob.year);
                const age = calculateAge(dobString);
                const message = getAgeValidationMessage(age);
                setAgeMessage(message);
            }
        } else {
            setDobError(null);
            setAgeMessage(null);
        }
    };

    const onSubmit = async (formValues) => {
        // Validate username
        if (!isUsernameValid) {
            setToast({ type: 'error', message: 'Please choose a valid username' });
            return;
        }

        // Validate DOB
        if (!dob.month || !dob.day || !dob.year) {
            setToast({ type: 'error', message: 'Please enter your date of birth' });
            return;
        }

        const dobValidation = validateDOB(dob.month, dob.day, dob.year);
        if (!dobValidation.isValid) {
            setToast({ type: 'error', message: dobValidation.error });
            return;
        }

        // Calculate age and validate
        const dobString = formatDOB(dob.month, dob.day, dob.year);
        const age = calculateAge(dobString);

        if (!isAgeValid(age, 13)) {
            setToast({ type: 'error', message: 'You must be at least 13 years old to use Focus' });
            return;
        }

        const isTeenUser = isTeen(age);

        try {
            // Sign up with Supabase Auth
            const { data, error } = await signUpWithEmail(
                formValues.email,
                formValues.password,
                formValues.username,
                dobString
            );

            if (error) {
                console.error('Signup error:', error);

                if (error.message.includes('already registered') || error.message.includes('already been registered')) {
                    setToast({ type: 'error', message: 'This email is already registered' });
                } else {
                    setToast({ type: 'error', message: error.message || 'Failed to create account. Please try again.' });
                }
                return;
            }

            // Check if user was created
            if (!data?.user) {
                setToast({ type: 'error', message: 'Failed to create account. Please try again.' });
                return;
            }

            // The database trigger should create profile, settings, and presence
            // But we'll create them manually as a fallback
            try {
                // Wait a moment for trigger to execute
                await new Promise(resolve => setTimeout(resolve, 500));

                // Try to create profile (will fail if trigger already created it)
                await createUserProfile(data.user.id, formValues.username, formValues.email, dobString, isTeenUser);
                await createUserSettings(data.user.id, isTeenUser);
                await createUserPresence(data.user.id);
            } catch (recordError) {
                // Ignore errors - trigger likely already created records
                console.log('Records may already exist from trigger:', recordError);
            }

            // V1.0: Skip email verification - immediately log user in and navigate to onboarding
            setToast({
                type: 'success',
                message: isTeenUser
                    ? 'Account created with Teen Care mode! Welcome to Focus ≡ƒÄ»'
                    : 'Account created! Welcome to Focus ≡ƒÄ»'
            });

            // Navigate to onboarding after a brief delay to show success message
            setTimeout(() => navigate('/onboarding'), 1500);
        } catch (err) {
            console.error('Unexpected signup error:', err);
            setToast({
                type: 'error',
                message: 'An unexpected error occurred. Please try again.'
            });
        }
    };

    // Generate month options
    const months = [
        'January', 'February', 'March', 'April', 'May', 'June',
        'July', 'August', 'September', 'October', 'November', 'December'
    ];

    // Generate day options (1-31)
    const days = Array.from({ length: 31 }, (_, i) => i + 1);

    // Generate year options (current year - 120 to current year - 5)
    const currentYear = new Date().getFullYear();
    const years = Array.from({ length: 116 }, (_, i) => currentYear - 5 - i);

    return (
        <form className={styles.form} onSubmit={(e) => { e.preventDefault(); handleSubmit(onSubmit); }}>
            <UsernameCheck
                value={values.username}
                onChange={handleChange}
                onValidityChange={setIsUsernameValid}
            />

            <Input
                name="email"
                type="email"
                placeholder="Email Address"
                value={values.email}
                onChange={handleChange}
                onBlur={handleBlur}
                error={errors.email}
                icon={<FaEnvelope />}
            />

            <Input
                name="password"
                type={showPassword ? 'text' : 'password'}
                placeholder="Password"
                value={values.password}
                onChange={handleChange}
                onBlur={handleBlur}
                error={errors.password}
                icon={<FaLock />}
                rightElement={
                    <button
                        type="button"
                        className={styles.eyeButton}
                        onClick={() => setShowPassword(!showPassword)}
                    >
                        {showPassword ? <FaEyeSlash /> : <FaEye />}
                    </button>
                }
            />

            <PasswordStrength strength={strength} score={score} />

            <Input
                name="confirmPassword"
                type="password"
                placeholder="Confirm Password"
                value={values.confirmPassword}
                onChange={handleChange}
                onBlur={handleBlur}
                error={errors.confirmPassword}
                icon={<FaLock />}
            />

            {/* Date of Birth Picker */}
            <div className={styles.dobSection}>
                <label className={styles.dobLabel}>
                    <FaCalendar className={styles.dobIcon} />
                    Date of Birth
                </label>
                <div className={styles.dobPicker}>
                    <select
                        className={styles.dobSelect}
                        value={dob.month}
                        onChange={(e) => handleDobChange('month', e.target.value)}
                    >
                        <option value="">Month</option>
                        {months.map((month, index) => (
                            <option key={month} value={index + 1}>
                                {month}
                            </option>
                        ))}
                    </select>

                    <select
                        className={styles.dobSelect}
                        value={dob.day}
                        onChange={(e) => handleDobChange('day', e.target.value)}
                    >
                        <option value="">Day</option>
                        {days.map((day) => (
                            <option key={day} value={day}>
                                {day}
                            </option>
                        ))}
                    </select>

                    <select
                        className={styles.dobSelect}
                        value={dob.year}
                        onChange={(e) => handleDobChange('year', e.target.value)}
                    >
                        <option value="">Year</option>
                        {years.map((year) => (
                            <option key={year} value={year}>
                                {year}
                            </option>
                        ))}
                    </select>
                </div>

                {dobError && <span className={styles.dobError}>{dobError}</span>}
                {ageMessage && (
                    <div className={`${styles.ageMessage} ${styles[ageMessage.type]}`}>
                        {ageMessage.text}
                    </div>
                )}
            </div>

            <div className={styles.terms}>
                <Checkbox
                    name="terms"
                    label="I agree to Terms & Privacy Policy"
                    checked={values.terms}
                    onChange={handleChange}
                />
                {errors.terms && <span className={styles.errorText}>{errors.terms}</span>}
            </div>

            <Button
                type="submit"
                variant="primary"
                fullWidth
                isLoading={isSubmitting}
                disabled={!isUsernameValid}
            >
                Create Account
            </Button>

            {toast && (
                <Toast
                    message={toast.message}
                    type={toast.type}
                    onClose={() => setToast(null)}
                />
            )}
        </form>
    );
};

export default SignupForm;

import React, { useRef, useState, useEffect } from 'react';
import styles from './BoltzPlayer.module.css';
import BoltzOverlay from './BoltzOverlay';
import BoltzUserInfo from './BoltzUserInfo';
import BoltzMusicInfo from './BoltzMusicInfo';
import BoltzActionsSidebar from './BoltzActionsSidebar';
import HeartAnimation from './HeartAnimation';
import VideoProgressBar from './VideoProgressBar';
import VolumeControl from './VolumeControl';
import { useViewTracking } from '../../hooks/useViewTracking';

const BoltzPlayer = ({
    boltz,
    isActive,
    playing,
    muted,
    preload = 'none',
    released = false,
    onTogglePlay,
    onToggleMute,
    onLike,
    onComment,
    onShare,
    onSave,
    onFollow,
    onOpenOptions,
    onOpenMusic,
    showHeartAnimation,
    videoRef,
    currentUserId
}) => {
    const [lastTap, setLastTap] = useState(0);
    const [progress, setProgress] = useState(0);
    const [videoReady, setVideoReady] = useState(false);
    const [videoErrored, setVideoErrored] = useState(false);
    const posterSrc = boltz.thumbnail_url || boltz.poster_url || boltz.preview_image || null;

    useViewTracking(boltz.id, isActive);

    const handleVideoTap = () => {
        const currentTime = new Date().getTime();
        const tapLength = currentTime - lastTap;

        if (tapLength < 300 && tapLength > 0) {
            // Double tap - like
            onLike();
        } else {
            // Single tap - pause/play
            onTogglePlay();
        }

        setLastTap(currentTime);
    };

    const handleTimeUpdate = (e) => {
        const video = e.target;
        const progress = (video.currentTime / video.duration) * 100;
        setProgress(progress);
    };

    return (
        <div className={styles.container}>
            {released ? (
                <div className={styles.videoPlaceholder} />
            ) : (
                <video
                    ref={videoRef}
                    src={boltz.video_url}
                    className={styles.video}
                    loop
                    playsInline
                    muted={muted}
                    autoPlay={playing}
                    preload={preload}
                    onClick={handleVideoTap}
                    onTimeUpdate={handleTimeUpdate}
                    onLoadedData={() => setVideoReady(true)}
                    onError={() => setVideoErrored(true)}
                />
            )}
            {!released && !videoReady && posterSrc && (
                <img src={posterSrc} alt="" className={styles.poster} loading="lazy" />
            )}
            {!released && videoErrored && (
                <div className={styles.focuslyPlaceholder}>Focusly</div>
            )}

            <BoltzOverlay />

            <BoltzUserInfo
                user={boltz.profiles || boltz.user}
                caption={boltz.caption}
                onFollow={() => onFollow(boltz.profiles?.id || boltz.user?.id)}
                isOwnContent={currentUserId === boltz.user_id}
            />

            {boltz.music && (
                <BoltzMusicInfo
                    music={boltz.music}
                    playing={playing}
                    onClick={onOpenMusic}
                />
            )}

            <BoltzActionsSidebar
                boltz={boltz}
                onLike={onLike}
                onComment={onComment}
                onShare={onShare}
                onSave={onSave}
                onOpenOptions={onOpenOptions}
                onOpenMusic={onOpenMusic}
                playing={playing}
            />

            {showHeartAnimation && <HeartAnimation />}

            {onToggleMute && <VolumeControl muted={muted} onToggle={onToggleMute} />}

            <VideoProgressBar progress={progress} />
        </div>
    );
};

