import React, { useRef, useEffect } from 'react';
import styles from './PhotoEditor.module.css';
import { usePhotoEditor } from '../../hooks/usePhotoEditor';
import Button from '../shared/Button';
import { Sliders, Crop, RotateCw } from 'lucide-react';

const FILTERS = [
    { id: 'none', label: 'Normal', style: '' },
    { id: 'lavender', label: 'Lavender', style: 'sepia(0.2) hue-rotate(240deg) contrast(1.1)' },
    { id: 'warm', label: 'Warm', style: 'sepia(0.3) contrast(1.1)' },
    { id: 'cool', label: 'Cool', style: 'hue-rotate(180deg) contrast(1.1)' },
    { id: 'bw', label: 'B&W', style: 'grayscale(1)' },
];

const PhotoEditor = ({ file, onSave, onCancel }) => {
    const canvasRef = useRef(null);
    const {
        image,
        rotation,
        setRotation,
        filter,
        setFilter,
        adjustments,
        setAdjustments,
        generateResult
    } = usePhotoEditor(URL.createObjectURL(file));

    useEffect(() => {
        // Draw image to canvas with filters
        const canvas = canvasRef.current;
        const ctx = canvas.getContext('2d');
        const img = new Image();
        img.src = image;
        img.onload = () => {
            canvas.width = img.width;
            canvas.height = img.height;

            ctx.filter = `${FILTERS.find(f => f.id === filter).style} brightness(${adjustments.brightness}%) contrast(${adjustments.contrast}%)`;

            ctx.save();
            ctx.translate(canvas.width / 2, canvas.height / 2);
            ctx.rotate((rotation * Math.PI) / 180);
            ctx.drawImage(img, -img.width / 2, -img.height / 2);
            ctx.restore();
        };
    }, [image, filter, adjustments, rotation]);

    const handleSave = async () => {
        // In a real app, we'd use generateResult from the hook which handles cropping
        // For this UI demo, we'll just return the original file or a blob from canvas
        onSave(file);
    };

    return (
        <div className={styles.container}>
            <div className={styles.canvasWrapper}>
                <canvas ref={canvasRef} className={styles.canvas} />
            </div>

            <div className={styles.controls}>
                <div className={styles.filters}>
                    {FILTERS.map(f => (
                        <button
                            key={f.id}
                            className={`${styles.filterBtn} ${filter === f.id ? styles.activeFilter : ''}`}
                            onClick={() => setFilter(f.id)}
                        >
                            <div className={styles.filterPreview} style={{ filter: f.style }} />
                            <span>{f.label}</span>
                        </button>
                    ))}
                </div>

                <div className={styles.adjustments}>
                    <div className={styles.sliderGroup}>
                        <label>Brightness</label>
                        <input
                            type="range"
                            min="50"
                            max="150"
                            value={adjustments.brightness}
                            onChange={(e) => setAdjustments({ ...adjustments, brightness: e.target.value })}
                        />
                    </div>
                    <div className={styles.sliderGroup}>
                        <label>Contrast</label>
                        <input
                            type="range"
                            min="50"
                            max="150"
                            value={adjustments.contrast}
                            onChange={(e) => setAdjustments({ ...adjustments, contrast: e.target.value })}
                        />
                    </div>
                </div>

                <div className={styles.actions}>
                    <Button variant="secondary" onClick={() => setRotation(r => r + 90)}>
                        <RotateCw size={18} />
                    </Button>
                    <div className={styles.mainActions}>
                        <Button variant="ghost" onClick={onCancel}>Cancel</Button>
                        <Button onClick={handleSave}>Save Edits</Button>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default PhotoEditor;

import React, { useRef, useEffect, useState } from 'react';
import styles from './VideoTimeline.module.css';
import { formatDuration } from '../../utils/formatDuration';
import { Clock } from 'lucide-react';

const VideoTimeline = ({
    videoRef,
    duration,
    currentTime,
    trimRange,
    onTrimChange,
    onSeek
}) => {
    const timelineRef = useRef(null);
    const [isDraggingPlayhead, setIsDraggingPlayhead] = useState(false);
    const [isDraggingStart, setIsDraggingStart] = useState(false);
    const [isDraggingEnd, setIsDraggingEnd] = useState(false);
    const [thumbnails, setThumbnails] = useState([]);
    const [startInput, setStartInput] = useState('');
    const [endInput, setEndInput] = useState('');

    // Update inputs when trimRange changes
    useEffect(() => {
        setStartInput(formatDuration(trimRange[0]));
        setEndInput(formatDuration(trimRange[1]));
    }, [trimRange]);

    // Generate thumbnails when video is loaded
    useEffect(() => {
        if (!videoRef?.current || !duration) return;

        const generateThumbnails = async () => {
            const video = videoRef.current;
            const canvas = document.createElement('canvas');
            const ctx = canvas.getContext('2d');
            const thumbCount = 10;
            const thumbs = [];

            canvas.width = 120;
            canvas.height = 67;

            for (let i = 0; i < thumbCount; i++) {
                const time = (duration / thumbCount) * i;
                video.currentTime = time;

                await new Promise(resolve => {
                    video.onseeked = () => {
                        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
                        thumbs.push({
                            time,
                            url: canvas.toDataURL('image/jpeg', 0.7)
                        });
                        resolve();
                    };
                });
            }

            setThumbnails(thumbs);
        };

        generateThumbnails().catch(console.error);
    }, [videoRef, duration]);

    const parseTimeInput = (input) => {
        // Parse formats: "1:23", "0:05", "23" (seconds only)
        const parts = input.split(':').map(p => parseInt(p.trim(), 10));
        if (parts.length === 1) {
            return parts[0] || 0; // Seconds only
        } else if (parts.length === 2) {
            return (parts[0] * 60) + (parts[1] || 0); // Minutes:Seconds
        }
        return 0;
    };

    const handleStartTimeChange = (e) => {
        const value = e.target.value;
        setStartInput(value);
    };

    const handleEndTimeChange = (e) => {
        const value = e.target.value;
        setEndInput(value);
    };

    const handleStartTimeBlur = () => {
        const time = parseTimeInput(startInput);
        const clampedTime = Math.max(0, Math.min(time, trimRange[1] - 0.1, duration));
        onTrimChange([clampedTime, trimRange[1]]);
        setStartInput(formatDuration(clampedTime));
    };

    const handleEndTimeBlur = () => {
        const time = parseTimeInput(endInput);
        const clampedTime = Math.max(trimRange[0] + 0.1, Math.min(time, duration));
        onTrimChange([trimRange[0], clampedTime]);
        setEndInput(formatDuration(clampedTime));
    };

    const handleMouseDown = (e, type) => {
        e.stopPropagation();
        if (type === 'playhead') setIsDraggingPlayhead(true);
        else if (type === 'start') setIsDraggingStart(true);
        else if (type === 'end') setIsDraggingEnd(true);
    };

    const handleMouseMove = (e) => {
        if (!timelineRef.current) return;
        if (!isDraggingPlayhead && !isDraggingStart && !isDraggingEnd) return;

        const rect = timelineRef.current.getBoundingClientRect();
        const percent = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
        const time = percent * duration;

        if (isDraggingPlayhead) {
            onSeek(time);
        } else if (isDraggingStart) {
            onTrimChange([Math.min(time, trimRange[1] - 0.1), trimRange[1]]);
        } else if (isDraggingEnd) {
            onTrimChange([trimRange[0], Math.max(time, trimRange[0] + 0.1)]);
        }
    };

    const handleMouseUp = () => {
        setIsDraggingPlayhead(false);
        setIsDraggingStart(false);
        setIsDraggingEnd(false);
    };

    useEffect(() => {
        if (isDraggingPlayhead || isDraggingStart || isDraggingEnd) {
            window.addEventListener('mousemove', handleMouseMove);
            window.addEventListener('mouseup', handleMouseUp);
            return () => {
                window.removeEventListener('mousemove', handleMouseMove);
                window.removeEventListener('mouseup', handleMouseUp);
            };
        }
    }, [isDraggingPlayhead, isDraggingStart, isDraggingEnd, trimRange]);

    const playheadPosition = duration > 0 ? (currentTime / duration) * 100 : 0;
    const trimStartPosition = duration > 0 ? (trimRange[0] / duration) * 100 : 0;
    const trimEndPosition = duration > 0 ? (trimRange[1] / duration) * 100 : 100;

    return (
        <div className={styles.container}>
            <div className={styles.header}>
                <div className={styles.timeDisplay}>
                    <span className={styles.currentTime}>{formatDuration(currentTime)}</span>
                    <span className={styles.separator}>/</span>
                    <span className={styles.totalTime}>{formatDuration(duration)}</span>
                </div>

                <div className={styles.manualInputs}>
                    <div className={styles.inputGroup}>
                        <label>
                            <Clock size={14} />
                            <span>Start</span>
                        </label>
                        <input
                            type="text"
                            value={startInput}
                            onChange={handleStartTimeChange}
                            onBlur={handleStartTimeBlur}
                            onKeyDown={(e) => e.key === 'Enter' && e.target.blur()}
                            placeholder="0:00"
                            className={styles.timeInput}
                        />
                    </div>
                    <div className={styles.inputGroup}>
                        <label>
                            <Clock size={14} />
                            <span>End</span>
                        </label>
                        <input
                            type="text"
                            value={endInput}
                            onChange={handleEndTimeChange}
                            onBlur={handleEndTimeBlur}
                            onKeyDown={(e) => e.key === 'Enter' && e.target.blur()}
                            placeholder="0:00"
                            className={styles.timeInput}
                        />
                    </div>
                </div>
            </div>

            <div
                ref={timelineRef}
                className={styles.timeline}
                onClick={(e) => {
                    const rect = timelineRef.current.getBoundingClientRect();
                    const percent = (e.clientX - rect.left) / rect.width;
                    onSeek(percent * duration);
                }}
            >
                {/* Thumbnail strip */}
                <div className={styles.thumbnailStrip}>
                    {thumbnails.map((thumb, i) => (
                        <div key={i} className={styles.thumbnail}>
                            <img src={thumb.url} alt={`Frame at ${formatDuration(thumb.time)}`} />
                        </div>
                    ))}
                </div>

                {/* Timeline track */}
                <div className={styles.track}>
                    {/* Dimmed regions outside trim */}
                    <div
                        className={styles.dimmedRegion}
                        style={{ left: 0, width: `${trimStartPosition}%` }}
                    />
                    <div
                        className={styles.dimmedRegion}
                        style={{ left: `${trimEndPosition}%`, width: `${100 - trimEndPosition}%` }}
                    />

                    {/* Active trim region */}
                    <div
                        className={styles.activeRegion}
                        style={{
                            left: `${trimStartPosition}%`,
                            width: `${trimEndPosition - trimStartPosition}%`
                        }}
                    />

                    {/* Trim handles */}
                    <div
                        className={`${styles.trimHandle} ${styles.trimHandleStart}`}
                        style={{ left: `${trimStartPosition}%` }}
                        onMouseDown={(e) => handleMouseDown(e, 'start')}
                    >
                        <div className={styles.trimHandleBar} />
                    </div>
                    <div
                        className={`${styles.trimHandle} ${styles.trimHandleEnd}`}
                        style={{ left: `${trimEndPosition}%` }}
                        onMouseDown={(e) => handleMouseDown(e, 'end')}
                    >
                        <div className={styles.trimHandleBar} />
                    </div>

                    {/* Playhead */}
                    <div
                        className={styles.playhead}
                        style={{ left: `${playheadPosition}%` }}
                        onMouseDown={(e) => handleMouseDown(e, 'playhead')}
                    >
                        <div className={styles.playheadLine} />
                        <div className={styles.playheadHandle} />
                    </div>
                </div>

                {/* Time markers */}
                <div className={styles.timeMarkers}>
                    {Array.from({ length: 11 }, (_, i) => {
                        const time = (duration / 10) * i;
                        return (
                            <div key={i} className={styles.timeMarker} style={{ left: `${i * 10}%` }}>
                                <div className={styles.markerTick} />
                                <span className={styles.markerLabel}>{formatDuration(time)}</span>
                            </div>
                        );
                    })}
                </div>
            </div>

            <div className={styles.trimInfo}>
                <span className={styles.trimLabel}>Selected Duration:</span>
                <span className={styles.trimDuration}>{formatDuration(trimRange[1] - trimRange[0])}</span>
            </div>
        </div>
    );
};

export default VideoTimeline;

import React, { useState, useRef, useEffect } from 'react';
import { Search, X, Clock, TrendingUp } from 'lucide-react';
import styles from './SearchBar.module.css';
import { useSearch } from '../../hooks/useSearch';
import Avatar from '../ui/Avatar';
import { useNavigate } from 'react-router-dom';

const SearchBar = ({ placeholder = "Search" }) => {
    const navigate = useNavigate();
    const {
        query,
        setQuery,
        results,
        loading,
        history,
        addToHistory,
        removeFromHistory
    } = useSearch();

    const [isFocused, setIsFocused] = useState(false);
    const wrapperRef = useRef(null);

    useEffect(() => {
        const handleClickOutside = (event) => {
            if (wrapperRef.current && !wrapperRef.current.contains(event.target)) {
                setIsFocused(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const handleSelect = (item, type) => {
        if (type === 'user') {
            addToHistory(item.username);
            navigate(`/profile/${item.username}`);
        } else if (type === 'hashtag') {
            addToHistory(`#${item.name}`);
            navigate(`/explore/tags/${item.name}`);
        } else if (type === 'history') {
            setQuery(item);
        }
        setIsFocused(false);
    };

    const handleSearchSubmit = (e) => {
        if (e.key === 'Enter' && query) {
            addToHistory(query);
            navigate(`/explore/search?q=${encodeURIComponent(query)}`);
            setIsFocused(false);
        }
    };

    return (
        <div className={styles.searchWrapper} ref={wrapperRef}>
            <div className={`${styles.inputContainer} ${isFocused ? styles.focused : ''}`}>
                <Search className={styles.searchIcon} size={18} />
                <input
                    type="text"
                    className={styles.input}
                    value={query}
                    onChange={(e) => setQuery(e.target.value)}
                    onFocus={() => setIsFocused(true)}
                    onKeyDown={handleSearchSubmit}
                    placeholder={placeholder}
                />
                {query && (
                    <button className={styles.clearButton} onClick={() => setQuery('')}>
                        <X size={16} />
                    </button>
                )}
            </div>

            {isFocused && (
                <div className={styles.dropdown}>
                    {/* Recent History */}
                    {!query && history.length > 0 && (
                        <div className={styles.section}>
                            <div className={styles.sectionHeader}>
                                <span>Recent</span>
                                <button className={styles.clearAll} onClick={() => { }}>Clear all</button>
                            </div>
                            {history.map((term, idx) => (
                                <div key={idx} className={styles.historyItem} onClick={() => handleSelect(term, 'history')}>
                                    <Clock size={16} className={styles.historyIcon} />
                                    <span>{term}</span>
                                    <button
                                        className={styles.removeHistory}
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            removeFromHistory(term);
                                        }}
                                    >
                                        <X size={14} />
                                    </button>
                                </div>
                            ))}
                        </div>
                    )}

                    {/* Search Results */}
                    {query && (
                        <div className={styles.results}>
                            {loading ? (
                                <div className={styles.loading}>Searching...</div>
                            ) : (
                                <>
                                    {results.users.length > 0 && (
                                        <div className={styles.section}>
                                            <div className={styles.sectionHeader}>Accounts</div>
                                            {results.users.map(user => (
                                                <div key={user.id} className={styles.resultItem} onClick={() => handleSelect(user, 'user')}>
                                                    <Avatar src={user.avatar_url} size="sm" />
                                                    <div className={styles.userInfo}>
                                                        <span className={styles.username}>{user.username}</span>
                                                        <span className={styles.fullname}>{user.full_name}</span>
                                                    </div>
                                                </div>
                                            ))}
                                        </div>
                                    )}

                                    {results.hashtags.length > 0 && (
                                        <div className={styles.section}>
                                            <div className={styles.sectionHeader}>Tags</div>
                                            {results.hashtags.map(tag => (
                                                <div key={tag.id} className={styles.resultItem} onClick={() => handleSelect(tag, 'hashtag')}>
                                                    <div className={styles.hashtagIcon}>#</div>
                                                    <div className={styles.tagInfo}>
                                                        <span className={styles.tagName}>#{tag.name}</span>
                                                        <span className={styles.tagCount}>{tag.count} posts</span>
                                                    </div>
                                                </div>
                                            ))}
                                        </div>
                                    )}

                                    {results.users.length === 0 && results.hashtags.length === 0 && (
                                        <div className={styles.noResults}>
                                            No results found for "{query}"
                                        </div>
                                    )}
                                </>
                            )}
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

