                    <>
                        <g transform="translate(35, 46)">
                            <circle cx="0" cy="0" r="10" fill={colors.eyeWhite} stroke={colors.outline} strokeWidth="2" />
                            <circle cx="0" cy="1" r="7" fill={colors.eyeIris} />
