    };

    // Map emotion to CSS class for body-part animations
    const getEmotionClass = () => {
        const validClasses = ['idle', 'idle_nervous', 'guardian_mode', 'thinking_focus',
            'happy_celebrate', 'concerned', 'happy', 'sad', 'speaking'];
        const base = isSpeaking ? 'speaking' : (emotion || 'idle');
        return validClasses.includes(base) ? styles[base] : styles.idle;
