import React, { useState, useEffect, useRef } from 'react';
import { focusToast } from '../../utils/focusToast';
import styles from './CallModal.module.css';

const CallModal = ({ type = 'audio', user, onClose, onAnswer, onDecline, isIncoming = false }) => {
    const [callStatus, setCallStatus] = useState(isIncoming ? 'incoming' : 'connecting');
    const [duration, setDuration] = useState(0);
    const [isMuted, setIsMuted] = useState(false);
    const [isVideoOff, setIsVideoOff] = useState(false);

    const localVideoRef = useRef(null);
    const remoteVideoRef = useRef(null);
    const peerConnectionRef = useRef(null);
    const localStreamRef = useRef(null);
    const timerRef = useRef(null);

    useEffect(() => {
        if (!isIncoming) {
            initializeCall();
        }

        return () => {
            cleanup();
        };
    }, []);

    useEffect(() => {
        if (callStatus === 'connected') {
            timerRef.current = setInterval(() => {
                setDuration(prev => prev + 1);
            }, 1000);
        }

        return () => {
            if (timerRef.current) {
                clearInterval(timerRef.current);
            }
        };
    }, [callStatus]);

    const initializeCall = async () => {
        try {
            // Get user media
            const stream = await navigator.mediaDevices.getUserMedia({
                audio: true,
                video: type === 'video'
            });

            localStreamRef.current = stream;

            if (type === 'video' && localVideoRef.current) {
                localVideoRef.current.srcObject = stream;
            }

            // Initialize WebRTC peer connection
            const configuration = {
                iceServers: [
                    { urls: 'stun:stun.l.google.com:19302' },
                    { urls: 'stun:stun1.l.google.com:19302' }
                ]
            };

            peerConnectionRef.current = new RTCPeerConnection(configuration);

            // Add local stream to peer connection
            stream.getTracks().forEach(track => {
                peerConnectionRef.current.addTrack(track, stream);
            });

            // Handle remote stream
            peerConnectionRef.current.ontrack = (event) => {
                if (remoteVideoRef.current) {
                    remoteVideoRef.current.srcObject = event.streams[0];
                }
                setCallStatus('connected');
            };

            // Handle ICE candidates
            peerConnectionRef.current.onicecandidate = (event) => {
                if (event.candidate) {
                    // Send ICE candidate to remote peer via signaling server
                    console.log('ICE candidate:', event.candidate);
                }
            };

            // Create and send offer
            const offer = await peerConnectionRef.current.createOffer();
            await peerConnectionRef.current.setLocalDescription(offer);

            // Send offer to remote peer via signaling server
            console.log('Offer created:', offer);

            // Simulate connection for demo
            setTimeout(() => {
                setCallStatus('connected');
            }, 2000);

        } catch (error) {
            console.error('Error initializing call:', error);
            focusToast.error('Failed to access camera/microphone');
            onClose();
        }
    };

    const handleAnswer = async () => {
        setCallStatus('connecting');
        await initializeCall();
        onAnswer?.();
    };

    const handleDecline = () => {
        cleanup();
        onDecline?.();
        onClose();
    };

    const handleEndCall = () => {
        cleanup();
        onClose();
    };

    const toggleMute = () => {
        if (localStreamRef.current) {
            const audioTrack = localStreamRef.current.getAudioTracks()[0];
            if (audioTrack) {
                audioTrack.enabled = !audioTrack.enabled;
                setIsMuted(!audioTrack.enabled);
            }
        }
    };

    const toggleVideo = () => {
        if (localStreamRef.current && type === 'video') {
            const videoTrack = localStreamRef.current.getVideoTracks()[0];
            if (videoTrack) {
                videoTrack.enabled = !videoTrack.enabled;
                setIsVideoOff(!videoTrack.enabled);
            }
        }
    };

    const cleanup = () => {
        if (localStreamRef.current) {
            localStreamRef.current.getTracks().forEach(track => track.stop());
        }
        if (peerConnectionRef.current) {
            peerConnectionRef.current.close();
        }
        if (timerRef.current) {
            clearInterval(timerRef.current);
        }
    };

    const formatDuration = (seconds) => {
        const mins = Math.floor(seconds / 60);
        const secs = seconds % 60;
        return `${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;
    };

    return (
        <div className={styles.overlay}>
            <div className={`${styles.modal} ${type === 'video' ? styles.videoCall : styles.audioCall}`}>
                {type === 'video' && callStatus === 'connected' && (
                    <div className={styles.videoContainer}>
                        <video
                            ref={remoteVideoRef}
                            autoPlay
                            playsInline
                            className={styles.remoteVideo}
                        />
                        <video
                            ref={localVideoRef}
                            autoPlay
                            playsInline
                            muted
                            className={styles.localVideo}
                        />
                    </div>
                )}

                <div className={styles.callInfo}>
                    <div className={styles.avatar}>
                        {user?.avatar_url ? (
                            <img src={user.avatar_url} alt={user.username} />
                        ) : (
