    useEffect(() => {
        if (!conversationId) return; // Guard clause

        console.log('≡ƒöì Checking for pending call in localStorage...');
        const pendingCallData = localStorage.getItem('pendingCall');

        if (pendingCallData) {
            try {
                const callData = JSON.parse(pendingCallData);
