                    console.log('Γ£à Pending call matches this conversation!');

                    // Clear from localStorage
                    localStorage.removeItem('pendingCall');

                    // Answer the call
                    console.log('≡ƒô₧ Auto-answering call:', callData.id, 'Type:', callData.call_type);
                    answerCall(callData.id, callData.call_type);
                } else {
                    console.log('ΓÜá∩╕Å Pending call is for different conversation');
                }
            } catch (err) {
                console.error('Γ¥î Error parsing pending call:', err);
                localStorage.removeItem('pendingCall');
            }
        } else {
            console.log('Γä╣∩╕Å No pending call found');
        }
    }, [conversationId, answerCall]);

    // Use passed otherUserData as fallback if useChatThread doesn't return data
    const otherUser = fetchedOtherUser || otherUserData;
    console.log('≡ƒæñ Using otherUser:', { fetchedOtherUser, otherUserData, final: otherUser });

    // Early return AFTER all hooks
    if (!conversationId) {
        console.warn('ΓÜá∩╕Å ChatPane rendered without conversationId!');
        return null;
    }

    // Combine real messages with optimistic messages
    const allMessages = [...messages, ...optimisticMessages];
    console.log('≡ƒÆ¼ Messages to display:', {
        realCount: messages.length,
        optimisticCount: optimisticMessages.length,
        totalCount: allMessages.length
    });

    const handleSend = async (contentOrData, options = {}) => {
        console.log('≡ƒÜÇ handleSend called with:', { contentOrData, options, conversationId });

        let content = contentOrData;
        let finalOptions = { ...options };

        // Handle object from EnhancedMessageInput (which passes { content, replyToId, ... })
        if (typeof contentOrData === 'object' && contentOrData !== null && !options.messageType) {
            console.log('≡ƒôª Detected object payload from EnhancedMessageInput');
            content = contentOrData.content;
            finalOptions = {
                ...finalOptions,
                ...contentOrData, // Merge type, metadata, etc.
                replyTo: contentOrData.replyToId // Map replyToId to replyTo
            };
        }

