            setReplyTo(null);

            // Force refetch messages to update UI immediately
            if (refetch) {
                console.log('≡ƒöä Refetching messages...');
                await refetch();
                // Clear optimistic messages after refetch to prevent duplicates
                clearOptimisticMessages();
            }

            return result;
        } catch (err) {
            console.error('Γ¥î handleSend failed:', err);
            console.error('Γ¥î Full error object:', JSON.stringify(err, null, 2));
            throw err;
        }
    };

    const handleReply = (message) => {
        console.log('Γå⌐∩╕Å handleReply called in ChatPane:', message);
        setReplyTo(message);
    };

    const handleReact = async (message, emoji) => {
        console.log('≡ƒÄ¡ handleReact called in ChatPane:', { message, emoji });
        try {
            // Get existing reactions or initialize empty array
            const existingReactions = message.reactions || [];

            // Check if user already reacted with this emoji
            const existingReactionIndex = existingReactions.findIndex(
                r => r.user_id === currentUserId && r.emoji === emoji
            );

            let newReactions;
            if (existingReactionIndex >= 0) {
                // Remove reaction if already exists
                newReactions = existingReactions.filter((_, idx) => idx !== existingReactionIndex);
            } else {
                // Add new reaction
                newReactions = [...existingReactions, { user_id: currentUserId, emoji }];
            }

            const { error } = await supabase
                .from('messages')
                .update({ reactions: newReactions })
                .eq('id', message.id);

            if (error) throw error;

            // Refetch messages to update UI
            refetch?.();

            focusToast.success(existingReactionIndex >= 0 ? 'Reaction removed' : 'Reaction added');
        } catch (error) {
            console.error('Failed to react:', error);
            focusToast.error('Failed to add reaction');
        }
    };

    // v2.0 ADVANCED HANDLERS - Restored
    const handleDelete = (message) => {
        console.log('≡ƒùæ∩╕Å handleDelete called in ChatPane:', message);
        setDeletingMessage(message);
    };

    const handleDeleteConfirm = async (forEveryone) => {
        console.log('≡ƒùæ∩╕Å handleDeleteConfirm called:', { deletingMessage, forEveryone });
        if (!deletingMessage) return;
        try {
            if (forEveryone) {
                console.log('≡ƒùæ∩╕Å Deleting for everyone:', deletingMessage.id);
                await deleteForEveryone(deletingMessage.id);
            } else {
                console.log('≡ƒùæ∩╕Å Deleting for me:', deletingMessage.id);
                await deleteForMe(deletingMessage.id, currentUserId);
            }
            console.log('Γ£à Delete successful');
            setDeletingMessage(null);
            refetch?.();
        } catch (error) {
            console.error('Γ¥î Failed to delete message:', error);
        }
    };

    const handleEdit = (message) => {
        if (!canEdit(message, currentUserId)) {
            focusToast.error('Cannot edit this message');
            return;
        }
        setEditingMessage(message);
    };

    const handleEditSubmit = async (newContent) => {
        if (!editingMessage) return;
        try {
            const success = await editMsg(editingMessage.id, newContent, editingMessage.content);
            if (success) {
                setEditingMessage(null);
                refetch?.();
            }
        } catch (error) {
            console.error('Failed to edit message:', error);
        }
    };

    const handleStar = async (message) => {
        try {
            const { error } = await supabase
                .from('messages')
                .update({ is_starred: !message.is_starred })
                .eq('id', message.id);

            if (error) throw error;
            focusToast.success(message.is_starred ? 'Removed from starred' : 'Added to starred');
        } catch (error) {
            console.error('Failed to star message:', error);
            focusToast.error('Failed to star message');
        }
    };

    const handleForward = (message) => {
        setForwardMessage(message);
    };

    const handleForwardSubmit = async (recipients) => {
        if (!forwardMessage || !recipients.length) return;
        try {
            await forwardToMultiple(forwardMessage, recipients, currentUserId);
            setForwardMessage(null);
        } catch (error) {
            console.error('Failed to forward message:', error);
        }
    };

    const handleMediaClick = (message) => {
        if (message.message_type === 'image' || message.message_type === 'video') {
            setMediaPreview({
                media: message.attachments.map(att => ({
                    url: att.url,
                    type: message.message_type,
                    name: att.name
                })),
                initialIndex: 0
            });
        }
    };

    const handleCall = async () => {
        if (!otherUserId) {
            focusToast.error('No user selected');
            return;
        }

        const call = await initiateCall(otherUserId, 'audio');
        if (call) {
            focusToast.success('Calling...');
        } else {
            focusToast.error('Failed to initiate call');
        }
    };

    const handleVideoCall = async () => {
        if (!otherUserId) {
            focusToast.error('No user selected');
            return;
        }

        const call = await initiateCall(otherUserId, 'video');
        if (call) {
            focusToast.success('Video calling...');
        } else {
            focusToast.error('Failed to initiate video call');
        }
    };

    const handleInfo = () => {
        setShowUserInfo(true);
    };

    // v2.0 Pin Handler - Restored
    const handlePin = async (message) => {
        try {
            if (isPinned(message.id)) {
                const pinnedMsg = pinnedMessages.find(p => p.message_id === message.id);
                if (pinnedMsg) {
                    await unpinMessage(pinnedMsg.id);
                }
            } else {
                if (!canPinMore) {
                    focusToast.error('You can only pin up to 3 messages');
                    return;
                }
                await pinMessage(message.id, currentUserId);
            }
        } catch (error) {
            console.error('Error pinning message:', error);
        }
    };

    const handleLocationSelect = async (location, isLive) => {
        try {
            await sendMessage('', {
                messageType: 'location',
                location: {
                    latitude: location.latitude,
                    longitude: location.longitude,
                    address: location.address
                },
                isLive: isLive
            });
            setShowLocationPicker(false);
            focusToast.success(isLive ? 'Sharing live location for 1 hour' : 'Location shared');
        } catch (error) {
            console.error('Failed to share location:', error);
            focusToast.error('Failed to share location');
        }
    };

    const handleVideoNoteComplete = async (videoBlob, duration) => {
        try {
            const videoFile = new File([videoBlob], `video-note-${Date.now()}.webm`, { type: 'video/webm' });
            const videoUrl = await uploadFile(videoFile);

            await sendMessage('', {
                messageType: 'video_note',
                attachments: [{
                    url: videoUrl,
                    type: 'video/webm',
                    duration: duration
                }]
            });

            setShowVideoRecorder(false);
            focusToast.success('Video note sent');
        } catch (error) {
            console.error('Failed to send video note:', error);
            focusToast.error('Failed to send video note');
        }
    };

    const handlePollCreate = async (pollData) => {
        try {
            await sendMessage(pollData.question, {
                messageType: 'poll',
                poll: {
                    question: pollData.question,
                    options: pollData.options,
                    allowMultiple: pollData.allowMultiple || false
                }
            });
            setShowPollCreator(false);
            focusToast.success('Poll created');
        } catch (error) {
            console.error('Failed to create poll:', error);
            focusToast.error('Failed to create poll');
        }
    };

    const handleEventCreate = async (eventData) => {
        try {
            await sendMessage(eventData.title, {
                messageType: 'event',
                event: {
                    title: eventData.title,
                    description: eventData.description,
                    date: eventData.date,
                    time: eventData.time,
                    location: eventData.location
                }
            });
            setShowEventCreator(false);
            focusToast.success('Event created');
        } catch (error) {
            console.error('Failed to create event:', error);
            focusToast.error('Failed to create event');
        }
    };

    const handleJumpToMessage = (message) => {
        // Scroll to message in the list
        const messageElement = document.getElementById(`message-${message.id}`);
        if (messageElement) {
            messageElement.scrollIntoView({ behavior: 'smooth', block: 'center' });
            messageElement.classList.add('highlight');
            setTimeout(() => messageElement.classList.remove('highlight'), 2000);
        }
    };

    // ≡ƒÜÇ NEW: GIF selection handler
    const handleGifSelect = async (gifData) => {
        try {
            await sendMessage('', {
                messageType: 'gif',
                metadata: {
                    url: gifData.url,
                    previewUrl: gifData.previewUrl,
                    width: gifData.width,
                    height: gifData.height,
                    title: gifData.title
                }
            });
            setShowGifPicker(false);
            focusToast.success('GIF sent!');
        } catch (error) {
            console.error('Failed to send GIF:', error);
            focusToast.error('Failed to send GIF');
        }
    };

    // ≡ƒÜÇ NEW: Share content handler
    const handleShareContent = (content, type) => {
        setContentToShare({ content, type });
        setShowShareModal(true);
    };

    const handleShareComplete = (count) => {
        focusToast.success(`Shared to ${count} conversation${count > 1 ? 's' : ''}!`);
        setShowShareModal(false);
        setContentToShare(null);
    };

    if (!otherUserId) {
        return (
            <div className={`${styles.chatPane} ${className}`}>
                <div className={styles.selectConversation}>
                    <svg width="120" height="120" viewBox="0 0 120 120" fill="none">
                        <path d="M15 99.68V25A10 10 0 0 1 25 15h70a10 10 0 0 1 10 10v50a10 10 0 0 1-10 10H40.42a10 10 0 0 0-7.81 3.75l-11.67 14.57A3 3 0 0 1 15 99.68z" stroke="currentColor" strokeWidth="4" strokeLinecap="round" />
                        <circle cx="45" cy="50" r="5" fill="currentColor" />
                        <circle cx="60" cy="50" r="5" fill="currentColor" />
                        <circle cx="75" cy="50" r="5" fill="currentColor" />
                    </svg>
                    <h3 className={styles.selectTitle}>Select a conversation</h3>
                    <p className={styles.selectText}>Choose a conversation from the inbox to start messaging</p>
                </div>
            </div>
        );
    }

    return (
        <div className={`${styles.chatPane} ${className}`}>
            <ChatHeader
                user={otherUser}
                onBack={onBack}
                onCall={handleCall}
                onVideoCall={handleVideoCall}
                onInfo={handleInfo}
                onSearch={() => setShowSearchPanel(true)}
                onShowPinned={() => setShowPinned(true)}
                onSchedule={() => setShowSchedule(true)}
                onDisappearingMessages={() => setShowDisappearing(true)}
                onReadReceipts={() => setShowReadReceipts(true)}
                onPINLock={() => setShowPINLock(true)}
            />

            {/* v2.0 Pinned Messages Banner */}
            <PinnedMessagesBanner
                conversationId={conversationId}
                groupId={null}
                currentUserId={currentUserId}
                onJumpToMessage={handleJumpToMessage}
            />

            <MessageList
                messages={allMessages}
                currentUserId={currentUserId}
                conversationId={conversationId}
                loading={otherUserData ? false : loading}
                isTyping={isTyping}
                typingUsers={typingUsers}
                typingUsername={otherUser?.username}
                onReply={handleReply}
                onReact={handleReact}
                // v2.0 Advanced features restored
                onDelete={handleDelete}
                onEdit={handleEdit}
                onStar={handleStar}
                onForward={handleForward}
                onPin={handlePin}
                onMediaClick={handleMediaClick}
            />

            {/* ≡ƒÜÇ NEW: Enhanced Message Input (with GIF, Stickers, etc.) */}
            {useEnhancedInput ? (
                <EnhancedMessageInput
                    conversationId={conversationId}
                    currentUserId={currentUserId}
                    replyTo={replyTo}
                    onClearReply={() => setReplyTo(null)}
                    onSendMessage={handleSend}
                    typingUsers={typingUsers}
                    onTypingChange={(isTyping) => {
                        if (isTyping) {
                            handleTyping();
                        } else {
                            stopTyping();
                        }
                    }}
                />
            ) : (
                /* Original MessageInputBar (fallback) */
                <MessageInputBar
                    onSend={handleSend}
                    onTyping={handleTyping}
                    onStopTyping={stopTyping}
                    replyTo={replyTo}
                    onCancelReply={() => setReplyTo(null)}
                    disabled={sending}
                    silentMode={silentMode}
                    onSilentModeToggle={() => setSilentMode(!silentMode)}
                    lastMessage={messages[messages.length - 1]}
                    onPollClick={() => setShowPollCreator(true)}
                    onLocationClick={() => setShowLocationPicker(true)}
                    onVideoNoteClick={() => setShowVideoRecorder(true)}
                    onEventClick={() => setShowEventCreator(true)}
                    onStickerClick={() => console.log('Sticker clicked')}
                    onGifClick={() => setShowGifPicker(true)}
                    isGroup={false}
                />
            )}

            {mediaPreview && (
                <MediaPreviewModal
                    media={mediaPreview.media}
                    initialIndex={mediaPreview.initialIndex}
                    onClose={() => setMediaPreview(null)}
                />
            )}

            {/* v2.0 Advanced Modals - Restored */}
            {forwardMessage && (
                <ForwardMessageModal
                    message={forwardMessage}
                    currentUserId={currentUserId}
                    onClose={() => setForwardMessage(null)}
                    onForward={handleForwardSubmit}
                />
            )}

            {editingMessage && (
                <EditMessageModal
                    message={editingMessage}
                    onClose={() => setEditingMessage(null)}
                    onSubmit={handleEditSubmit}
                    isLoading={isEditing}
                />
            )}

            {deletingMessage && (
                <DeleteMessageModal
                    message={deletingMessage}
                    currentUserId={currentUserId}
                    onClose={() => setDeletingMessage(null)}
                    onConfirm={handleDeleteConfirm}
                    isLoading={isDeleting}
                />
            )}

            {showSearchPanel && (
                <MessageSearchPanel
                    conversationId={conversationId}
                    onClose={() => setShowSearchPanel(false)}
                    onSelectMessage={handleJumpToMessage}
                />
            )}

            {showPinned && (
                <PinnedMessagesPanel
                    conversationId={conversationId}
                    currentUserId={currentUserId}
                    otherUserId={otherUserId}
                    onClose={() => setShowPinned(false)}
                    onJumpToMessage={handleJumpToMessage}
                />
            )}

            {showUserInfo && (
                <UserInfoModal
                    user={otherUser}
                    onClose={() => setShowUserInfo(false)}
                />
            )}

            {/* v2.0 Location & Media Features */}
            {showLocationPicker && (
                <LocationPicker
                    onSelect={handleLocationSelect}
                    onClose={() => setShowLocationPicker(false)}
                />
            )}

            {showPollCreator && (
                <PollCreator
                    onSubmit={handlePollCreate}
                    onClose={() => setShowPollCreator(false)}
                />
            )}

            {showEventCreator && (
                <EventCreator
                    onSubmit={handleEventCreate}
                    onClose={() => setShowEventCreator(false)}
                />
            )}

            {showVideoRecorder && (
                <VideoNoteRecorder
                    onComplete={handleVideoNoteComplete}
                    onClose={() => setShowVideoRecorder(false)}
                />
            )}

            {/* ≡ƒÜÇ NEW: GIF Picker Modal */}
            {showGifPicker && (
                <GifPicker
                    onSelect={handleGifSelect}
                    onClose={() => setShowGifPicker(false)}
                />
            )}

            {/* ≡ƒÜÇ NEW: Share to Messages Modal */}
            {showShareModal && contentToShare && (
                <ShareToMessages
                    content={contentToShare.content}
                    contentType={contentToShare.type}
                    onClose={() => {
                        setShowShareModal(false);
                        setContentToShare(null);
                    }}
                    onShare={handleShareComplete}
                />
            )}

            {/* Active call window - Modern Social Media Style */}
            {activeCall && (
                <ModernCallWindow
                    callId={activeCall.id}
                    userId={user?.id}
                    otherUser={otherUser}
                    isInitiator={isInitiator}
                    audioOnly={callType === 'audio'}
                    onEndCall={endCall}
                />
            )}

        </div>
    );
};

export default React.memo(ChatPane, (prevProps, nextProps) => {
    // Only re-render if the conversation ID changes
    return prevProps.conversationId === nextProps.conversationId;
});

import React, { useState, useEffect, useRef } from 'react';
import { useMessageEdit } from '../../hooks/useMessageEdit';
import Button from '../ui/Button';
import styles from './EditMessageModal.module.css';

const EditMessageModal = ({ message, onClose, onSuccess }) => {
    const [content, setContent] = useState(message?.content || '');
    const [showHistory, setShowHistory] = useState(false);
    const [editHistory, setEditHistory] = useState([]);
    const textareaRef = useRef(null);

    const { editing, canEdit, editMessage, editGroupMessage, getEditHistory } = useMessageEdit();

    useEffect(() => {
        // Focus textarea on mount
        textareaRef.current?.focus();

        // Load edit history
        loadEditHistory();
    }, []);

    const loadEditHistory = async () => {
        const isGroupMessage = !!message.group_id;
        const history = await getEditHistory(message.id, isGroupMessage);
        setEditHistory(history);
    };

    const handleSubmit = async (e) => {
        e.preventDefault();

        if (!content.trim()) {
            return;
        }

        const isGroupMessage = !!message.group_id;
        const success = isGroupMessage
            ? await editGroupMessage(message.id, content, message.content)
            : await editMessage(message.id, content, message.content);

        if (success) {
            onSuccess?.();
            onClose();
        }
    };

    const handleKeyDown = (e) => {
        if (e.key === 'Enter' && !e.shiftKey) {
            e.preventDefault();
            handleSubmit(e);
        } else if (e.key === 'Escape') {
            onClose();
        }
    };

    const timeRemaining = () => {
        const messageTime = new Date(message.created_at);
        const now = new Date();
        const diffMinutes = 15 - Math.floor((now - messageTime) / 1000 / 60);
        return Math.max(0, diffMinutes);
    };

    return (
        <div className={styles.overlay} onClick={onClose}>
            <div className={styles.modal} onClick={(e) => e.stopPropagation()}>
                <div className={styles.header}>
                    <h2 className={styles.title}>Edit Message</h2>
                    <button className={styles.closeButton} onClick={onClose}>
                        <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
                            <path d="M18 6L6 18M6 6l12 12" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
                        </svg>
                    </button>
                </div>

                <div className={styles.content}>
                    <div className={styles.timeWarning}>
                        <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
                            <circle cx="8" cy="8" r="7" stroke="currentColor" strokeWidth="2" />
                            <path d="M8 4v4l3 2" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
                        </svg>
                        <span>You can edit this message for {timeRemaining()} more minutes</span>
                    </div>

                    <form onSubmit={handleSubmit}>
                        <textarea
                            ref={textareaRef}
                            className={styles.textarea}
                            value={content}
                            onChange={(e) => setContent(e.target.value)}
                            onKeyDown={handleKeyDown}
                            placeholder="Edit your message..."
                            rows={4}
                            maxLength={5000}
                        />

                        <div className={styles.charCount}>
                            {content.length}/5000
                        </div>

                        {editHistory.length > 0 && (
                            <button
                                type="button"
                                className={styles.historyToggle}
                                onClick={() => setShowHistory(!showHistory)}
                            >
                                {showHistory ? 'Hide' : 'Show'} edit history ({editHistory.length})
                            </button>
                        )}

                        {showHistory && editHistory.length > 0 && (
                            <div className={styles.history}>
                                <h3 className={styles.historyTitle}>Edit History</h3>
                                {editHistory.map((edit, index) => (
                                    <div key={edit.id} className={styles.historyItem}>
                                        <div className={styles.historyTime}>
                                            {new Date(edit.edited_at).toLocaleString()}
                                        </div>
                                        <div className={styles.historyContent}>
                                            {edit.previous_content}
                                        </div>
                                    </div>
                                ))}
                            </div>
                        )}

                        <div className={styles.actions}>
                            <Button
                                variant="secondary"
                                onClick={onClose}
                                type="button"
                            >
                                Cancel
                            </Button>
                            <Button
                                variant="primary"
                                type="submit"
                                disabled={editing || !content.trim() || content.trim() === message.content}
                                loading={editing}
                            >
                                Save Changes
                            </Button>
                        </div>
                    </form>
                </div>
            </div>
        </div>
    );
};

export default EditMessageModal;

import React, { useState, useEffect } from 'react';
import { supabase } from '../../lib/supabase';
import MessageBubble from './MessageBubble';
import { formatDateDivider } from '../../utils/formatDateDivider';
import styles from './FavoritesPanel.module.css';

const FavoritesPanel = ({ userId, onClose }) => {
    const [favorites, setFavorites] = useState([]);
    const [loading, setLoading] = useState(true);
    const [filter, setFilter] = useState('all'); // all, images, videos, links, files

    useEffect(() => {
        fetchFavorites();
    }, [userId, filter]);

    const fetchFavorites = async () => {
        if (!userId) return;

        setLoading(true);
        try {
            let query = supabase
                .from('messages')
                .select('*, sender:profiles!sender_id(*)')
                .eq('is_starred', true)
                .or(`sender_id.eq.${userId},receiver_id.eq.${userId}`)
                .order('created_at', { ascending: false });

            if (filter === 'images') {
                query = query.eq('message_type', 'image');
            } else if (filter === 'videos') {
                query = query.eq('message_type', 'video');
            } else if (filter === 'files') {
                query = query.eq('message_type', 'file');
            } else if (filter === 'links') {
                query = query.like('content', '%http%');
            }

            const { data, error } = await query;

            if (error) throw error;
            setFavorites(data || []);
        } catch (error) {
            console.error('Error fetching favorites:', error);
        } finally {
            setLoading(false);
        }
    };

    const handleUnstar = async (messageId) => {
        try {
            const { error } = await supabase
                .from('messages')
                .update({ is_starred: false })
                .eq('id', messageId);

            if (error) throw error;

            // Remove from local state
            setFavorites(prev => prev.filter(msg => msg.id !== messageId));
        } catch (error) {
            console.error('Error unstarring message:', error);
        }
    };

    const groupByDate = (messages) => {
        const groups = {};
        messages.forEach(message => {
            const date = formatDateDivider(message.created_at);
            if (!groups[date]) {
                groups[date] = [];
            }
            groups[date].push(message);
        });
        return groups;
    };

    const groupedFavorites = groupByDate(favorites);

    return (
        <div className={styles.overlay} onClick={onClose}>
            <div className={styles.panel} onClick={(e) => e.stopPropagation()}>
                {/* Header */}
                <div className={styles.header}>
                    <div className={styles.headerLeft}>
                        <svg width="24" height="24" viewBox="0 0 24 24" fill="currentColor">
                            <path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z" />
                        </svg>
                        <h2>Starred Messages</h2>
                    </div>

                    <button className={styles.closeButton} onClick={onClose}>
                        <svg width="20" height="20" viewBox="0 0 24 24" fill="none">
                            <path d="M18 6L6 18M6 6l12 12" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
                        </svg>
                    </button>
                </div>

                {/* Filters */}
                <div className={styles.filters}>
                    <button
                        className={`${styles.filterButton} ${filter === 'all' ? styles.active : ''}`}
                        onClick={() => setFilter('all')}
                    >
                        All
                    </button>
                    <button
                        className={`${styles.filterButton} ${filter === 'images' ? styles.active : ''}`}
                        onClick={() => setFilter('images')}
                    >
                        <svg width="16" height="16" viewBox="0 0 24 24" fill="none">
                            <rect x="3" y="3" width="18" height="18" rx="2" stroke="currentColor" strokeWidth="2" />
                            <circle cx="8.5" cy="8.5" r="1.5" fill="currentColor" />
                            <path d="M21 15l-5-5L5 21" stroke="currentColor" strokeWidth="2" />
                        </svg>
                        Photos
                    </button>
                    <button
                        className={`${styles.filterButton} ${filter === 'videos' ? styles.active : ''}`}
                        onClick={() => setFilter('videos')}
                    >
                        <svg width="16" height="16" viewBox="0 0 24 24" fill="none">
