                                <svg width="20" height="20" viewBox="0 0 20 20" fill="none">
                                    <path d="M10 2a6 6 0 0 1 6 6c0 4-6 10-6 10S4 12 4 8a6 6 0 0 1 6-6z"
                                        stroke="currentColor" strokeWidth="2" />
                                    <circle cx="10" cy="8" r="2" fill="currentColor" />
                                </svg>
