                        variant="primary"
                        onClick={handleShare}
                        disabled={!location || sharing}
                        loading={sharing}
                        fullWidth
                    >
                        Share Location
                    </Button>
                </div>
            </div>
        </div>
    );
};

export default LocationPicker;

import React, { useState, useEffect } from 'react';
import { useClickOutside } from '../../hooks/useClickOutside';
import styles from './MediaPreviewModal.module.css';

const MediaPreviewModal = ({ media, initialIndex = 0, onClose }) => {
    const [currentIndex, setCurrentIndex] = useState(initialIndex);
    const [isZoomed, setIsZoomed] = useState(false);
    const modalRef = React.useRef(null);

    useClickOutside(modalRef, onClose);

    useEffect(() => {
        const handleKeyDown = (e) => {
            if (e.key === 'Escape') onClose();
            if (e.key === 'ArrowLeft') handlePrevious();
            if (e.key === 'ArrowRight') handleNext();
        };

        document.addEventListener('keydown', handleKeyDown);
        document.body.style.overflow = 'hidden';

        return () => {
            document.removeEventListener('keydown', handleKeyDown);
            document.body.style.overflow = 'auto';
        };
    }, [currentIndex]);

    const handlePrevious = () => {
        setCurrentIndex((prev) => (prev > 0 ? prev - 1 : media.length - 1));
        setIsZoomed(false);
    };

    const handleNext = () => {
        setCurrentIndex((prev) => (prev < media.length - 1 ? prev + 1 : 0));
        setIsZoomed(false);
    };

    const handleDownload = async () => {
        const currentMedia = media[currentIndex];
        try {
            const response = await fetch(currentMedia.url);
            const blob = await response.blob();
            const url = window.URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = currentMedia.name || `media-${Date.now()}`;
            document.body.appendChild(a);
            a.click();
            window.URL.revokeObjectURL(url);
            document.body.removeChild(a);
        } catch (error) {
            console.error('Download failed:', error);
        }
    };

    const currentMedia = media[currentIndex];

    return (
        <div className={styles.overlay}>
            <div ref={modalRef} className={styles.modal}>
                {/* Header */}
                <div className={styles.header}>
                    <div className={styles.info}>
                        <span className={styles.counter}>
                            {currentIndex + 1} / {media.length}
                        </span>
                        {currentMedia.name && (
                            <span className={styles.filename}>{currentMedia.name}</span>
                        )}
                    </div>

                    <div className={styles.actions}>
                        <button
                            className={styles.actionButton}
                            onClick={handleDownload}
                            title="Download"
                        >
                            <svg width="20" height="20" viewBox="0 0 24 24" fill="none">
                                <path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4M7 10l5 5 5-5M12 15V3" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
                            </svg>
                        </button>

                        <button
                            className={styles.actionButton}
                            onClick={onClose}
                            title="Close"
                        >
                            <svg width="20" height="20" viewBox="0 0 24 24" fill="none">
                                <path d="M18 6L6 18M6 6l12 12" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
                            </svg>
                        </button>
                    </div>
                </div>

                {/* Media Content */}
                <div className={styles.content}>
                    {currentMedia.type === 'image' ? (
                        <img
                            src={currentMedia.url}
                            alt={currentMedia.name || 'Media'}
                            className={`${styles.image} ${isZoomed ? styles.zoomed : ''}`}
                            onClick={() => setIsZoomed(!isZoomed)}
                        />
                    ) : currentMedia.type === 'video' ? (
                        <video
                            src={currentMedia.url}
                            controls
                            autoPlay
                            className={styles.video}
                        />
                    ) : currentMedia.type === 'audio' ? (
                        <div className={styles.audioContainer}>
                            <svg width="80" height="80" viewBox="0 0 24 24" fill="none">
                                <path d="M9 18V5l12-2v13M9 18c0 1.66-1.34 3-3 3s-3-1.34-3-3 1.34-3 3-3 3 1.34 3 3zm12-2c0 1.66-1.34 3-3 3s-3-1.34-3-3 1.34-3 3-3 3 1.34 3 3z" stroke="currentColor" strokeWidth="2" />
                            </svg>
                            <audio src={currentMedia.url} controls className={styles.audio} />
                        </div>
                    ) : (
                        <div className={styles.fileContainer}>
                            <svg width="80" height="80" viewBox="0 0 24 24" fill="none">
                                <path d="M13 2H6a2 2 0 00-2 2v16a2 2 0 002 2h12a2 2 0 002-2V9z" stroke="currentColor" strokeWidth="2" />
                                <path d="M13 2v7h7" stroke="currentColor" strokeWidth="2" />
                            </svg>
                            <p className={styles.fileName}>{currentMedia.name}</p>
                            <button className={styles.downloadButton} onClick={handleDownload}>
                                Download File
                            </button>
                        </div>
                    )}
                </div>

                {/* Navigation */}
                {media.length > 1 && (
                    <>
                        <button
                            className={`${styles.navButton} ${styles.prev}`}
                            onClick={handlePrevious}
                            title="Previous"
                        >
                            <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
                                <path d="M15 18l-6-6 6-6" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
                            </svg>
                        </button>

                        <button
                            className={`${styles.navButton} ${styles.next}`}
                            onClick={handleNext}
                            title="Next"
                        >
                            <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
                                <path d="M9 18l6-6-6-6" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
                            </svg>
                        </button>
                    </>
                )}

                {/* Thumbnails */}
                {media.length > 1 && (
                    <div className={styles.thumbnails}>
                        {media.map((item, index) => (
                            <button
                                key={index}
                                className={`${styles.thumbnail} ${index === currentIndex ? styles.active : ''}`}
                                onClick={() => {
                                    setCurrentIndex(index);
                                    setIsZoomed(false);
                                }}
                            >
                                {item.type === 'image' ? (
                                    <img src={item.url} alt={`Thumbnail ${index + 1}`} />
                                ) : item.type === 'video' ? (
                                    <div className={styles.videoThumb}>
                                        <svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor">
                                            <path d="M8 5v14l11-7z" />
                                        </svg>
                                    </div>
                                ) : (
                                    <div className={styles.fileThumb}>
                                        <svg width="20" height="20" viewBox="0 0 24 24" fill="none">
                                            <path d="M13 2H6a2 2 0 00-2 2v16a2 2 0 002 2h12a2 2 0 002-2V9z" stroke="currentColor" strokeWidth="2" />
                                        </svg>
                                    </div>
                                )}
                            </button>
                        ))}
                    </div>
                )}
            </div>
        </div>
    );
};

export default MediaPreviewModal;

import React, { useState, useRef, useEffect } from 'react';
import { formatTimeAgo } from '../../utils/formatTimeAgo';
import MessageStatusTicks from './MessageStatusTicks';
import VoiceMessagePlayer from './VoiceMessagePlayer';
import PollDisplay from './PollDisplay';
import EventDisplay from './EventDisplay';
import { useAuth } from '../../hooks/useAuth';
import styles from './MessageBubble.module.css';

const MessageBubble = ({
    message,
    isOwn,
    showAvatar = false,
    onMediaClick
}) => {
    const { user } = useAuth();

    // Helper to handle double-serialized JSON messages
    const getDisplayContent = (content) => {
        if (!content) return '';
        try {
            if (typeof content === 'string' && content.trim().startsWith('{') && content.includes('"content":')) {
                const parsed = JSON.parse(content);
                return parsed.content || content;
            }
        } catch (e) {
            // Not JSON or invalid, return as is
        }
        return content;
    };

    const renderContent = () => {
        const type = message.type || message.message_type || 'text';
        const displayContent = getDisplayContent(message.content);

        // Show deleted placeholder if message is deleted
        if (message.is_deleted) {
            return (
                <div className={styles.deletedMessage}>
                    <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
                        <path d="M2 4h12M5.5 4V3a1 1 0 0 1 1-1h3a1 1 0 0 1 1 1v1m1.5 0v9a1 1 0 0 1-1 1h-7a1 1 0 0 1-1-1V4h9z"
                            stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
                    </svg>
                    <span>This message was deleted</span>
                </div>
            );
        }

        if (type === 'image') {
            return (
                <div className={styles.mediaContainer} onClick={() => onMediaClick?.(message)}>
                    <img src={message.attachments?.[0]?.url} alt="Shared image" className={styles.image} />
                    {displayContent && <p className={styles.caption}>{displayContent}</p>}
                </div>
            );
        }

        if (type === 'video') {
            return (
                <div className={styles.mediaContainer} onClick={() => onMediaClick?.(message)}>
                    <video src={message.attachments?.[0]?.url} controls className={styles.video} />
                    {displayContent && <p className={styles.caption}>{displayContent}</p>}
                </div>
            );
        }

        if (type === 'audio') {
            return (
                <VoiceMessagePlayer
                    audioUrl={message.attachments?.[0]?.url}
                    duration={message.attachments?.[0]?.duration}
                    isOwn={isOwn}
                />
            );
        }

        if (type === 'poll') {
            return <PollDisplay message={message} />;
        }

        if (type === 'event') {
            return <EventDisplay message={message} />;
        }

        if (type === 'file') {
            return (
                <a href={message.attachments?.[0]?.url} download className={styles.fileLink}>
                    <svg width="20" height="20" viewBox="0 0 20 20" fill="none">
                        <path d="M6 2h8l4 4v11a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2z" stroke="currentColor" strokeWidth="2" />
                    </svg>
                    <span>{message.attachments?.[0]?.name || 'File'}</span>
                </a>
            );
        }

        if (type === 'sticker') {
            return (
                <div className={styles.stickerContainer}>
                    <img src={message.content} alt="Sticker" className={styles.sticker} />
                </div>
            );
        }

        if (type === 'gif') {
            return (
                <div className={styles.gifContainer}>
                    <img src={message.content} alt="GIF" className={styles.gif} />
                </div>
            );
        }

        return <p className={styles.text}>{displayContent}</p>;
    };

    return (
        <div className={`${styles.messageWrapper} ${isOwn ? styles.own : styles.other}`}>
            <div className={styles.messageBubble}>
                {message.forwarded_from && (
                    <div className={styles.forwardedLabel}>
                        <svg width="14" height="14" viewBox="0 0 14 14" fill="none">
                            <path d="M7 2v8M10 7l-3 3-3-3" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
                        </svg>
                        <span>Forwarded</span>
                    </div>
                )}

                {renderContent()}

                <div className={styles.messageFooter}>
                    <span className={styles.timestamp}>
                        {formatTimeAgo(message.created_at)}
                        {message.is_edited && <span className={styles.edited}> (edited)</span>}
                    </span>
                    {isOwn && !message._optimistic && !message._failed && (
                        <MessageStatusTicks
                            isSent={true}
                            isDelivered={message.is_delivered || message.is_read}
                            isRead={message.is_read}
                            size="sm"
                        />
                    )}
                    {message._optimistic && <span className={styles.sending}>Sending...</span>}
                    {message._failed && <span className={styles.failed}>Failed</span>}
                </div>
            </div>
        </div>
    );
};

export default MessageBubble;

import React, { useState, useEffect } from 'react';
import { supabase } from '../../lib/supabase';
import useDebounce from '../../hooks/useDebounce';
import { formatDateDivider } from '../../utils/formatDateDivider';
import styles from './MessageSearchModal.module.css';

const MessageSearchModal = ({ currentUserId, onClose, onSelectMessage }) => {
    const [searchQuery, setSearchQuery] = useState('');
    const [results, setResults] = useState([]);
    const [loading, setLoading] = useState(false);
    const [filters, setFilters] = useState({
        sender: '',
        dateFrom: '',
        dateTo: '',
        mediaType: 'all' // all, image, video, audio, file
    });

    const debouncedSearch = useDebounce(searchQuery, 400);

    useEffect(() => {
        if (debouncedSearch) {
            searchMessages();
        } else {
            setResults([]);
        }
    }, [debouncedSearch, filters]);

    const searchMessages = async () => {
        setLoading(true);
        try {
            let query = supabase
                .from('messages')
                .select('*, sender:profiles!sender_id(*), receiver:profiles!receiver_id(*)')
                .or(`sender_id.eq.${currentUserId},receiver_id.eq.${currentUserId}`)
                .ilike('content', `%${debouncedSearch}%`)
                .order('created_at', { ascending: false })
                .limit(50);

            // Apply filters
            if (filters.sender) {
                query = query.or(`sender_id.eq.${filters.sender},receiver_id.eq.${filters.sender}`);
            }

            if (filters.dateFrom) {
                query = query.gte('created_at', new Date(filters.dateFrom).toISOString());
            }

            if (filters.dateTo) {
                query = query.lte('created_at', new Date(filters.dateTo).toISOString());
            }

            if (filters.mediaType !== 'all') {
                query = query.eq('message_type', filters.mediaType);
            }

            const { data, error } = await query;

            if (error) throw error;
            setResults(data || []);
        } catch (error) {
            console.error('Error searching messages:', error);
        } finally {
            setLoading(false);
        }
    };

    const highlightText = (text, query) => {
        if (!query || !text) return text;

        const parts = text.split(new RegExp(`(${query})`, 'gi'));
        return parts.map((part, index) =>
            part.toLowerCase() === query.toLowerCase() ?
                <mark key={index} className={styles.highlight}>{part}</mark> :
                part
        );
    };

    const handleSelectMessage = (message) => {
        const otherUserId = message.sender_id === currentUserId ? message.receiver_id : message.sender_id;
        onSelectMessage(message, otherUserId);
        onClose();
    };

    const clearFilters = () => {
        setFilters({
            sender: '',
            dateFrom: '',
            dateTo: '',
            mediaType: 'all'
        });
    };

    return (
        <div className={styles.overlay} onClick={onClose}>
            <div className={styles.modal} onClick={(e) => e.stopPropagation()}>
                <div className={styles.header}>
                    <h2>Search Messages</h2>
                    <button className={styles.closeButton} onClick={onClose}>
                        <svg width="20" height="20" viewBox="0 0 24 24" fill="none">
                            <path d="M18 6L6 18M6 6l12 12" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
                        </svg>
                    </button>
                </div>

                <div className={styles.searchSection}>
                    <div className={styles.searchBar}>
                        <svg width="20" height="20" viewBox="0 0 24 24" fill="none">
                            <circle cx="11" cy="11" r="8" stroke="currentColor" strokeWidth="2" />
                            <path d="M21 21l-4.35-4.35" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
                        </svg>
                        <input
                            type="text"
                            placeholder="Search in messages..."
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                            autoFocus
                        />
                    </div>

                    <div className={styles.filters}>
                        <select
                            value={filters.mediaType}
                            onChange={(e) => setFilters(prev => ({ ...prev, mediaType: e.target.value }))}
                            className={styles.filterSelect}
                        >
                            <option value="all">All Types</option>
                            <option value="text">Text Only</option>
                            <option value="image">Images</option>
                            <option value="video">Videos</option>
                            <option value="audio">Audio</option>
                            <option value="file">Files</option>
                        </select>

                        <input
                            type="date"
                            value={filters.dateFrom}
                            onChange={(e) => setFilters(prev => ({ ...prev, dateFrom: e.target.value }))}
                            placeholder="From date"
                            className={styles.filterInput}
                        />

                        <input
                            type="date"
                            value={filters.dateTo}
                            onChange={(e) => setFilters(prev => ({ ...prev, dateTo: e.target.value }))}
                            placeholder="To date"
                            className={styles.filterInput}
                        />

                        {(filters.dateFrom || filters.dateTo || filters.mediaType !== 'all') && (
                            <button className={styles.clearFilters} onClick={clearFilters}>
                                Clear Filters
                            </button>
                        )}
                    </div>
                </div>

                <div className={styles.results}>
                    {loading ? (
                        <div className={styles.loading}>
                            <div className={styles.spinner}></div>
                            <p>Searching...</p>
                        </div>
                    ) : results.length > 0 ? (
                        <div className={styles.resultsList}>
                            <p className={styles.resultsCount}>
                                Found {results.length} {results.length === 1 ? 'message' : 'messages'}
                            </p>
                            {results.map((message) => {
                                const isOwn = message.sender_id === currentUserId;
                                const otherUser = isOwn ? message.receiver : message.sender;

                                return (
                                    <div
                                        key={message.id}
                                        className={styles.resultItem}
                                        onClick={() => handleSelectMessage(message)}
                                    >
                                        <div className={styles.resultHeader}>
                                            <div className={styles.userInfo}>
                                                <div className={styles.avatar}>
                                                    {otherUser?.avatar_url ? (
                                                        <img src={otherUser.avatar_url} alt={otherUser.username} />
                                                    ) : (
                                                        <div className={styles.avatarPlaceholder}>
                                                            {otherUser?.username?.[0]?.toUpperCase()}
                                                        </div>
                                                    )}
                                                </div>
                                                <div>
                                                    <span className={styles.username}>
                                                        {isOwn ? 'You' : otherUser?.username}
                                                    </span>
                                                    <span className={styles.arrow}>ΓåÆ</span>
                                                    <span className={styles.username}>
                                                        {isOwn ? otherUser?.username : 'You'}
                                                    </span>
                                                </div>
                                            </div>
                                            <span className={styles.date}>
                                                {formatDateDivider(message.created_at)}
                                            </span>
                                        </div>

                                        <div className={styles.messageContent}>
                                            {message.message_type === 'image' && (
                                                <span className={styles.mediaTag}>≡ƒô╖ Image</span>
                                            )}
                                            {message.message_type === 'video' && (
                                                <span className={styles.mediaTag}>≡ƒÄÑ Video</span>
                                            )}
                                            {message.message_type === 'audio' && (
                                                <span className={styles.mediaTag}>≡ƒÄ╡ Audio</span>
                                            )}
                                            {message.message_type === 'file' && (
                                                <span className={styles.mediaTag}>≡ƒôÄ File</span>
                                            )}
                                            <p>{highlightText(message.content, searchQuery)}</p>
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    ) : searchQuery ? (
                        <div className={styles.empty}>
                            <svg width="80" height="80" viewBox="0 0 24 24" fill="none">
                                <circle cx="11" cy="11" r="8" stroke="currentColor" strokeWidth="2" />
                                <path d="M21 21l-4.35-4.35" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
                            </svg>
                            <p>No messages found</p>
                            <span>Try different keywords or adjust filters</span>
                        </div>
                    ) : (
                        <div className={styles.empty}>
                            <svg width="80" height="80" viewBox="0 0 24 24" fill="none">
                                <circle cx="11" cy="11" r="8" stroke="currentColor" strokeWidth="2" />
                                <path d="M21 21l-4.35-4.35" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
                            </svg>
                            <p>Search your messages</p>
                            <span>Enter keywords to search across all conversations</span>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

export default MessageSearchModal;

import React, { useState, useEffect } from 'react';
import { useMessageSearch } from '../../hooks/useMessageSearch';
import { useAuth } from '../../hooks/useAuth';
import Avatar from '../ui/Avatar';
import styles from './MessageSearchPanel.module.css';

const MessageSearchPanel = ({ conversationId, onClose, onSelectMessage }) => {
    const { user } = useAuth();
    const [query, setQuery] = useState('');
    const [activeFilter, setActiveFilter] = useState('all');
    const { searching, results, searchMessages, searchByMediaType, clearResults } = useMessageSearch();

    useEffect(() => {
        if (query.length >= 2) {
            if (activeFilter === 'all') {
                searchMessages(query, { conversationId });
            } else {
                searchByMediaType(activeFilter, conversationId);
            }
        } else {
            clearResults();
        }
    }, [query, activeFilter, conversationId]);

    const filters = [
        { id: 'all', label: 'All', icon: '≡ƒÆ¼' },
        { id: 'image', label: 'Photos', icon: '≡ƒô╖' },
        { id: 'video', label: 'Videos', icon: '≡ƒÄÑ' },
        { id: 'audio', label: 'Audio', icon: '≡ƒÄ╡' },
        { id: 'file', label: 'Files', icon: '≡ƒôÄ' }
    ];

    const handleSelectMessage = (message) => {
        onSelectMessage?.(message);
        onClose();
    };

    const formatDate = (dateString) => {
        const date = new Date(dateString);
        const now = new Date();
        const diff = now - date;
        const days = Math.floor(diff / (1000 * 60 * 60 * 24));

        if (days === 0) return 'Today';
        if (days === 1) return 'Yesterday';
        if (days < 7) return `${days} days ago`;
        return date.toLocaleDateString();
    };

    return (
        <div className={styles.panel}>
            <div className={styles.header}>
                <h2>Search Messages</h2>
                <button className={styles.closeButton} onClick={onClose}>
                    <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
                        <path d="M18 6L6 18M6 6l12 12" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
                    </svg>
                </button>
            </div>

            <div className={styles.searchBar}>
                <svg width="20" height="20" viewBox="0 0 24 24" fill="none">
                    <circle cx="11" cy="11" r="8" stroke="currentColor" strokeWidth="2" />
                    <path d="M21 21l-4.35-4.35" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
                </svg>
                <input
                    type="text"
                    placeholder="Search in conversation..."
                    value={query}
                    onChange={(e) => setQuery(e.target.value)}
                    autoFocus
                />
                {query && (
                    <button className={styles.clearButton} onClick={() => setQuery('')}>
                        <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
                            <path d="M12 4L4 12M4 4l8 8" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
                        </svg>
                    </button>
                )}
            </div>

            <div className={styles.filters}>
                {filters.map(filter => (
                    <button
                        key={filter.id}
                        className={`${styles.filterButton} ${activeFilter === filter.id ? styles.active : ''}`}
                        onClick={() => setActiveFilter(filter.id)}
                    >
                        <span className={styles.filterIcon}>{filter.icon}</span>
                        <span className={styles.filterLabel}>{filter.label}</span>
                    </button>
                ))}
            </div>

            <div className={styles.results}>
                {searching ? (
                    <div className={styles.loading}>
                        <div className={styles.spinner}></div>
                        <p>Searching...</p>
                    </div>
                ) : results.length > 0 ? (
                    <>
                        <div className={styles.resultCount}>
                            {results.length} {results.length === 1 ? 'result' : 'results'}
                        </div>
                        {results.map(message => (
                            <div
                                key={message.id}
                                className={styles.resultItem}
                                onClick={() => handleSelectMessage(message)}
                            >
                                <Avatar
                                    src={message.sender?.avatar_url}
                                    alt={message.sender?.username}
                                    size="sm"
                                    fallback={message.sender?.username?.[0]?.toUpperCase()}
                                />
                                <div className={styles.resultContent}>
                                    <div className={styles.resultHeader}>
                                        <span className={styles.resultSender}>
                                            {message.sender?.full_name || message.sender?.username}
                                        </span>
                                        <span className={styles.resultDate}>
                                            {formatDate(message.created_at)}
                                        </span>
                                    </div>
                                    <div className={styles.resultText}>
                                        {message.message_type === 'text' ? (
                                            message.content
                                        ) : (
                                            <span className={styles.mediaType}>
                                                {message.message_type === 'image' && '≡ƒô╖ Photo'}
                                                {message.message_type === 'video' && '≡ƒÄÑ Video'}
                                                {message.message_type === 'audio' && '≡ƒÄ╡ Audio'}
                                                {message.message_type === 'file' && '≡ƒôÄ File'}
                                            </span>
                                        )}
                                    </div>
                                </div>
                            </div>
                        ))}
                    </>
                ) : query.length >= 2 ? (
                    <div className={styles.empty}>
                        <svg width="64" height="64" viewBox="0 0 64 64" fill="none">
                            <circle cx="32" cy="32" r="28" stroke="currentColor" strokeWidth="2" opacity="0.3" />
                            <path d="M32 20v16M32 44h.01" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
                        </svg>
                        <p>No messages found</p>
                        <span>Try a different search term</span>
                    </div>
                ) : (
                    <div className={styles.empty}>
                        <svg width="64" height="64" viewBox="0 0 64 64" fill="none">
                            <circle cx="28" cy="28" r="16" stroke="currentColor" strokeWidth="2" />
                            <path d="M42 42l8 8" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
                        </svg>
                        <p>Search messages</p>
                        <span>Type at least 2 characters to search</span>
                    </div>
                )}
            </div>
        </div>
    );
};

export default MessageSearchPanel;

import React, { useState, useEffect } from 'react';
import { supabase } from '../../lib/supabase';
import useDebounce from '../../hooks/useDebounce';
import { focusToast } from '../../utils/focusToast';
import styles from './NewMessageModal.module.css';

const NewMessageModal = ({ currentUserId, onClose, onSelectUser }) => {
    const [searchQuery, setSearchQuery] = useState('');
    const [users, setUsers] = useState([]);
    const [recentChats, setRecentChats] = useState([]);
    const [suggestedUsers, setSuggestedUsers] = useState([]);
    const [loading, setLoading] = useState(false);
    const [activeTab, setActiveTab] = useState('recent'); // recent, search, suggested

    const debouncedSearch = useDebounce(searchQuery, 300);

    useEffect(() => {
        fetchRecentChats();
        fetchSuggestedUsers();
    }, [currentUserId]);

    useEffect(() => {
        if (debouncedSearch) {
            searchUsers();
            setActiveTab('search');
        } else {
            setUsers([]);
            setActiveTab('recent');
        }
    }, [debouncedSearch]);

    const fetchRecentChats = async () => {
        try {
            // Get recent conversations
            const { data: messagesData, error: messagesError } = await supabase
                .from('messages')
                .select('sender_id, receiver_id, created_at')
                .or(`sender_id.eq.${currentUserId},receiver_id.eq.${currentUserId}`)
                .order('created_at', { ascending: false })
                .limit(50);

            if (messagesError) throw messagesError;

            // Extract unique user IDs
            const userIds = new Set();
            messagesData?.forEach(msg => {
                const otherUserId = msg.sender_id === currentUserId ? msg.receiver_id : msg.sender_id;
                if (otherUserId !== currentUserId) {
                    userIds.add(otherUserId);
                }
            });

            // Fetch user profiles
            if (userIds.size > 0) {
                const { data: profilesData, error: profilesError } = await supabase
                    .from('profiles')
                    .select('*')
                    .in('id', Array.from(userIds))
                    .limit(10);

                if (profilesError) throw profilesError;
                setRecentChats(profilesData || []);
            }
        } catch (error) {
            console.error('Error fetching recent chats:', error);
        }
    };

    const fetchSuggestedUsers = async () => {
        try {
            // Get users that current user follows
            const { data: followingData, error: followingError } = await supabase
                .from('follows')
                .select('following_id')
                .eq('follower_id', currentUserId);

            if (followingError) throw followingError;

            const followingIds = followingData?.map(f => f.following_id) || [];

            if (followingIds.length > 0) {
                const { data: profilesData, error: profilesError } = await supabase
                    .from('profiles')
                    .select('*')
                    .in('id', followingIds)
                    .limit(10);

                if (profilesError) throw profilesError;
                setSuggestedUsers(profilesData || []);
            }
        } catch (error) {
            console.error('Error fetching suggested users:', error);
        }
    };

    const searchUsers = async () => {
        setLoading(true);
        try {
            const { data, error } = await supabase
                .from('profiles')
                .select('*')
                .neq('id', currentUserId)
                .or(`username.ilike.%${debouncedSearch}%,full_name.ilike.%${debouncedSearch}%`)
                .limit(20);

            if (error) throw error;
            setUsers(data || []);
        } catch (error) {
            console.error('Error searching users:', error);
            focusToast.error('Failed to search users');
        } finally {
            setLoading(false);
        }
    };

    const handleSelectUser = (user) => {
        onSelectUser(user);
        onClose();
    };

    const renderUserItem = (user) => (
        <div
            key={user.id}
            className={styles.userItem}
            onClick={() => handleSelectUser(user)}
        >
            <div className={styles.avatar}>
                {user.avatar_url ? (
                    <img src={user.avatar_url} alt={user.username} />
                ) : (
                    <div className={styles.avatarPlaceholder}>
                        {user.username?.[0]?.toUpperCase()}
                    </div>
                )}
            </div>
            <div className={styles.userInfo}>
                <span className={styles.username}>{user.username}</span>
                {user.full_name && <span className={styles.fullName}>{user.full_name}</span>}
                {user.bio && <span className={styles.bio}>{user.bio}</span>}
            </div>
            <div className={styles.arrow}>
                <svg width="20" height="20" viewBox="0 0 24 24" fill="none">
                    <path d="M9 18l6-6-6-6" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
                </svg>
            </div>
        </div>
    );

    return (
        <div className={styles.overlay} onClick={onClose}>
            <div className={styles.modal} onClick={(e) => e.stopPropagation()}>
                <div className={styles.header}>
                    <div className={styles.headerTitle}>
                        <h2>New Message</h2>
                        <button
                            className={styles.createGroupButton}
                            onClick={() => focusToast.info('Group chats coming soon!')}
                        >
                            <svg width="16" height="16" viewBox="0 0 24 24" fill="none">
                                <path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
                                <circle cx="9" cy="7" r="4" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
                                <path d="M23 21v-2a4 4 0 0 0-3-3.87" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
                                <path d="M16 3.13a4 4 0 0 1 0 7.75" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
                            </svg>
                            Create Group
                        </button>
                    </div>
                    <button className={styles.closeButton} onClick={onClose}>
                        <svg width="20" height="20" viewBox="0 0 24 24" fill="none">
                            <path d="M18 6L6 18M6 6l12 12" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
                        </svg>
                    </button>
                </div>

                <div className={styles.searchSection}>
                    <div className={styles.searchBar}>
                        <svg width="20" height="20" viewBox="0 0 24 24" fill="none">
                            <circle cx="11" cy="11" r="8" stroke="currentColor" strokeWidth="2" />
                            <path d="M21 21l-4.35-4.35" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
                        </svg>
                        <input
                            type="text"
                            placeholder="Search users..."
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                            autoFocus
                        />
                    </div>
                </div>

                <div className={styles.content}>
                    {activeTab === 'search' && (
                        <div className={styles.section}>
                            <h3>Search Results</h3>
                            {loading ? (
                                <div className={styles.loading}>
                                    <div className={styles.spinner}></div>
                                    <p>Searching...</p>
                                </div>
                            ) : users.length > 0 ? (
                                <div className={styles.usersList}>
                                    {users.map(renderUserItem)}
                                </div>
                            ) : (
                                <div className={styles.empty}>
                                    <svg width="80" height="80" viewBox="0 0 24 24" fill="none">
                                        <circle cx="11" cy="11" r="8" stroke="currentColor" strokeWidth="2" />
                                        <path d="M21 21l-4.35-4.35" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
                                    </svg>
                                    <p>No users found</p>
                                </div>
                            )}
                        </div>
                    )}

                    {activeTab === 'recent' && (
                        <>
                            {recentChats.length > 0 && (
                                <div className={styles.section}>
                                    <h3>Recent Chats</h3>
                                    <div className={styles.usersList}>
                                        {recentChats.map(renderUserItem)}
                                    </div>
                                </div>
                            )}

                            {suggestedUsers.length > 0 && (
                                <div className={styles.section}>
                                    <h3>People You Follow</h3>
                                    <div className={styles.usersList}>
                                        {suggestedUsers.map(renderUserItem)}
                                    </div>
                                </div>
                            )}

                            {recentChats.length === 0 && suggestedUsers.length === 0 && (
                                <div className={styles.empty}>
                                    <svg width="80" height="80" viewBox="0 0 24 24" fill="none">
                                        <path d="M15 99.68V25A10 10 0 0 1 25 15h70a10 10 0 0 1 10 10v50a10 10 0 0 1-10 10H40.42a10 10 0 0 0-7.81 3.75l-11.67 14.57A3 3 0 0 1 15 99.68z" stroke="currentColor" strokeWidth="2" />
                                    </svg>
                                    <p>No recent conversations</p>
                                    <span>Search for users to start a new chat</span>
                                </div>
                            )}
                        </>
                    )}
                </div>
            </div>
        </div>
    );
};

export default NewMessageModal;

import React, { useState, useEffect } from 'react';
import { useLockedChats } from '../../hooks/useLockedChats';
import { useAuth } from '../../hooks/useAuth';
import Button from '../ui/Button';
import styles from './PINLockScreen.module.css';

const PINLockScreen = ({ chatId, onUnlock, onClose, mode = 'verify' }) => {
    const { user } = useAuth();
    const { masterPin, verifyPin, setPin } = useLockedChats(user?.id);
    const [pin, setPinValue] = useState('');
    const [confirmPin, setConfirmPin] = useState('');
    const [error, setError] = useState('');
    const [step, setStep] = useState(mode === 'setup' ? 'create' : 'verify');

    const handleKeyPress = (num) => {
        if (step === 'create') {
            if (pin.length < 4) {
                setPinValue(pin + num);
            }
        } else if (step === 'confirm') {
            if (confirmPin.length < 4) {
                setConfirmPin(confirmPin + num);
            }
        } else {
            if (pin.length < 4) {
                setPinValue(pin + num);
            }
        }
    };

    const handleDelete = () => {
        if (step === 'confirm') {
            setConfirmPin(confirmPin.slice(0, -1));
        } else {
            setPinValue(pin.slice(0, -1));
        }
    };

    useEffect(() => {
        if (step === 'create' && pin.length === 4) {
            setStep('confirm');
        } else if (step === 'confirm' && confirmPin.length === 4) {
            if (pin === confirmPin) {
                handleSetPin();
            } else {
                setError('PINs do not match');
                setTimeout(() => {
                    setPinValue('');
                    setConfirmPin('');
                    setStep('create');
                    setError('');
                }, 1500);
            }
        } else if (step === 'verify' && pin.length === 4) {
            handleVerify();
        }
    }, [pin, confirmPin, step]);

    const handleSetPin = async () => {
        const success = await setPin(pin);
        if (success) {
            onUnlock?.();
        }
    };

    const handleVerify = () => {
        const isValid = verifyPin(pin);
        if (isValid) {
            onUnlock?.();
        } else {
            setError('Incorrect PIN');
            setTimeout(() => {
                setPinValue('');
                setError('');
            }, 1000);
        }
    };

    const renderDots = () => {
        const currentPin = step === 'confirm' ? confirmPin : pin;
        return (
            <div className={styles.dots}>
                {[0, 1, 2, 3].map(i => (
                    <div
                        key={i}
                        className={`${styles.dot} ${i < currentPin.length ? styles.filled : ''} ${error ? styles.error : ''}`}
                    />
                ))}
            </div>
        );
    };

    return (
        <div className={styles.overlay}>
            <div className={styles.screen}>
                <div className={styles.header}>
                    <svg width="64" height="64" viewBox="0 0 64 64" fill="none">
                        <circle cx="32" cy="32" r="28" fill="rgba(139, 92, 246, 0.2)" />
                        <path d="M32 24v8M28 36h8M32 44h.01" stroke="#a78bfa" strokeWidth="3" strokeLinecap="round" />
                    </svg>
                    <h2>
                        {step === 'create' && 'Create PIN'}
                        {step === 'confirm' && 'Confirm PIN'}
                        {step === 'verify' && 'Enter PIN'}
                    </h2>
                    <p>
                        {step === 'create' && 'Enter a 4-digit PIN'}
                        {step === 'confirm' && 'Re-enter your PIN'}
                        {step === 'verify' && 'Enter your PIN to unlock'}
                    </p>
                </div>

                {renderDots()}

                {error && <div className={styles.errorMessage}>{error}</div>}

                <div className={styles.keypad}>
                    {[1, 2, 3, 4, 5, 6, 7, 8, 9].map(num => (
                        <button
                            key={num}
                            className={styles.key}
                            onClick={() => handleKeyPress(num.toString())}
                        >
                            {num}
                        </button>
                    ))}
                    <button className={styles.key} onClick={onClose}>
                        <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
                            <path d="M18 6L6 18M6 6l12 12" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
                        </svg>
                    </button>
                    <button className={styles.key} onClick={() => handleKeyPress('0')}>
                        0
                    </button>
                    <button className={styles.key} onClick={handleDelete}>
                        <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
                            <path d="M19 7l-1 12a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 7M10 11v6M14 11v6M4 7h16M9 7V4a1 1 0 0 1 1-1h4a1 1 0 0 1 1 1v3"
                                stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
                        </svg>
                    </button>
                </div>
            </div>
        </div>
    );
};

export default PINLockScreen;

import React, { useState, useEffect } from 'react';
import { supabase } from '../../lib/supabase';
import MessageBubble from './MessageBubble';
import { formatDateDivider } from '../../utils/formatDateDivider';
import styles from './PinnedMessagesPanel.module.css';

const PinnedMessagesPanel = ({ currentUserId, otherUserId, onClose, onJumpToMessage }) => {
    const [pinnedMessages, setPinnedMessages] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        fetchPinnedMessages();

        // Subscribe to changes
        const subscription = supabase
            .channel(`pinned-messages:${currentUserId}:${otherUserId}`)
            .on('postgres_changes', {
                event: '*',
                schema: 'public',
                table: 'messages',
                filter: `is_pinned=eq.true`
            }, () => {
                fetchPinnedMessages();
            })
            .subscribe();

        return () => {
            supabase.removeChannel(subscription);
        };
    }, [currentUserId, otherUserId]);

    const fetchPinnedMessages = async () => {
        if (!currentUserId || !otherUserId) return;

        setLoading(true);
        try {
            const { data, error } = await supabase
                .from('messages')
                .select('*, sender:profiles!sender_id(*)')
                .eq('is_pinned', true)
                .or(`and(sender_id.eq.${currentUserId},receiver_id.eq.${otherUserId}),and(sender_id.eq.${otherUserId},receiver_id.eq.${currentUserId})`)
                .order('created_at', { ascending: false });

            if (error) throw error;
            setPinnedMessages(data || []);
        } catch (error) {
            console.error('Error fetching pinned messages:', error);
        } finally {
            setLoading(false);
        }
    };

    const handleUnpin = async (messageId) => {
        try {
            const { error } = await supabase
                .from('messages')
                .update({ is_pinned: false })
                .eq('id', messageId);

            if (error) throw error;
            setPinnedMessages(prev => prev.filter(msg => msg.id !== messageId));
        } catch (error) {
            console.error('Error unpinning message:', error);
        }
    };

    const handleJumpToMessage = (message) => {
        onJumpToMessage(message);
        onClose();
    };

    const groupByDate = (messages) => {
        const groups = {};
        messages.forEach(message => {
            const date = formatDateDivider(message.created_at);
            if (!groups[date]) {
                groups[date] = [];
            }
            groups[date].push(message);
        });
        return groups;
    };

    const groupedMessages = groupByDate(pinnedMessages);

    return (
        <div className={styles.overlay} onClick={onClose}>
            <div className={styles.panel} onClick={(e) => e.stopPropagation()}>
                <div className={styles.header}>
                    <div className={styles.headerLeft}>
                        <svg width="24" height="24" viewBox="0 0 24 24" fill="currentColor">
                            <path d="M16 12V4H17V2H7V4H8V12L6 14V16H11.2V22H12.8V16H18V14L16 12Z" />
                        </svg>
                        <h2>Pinned Messages</h2>
                    </div>

                    <button className={styles.closeButton} onClick={onClose}>
                        <svg width="20" height="20" viewBox="0 0 24 24" fill="none">
                            <path d="M18 6L6 18M6 6l12 12" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
                        </svg>
                    </button>
                </div>

                <div className={styles.content}>
                    {loading ? (
                        <div className={styles.loading}>
                            <div className={styles.spinner}></div>
                            <p>Loading pinned messages...</p>
                        </div>
                    ) : pinnedMessages.length === 0 ? (
                        <div className={styles.empty}>
                            <svg width="80" height="80" viewBox="0 0 24 24" fill="none">
                                <path d="M16 12V4H17V2H7V4H8V12L6 14V16H11.2V22H12.8V16H18V14L16 12Z" stroke="currentColor" strokeWidth="2" />
                            </svg>
                            <h3>No pinned messages</h3>
                            <p>Pin important messages to find them easily later</p>
                        </div>
                    ) : (
                        <div className={styles.messagesList}>
                            {Object.entries(groupedMessages).map(([date, messages]) => (
                                <div key={date} className={styles.dateGroup}>
                                    <div className={styles.dateDivider}>{date}</div>
                                    {messages.map((message) => (
                                        <div key={message.id} className={styles.pinnedItem}>
                                            <div className={styles.messageWrapper}>
                                                <MessageBubble
                                                    message={message}
                                                    isOwn={message.sender_id === currentUserId}
                                                    showAvatar={true}
                                                    onReply={() => { }}
                                                    onReact={() => { }}
                                                    onDelete={() => { }}
                                                    onEdit={() => { }}
                                                />
                                            </div>

                                            <div className={styles.actions}>
                                                <button
                                                    className={styles.actionButton}
                                                    onClick={() => handleJumpToMessage(message)}
                                                    title="Jump to message"
                                                >
                                                    <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
                                                        <path d="M5 12h14M12 5l7 7-7 7" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
                                                    </svg>
                                                    Jump to message
                                                </button>

                                                <button
                                                    className={styles.unpinButton}
                                                    onClick={() => handleUnpin(message.id)}
                                                    title="Unpin message"
                                                >
                                                    <svg width="18" height="18" viewBox="0 0 24 24" fill="currentColor">
                                                        <path d="M16 12V4H17V2H7V4H8V12L6 14V16H11.2V22H12.8V16H18V14L16 12Z" />
                                                    </svg>
                                                    Unpin
                                                </button>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            ))}
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

export default PinnedMessagesPanel;

import React, { useState, useEffect } from 'react';
import { useReadReceiptSettings } from '../../hooks/useReadReceiptSettings';
import { useAuth } from '../../hooks/useAuth';
import Button from '../ui/Button';
import styles from './ReadReceiptSettings.module.css';

const ReadReceiptSettings = ({ conversationId, onClose }) => {
    const { user } = useAuth();
    const {
        globalSetting,
        conversationSettings,
        loading,
        toggleGlobalReadReceipts,
        setConversationReadReceipt,
        areReadReceiptsEnabled
    } = useReadReceiptSettings(user?.id);

    const [localGlobal, setLocalGlobal] = useState(globalSetting);
    const [localConversation, setLocalConversation] = useState(
        conversationId ? areReadReceiptsEnabled(conversationId) : null
    );

    useEffect(() => {
        setLocalGlobal(globalSetting);
        if (conversationId) {
            setLocalConversation(areReadReceiptsEnabled(conversationId));
        }
    }, [globalSetting, conversationId, areReadReceiptsEnabled]);

    const handleGlobalToggle = async () => {
        await toggleGlobalReadReceipts();
    };

    const handleConversationToggle = async () => {
        if (conversationId) {
            await setConversationReadReceipt(conversationId, !localConversation);
        }
    };

    return (
        <div className={styles.overlay} onClick={onClose}>
            <div className={styles.modal} onClick={(e) => e.stopPropagation()}>
                <div className={styles.header}>
                    <svg width="48" height="48" viewBox="0 0 48 48" fill="none">
                        <circle cx="24" cy="24" r="20" fill="rgba(139, 92, 246, 0.2)" />
                        <path d="M16 24l4 4 8-8" stroke="#a78bfa" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
                        <path d="M28 24l4 4" stroke="#a78bfa" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
                    </svg>
                    <h2>Read Receipts</h2>
                    <p>Control who can see when you've read their messages</p>
                </div>

                <div className={styles.content}>
                    {/* Global Setting */}
                    <div className={styles.setting}>
                        <div className={styles.settingInfo}>
                            <div className={styles.settingTitle}>Read Receipts</div>
                            <div className={styles.settingDescription}>
                                Let others know when you've read their messages
                            </div>
                        </div>
                        <label className={styles.switch}>
                            <input
                                type="checkbox"
                                checked={localGlobal}
                                onChange={handleGlobalToggle}
                                disabled={loading}
                            />
                            <span className={styles.slider}></span>
                        </label>
                    </div>

                    {/* Conversation-Specific Setting */}
                    {conversationId && (
                        <>
                            <div className={styles.divider}></div>
                            <div className={styles.setting}>
                                <div className={styles.settingInfo}>
                                    <div className={styles.settingTitle}>This Conversation</div>
                                    <div className={styles.settingDescription}>
                                        Override global setting for this chat
                                    </div>
                                </div>
                                <label className={styles.switch}>
                                    <input
                                        type="checkbox"
                                        checked={localConversation}
                                        onChange={handleConversationToggle}
                                        disabled={loading}
                                    />
                                    <span className={styles.slider}></span>
                                </label>
                            </div>
                        </>
                    )}

                    <div className={styles.note}>
                        <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
                            <circle cx="8" cy="8" r="7" stroke="currentColor" strokeWidth="1.5" />
                            <path d="M8 4v4M8 11h.01" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
                        </svg>
                        <span>
                            When disabled, others won't see read receipts from you, but you also won't see theirs
                        </span>
                    </div>
                </div>

                <div className={styles.footer}>
                    <Button variant="primary" onClick={onClose} fullWidth>
                        Done
                    </Button>
                </div>
            </div>
        </div>
    );
};

