import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { X, UserPlus, Check } from 'lucide-react';
import { formatDistanceToNow } from 'date-fns';
import { supabase } from '../../lib/supabase';
import { useAuth } from '../../hooks/useAuth';
import UserAvatar from '../ui/Avatar';
import Icon from '../ui/Icon';
import styles from './NotificationCard.module.css';

const TYPE_ICONS = {
    // Interactions
    like: 'Heart', comment: 'MessageCircle', follow: 'UserPlus', mention: 'AtSign',
    message: 'MessageSquare', share: 'Send', tag: 'Tag', boltz_like: 'Zap',
    boltz_comment: 'MessageCircle', reply: 'CornerDownRight',

    // Security
    login_new_device: 'Smartphone', suspicious_login: 'AlertTriangle',
    password_change: 'Key', account_locked: 'Lock', security_alert: 'ShieldAlert',
    session_revoked: 'LogOut', two_factor_enabled: 'ShieldCheck',

    // Verification
    badge_granted: 'Award', trust_level_up: 'TrendingUp', trust_level_down: 'TrendingDown',
    vouched: 'ThumbsUp', guardian_action: 'UserCheck', teen_alert: 'AlertCircle',
    focusid_upgrade: 'Verified', verification_approved: 'CheckCircle',

    system: 'Bell',
};

const TYPE_COLORS = {
    // Interactions
    like: '#ff3040', comment: '#7C3AED', follow: '#2563EB', mention: '#059669',
    message: '#D97706', share: '#7C3AED', tag: '#9333EA',

    // Security
    login_new_device: '#f59e0b', suspicious_login: '#ef4444', password_change: '#3b82f6',
    account_locked: '#dc2626', security_alert: '#ef4444',

    // Verification
    badge_granted: '#8B5CF6', trust_level_up: '#10b981', trust_level_down: '#ef4444',
    vouched: '#3b82f6', focusid_upgrade: '#8B5CF6', verification_approved: '#10b981',

    system: '#666',
};

const getNotificationText = (n) => {
    const name = n.actor?.full_name || n.actor?.username || 'Someone';
    switch (n.type) {
        case 'like': return <><strong>{name}</strong> liked your post</>;
        case 'comment': return <><strong>{name}</strong> commented: <span className={styles.preview}>"{(n.body || '').slice(0, 60)}"</span></>;
        case 'follow': return <><strong>{name}</strong> started following you</>;
        case 'mention': return <><strong>{name}</strong> mentioned you in a comment</>;
        case 'message': return <><strong>{name}</strong> sent you a message</>;
        case 'share': return <><strong>{name}</strong> shared your post</>;
        case 'tag': return <><strong>{name}</strong> tagged you in a post</>;
        case 'boltz_like': return <><strong>{name}</strong> liked your boltz</>;

        // Security
        case 'login_new_device': return <>New login detected from an unrecognized device</>;
        case 'suspicious_login': return <strong style={{color: '#ef4444'}}>Suspicious login attempt blocked</strong>;
        case 'password_change': return <>Your password was recently changed</>;
        case 'security_alert': return <strong>{n.body || 'Security Alert!'}</strong>;

        // Verification
        case 'badge_granted': return <>Congratulations! You've been granted the verified badge</>;
        case 'trust_level_up': return <>Your Trust Tier has been upgraded</>;
        case 'verification_approved': return <>Your Focus ID verification was approved</>;

        default: return n.body || 'New notification';
    }
};

const NotificationCard = ({ notification: n, onMarkAsRead, onDelete }) => {
    const { user } = useAuth();
    const navigate = useNavigate();
    const [followState, setFollowState] = useState('idle'); // idle | loading | followed

    const isUnread = !(n.is_read ?? n.read);
    const iconName = TYPE_ICONS[n.type] || 'Bell';
    const iconColor = TYPE_COLORS[n.type] || '#666';

    const handleClick = () => {
        if (isUnread) onMarkAsRead(n.id);

        // INTERACTION DEEP LINKS
        if (['like', 'comment', 'mention', 'tag', 'share', 'reply', 'boltz_like', 'boltz_comment'].includes(n.type) && n.content_id) {
            const openComments = ['comment', 'reply', 'boltz_comment'].includes(n.type);
            navigate(n.content_type === 'boltz' ? `/boltz/${n.content_id}` : `/p/${n.content_id}`, {
                state: openComments ? { openComments: true, source: 'notification' } : undefined
            });
        } else if (n.type === 'follow' && n.actor?.username) {
            navigate(`/profile/${n.actor.username}`);
        } else if (n.type === 'message') {
            navigate(n.conversation_id ? `/messages/${n.conversation_id}` : '/messages');
        } 

        // SECURITY DEEP LINKS
        else if (['login_new_device', 'session_revoked', 'suspicious_login', 'password_change', 'account_locked', 'security_alert'].includes(n.type)) {
            navigate('/settings', { state: { section: 'security' } });
        }

        // VERIFICATION DEEP LINKS
        else if (['badge_granted', 'badge_revoked', 'trust_level_up', 'trust_level_down', 'vouched', 'focusid_upgrade', 'verification_approved', 'verification_rejected'].includes(n.type)) {
            navigate('/verification-center');
        }
    };

    const handleFollow = async (e) => {
        e.stopPropagation();
        if (!user || followState !== 'idle') return;
        setFollowState('loading');
        try {
            await supabase.from('follows').insert({
                follower_id: user.id,
                following_id: n.actor?.id,
            });
            setFollowState('followed');
        } catch {
            setFollowState('idle');
        }
    };

    return (
        <div
            className={`${styles.card} ${isUnread ? styles.unread : ''}`}
            onClick={handleClick}
            role="button"
            tabIndex={0}
            onKeyDown={(e) => { if (e.key === 'Enter') handleClick(); }}
        >
            {/* Unread accent */}
            {isUnread && <div className={styles.unreadAccent} />}

            {/* Avatar + type badge */}
            <div className={styles.avatarArea}>
                <UserAvatar
                    src={n.actor?.avatar_url}
                    username={n.actor?.username}
                    fullName={n.actor?.full_name}
                    size="md"
                    onClick={(e) => {
                        e.stopPropagation();
                        if (n.actor?.username) navigate(`/profile/${n.actor.username}`);
                    }}
                />
                <div
                    className={styles.typeBadge}
                    style={{ background: iconColor }}
                    aria-hidden="true"
                >
                    <Icon name={iconName} size={12} />
                </div>
            </div>

            {/* Content */}
            <div className={styles.content}>
                <p className={styles.text}>{getNotificationText(n)}</p>
                <span className={styles.time}>
                    {formatDistanceToNow(new Date(n.created_at), { addSuffix: true }).replace('about ', '')}
                </span>

                {/* Follow-back button */}
                {n.type === 'follow' && followState !== 'followed' && (
                    <button
                        className={styles.followBtn}
                        onClick={handleFollow}
                        disabled={followState === 'loading'}
                    >
                        {followState === 'loading' ? 'ΓÇª' : 'Follow back'}
                    </button>
                )}
                {n.type === 'follow' && followState === 'followed' && (
                    <span className={styles.followedBadge}>
                        <Check size={12} /> Following
                    </span>
                )}
            </div>

            {/* Post thumbnail */}
            {n.metadata?.preview_image && (
                <div className={styles.thumbnail}>
                    <img src={n.metadata.preview_image} alt="" />
                </div>
            )}

            {/* Delete */}
            <button
                className={styles.deleteBtn}
                onClick={(e) => { e.stopPropagation(); onDelete(n.id); }}
                aria-label="Dismiss"
            >
                <X size={14} />
            </button>
        </div>
    );
};

export default NotificationCard;

import React, { useEffect, useMemo, useRef, useState } from 'react';
import { AnimatePresence, motion } from 'framer-motion';
import { Upload, Camera, ShieldCheck, RefreshCcw, QrCode, Share2, ArrowLeft } from 'lucide-react';
import { QRCodeSVG } from 'qrcode.react';
import Button from '../shared/Button';
import FocuslyAvatar from '../focusly-ai/FocuslyAvatar';
import { triggerHaptic } from '../../utils/haptics';
import {
    generateLivenessActions,
    runFaceSimilarityCheck,
    persistTrustShieldState,
    createGuardianHandshake,
} from '../../utils/trustShieldEngine';
import styles from './StepTrustShield.module.css';
import { useAuth } from '../../hooks/useAuth';
import useOCRScanner from '../../hooks/useOCRScanner';
import { v4 as uuidv4 } from 'uuid';
import { supabase } from '../../lib/supabase';

const StepTrustShield = ({ formData, updateFormData, onNext, onBack }) => {
    const { user } = useAuth();
    const { scanID, progress: ocrProgress, statusMessage: ocrStatus } = useOCRScanner();
    const [stage, setStage] = useState('ocr');
    const [ocrHint, setOcrHint] = useState('Position ID within frame');
    const [idFile, setIdFile] = useState(null);
    const [ocrResult, setOcrResult] = useState(null);
    const [livenessActions, setLivenessActions] = useState([]);
    const [currentActionIndex, setCurrentActionIndex] = useState(0);
    const [matchResult, setMatchResult] = useState(null);
    const [videoReady, setVideoReady] = useState(false);
    const [cameraDenied, setCameraDenied] = useState(false);
    const [error, setError] = useState('');
    const [handoffToken, setHandoffToken] = useState(null);
    const streamRef = useRef(null);
    const videoRef = useRef(null);
    const channelRef = useRef(null);

    const progress = useMemo(() => {
        if (stage === 'ocr') return 25;
        if (stage === 'liveness') return 55 + currentActionIndex * 15;
        if (stage === 'processing') return 85;
        if (stage === 'result') return 100;
        if (stage === 'guardian') return 100;
        return 0;
    }, [stage, currentActionIndex]);

    const isTeen = useMemo(() => {
        const dob = ocrResult?.dob || formData?.ageInfo?.dateOfBirth;
        if (!dob) return false;
        const date = new Date(dob);
        if (Number.isNaN(date.getTime())) return false;
        const now = new Date();
        let age = now.getFullYear() - date.getFullYear();
        const passed = now.getMonth() > date.getMonth() || (now.getMonth() === date.getMonth() && now.getDate() >= date.getDate());
        if (!passed) age -= 1;
        return age >= 13 && age <= 17;
    }, [ocrResult?.dob, formData?.ageInfo?.dateOfBirth]);

    const handshakeLink = useMemo(() => formData?.guardianHandshakeLink || '', [formData?.guardianHandshakeLink]);

    // ΓöÇΓöÇ The Founder's Backdoor ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const keysPressed = useRef(new Set());
    useEffect(() => {
        const handleKeyDown = async (e) => {
            if (process.env.NODE_ENV !== 'development') return;
            keysPressed.current.add(e.key.toLowerCase());
            
            if (e.ctrlKey && e.shiftKey && keysPressed.current.has('v')) {
                try {
                    if (user?.id) {
                        await supabase.from('profiles').update({ verification_status: 'VERIFIED', trust_shield_status: 'VERIFIED' }).eq('id', user.id);
                        localStorage.setItem('bypass_used', 'true');
                        window.location.href = '/home';
                    }
                } catch (err) {}
            }
        };
        
        const handleKeyUp = (e) => {
            keysPressed.current.delete(e.key.toLowerCase());
        };

        window.addEventListener('keydown', handleKeyDown);
        window.addEventListener('keyup', handleKeyUp);
        return () => {
            window.removeEventListener('keydown', handleKeyDown);
            window.removeEventListener('keyup', handleKeyUp);
        };
    }, [user]);

    // ΓöÇΓöÇ Typewriter Effect ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const [typewriterText, setTypewriterText] = useState('');
    const fullWaitingText = "Awaiting completion from your mobile browser...";

    useEffect(() => {
        if (stage === 'waiting_mobile') {
          setTypewriterText('');
          let i = 0;
          const interval = setInterval(() => {
            setTypewriterText(fullWaitingText.slice(0, i + 1));
            i++;
            if (i >= fullWaitingText.length) {
              clearInterval(interval);
            }
          }, 50);
          return () => clearInterval(interval);
        }
    }, [stage, fullWaitingText]);

    useEffect(() => {
        const hints = [
            'Position ID within frame',
            'Avoid glare on the card',
            'Keep Name and DOB visible',
        ];
        let index = 0;
        const timer = setInterval(() => {
            index = (index + 1) % hints.length;
            setOcrHint(hints[index]);
        }, 1800);
        return () => clearInterval(timer);
    }, []);

    useEffect(() => {
        return () => {
            if (streamRef.current) {
                streamRef.current.getTracks().forEach((track) => track.stop());
            }
            if (channelRef.current) {
                supabase.removeChannel(channelRef.current);
            }
        };
    }, []);

    const stopCamera = () => {
        if (streamRef.current) {
            streamRef.current.getTracks().forEach((track) => track.stop());
            streamRef.current = null;
        }
        if (videoRef.current) {
            videoRef.current.srcObject = null;
        }
        setVideoReady(false);
    };

    const startCamera = async () => {
        setError('');
        try {
            const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'user' }, audio: false });
            streamRef.current = stream;
            if (videoRef.current) {
                videoRef.current.srcObject = stream;
            }
            setVideoReady(true);
            setCameraDenied(false);
        } catch (err) {
            try {
                const fallbackStream = await navigator.mediaDevices.getUserMedia({ video: true, audio: false });
                streamRef.current = fallbackStream;
                if (videoRef.current) {
                    videoRef.current.srcObject = fallbackStream;
                }
                setVideoReady(true);
                setCameraDenied(false);
            } catch (fallbackErr) {
                setCameraDenied(true);
                setError('Camera access is required for liveness challenge. Consider using your phone.');
            }
        }
    };

    const initiatePhoneHandoff = async () => {
        if (!user?.id) return;
        setStage('waiting_mobile');
        stopCamera();

        try {
            const channel = supabase.channel(`handoff_${user.id}`)
                .on('postgres_changes', {
                    event: 'UPDATE',
                    schema: 'public',
                    table: 'profiles',
                    filter: `id=eq.${user.id}`
                }, (payload) => {
                    if (payload.new.verification_status === 'VERIFIED') {
                        updateFormData('trustShieldStatus', 'VERIFIED');
                        updateFormData('trustShieldInitialized', true);
                        setMatchResult({ passed: true, score: 0.99 });
                        setStage('result');
                        setTimeout(() => {
                            window.location.href = '/home';
                        }, 1000);
                    }
                })
                .subscribe();
                
            channelRef.current = channel;
        } catch (err) {
            setError('Failed to initiate phone handoff.');
        }
    };

    const handleIdUpload = async (event) => {
        if (!user?.id) {
            setError('Session expired. Please log in again.');
            return;
        }
        const file = event.target.files?.[0];
        if (!file) return;
        setIdFile(file);
        setError('');
        const result = await scanID(file);
        if (!result.ok) {
            setError(result.reason);
            return;
        }
        setOcrResult(result);
        updateFormData('trustShieldOCR', result);
        try {
            await persistTrustShieldState({
                userId: user?.id,
                verificationStatus: 'PENDING',
                ocrResult: result,
                attemptResult: 'PENDING',
                stage: 'ocr',
            });
        } catch (persistError) {
            setError(persistError.message || 'Failed to persist OCR verification state.');
        }
    };

    const beginLiveness = async () => {
        if (!ocrResult?.name || !ocrResult?.dob) {
            setError('Name and DOB are required before liveness check.');
            return;
        }
        const actions = generateLivenessActions();
        setLivenessActions(actions);
        setCurrentActionIndex(0);
        setStage('liveness');
        await startCamera();
    };

    const completeAction = () => {
        if (!user?.id) {
            setError('Session expired. Please log in again.');
            return;
        }
        if (currentActionIndex < livenessActions.length - 1) {
            setCurrentActionIndex((prev) => prev + 1);
            return;
        }
        setStage('processing');
        stopCamera();
        window.setTimeout(async () => {
            const result = await runFaceSimilarityCheck({ idImageFile: idFile, selfieCaptured: true });
            setMatchResult(result);
            if (result.passed) {
                triggerHaptic(24);
                updateFormData('trustShieldStatus', 'VERIFIED');
                updateFormData('trustShieldInitialized', true);
                updateFormData('trustShieldFaceScore', result.score);
                try {
                    if (isTeen) {
                        const handshakeToken = await createGuardianHandshake({
                            teenUserId: user?.id,
                            metadata: { ocr: ocrResult, face_score: result.score },
                        });
                        const generatedLink = `https://focus-macha.loca.lt/verification/parent-consent?token=${handshakeToken}`;
                        updateFormData('guardianHandshakeLink', generatedLink);
                        await persistTrustShieldState({
                            userId: user?.id,
                            verificationStatus: 'PENDING',
                            ocrResult,
                            faceScore: result.score,
                            attemptResult: 'SUCCESS',
                            stage: 'guardian_pending',
                            handshakeToken,
                        });
                        setStage('guardian');
                    } else {
                        await persistTrustShieldState({
                            userId: user?.id,
                            verificationStatus: 'VERIFIED',
                            ocrResult,
                            faceScore: result.score,
                            attemptResult: 'SUCCESS',
                            stage: 'face_match',
                        });
                        setStage('result');
                    }
                } catch (persistError) {
                    setError(persistError.message || 'Could not persist verification result.');
                    setStage('result');
                } finally {
                    setIdFile(null);
                }
                return;
            }
            try {
                await persistTrustShieldState({
                    userId: user?.id,
                    verificationStatus: 'PENDING',
                    ocrResult,
                    faceScore: result.score,
                    attemptResult: 'FAILURE',
                    stage: 'face_match',
                    reason: result.reason || 'Face similarity threshold not met.',
                });
            } catch (_) {}
            setIdFile(null);
            setStage('result');
        }, 1800);
    };

    const finishFlow = () => {
        if (!matchResult?.passed && !formData?.trustShieldInitialized) {
            setError('Complete verification before continuing.');
            return;
        }
        if (isTeen) {
            updateFormData('guardianHandshakeLink', handshakeLink || formData?.guardianHandshakeLink || '');
        }
        onNext();
    };

    const openWhatsApp = () => {
        const text = encodeURIComponent(
            `Focus Trust Shield guardian approval link:\n${handshakeLink}\n\nPlease verify to unlock teen safety mode.`
        );
        window.open(`https://wa.me/?text=${text}`, '_blank', 'noopener,noreferrer');
    };

    return (
        <div className={styles.container}>
            <div className={styles.header}>
                <h2 className={styles.title}>Focus Trust Shield</h2>
                <p className={styles.subtitle}>
                    Real people make a real nation. Let&apos;s verify your soul, Macha!
                </p>
            </div>

            <div className={styles.focuslyGuide}>
                <FocuslyAvatar
                    emotion={
                        stage === 'processing'
                            ? 'thinking'
                            : stage === 'result'
                                ? matchResult?.passed ? 'happy' : 'confused'
                                : 'wave'
                    }
                    size="small"
                />
                <p>
                    {stage === 'ocr' && 'Place your ID inside the frame. I will read your Name and DOB in seconds.'}
                    {stage === 'liveness' && `Do this now: ${livenessActions[currentActionIndex] || 'Hold steady'}`}
                    {stage === 'processing' && 'Comparing your live presence with your ID photo...'}
                    {stage === 'waiting_mobile' && typewriterText}
                    {stage === 'result' && (matchResult?.passed
                        ? 'Identity verified. You are now trust-locked and bulletproof.'
                        : 'No stress. Retry with better lighting and face centered in the ring.')}
                    {stage === 'guardian' && 'Teen shield active. Share this guardian handshake to unlock full Focus access.'}
                </p>
            </div>

            <div className={styles.progressTrack}>
                <motion.div className={styles.progressFill} animate={{ width: `${progress}%` }} />
            </div>

            {error && <p className={styles.error}>{error}</p>}

            <div className={styles.stageCard}>
                <AnimatePresence mode="wait">
                    {stage === 'ocr' && (
                        <motion.div
                            key="ocr"
                            initial={{ opacity: 0, y: 12 }}
                            animate={{ opacity: 1, y: 0 }}
                            exit={{ opacity: 0, y: -12 }}
                            className={styles.stage}
                        >
                            <div className={styles.scannerOverlay}>
                                <div className={styles.documentFrame}>
                                    <span className={styles.cornerTopLeft} />
                                    <span className={styles.cornerTopRight} />
                                    <span className={styles.cornerBottomLeft} />
                                    <span className={styles.cornerBottomRight} />
                                    <p className={styles.overlayHint}>{ocrHint}</p>
                                </div>
                            </div>
                            <label className={styles.uploadBtn}>
                                <Upload size={16} />
                                Upload Government or Student ID
                                <input type="file" accept="image/*" onChange={handleIdUpload} hidden />
                            </label>
                            {ocrStatus && (
                                <p style={{ fontSize: '0.85rem', color: '#a78bfa', marginTop: '0.5rem', textAlign: 'center' }}>
                                    {ocrStatus} {ocrProgress > 0 && `${ocrProgress}%`}
                                </p>
                            )}
                            {ocrResult && (
                                <div className={styles.extractedCard}>
                                    <p><strong>Name:</strong> {ocrResult.name || 'Not found'}</p>
                                    <p><strong>DOB:</strong> {ocrResult.dob || 'Not found'}</p>
                                </div>
                            )}
                            <Button 
                                variant="primary" 
                                onClick={beginLiveness} 
                                disabled={!ocrResult || !ocrResult.dob || !ocrResult.name || /screenshot/i.test(ocrResult.name)}
                            >
                                Continue to Liveness
                            </Button>
                        </motion.div>
                    )}

                    {stage === 'liveness' && (
                        <motion.div key="liveness" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className={styles.stage}>
                            <div className={styles.cameraRingWrap}>
                                <svg className={styles.progressRing} viewBox="0 0 120 120">
                                    <circle cx="60" cy="60" r="54" className={styles.ringBase} />
                                    <circle
                                        cx="60"
                                        cy="60"
                                        r="54"
                                        className={styles.ringProgress}
                                        style={{ strokeDashoffset: `${339 - ((currentActionIndex + 1) / Math.max(livenessActions.length, 1)) * 339}` }}
                                    />
                                </svg>
                                <video ref={videoRef} autoPlay muted playsInline className={styles.cameraVideo} />
                            </div>
                            <p className={styles.actionText}>{livenessActions[currentActionIndex]}</p>
                            {cameraDenied && <p className={styles.warning}>Camera permission blocked. Enable camera and retry.</p>}
                            <div className={styles.inlineButtons} style={{ flexDirection: 'column', gap: '8px' }}>
                                <Button variant="primary" onClick={completeAction} disabled={!videoReady}>
                                    <Camera size={16} /> I completed this action
                                </Button>
                                <Button variant="ghost" onClick={initiatePhoneHandoff}>
                                    <QrCode size={16} /> No Camera? Use Phone
                                </Button>
                            </div>
                        </motion.div>
                    )}

                    {stage === 'processing' && (
                        <motion.div key="processing" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className={styles.stage}>
                            <div className={styles.processingGlass}>
                                <div className={styles.loaderOrb} />
                                <p>Secure Face Similarity Engine running...</p>
                            </div>
                        </motion.div>
                    )}

                    {stage === 'waiting_mobile' && (
                        <motion.div key="waiting_mobile" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className={styles.stage}>
                            <h3>Focus Bridge Active</h3>
                            <p className={styles.guardianCopy}>
                                Scan this code with your mobile (Chrome/Safari) to use your phone's camera. Leave this tab open.
                            </p>
                            <div style={{
                                width: '100%',
                                maxWidth: '280px',
                                margin: '20px auto',
                                aspectRatio: '1/1',
                                padding: '24px',
                                background: '#fff',
                                display: 'flex',
                                justifyContent: 'center',
                                alignItems: 'center',
                                borderRadius: '16px',
                                boxShadow: '0 10px 40px rgba(168,85,247,0.3)',
                                boxSizing: 'border-box'
                            }}>
                                <QRCodeSVG 
                                    value={`${window.location.origin}/verify-mobile?uid=${user?.id}`} 
                                    style={{ width: '100%', height: '100%' }}
                                    level={"H"}
                                    bgColor="#ffffff" 
                                    fgColor="#000000" 
                                />
                            </div>
                            <div className={styles.processingGlass} style={{ marginTop: '20px', background: 'transparent' }}>
                                <div className={styles.loaderOrb} style={{ width: '20px', height: '20px' }} />
                                <p style={{ fontSize: '0.9rem', color: '#d8b4fe' }}>{typewriterText}</p>
                            </div>
                        </motion.div>
                    )}

                    {stage === 'result' && (
                        <motion.div key="result" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className={styles.stage}>
                            {matchResult?.passed ? (
                                <div className={styles.successBlock}>
                                    <ShieldCheck size={26} />
                                    <h3>Identity Verified</h3>
                                    <p>Trust Shield Badge unlocked. Similarity score: {(matchResult.score * 100).toFixed(0)}%</p>
                                    <Button variant="primary" onClick={finishFlow}>Continue</Button>
                                </div>
                            ) : (
                                <div className={styles.failureBlock}>
                                    <h3>Verification did not pass</h3>
                                    <p>{matchResult?.reason || 'Face comparison was inconclusive.'}</p>
                                    <Button variant="primary" onClick={() => setStage('liveness')}>
                                        <RefreshCcw size={16} /> Retry
                                    </Button>
                                </div>
                            )}
                        </motion.div>
                    )}

                    {stage === 'guardian' && (
                        <motion.div key="guardian" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className={styles.stage}>
                            <h3>Guardian Handshake</h3>
                            <p className={styles.guardianCopy}>
                                Because you are between 13-17, we need one verified adult handshake for your safety.
                            </p>
                            <div style={{
                                width: '100%',
                                maxWidth: '200px',
                                margin: '20px auto',
                                aspectRatio: '1/1',
                                padding: '16px',
                                background: '#fff',
                                display: 'flex',
                                justifyContent: 'center',
                                alignItems: 'center',
                                borderRadius: '12px',
                                boxShadow: '0 5px 20px rgba(168,85,247,0.2)',
                                boxSizing: 'border-box'
                            }}>
                                <QRCodeSVG 
                                    value={handshakeLink} 
                                    style={{ width: '100%', height: '100%' }}
                                    level={"M"}
                                    bgColor="#ffffff" 
                                    fgColor="#000000" 
                                />
                            </div>
                            <p className={styles.linkText}>{handshakeLink}</p>
                            <div className={styles.inlineButtons}>
                                <Button variant="ghost" onClick={openWhatsApp}>
                                    <Share2 size={16} /> Share on WhatsApp
                                </Button>
                                <Button variant="primary" onClick={finishFlow}>Continue</Button>
                            </div>
                        </motion.div>
                    )}
                </AnimatePresence>
            </div>

            <div className={styles.progressInfo}>
                <Button variant="ghost" onClick={onBack}>
                    <ArrowLeft size={14} /> Back
                </Button>
                <span>Step 4 of 5</span>
            </div>
        </div>
    );
};

export default StepTrustShield;

/**
 * MediaCarousel Component
 * Swipeable image/video carousel with pinch-to-zoom
 */

import React, { useState, useRef, useEffect } from 'react';
import styles from './MediaCarousel.module.css';

const MediaCarousel = ({ media, onImageClick }) => {
    const [currentIndex, setCurrentIndex] = useState(0);
    const [touchStart, setTouchStart] = useState(0);
    const [touchEnd, setTouchEnd] = useState(0);
    const carouselRef = useRef(null);

    const minSwipeDistance = 50;

    const goToNext = () => {
        setCurrentIndex((prev) => (prev + 1) % media.length);
    };

    const goToPrevious = () => {
        setCurrentIndex((prev) => (prev - 1 + media.length) % media.length);
    };

    const goToSlide = (index) => {
        setCurrentIndex(index);
    };

    // Touch handlers for swipe
    const onTouchStart = (e) => {
        setTouchEnd(0);
        setTouchStart(e.targetTouches[0].clientX);
    };

    const onTouchMove = (e) => {
        setTouchEnd(e.targetTouches[0].clientX);
    };

    const onTouchEnd = () => {
        if (!touchStart || !touchEnd) return;

        const distance = touchStart - touchEnd;
        const isLeftSwipe = distance > minSwipeDistance;
        const isRightSwipe = distance < -minSwipeDistance;

        if (isLeftSwipe) {
            goToNext();
        } else if (isRightSwipe) {
            goToPrevious();
        }
    };

    // Keyboard navigation
    useEffect(() => {
        const handleKeyDown = (e) => {
            if (e.key === 'ArrowLeft') goToPrevious();
            if (e.key === 'ArrowRight') goToNext();
        };

        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, []);

    if (!media || media.length === 0) return null;
    if (media.length === 1) {
        return (
            <div className={styles.singleMedia} onClick={onImageClick}>
                <img src={media[0]} alt="Post" className={styles.image} />
            </div>
        );
    }

    return (
        <div
            className={styles.carousel}
            ref={carouselRef}
            onTouchStart={onTouchStart}
            onTouchMove={onTouchMove}
            onTouchEnd={onTouchEnd}
        >
            <div
                className={styles.carouselTrack}
                style={{ transform: `translateX(-${currentIndex * 100}%)` }}
            >
                {media.map((src, index) => (
                    <div key={index} className={styles.slide} onClick={onImageClick}>
                        <img src={src} alt={`Slide ${index + 1}`} className={styles.image} />
                    </div>
                ))}
            </div>

            {/* Navigation arrows */}
            {currentIndex > 0 && (
                <button
                    className={`${styles.navBtn} ${styles.prevBtn}`}
                    onClick={(e) => {
                        e.stopPropagation();
                        goToPrevious();
                    }}
                    aria-label="Previous"
                >
                    ΓÇ╣
                </button>
            )}
            {currentIndex < media.length - 1 && (
                <button
                    className={`${styles.navBtn} ${styles.nextBtn}`}
                    onClick={(e) => {
                        e.stopPropagation();
                        goToNext();
                    }}
                    aria-label="Next"
                >
                    ΓÇ║
                </button>
            )}

            {/* Dot indicators */}
            <div className={styles.indicators}>
                {media.map((_, index) => (
                    <button
                        key={index}
                        className={`${styles.dot} ${index === currentIndex ? styles.activeDot : ''}`}
                        onClick={(e) => {
                            e.stopPropagation();
                            goToSlide(index);
                        }}
                        aria-label={`Go to slide ${index + 1}`}
                    />
                ))}
            </div>
        </div>
    );
};

export default MediaCarousel;

/**
 * DistressResponse.js
 * ===================
 * Emergency support modal shown when distress is detected
 * Features: Focusly in guardian_mode, crisis helplines, breathing exercise
 *
 * H2 Innovative ΓÇö Pillar 5: Safety Net
 */

import React, { useState, useEffect } from 'react';
import FocuslyLion from '../focusly-ai/FocuslyLion';
import { CRISIS_HELPLINES } from '../../hooks/useDistressDetection';
import styles from './DistressResponse.module.css';

const BREATHING_PHASES = [
  { label: 'Breathe In', duration: 4000, color: '#7c6bfe' },
  { label: 'Hold', duration: 7000, color: '#38bdf8' },
  { label: 'Breathe Out', duration: 8000, color: '#a78bfa' },
];

const DistressResponse = ({ isOpen, onClose, tier = 'high' }) => {
  const [visible, setVisible] = useState(false);
  const [breathingPhase, setBreathingPhase] = useState(0);
  const [showBreathing, setShowBreathing] = useState(false);
  const [breathCycle, setBreathCycle] = useState(false);

  useEffect(() => {
    if (isOpen) setTimeout(() => setVisible(true), 50);
    else setVisible(false);
  }, [isOpen]);

  // Breathing exercise loop
  useEffect(() => {
    if (!showBreathing) return;
    let idx = 0;
    setBreathingPhase(0);

    const next = () => {
      idx = (idx + 1) % BREATHING_PHASES.length;
      setBreathingPhase(idx);
    };

    const timers = [];
    let elapsed = 0;
    BREATHING_PHASES.forEach((phase, i) => {
      timers.push(setTimeout(() => {
        setBreathingPhase(i);
        setBreathCycle(c => !c);
      }, elapsed));
      elapsed += phase.duration;
    });

    const interval = setInterval(() => {
      elapsed = 0;
      BREATHING_PHASES.forEach((phase, i) => {
        timers.push(setTimeout(() => setBreathingPhase(i), elapsed));
        elapsed += phase.duration;
      });
    }, BREATHING_PHASES.reduce((s, p) => s + p.duration, 0));

    return () => {
      timers.forEach(clearTimeout);
      clearInterval(interval);
    };
  }, [showBreathing]);

  if (!isOpen) return null;

  const phase = BREATHING_PHASES[breathingPhase];
  const isCritical = tier === 'critical';

  return (
    <div className={`${styles.overlay} ${visible ? styles.overlayVisible : ''}`}>
      <div className={`${styles.modal} ${visible ? styles.modalVisible : ''}`}>

        {/* Close ΓÇö only for medium/low tier */}
        {!isCritical && (
          <button className={styles.closeBtn} onClick={onClose}>├ù</button>
        )}

        {/* Focusly in guardian_mode */}
        <div className={styles.lionWrap}>
          <FocuslyLion emotion="guardian_mode" gesture="protective" className={styles.lion} />
          <div className={styles.shield}>≡ƒ¢í∩╕Å</div>
        </div>

        <div className={styles.badge} style={{ background: isCritical ? 'rgba(239,68,68,0.12)' : 'rgba(124,107,254,0.12)', borderColor: isCritical ? 'rgba(239,68,68,0.4)' : 'rgba(124,107,254,0.4)', color: isCritical ? '#f87171' : '#a78bfa' }}>
          {isCritical ? '≡ƒÜ¿ Immediate Support Available' : '≡ƒÆ£ Focusly is Here'}
        </div>

        <h2 className={styles.title}>You are not alone.</h2>

        <p className={styles.message}>
          {isCritical
            ? "Focusly noticed something concerning. Please reach out ΓÇö there are real people here who care and real professionals ready to listen."
            : "It sounds like you're going through something difficult. That takes courage to share. Focusly is right here with you. ≡ƒÆ£"}
        </p>

        {/* Helplines */}
        <div className={styles.helplinesSection}>
          <p className={styles.helplineTitle}>≡ƒô₧ Reach Out Right Now</p>
          <div className={styles.helplines}>
            {CRISIS_HELPLINES.map((h, i) => (
              <div key={i} className={styles.helpline}>
                <span className={styles.helplineFlag}>{h.flag}</span>
                <div className={styles.helplineInfo}>
                  <strong>{h.name}</strong>
                  {h.number && (
                    <a href={`tel:${h.number}`} className={styles.helplineNumber}>
                      ≡ƒô₧ {h.number}
                    </a>
                  )}
                  {h.url && (
                    <a href={h.url} target="_blank" rel="noopener noreferrer" className={styles.helplineNumber}>
                      ≡ƒîÉ Open Chat
                    </a>
                  )}
                  <small>{h.available}</small>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Breathing exercise toggle */}
        {!showBreathing ? (
          <button className={styles.breathBtn} onClick={() => setShowBreathing(true)}>
            ≡ƒî¼∩╕Å Try a Breathing Exercise
          </button>
        ) : (
          <div className={styles.breathingBox}>
            <div
              className={styles.breathCircle}
              style={{
                borderColor: phase.color,
                boxShadow: `0 0 30px ${phase.color}40`,
                transform: breathingPhase === 0 ? 'scale(1.2)' : breathingPhase === 1 ? 'scale(1.2)' : 'scale(1)',
                transition: `transform ${phase.duration}ms ease-in-out, border-color 0.5s`,
              }}
            >
              <span className={styles.breathLabel}>{phase.label}</span>
              <span className={styles.breathCount}>
                {breathingPhase === 0 ? '4s' : breathingPhase === 1 ? '7s' : '8s'}
              </span>
            </div>
            <p className={styles.breathingInstruction}>4-7-8 Breathing Technique</p>
          </div>
        )}

        {/* Actions */}
        <div className={styles.actions}>
          <button className={styles.primaryBtn} onClick={onClose}>
            ≡ƒÆ£ I'm okay ΓÇö Continue
          </button>
          {isCritical && (
            <p className={styles.disclaimer}>
              Our team has been notified and will check in with you shortly. You matter. ≡ƒªü
            </p>
          )}
        </div>
      </div>
    </div>
  );
};

export default DistressResponse;

