import React, { useState, useRef } from 'react';
import { useClickOutside } from '../../hooks/useClickOutside';
import styles from './Select.module.css';

const Select = ({
    value,
    onChange,
    options = [],
    placeholder = 'Select an option',
    label,
    description,
    disabled = false,
    className = '',
    ...props
}) => {
    const [isOpen, setIsOpen] = useState(false);
    const dropdownRef = useClickOutside(() => setIsOpen(false));

    const selectedOption = options.find(opt => opt.value === value);

    const handleSelect = (option) => {
        onChange(option.value);
        setIsOpen(false);
    };

    const handleKeyDown = (e) => {
        if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            setIsOpen(!isOpen);
        } else if (e.key === 'Escape') {
            setIsOpen(false);
        }
    };

    return (
        <div className={`${styles.selectContainer} ${className}`}>
            {(label || description) && (
                <div className={styles.labelContainer}>
                    {label && <label className={styles.label}>{label}</label>}
                    {description && <span className={styles.description}>{description}</span>}
                </div>
            )}
            <div className={styles.selectWrapper} ref={dropdownRef}>
                <button
                    type="button"
                    className={`${styles.select} ${isOpen ? styles.open : ''} ${disabled ? styles.disabled : ''}`}
                    onClick={() => !disabled && setIsOpen(!isOpen)}
                    onKeyDown={handleKeyDown}
                    disabled={disabled}
                    aria-haspopup="listbox"
                    aria-expanded={isOpen}
                    {...props}
                >
                    <span className={styles.selectedValue}>
                        {selectedOption?.label || placeholder}
                    </span>
                    <svg
                        className={styles.chevron}
                        width="20"
                        height="20"
                        viewBox="0 0 20 20"
                        fill="none"
                        xmlns="http://www.w3.org/2000/svg"
                    >
                        <path
                            d="M5 7.5L10 12.5L15 7.5"
                            stroke="currentColor"
                            strokeWidth="2"
                            strokeLinecap="round"
                            strokeLinejoin="round"
                        />
                    </svg>
                </button>

                {isOpen && (
                    <div className={styles.dropdown} role="listbox">
                        {options.map((option) => (
                            <button
                                key={option.value}
                                type="button"
                                className={`${styles.option} ${option.value === value ? styles.selected : ''}`}
                                onClick={() => handleSelect(option)}
                                role="option"
                                aria-selected={option.value === value}
                            >
                                {option.icon && <span className={styles.optionIcon}>{option.icon}</span>}
                                <span className={styles.optionLabel}>{option.label}</span>
                                {option.description && (
                                    <span className={styles.optionDescription}>{option.description}</span>
                                )}
                            </button>
                        ))}
                    </div>
                )}
            </div>
        </div>
    );
};

export default Select;

/**
 * Age Verification Modal
 * Collects and verifies user age, applies appropriate mode
 */

import React, { useState } from 'react';
import { verifyAge, getAccountType } from '../../utils/ageVerification';
import { useAuth } from '../../hooks/useAuth';
import styles from './AgeVerificationModal.module.css';

const AgeVerificationModal = ({ isOpen, onClose, onComplete }) => {
    const { user } = useAuth();
    const [birthDate, setBirthDate] = useState('');
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');
    const [accountTypePreview, setAccountTypePreview] = useState(null);

    // Calculate age and preview account type as user types
    const handleDateChange = (e) => {
        const date = e.target.value;
        setBirthDate(date);
        setError('');

        if (date) {
            const age = calculateAge(date);
            if (age !== null) {
                const type = getAccountType(age);
                setAccountTypePreview({ age, ...type });
            }
        } else {
            setAccountTypePreview(null);
        }
    };

    const calculateAge = (birthDateString) => {
        if (!birthDateString) return null;

        const today = new Date();
        const birth = new Date(birthDateString);
        let age = today.getFullYear() - birth.getFullYear();
        const monthDiff = today.getMonth() - birth.getMonth();

        if (monthDiff < 0 || (monthDiff === 0 && today.getDate() < birth.getDate())) {
            age--;
        }

        return age;
    };

    const handleSubmit = async (e) => {
        e.preventDefault();

        if (!birthDate) {
            setError('Please enter your birth date');
            return;
        }

        const age = calculateAge(birthDate);

        if (age === null || age < 0) {
            setError('Please enter a valid birth date');
            return;
        }

        if (age > 120) {
            setError('Please enter a valid birth date');
            return;
        }

        setLoading(true);
        setError('');

        try {
            const result = await verifyAge(user.id, birthDate, 'self_reported');

            if (result.success) {
                onComplete(result);
            }
        } catch (err) {
            setError(err.message || 'Failed to verify age. Please try again.');
        } finally {
            setLoading(false);
        }
    };

    if (!isOpen) return null;

    return (
        <div className="age-verification-overlay">
            <div className="age-verification-modal">
                <div className="modal-header">
                    <h2>Welcome to Focus! ≡ƒÄë</h2>
                    <p>To provide you with the best and safest experience, we need to verify your age.</p>
                </div>

                <form onSubmit={handleSubmit} className="verification-form">
                    <div className="form-group">
                        <label htmlFor="birthdate">
                            Date of Birth
                            <span className="required">*</span>
                        </label>
                        <input
                            type="date"
                            id="birthdate"
                            value={birthDate}
                            onChange={handleDateChange}
                            max={new Date().toISOString().split('T')[0]}
                            required
                            className="date-input"
                        />
                        <small className="form-hint">
                            We use this to provide age-appropriate features and comply with privacy laws.
                        </small>
                    </div>

                    {accountTypePreview && (
                        <div className={`account-type-preview ${accountTypePreview.type}`}>
                            <div className="preview-icon">
                                {accountTypePreview.type === 'coppa' && '≡ƒæ╢'}
                                {accountTypePreview.type === 'teen' && '≡ƒºæ'}
