    const [safetySettings, setSafetySettings] = useState(null);
    const [screenTimeStatus, setScreenTimeStatus] = useState(null);
    const [trustedContacts, setTrustedContacts] = useState([]);

    // Loading states
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    // Calculate age from birth date
    const calculateAge = (birthDate) => {
        if (!birthDate) return null;
        const today = new Date();
        const birth = new Date(birthDate);
        let age = today.getFullYear() - birth.getFullYear();
        const monthDiff = today.getMonth() - birth.getMonth();
        if (monthDiff < 0 || (monthDiff === 0 && today.getDate() < birth.getDate())) {
            age--;
        }
        return age;
    };

    // Fetch user's teen care status
    const fetchUserStatus = useCallback(async () => {
        if (!user?.id) return;

        try {
            setLoading(true);

            // Check if user is a guardian
            const { data: guardianData } = await supabase
                .from('guardian_relationships')
                .select('*')
                .eq('guardian_id', user.id)
                .eq('status', 'active');

            setIsGuardian(guardianData?.length > 0);

            // Check if user is a teen
            const { data: teenSettings } = await supabase
                .from('teen_safety_settings')
                .select('*')
                .eq('teen_id', user.id)
                .single();

            if (teenSettings) {
                setIsTeen(true);
                setSafetySettings(teenSettings);
                setIsCoppaMode(teenSettings.coppa_mode);
                setUserAge(calculateAge(teenSettings.birth_date));
            }

            // Fetch linked teens for guardians
            if (guardianData?.length > 0) {
                const teenIds = guardianData.map(g => g.teen_id);
                const { data: teens } = await supabase
                    .from('users')
                    .select('id, username, avatar_url, birth_date')
                    .in('id', teenIds);

                setLinkedTeens(teens || []);
            }

            // Fetch guardians for teens
            const { data: guardianLinks } = await supabase
                .from('guardian_relationships')
                .select(`
                    *,
                    guardian:guardian_id (id, username, avatar_url)
                `)
                .eq('teen_id', user.id)
                .eq('status', 'active');

            if (guardianLinks) {
                setMyGuardians(guardianLinks.map(g => g.guardian));
            }

            setError(null);
        } catch (err) {
            console.error('Error fetching teen care status:', err);
            setError(err.message);
        } finally {
            setLoading(false);
        }
    }, [user?.id]);

    useEffect(() => {
        fetchUserStatus();
    }, [fetchUserStatus]);

    // Generate invitation code
    const generateInvitationCode = useCallback(async (teenId = user?.id) => {
        const code = Math.random().toString(36).substring(2, 10).toUpperCase();
        const expiresAt = new Date();
        expiresAt.setDate(expiresAt.getDate() + 7); // 7 days expiry

        const { data, error } = await supabase
            .from('guardian_relationships')
            .insert({
                teen_id: teenId,
                invitation_code: code,
                invitation_expires_at: expiresAt.toISOString(),
                status: 'pending',
                invited_by: user?.id
            })
            .select()
            .single();

        if (error) throw error;
        return { code, expiresAt, id: data.id };
    }, [user?.id]);

    // Accept guardian invitation
    const acceptInvitation = useCallback(async (code) => {
        // Find the invitation
        const { data: invitation, error: findError } = await supabase
            .from('guardian_relationships')
            .select('*')
            .eq('invitation_code', code)
            .eq('status', 'pending')
            .single();

        if (findError || !invitation) {
            throw new Error('Invalid or expired invitation code');
        }

        // Check if expired
        if (new Date(invitation.invitation_expires_at) < new Date()) {
            throw new Error('Invitation code has expired');
        }

        // Accept the invitation
        const { error: updateError } = await supabase
            .from('guardian_relationships')
            .update({
                guardian_id: user?.id,
                status: 'active',
                approved_at: new Date().toISOString()
            })
            .eq('id', invitation.id);

        if (updateError) throw updateError;

        // Mark user as guardian
        await supabase
            .from('users')
            .update({ is_guardian: true })
            .eq('id', user?.id);

        await fetchUserStatus();
        return invitation;
    }, [user?.id, fetchUserStatus]);

    // Send invitation to teen
    const inviteTeen = useCallback(async (teenEmail) => {
        // Find teen by email
        const { data: teen, error: findError } = await supabase
            .from('users')
            .select('id, username, email')
            .eq('email', teenEmail)
            .single();

        if (findError || !teen) {
            throw new Error('User not found with that email');
        }

        // Create guardian relationship
        const { data, error } = await supabase
            .from('guardian_relationships')
            .insert({
                guardian_id: user?.id,
                teen_id: teen.id,
                relationship_type: 'parent',
                status: 'pending',
                invited_by: user?.id
            })
            .select()
            .single();

        if (error) throw error;

        // TODO: Send notification to teen

        return { teen, invitation: data };
    }, [user?.id]);

    // Remove guardian link
    const removeGuardian = useCallback(async (guardianId) => {
        const { error } = await supabase
            .from('guardian_relationships')
            .update({
                status: 'revoked',
                revoked_at: new Date().toISOString(),
                revoked_by: user?.id
            })
            .eq('guardian_id', guardianId)
            .eq('teen_id', user?.id);

        if (error) throw error;
        await fetchUserStatus();
    }, [user?.id, fetchUserStatus]);

    // Update safety settings
    const updateSafetySettings = useCallback(async (settings) => {
        const { error } = await supabase
            .from('teen_safety_settings')
            .upsert({
                teen_id: user?.id,
                ...settings,
                updated_at: new Date().toISOString()
            });

        if (error) throw error;
        setSafetySettings(prev => ({ ...prev, ...settings }));
    }, [user?.id]);

    // Fetch alerts for guardian
    const fetchAlerts = useCallback(async (teenId = null) => {
        let query = supabase
            .from('safety_alerts')
            .select(`
                *,
                teen:teen_id (id, username, avatar_url)
            `)
            .eq('guardian_id', user?.id)
            .order('created_at', { ascending: false });

        if (teenId) {
            query = query.eq('teen_id', teenId);
        }

        const { data, error } = await query.limit(50);
        if (error) throw error;

        setGuardianAlerts(data || []);
        return data;
    }, [user?.id]);

    // Mark alert as reviewed
    const reviewAlert = useCallback(async (alertId, status, notes = '') => {
        const { error } = await supabase
            .from('safety_alerts')
            .update({
                status,
                resolution_notes: notes,
                resolved_at: status === 'resolved' ? new Date().toISOString() : null,
                resolved_by: user?.id
            })
            .eq('id', alertId);

        if (error) throw error;
        await fetchAlerts();
    }, [user?.id, fetchAlerts]);

    // Create safety alert
    const createAlert = useCallback(async (alert) => {
        // Get all guardians for this teen
        const { data: guardians } = await supabase
            .from('guardian_relationships')
            .select('guardian_id')
            .eq('teen_id', alert.teen_id)
            .eq('status', 'active');

        // Create alert for each guardian
        const alerts = guardians?.map(g => ({
            ...alert,
            guardian_id: g.guardian_id,
            created_at: new Date().toISOString()
        })) || [];

        if (alerts.length > 0) {
            const { error } = await supabase
                .from('safety_alerts')
                .insert(alerts);

            if (error) throw error;
        }

        return alerts;
    }, []);

    // Panic button activation
    const activatePanicButton = useCallback(async (message = '', location = null) => {
        const { data, error } = await supabase
            .from('panic_activations')
            .insert({
                teen_id: user?.id,
                message,
                latitude: location?.latitude,
                longitude: location?.longitude,
                location_accuracy: location?.accuracy,
                guardians_notified: myGuardians.map(g => g.id)
            })
            .select()
            .single();

        if (error) throw error;

        // Create critical alert for all guardians
        await createAlert({
            teen_id: user?.id,
            alert_type: 'panic_button',
            severity: 'critical',
            title: 'Panic Button Activated',
            description: message || 'Your teen has activated the panic button and may need help.',
            status: 'new'
        });

        return data;
    }, [user?.id, myGuardians, createAlert]);

    // Check screen time
    const checkScreenTime = useCallback(async () => {
        if (!isTeen) return null;

        const { data, error } = await supabase
            .rpc('check_screen_time_limit', { user_id: user?.id });

        if (error) {
            console.error('Error checking screen time:', error);
            return null;
        }

        setScreenTimeStatus(data);
        return data;
    }, [user?.id, isTeen]);

    // Log screen time usage
    const logScreenTime = useCallback(async (minutes, category = 'general') => {
        const today = new Date().toISOString().split('T')[0];

        const { error } = await supabase
            .from('screen_time_usage')
            .upsert({
                teen_id: user?.id,
                date: today,
                total_minutes: minutes,
                [`${category}_minutes`]: minutes
            }, {
                onConflict: 'teen_id,date'
            });

        if (error) console.error('Error logging screen time:', error);
    }, [user?.id]);

    // Fetch trusted contacts
    const fetchTrustedContacts = useCallback(async () => {
        const { data, error } = await supabase
            .from('trusted_contacts')
            .select(`
                *,
                contact:contact_user_id (id, username, avatar_url)
            `)
            .eq('teen_id', user?.id);

        if (error) throw error;
        setTrustedContacts(data || []);
        return data;
    }, [user?.id]);

    // Add trusted contact
    const addTrustedContact = useCallback(async (contact) => {
        const { data, error } = await supabase
            .from('trusted_contacts')
            .insert({
                teen_id: user?.id,
                ...contact
            })
            .select()
            .single();

        if (error) throw error;
        await fetchTrustedContacts();
        return data;
    }, [user?.id, fetchTrustedContacts]);

    const value = {
        // Status
        isGuardian,
        isTeen,
        isCoppaMode,
        userAge,
        loading,
        error,

        // Guardian features
        linkedTeens,
        guardianAlerts,
        pendingInvitations,
        fetchAlerts,
        reviewAlert,
        inviteTeen,
        acceptInvitation,
        generateInvitationCode,

        // Teen features
        myGuardians,
        safetySettings,
        screenTimeStatus,
        trustedContacts,
        updateSafetySettings,
        removeGuardian,
        activatePanicButton,
        checkScreenTime,
        logScreenTime,
        fetchTrustedContacts,
        addTrustedContact,

        // Shared
        createAlert,
        refreshStatus: fetchUserStatus
    };

    return (
        <TeenCareContext.Provider value={value}>
            {children}
        </TeenCareContext.Provider>
    );
};

export default TeenCareContext;

// useAdminSupport hook - For admin support ticket management
import { useState, useEffect, useCallback } from 'react';
import { getTicketQueue, addTicketMessage, updateTicketStatus } from '../utils/supabaseSupport';
import { sendTicketUpdate } from '../utils/emailNotifications';
import { supabase } from '../lib/supabase';
import { useAuth } from './useAuth';
import { toast } from 'react-toastify';

export const useAdminSupport = () => {
    const { user } = useAuth();
    const [tickets, setTickets] = useState([]);
    const [loading, setLoading] = useState(true);
    const [filters, setFilters] = useState({ status: 'open', limit: 50, offset: 0 });
    const [isProcessing, setIsProcessing] = useState(false);

    const fetchTickets = useCallback(async () => {
        setLoading(true);
        try {
            const result = await getTicketQueue(filters);
            if (result.success) {
                setTickets(result.data);
            }
        } catch (error) {
            console.error('Error fetching tickets:', error);
            toast.error('Failed to load tickets');
        } finally {
            setLoading(false);
        }
    }, [filters]);

    useEffect(() => {
        fetchTickets();
    }, [fetchTickets]);

    /**
     * Reply to a ticket
     * @param {string} ticketId - Ticket ID
     * @param {string} message - Reply message
     * @param {boolean} changeStatus - Whether to update ticket status
     * @param {string} newStatus - New status if changing
     * @returns {Promise<void>}
     */
    const replyToTicket = useCallback(async (ticketId, message, changeStatus = false, newStatus = null) => {
        if (!user) return;

        setIsProcessing(true);
        try {
            // Add message
            const messageResult = await addTicketMessage({
                ticket_id: ticketId,
                sender_id: user.id,
                message,
                is_admin: true,
                is_internal_note: false
            });

            if (!messageResult.success) {
                throw new Error(messageResult.error);
            }

            // Update status if needed
            if (changeStatus && newStatus) {
                await updateTicketStatus(ticketId, { status: newStatus });
            }

            // Get ticket for email
            const ticket = tickets.find(t => t.id === ticketId);
            if (ticket && ticket.user) {
                try {
                    await sendTicketUpdate(ticket, ticket.user, message);
                } catch (emailError) {
                    console.warn('Failed to send update email:', emailError);
                }
            }

            toast.success('Reply sent successfully');
            fetchTickets();
        } catch (error) {
            console.error('Error replying to ticket:', error);
            toast.error('Failed to send reply');
        } finally {
            setIsProcessing(false);
        }
    }, [user, tickets, fetchTickets]);

    /**
     * Assign ticket to admin
     * @param {string} ticketId - Ticket ID
     * @param {string} adminId - Admin user ID
     * @returns {Promise<void>}
     */
    const assignTicket = useCallback(async (ticketId, adminId) => {
        setIsProcessing(true);
        try {
            const result = await updateTicketStatus(ticketId, { assigned_to: adminId });

            if (result.success) {
                toast.success('Ticket assigned');
                fetchTickets();
            } else {
                throw new Error(result.error);
            }
        } catch (error) {
            console.error('Error assigning ticket:', error);
            toast.error('Failed to assign ticket');
        } finally {
            setIsProcessing(false);
        }
    }, [fetchTickets]);

    return {
        tickets,
        loading,
        filters,
        setFilters,
        replyToTicket,
        assignTicket,
        isProcessing,
        refreshTickets: fetchTickets
    };
};

export default useAdminSupport;

import { useState } from 'react';
import { supabase } from '../lib/supabase';
import { focusToast } from '../utils/focusToast';

export const useAttachmentUpload = () => {
    const [uploading, setUploading] = useState(false);
    const [progress, setProgress] = useState(0);

    const uploadFile = async (file, userId) => {
        try {
            setUploading(true);
            setProgress(0);

            // Determine file type
            const fileType = file.type.split('/')[0]; // image, video, audio, etc.
            const fileExt = file.name.split('.').pop();
            const fileName = `${userId}/${Date.now()}_${Math.random().toString(36).substring(7)}.${fileExt}`;

            // Upload to Supabase storage
            const { data, error } = await supabase.storage
                .from('message-attachments')
                .upload(fileName, file, {
                    cacheControl: '3600',
                    upsert: false,
                    onUploadProgress: (progressEvent) => {
                        const percentCompleted = Math.round(
                            (progressEvent.loaded * 100) / progressEvent.total
                        );
                        setProgress(percentCompleted);
                    }
                });

            if (error) throw error;

            // Get public URL
            const { data: { publicUrl } } = supabase.storage
                .from('message-attachments')
                .getPublicUrl(fileName);

            setProgress(100);

            return {
                url: publicUrl,
                type: fileType,
                name: file.name,
                size: file.size,
                mimeType: file.type
            };
        } catch (err) {
            console.error('Error uploading file:', err);
            focusToast.error('Failed to upload file');
            throw err;
        } finally {
            setUploading(false);
            setTimeout(() => setProgress(0), 1000);
        }
    };

    const uploadMultiple = async (files, userId) => {
        try {
            setUploading(true);
            const uploads = await Promise.all(
                Array.from(files).map(file => uploadFile(file, userId))
            );
            return uploads;
        } catch (err) {
            console.error('Error uploading multiple files:', err);
            throw err;
        }
    };

    return {
        uploadFile,
        uploadMultiple,
        uploading,
        progress
    };
};

import { useState, useEffect, useCallback, useRef } from 'react';

/**
 * Avatar animation states
 */
export const ANIMATION_STATES = {
    IDLE: 'idle',
    WAVE: 'wave',
    JUMP: 'jump',
    DANCE: 'dance',
    THINK: 'think',
    NOD: 'nod',
    SHAKE: 'shake',
    POINT: 'point'
};

/**
 * Avatar expressions
 */
export const EXPRESSIONS = {
    NEUTRAL: 'neutral',
    HAPPY: 'happy',
    SAD: 'sad',
    EXCITED: 'excited',
    SURPRISED: 'surprised',
    THINKING: 'thinking',
    LOVE: 'love',
    CONFUSED: 'confused'
};

/**
 * Custom hook for avatar animation management
 * Handles animation states, expressions, and transitions
 */
export const useAvatarAnimation = () => {
    const [currentAnimation, setCurrentAnimation] = useState(ANIMATION_STATES.IDLE);
    const [currentExpression, setCurrentExpression] = useState(EXPRESSIONS.NEUTRAL);
    const [isBlinking, setIsBlinking] = useState(false);
    const [animationQueue, setAnimationQueue] = useState([]);
    const animationTimeoutRef = useRef(null);
    const blinkIntervalRef = useRef(null);

    // Setup idle animations (blinking)
    useEffect(() => {
        // Random blinking every 3-5 seconds
        const setupBlinking = () => {
            const blinkDelay = 3000 + Math.random() * 2000; // 3-5 seconds

            blinkIntervalRef.current = setTimeout(() => {
                setIsBlinking(true);

                // Blink duration: 150ms
                setTimeout(() => {
                    setIsBlinking(false);
                    setupBlinking(); // Schedule next blink
                }, 150);
            }, blinkDelay);
        };

        setupBlinking();

        return () => {
            if (blinkIntervalRef.current) {
                clearTimeout(blinkIntervalRef.current);
            }
        };
    }, []);

    // Process animation queue
    useEffect(() => {
        if (animationQueue.length > 0 && currentAnimation === ANIMATION_STATES.IDLE) {
            const nextAnimation = animationQueue[0];
            playAnimation(nextAnimation.name, nextAnimation.duration);
            setAnimationQueue(prev => prev.slice(1));
        }
    }, [animationQueue, currentAnimation]);

    /**
     * Play an animation
     * @param {string} animationName - Animation to play
     * @param {number} duration - Duration in milliseconds
     */
    const playAnimation = useCallback((animationName, duration = 1000) => {
        // Clear any existing animation timeout
        if (animationTimeoutRef.current) {
            clearTimeout(animationTimeoutRef.current);
        }

        setCurrentAnimation(animationName);

        // Return to idle after duration
        animationTimeoutRef.current = setTimeout(() => {
            setCurrentAnimation(ANIMATION_STATES.IDLE);
        }, duration);
    }, []);

    /**
     * Queue an animation
     * @param {string} animationName - Animation to queue
     * @param {number} duration - Duration in milliseconds
     */
    const queueAnimation = useCallback((animationName, duration = 1000) => {
        setAnimationQueue(prev => [...prev, { name: animationName, duration }]);
    }, []);

    /**
     * Set expression
     * @param {string} expression - Expression to set
     * @param {number} duration - Duration (0 = permanent until changed)
     */
    const setExpression = useCallback((expression, duration = 0) => {
        setCurrentExpression(expression);

        if (duration > 0) {
            setTimeout(() => {
                setCurrentExpression(EXPRESSIONS.NEUTRAL);
            }, duration);
        }
    }, []);

    /**
     * Wave animation
     */
    const wave = useCallback(() => {
        playAnimation(ANIMATION_STATES.WAVE, 1500);
    }, [playAnimation]);

    /**
     * Jump animation (for excitement/achievement)
     */
    const jump = useCallback(() => {
        playAnimation(ANIMATION_STATES.JUMP, 800);
    }, [playAnimation]);

    /**
     * Dance animation (for celebration)
     */
    const dance = useCallback(() => {
        playAnimation(ANIMATION_STATES.DANCE, 2000);
    }, [playAnimation]);

    /**
     * Think animation
     */
    const think = useCallback(() => {
        playAnimation(ANIMATION_STATES.THINK, 1500);
    }, [playAnimation]);

    /**
     * Nod animation (yes)
     */
    const nod = useCallback(() => {
        playAnimation(ANIMATION_STATES.NOD, 800);
    }, [playAnimation]);

    /**
     * Shake animation (no)
     */
    const shake = useCallback(() => {
        playAnimation(ANIMATION_STATES.SHAKE, 800);
    }, [playAnimation]);

    /**
     * Point animation
     */
    const point = useCallback(() => {
        playAnimation(ANIMATION_STATES.POINT, 1200);
    }, [playAnimation]);

    /**
     * React to emotion
     * @param {string} emotion - Emotion to react to
     */
    const reactToEmotion = useCallback((emotion) => {
        const reactions = {
            happy: () => {
                setExpression(EXPRESSIONS.HAPPY, 3000);
                jump();
            },
            excited: () => {
                setExpression(EXPRESSIONS.EXCITED, 3000);
                dance();
            },
            sad: () => {
                setExpression(EXPRESSIONS.SAD, 3000);
            },
            surprised: () => {
                setExpression(EXPRESSIONS.SURPRISED, 2000);
            },
            thinking: () => {
                setExpression(EXPRESSIONS.THINKING, 2000);
                think();
            },
            love: () => {
                setExpression(EXPRESSIONS.LOVE, 3000);
            },
            confused: () => {
                setExpression(EXPRESSIONS.CONFUSED, 2000);
            }
        };

        const reaction = reactions[emotion];
        if (reaction) {
            reaction();
        }
    }, [setExpression, jump, dance, think]);

    /**
     * Greeting animation
     */
    const greet = useCallback(() => {
        setExpression(EXPRESSIONS.HAPPY, 2000);
        wave();
    }, [setExpression, wave]);

    /**
     * Celebration animation
     */
    const celebrate = useCallback(() => {
        setExpression(EXPRESSIONS.EXCITED, 3000);
        dance();
    }, [setExpression, dance]);

    /**
     * Clear animation queue
     */
    const clearQueue = useCallback(() => {
        setAnimationQueue([]);
    }, []);

    /**
     * Reset to idle state
     */
    const reset = useCallback(() => {
        if (animationTimeoutRef.current) {
            clearTimeout(animationTimeoutRef.current);
        }
        setCurrentAnimation(ANIMATION_STATES.IDLE);
        setCurrentExpression(EXPRESSIONS.NEUTRAL);
        setAnimationQueue([]);
    }, []);

    return {
        currentAnimation,
        currentExpression,
        isBlinking,
        playAnimation,
        queueAnimation,
        setExpression,
        wave,
        jump,
        dance,
        think,
        nod,
        shake,
        point,
        reactToEmotion,
        greet,
        celebrate,
        clearQueue,
        reset,
        ANIMATION_STATES,
        EXPRESSIONS
    };
};

export default useAvatarAnimation;

import { useState } from 'react';
import { useAuth } from './useAuth';
import { submitBadgeApplication, fetchUserApplications } from '../utils/supabaseBadges';
import { notifyApplicationSubmitted } from '../utils/badgeNotification';
import { supabase } from '../lib/supabase';

/**
 * useBadgeApplication Hook
 * Handles badge application submission and status tracking
 */
export const useBadgeApplication = () => {
    const { user } = useAuth();
    const [submitting, setSubmitting] = useState(false);
    const [uploading, setUploading] = useState(false);

    /**
     * Upload file to Supabase Storage
     */
    const uploadFile = async (file, userId, badgeName) => {
        try {
            setUploading(true);
            const fileExt = file.name.split('.').pop();
            const fileName = `${userId}/${badgeName}/${Date.now()}.${fileExt}`;

            const { data, error } = await supabase.storage
                .from('badge-applications')
                .upload(fileName, file);

            if (error) throw error;

            const { data: { publicUrl } } = supabase.storage
                .from('badge-applications')
                .getPublicUrl(fileName);

            return publicUrl;
        } catch (error) {
            console.error('Error uploading file:', error);
            throw error;
        } finally {
            setUploading(false);
        }
    };

    /**
     * Submit badge application
     */
    const submitApplication = async (badgeName, formData) => {
        if (!user) {
            return { success: false, error: 'User not authenticated' };
        }

        try {
            setSubmitting(true);

            // Handle file uploads if present
            const processedData = { ...formData };
            for (const [key, value] of Object.entries(formData)) {
                if (value instanceof File) {
                    const url = await uploadFile(value, user.id, badgeName);
                    processedData[key] = url;
                }
            }

            const result = await submitBadgeApplication(user.id, badgeName, processedData);

            if (result.success) {
                notifyApplicationSubmitted(badgeName);
            }

            return result;
        } catch (error) {
            console.error('Error submitting application:', error);
            return { success: false, error: error.message };
        } finally {
            setSubmitting(false);
        }
    };

    /**
     * Fetch user's applications
     */
    const getApplications = async () => {
        if (!user) return [];
        return await fetchUserApplications(user.id);
    };

    /**
     * Check if user has pending application for badge
     */
    const hasPendingApplication = async (badgeName) => {
        const applications = await getApplications();
        return applications.some(
            app => app.badge?.name === badgeName &&
                ['pending', 'under_review'].includes(app.status)
        );
    };

    return {
        submitApplication,
        getApplications,
        hasPendingApplication,
        submitting,
        uploading
    };
};

import { useState, useEffect } from 'react';
import { useAuth } from './useAuth';
import { useTrustScore } from './useTrustScore';
import { checkAllBadges, getEligibleBadges, getLockedBadgesWithProgress } from '../utils/badgeCriteriaChecker';
import { fetchUserBadges } from '../utils/supabaseBadges';
import { supabase } from '../lib/supabase';

/**
 * useBadgeCriteria Hook
 * Checks badge eligibility and returns available/locked badges with progress
 */
export const useBadgeCriteria = () => {
    const { user } = useAuth();
    const { score: trustScore } = useTrustScore(user);

    const [metrics, setMetrics] = useState({});
    const [criteria, setCriteria] = useState({});
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        if (!user) {
            setLoading(false);
            return;
        }

        const loadMetrics = async () => {
            try {
                setLoading(true);

                // Fetch user metrics from various sources
                const [
                    { data: profile },
                    { count: postsCount },
                    { count: followersCount },
                    { data: userBadges }
                ] = await Promise.all([
                    supabase.from('profiles').select('*').eq('id', user.id).single(),
                    supabase.from('posts').select('*', { count: 'exact', head: true }).eq('user_id', user.id),
                    supabase.from('follows').select('*', { count: 'exact', head: true }).eq('following_id', user.id),
                    fetchUserBadges(user.id)
                ]);

                // Calculate account age
                const accountCreatedAt = new Date(user.created_at);
                const now = new Date();
                const accountAgeDays = Math.floor((now - accountCreatedAt) / (1000 * 60 * 60 * 24));

                // Calculate engagement rate (simplified)
                const engagementRate = postsCount > 0 ? (followersCount / postsCount) * 0.1 : 0;

                const userMetrics = {
                    trustScore,
                    accountAgeDays,
                    postsCount: postsCount || 0,
                    followersCount: followersCount || 0,
                    engagementRate,
                    violations: 0, // Would come from moderation system
                    trustScoreDaysMaintained: 0, // Would track this separately
                    accurateReports: 0, // Would come from reporting system
                    moderationScore: 0, // Would come from moderation system
                    helpfulVotes: 0, // Would come from voting system
                    trendingPostsCount: 0 // Would come from trending system
                };

                setMetrics(userMetrics);

                // Check all badge criteria
                const allCriteria = checkAllBadges(user, userMetrics);
                setCriteria(allCriteria);

            } catch (err) {
                console.error('Error loading badge criteria:', err);
            } finally {
                setLoading(false);
            }
        };

        loadMetrics();
    }, [user, trustScore]);

    const eligibleBadges = getEligibleBadges(user || {}, metrics);
    const lockedBadges = getLockedBadgesWithProgress(user || {}, metrics);

    return {
        criteria,
        metrics,
        eligibleBadges,
        lockedBadges,
        loading
    };
};

import { useState, useEffect } from 'react';
import { useAuth } from './useAuth';
import { useBadgeCriteria } from './useBadgeCriteria';
import { useUserBadges } from './useUserBadges';
import { formatBadgeProgress } from '../utils/badgeFormatter';
import { BADGE_DEFINITIONS } from '../utils/badgeRules';

/**
 * useBadgeProgress Hook
 * Tracks progress toward locked badges
 */
export const useBadgeProgress = () => {
    const { user } = useAuth();
    const { criteria, lockedBadges, loading: criteriaLoading } = useBadgeCriteria();
    const { badges, loading: badgesLoading } = useUserBadges();

    const [progress, setProgress] = useState([]);
    const loading = criteriaLoading || badgesLoading;

    useEffect(() => {
        if (!user || loading) return;

        // Get badges user doesn't have
        const earnedBadgeNames = badges.map(b => b.badge?.name);
        const progressData = lockedBadges
            .filter(locked => !earnedBadgeNames.includes(locked.badgeType))
            .map(locked => {
                const definition = BADGE_DEFINITIONS[locked.badgeType];
                const progressPercent = formatBadgeProgress(locked);

                return {
                    badgeType: locked.badgeType,
                    name: definition?.name,
                    description: definition?.description,
                    icon: definition?.icon,
                    color: definition?.color,
                    gradient: definition?.gradient,
                    progress: locked.progress,
                    progressPercent,
                    checks: locked.checks,
                    message: locked.message,
                    requiresApplication: locked.requiresApplication
                };
            })
            .sort((a, b) => b.progressPercent - a.progressPercent); // Sort by progress

        setProgress(progressData);
    }, [user, lockedBadges, badges, loading]);

    // Get next badge to earn (highest progress)
    const nextBadge = progress[0] || null;

    // Get badges close to earning (>50% progress)
    const closeToEarning = progress.filter(p => p.progressPercent >= 50);

    return {
        progress,
        nextBadge,
        closeToEarning,
        loading
    };
};

import { useState, useEffect } from 'react';
import { supabase } from '../lib/supabase';
import { useAuth } from './useAuth';

/**
 * Hook to fetch and manage blocked users
 * @returns {Object} { blockedUsers, loading, blockUser, unblockUser }
 */
export const useBlockedUsers = () => {
    const { user } = useAuth();
    const [blockedUsers, setBlockedUsers] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    useEffect(() => {
        if (!user) {
            setBlockedUsers([]);
            setLoading(false);
            return;
        }

        fetchBlockedUsers();

        // Subscribe to real-time changes
        const channel = supabase
            .channel(`blocked-users-${user.id}`)
            .on('postgres_changes', {
                event: '*',
                schema: 'public',
                table: 'blocks',
                filter: `blocker_id=eq.${user.id}`
            }, (payload) => {
                console.log('≡ƒÜ½ Blocked users updated:', payload);
                if (payload.eventType === 'INSERT') {
                    fetchBlockedUsers();
                } else if (payload.eventType === 'DELETE') {
                    setBlockedUsers(prev => prev.filter(u => u.id !== payload.old.blocked_id));
                }
            })
            .subscribe();

        return () => {
            channel.unsubscribe();
        };
    }, [user]);

    const fetchBlockedUsers = async () => {
        try {
            setLoading(true);
            console.log('≡ƒÜ½ Fetching blocked users...');

            const { data, error: fetchError } = await supabase
                .from('blocks')
                .select(`
                    blocked_id,
                    reason,
                    created_at,
                    blocked:profiles!blocks_blocked_id_fkey(
                        id,
                        username,
                        full_name,
                        avatar_url,
                        verified
                    )
                `)
                .eq('blocker_id', user.id)
                .order('created_at', { ascending: false });

            if (fetchError) throw fetchError;

            console.log('Γ£à Blocked users fetched:', data?.length || 0);
            setBlockedUsers(data || []);
            setError(null);
        } catch (err) {
            console.error('Γ¥î Error fetching blocked users:', err);
            setError(err.message);
            setBlockedUsers([]);
        } finally {
            setLoading(false);
        }
    };

    const blockUser = async (userId, reason = '') => {
        try {
            const { error } = await supabase
                .from('blocks')
                .insert({
                    blocker_id: user.id,
                    blocked_id: userId,
                    reason
                });

            if (error) throw error;

            console.log('Γ£à User blocked successfully');
            await fetchBlockedUsers();
            return { success: true };
        } catch (err) {
            console.error('Γ¥î Error blocking user:', err);
            return { success: false, error: err.message };
        }
    };

    const unblockUser = async (userId) => {
        try {
            const { error } = await supabase
                .from('blocks')
                .delete()
                .eq('blocker_id', user.id)
                .eq('blocked_id', userId);

            if (error) throw error;

            console.log('Γ£à User unblocked successfully');
            setBlockedUsers(prev => prev.filter(u => u.blocked_id !== userId));
            return { success: true };
        } catch (err) {
            console.error('Γ¥î Error unblocking user:', err);
            return { success: false, error: err.message };
        }
    };

    return { blockedUsers, loading, error, blockUser, unblockUser, refetch: fetchBlockedUsers };
};

/**
 * useBoltzIntersection ΓÇö Focus App v2.0
 *
 * IntersectionObserver-based video play/pause for the Boltz feed.
 * Replaces the swipe-index approach with viewport detection.
 *
 * Features:
 * - Auto-play when 65%+ of video is visible
 * - Auto-pause when card leaves viewport
 * - Pre-load N+1 and N+2 videos
 * - Release memory for N-3 and beyond
 *
 * Usage:
 *   const { registerRef, activeIndex } = useBoltzIntersection(boltz.length);
 *   // then: <div ref={el => registerRef(el, index)}>
 */

import { useState, useEffect, useRef, useCallback } from 'react';

const VISIBLE_THRESHOLD = 0.65;
const PRELOAD_BUFFER = 2;
const RELEASE_BUFFER = 3;

export const useBoltzIntersection = (totalCount = 0, onActiveChange) => {
    const [activeIndex, setActiveIndex] = useState(0);
    const refsMap = useRef(new Map()); // index ΓåÆ DOM element
    const observerRef = useRef(null);

    const registerRef = useCallback((el, index) => {
        if (el) {
            refsMap.current.set(index, el);
        } else {
            refsMap.current.delete(index);
        }
    }, []);

    useEffect(() => {
        // Clean up old observer
        if (observerRef.current) {
            observerRef.current.disconnect();
        }

        const observer = new IntersectionObserver(
            (entries) => {
                let mostVisible = null;
                let mostRatio = 0;

                entries.forEach(entry => {
                    if (entry.isIntersecting && entry.intersectionRatio > mostRatio) {
                        mostRatio = entry.intersectionRatio;
                        mostVisible = entry.target;
                    }
                });

                if (mostVisible && mostRatio >= VISIBLE_THRESHOLD) {
                    // Find index of the most visible element
                    for (const [idx, el] of refsMap.current.entries()) {
                        if (el === mostVisible) {
                            if (activeIndex !== idx) {
                                requestAnimationFrame(() => {
                                    setActiveIndex(idx);
                                    onActiveChange?.(idx);
                                });
                            }
                            break;
                        }
                    }
                }
            },
            {
                threshold: [0, 0.25, 0.5, VISIBLE_THRESHOLD, 0.8, 1.0],
                rootMargin: '0px',
            }
        );

        observerRef.current = observer;

        // Observe all registered elements
        refsMap.current.forEach((el) => {
            observer.observe(el);
        });

        return () => {
            observer.disconnect();
        };
    }, [totalCount, onActiveChange]);

    // Re-observe when refs change
    const activateObserver = useCallback(() => {
        if (!observerRef.current) return;
        observerRef.current.disconnect();
        refsMap.current.forEach((el) => {
            observerRef.current.observe(el);
        });
    }, []);

    // Helper: should this index be pre-loaded?
    const shouldPreload = useCallback((index) => {
        return index >= activeIndex && index <= activeIndex + PRELOAD_BUFFER;
    }, [activeIndex]);

    // Helper: should this index release its source to save memory?
    const shouldRelease = useCallback((index) => {
        return index < activeIndex - RELEASE_BUFFER;
    }, [activeIndex]);

    return {
        registerRef,
        activateObserver,
        activeIndex,
        shouldPreload,
        shouldRelease,
    };
};

import { useState, useCallback, useEffect } from 'react';
import { supabase, supabaseUrl, supabaseAnonKey } from '../lib/supabase';
import { useAuth } from './useAuth';

export const useCall = (conversationId = null, listenForIncoming = false) => {
    const { user, session } = useAuth();
    const [activeCall, setActiveCall] = useState(null);
    const [incomingCall, setIncomingCall] = useState(null);
    const [callStatus, setCallStatus] = useState('idle');
    const [callType, setCallType] = useState(null);
    const [remoteUserId, setRemoteUserId] = useState(null);
    const [isInitiator, setIsInitiator] = useState(false);

    // Initiate a call
    const initiateCall = useCallback(async (recipientId, type = 'audio', convId = null) => {
        if (!user) return null;

        try {
            console.log(`≡ƒô₧ Initiating ${type} call to:`, recipientId);
            setCallStatus('calling');
            setCallType(type);
            setRemoteUserId(recipientId);
            setIsInitiator(true);

            const targetConvId = convId || conversationId;

            if (!targetConvId) {
                throw new Error('No conversation ID available for call');
            }

            // Create call record
            const response = await fetch(
                `${supabaseUrl}/rest/v1/calls`,
                {
                    method: 'POST',
                    headers: {
                        'apikey': supabaseAnonKey,
                        'Authorization': `Bearer ${session.access_token}`,
                        'Content-Type': 'application/json',
                        'Prefer': 'return=representation'
                    },
                    body: JSON.stringify({
                        conversation_id: targetConvId,
                        caller_id: user.id,
                        receiver_id: recipientId,
                        call_type: type,
                        status: 'ringing',
                        started_at: new Date().toISOString()
                    })
                }
            );

            if (!response.ok) {
                throw new Error(`HTTP ${response.status}`);
            }

            const [call] = await response.json();
            console.log('≡ƒô₧ Call record created:', call.id);

            setActiveCall(call);
            playRingtone();

            return call;
        } catch (err) {
            console.error('Error initiating call:', err);
            setCallStatus('idle');
            setIsInitiator(false);
            return null;
        }
    }, [user, conversationId, session]);

    // Answer incoming call
    const answerCall = useCallback(async (callId, type = 'audio') => {
        try {
            console.log('Γ£à Answering call:', callId, 'Type:', type);

            // Set active call and type
            setActiveCall({ id: callId });
            setCallStatus('active');
            setCallType(type);
            setIsInitiator(false);

            // Update call status in database
            await supabase
                .from('calls')
                .update({ status: 'answered' })
                .eq('id', callId);

            stopRingtone();
            console.log('Γ£à Call answered');
        } catch (err) {
            console.error('Error answering call:', err);
        }
    }, []);

    // Decline incoming call
    const declineCall = useCallback(async (callId) => {
        try {
            console.log('Γ¥î Declining call:', callId);

            await supabase
                .from('calls')
                .update({
                    status: 'rejected',
                    ended_at: new Date().toISOString()
                })
                .eq('id', callId);

            setIncomingCall(null);
            setCallStatus('idle');
            stopRingtone();
        } catch (err) {
            console.error('Error declining call:', err);
        }
    }, []);

    // End active call
    const endCall = useCallback(async () => {
        if (!activeCall) return;

        try {
            console.log('≡ƒô┤ Ending call:', activeCall.id);

            const endTime = new Date();
            const startTime = new Date(activeCall.started_at);
            const duration = Math.floor((endTime - startTime) / 1000);

            await supabase
                .from('calls')
                .update({
                    status: 'ended',
                    ended_at: endTime.toISOString(),
                    duration_seconds: duration
                })
                .eq('id', activeCall.id);

        } catch (err) {
            console.error('Error ending call:', err);
        } finally {
            // ALWAYS clear state, even if DB update fails
            setActiveCall(null);
            setCallStatus('idle');
            setCallType(null);
            setRemoteUserId(null);
            setIsInitiator(false);
            stopRingtone();
        }
    }, [activeCall]);



    // Ringtone helpers
    const playRingtone = () => {
        try {
            if (window.activeRingtone) {
                window.activeRingtone.play().catch(() => { });
                return;
            }

            const audio = new Audio('/sounds/ringtone.mp3');
            audio.loop = true;
            audio.volume = 0.5;
            audio.play().catch(err => {
                // Ignore NotSupportedError (missing file) to prevent console noise
                if (err.name !== 'NotSupportedError') {
                    console.log('Ringtone play failed:', err);
                }
            });
            window.activeRingtone = audio;
        } catch (err) {
            // Ignore errors
        }
    };

    // Listen for incoming calls (if enabled)
    useEffect(() => {
        if (!user || !listenForIncoming) {
            if (!listenForIncoming) {
                console.log('≡ƒôí useCall: NOT setting up call subscription (listenForIncoming is false)');
            }
            return;
        }

        console.log('≡ƒôí useCall: Setting up call subscription');

        const subscription = supabase
            .channel(`calls-${user.id}`)
            .on('postgres_changes',
                {
                    event: 'INSERT',
                    schema: 'public',
                    table: 'calls',
                    filter: `receiver_id=eq.${user.id}`
                },
                (payload) => {
                    console.log('≡ƒöö Incoming call detected:', payload.new);
                    setIncomingCall(payload.new);
                    playRingtone();
                }
            )
            .subscribe();

        return () => {
            subscription.unsubscribe();
            stopRingtone();
        };
    }, [user, listenForIncoming]);

    // Ringtone helpers
    const stopRingtone = () => {
        if (window.activeRingtone) {
            window.activeRingtone.pause();
            window.activeRingtone.currentTime = 0;
            window.activeRingtone = null;
        }
    };

    return {
        activeCall,
        incomingCall,
        callStatus,
        callType,
        isInitiator,
        initiateCall,
        answerCall,
        declineCall,
        endCall,
        // For compatibility
        localStream: null,
        remoteStream: null,
        isConnected: false,
        toggleAudio: () => { },
        toggleVideo: () => { },
        webRTCError: null
    };
};

import { useState, useCallback, useEffect } from 'react';
import { supabase } from '../lib/supabase';

/**
 * Hook for filtering and organizing chats
 * Filter by unread, groups, type, etc.
 */
export const useChatFilters = (userId) => {
    const [activeFilter, setActiveFilter] = useState('all');
    const [unreadCount, setUnreadCount] = useState(0);
    const [groupCount, setGroupCount] = useState(0);

    // Load counts
    useEffect(() => {
        if (userId) {
            loadCounts();
        }
    }, [userId]);

    const loadCounts = useCallback(async () => {
        try {
            // Count unread messages
            const { count: unread } = await supabase
                .from('messages')
                .select('*', { count: 'exact', head: true })
                .eq('receiver_id', userId)
                .is('read_at', null);

            setUnreadCount(unread || 0);

            // Count group chats
            const { count: groups } = await supabase
                .from('group_participants')
                .select('*', { count: 'exact', head: true })
                .eq('user_id', userId);

            setGroupCount(groups || 0);
        } catch (error) {
            console.error('Error loading counts:', error);
        }
    }, [userId]);

    // Filter conversations
    const filterConversations = useCallback((conversations, filter) => {
        switch (filter) {
            case 'unread':
                return conversations.filter(conv => conv.unread_count > 0);
            case 'groups':
                return conversations.filter(conv => conv.type === 'group');
            case 'personal':
                return conversations.filter(conv => conv.type === 'conversation');
            case 'archived':
                return conversations.filter(conv => conv.is_archived);
            default:
                return conversations;
        }
    }, []);

    return {
        activeFilter,
        setActiveFilter,
        unreadCount,
        groupCount,
        filterConversations,
        loadCounts
    };
};

import { useState, useEffect, useRef } from 'react';
import { supabase } from '../lib/supabase';
import { focusToast } from '../utils/focusToast';

export const useChatThread = (currentUserId, conversationId, session) => {
    const [messages, setMessages] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [conversation, setConversation] = useState(null);
    const [participants, setParticipants] = useState([]);
    const subscriptionRef = useRef(null);

    useEffect(() => {
        if (!currentUserId || !conversationId) return;

        fetchConversation();
        fetchMessages();

        // Subscribe to real-time message updates
        subscriptionRef.current = supabase
            .channel(`chat_${conversationId}`)
            .on('postgres_changes', {
                event: 'INSERT',
                schema: 'public',
                table: 'messages',
                filter: `conversation_id=eq.${conversationId}`
            }, handleNewMessage)
            .on('postgres_changes', {
                event: 'UPDATE',
                schema: 'public',
                table: 'messages',
                filter: `conversation_id=eq.${conversationId}`
            }, handleMessageUpdate)
            .on('postgres_changes', {
                event: 'DELETE',
                schema: 'public',
                table: 'messages',
                filter: `conversation_id=eq.${conversationId}`
            }, handleMessageDelete)
            .subscribe();

        return () => {
            if (subscriptionRef.current) {
                subscriptionRef.current.unsubscribe();
            }
        };
    }, [currentUserId, conversationId]);

    const fetchConversation = async () => {
        try {
            console.log('≡ƒöì useChatThread: Fetching conversation:', conversationId);
            // Get conversation details
            const { data: conv, error: convError } = await supabase
                .from('conversations')
                .select('*')
                .eq('id', conversationId)
                .single();

            if (convError) {
                console.error('Γ¥î Error fetching conversation:', convError);
                throw convError;
            }
            console.log('Γ£à Conversation fetched:', conv);
            setConversation(conv);

            // Get participants
            console.log('≡ƒöì Fetching participants for conversation:', conversationId);
            const { data: parts, error: partsError } = await supabase
                .from('conversation_participants')
                .select(`
                    *,
                    profile:user_id (*)
                `)
                .eq('conversation_id', conversationId);

            if (partsError) {
                console.error('Error fetching participants:', partsError);
                throw partsError;
            }

            console.log('≡ƒôï Fetched participants:', parts);
            setParticipants(parts || []);
        } catch (err) {
            console.error('Error fetching conversation:', err);
            setError(err.message);
        }
    };

    const fetchMessages = async () => {
        try {
            setLoading(true);
            console.log('≡ƒô¿ Fetching messages for conversation:', conversationId);

            // Use session passed from parent
            console.log('≡ƒöÉ Using passed session:', session ? 'YES' : 'NO');

            if (!session) {
                console.error('Γ¥î No session for fetch');
                setMessages([]);
                setLoading(false);
                return;
            }

            // Use native Supabase JS SDK
            console.log('≡ƒôí Fetching via SDK...');
            const { data, error: fetchErr } = await supabase
                .from('messages')
                .select('*')
                .eq('conversation_id', conversationId)
                .order('created_at', { ascending: true });

            if (fetchErr) {
                console.error('Γ¥î Fetch error:', fetchErr.message);
                throw new Error(fetchErr.message);
            }

            console.log('≡ƒô¿ Fetch result:', {
                messageCount: data?.length || 0,
                conversationId,
            });

            setMessages(data || []);
            setError(null);

            // Mark messages as read
            await markMessagesAsRead();
        } catch (err) {
            console.error('Error fetching messages:', err);
            setError(err.message);
            focusToast.error('Failed to load messages');
        } finally {
            setLoading(false);
        }
    };

    const markMessagesAsRead = async () => {
        try {
            await supabase.rpc('mark_messages_as_read', {
                p_conversation_id: conversationId,
                p_user_id: currentUserId,
                p_message_id: null
            });
        } catch (err) {
            console.error('Error marking messages as read:', err);
        }
    };

    const handleNewMessage = (payload) => {
        console.log('New message:', payload);
        setMessages(prev => [...prev, payload.new]);
    };

    const handleMessageUpdate = (payload) => {
        console.log('Message updated:', payload);
        setMessages(prev => prev.map(msg =>
            msg.id === payload.new.id ? { ...msg, ...payload.new } : msg
        ));
    };

