import { useState, useCallback } from 'react';
import { useRobustQuery } from './useRobustQuery';
import { useRealtimeSubscription } from './useRealtimeSubscription';
import { generateFeed } from '../utils/feedAlgorithm';
import { useAuth } from './useAuth';

export const useFeed = () => {
    const { user } = useAuth();
    const [posts, setPosts] = useState([]);
    const [page, setPage] = useState(0);
    const [hasMore, setHasMore] = useState(true);
    const [newPostsCount, setNewPostsCount] = useState(0);
    const [moreLoading, setMoreLoading] = useState(false);

    // 1. Initial Fetch with Robust Query
    const fetchInitialFeed = useCallback(async () => {
        if (!user) return [];
        return await generateFeed(user.id, 0, 10);
    }, [user]);

    const {
        data: initialPosts,
        loading: initialLoading,
        error: initialError,
        refetch: refetchInitial
    } = useRobustQuery(fetchInitialFeed, {
        enabled: !!user,
        retries: 3,
        onSuccess: (data) => {
            setPosts(data || []);
            setPage(0);
            setHasMore((data || []).length === 10);
        }
    });

    // 2. Load More (Manual Robust Fetch)
    const loadMore = async () => {
        if (moreLoading || !hasMore || initialLoading) return;
        setMoreLoading(true);

        try {
            const nextPage = page + 1;

            // Simple retry logic for load more
            let attempts = 0;
            let success = false;
            let newItems = [];

            while (attempts < 3 && !success) {
                try {
                    newItems = await generateFeed(user.id, nextPage, 10);
                    success = true;
                } catch (err) {
                    attempts++;
                    await new Promise(r => setTimeout(r, 1000));
                }
            }

            if (success) {
                setPosts(prev => {
                    const existingIds = new Set(prev.map(p => p.id));
                    const unique = newItems.filter(p => !existingIds.has(p.id));
                    return [...prev, ...unique];
                });
                setPage(nextPage);
                setHasMore(newItems.length === 10);
            } else {
                setHasMore(false); // Stop trying if we failed 3 times
            }
        } finally {
            setMoreLoading(false);
        }
    };

    // 3. Realtime Subscription
    useRealtimeSubscription({
        channelName: 'home-feed-updates',
        table: 'posts',
        event: 'INSERT',
        enabled: !!user,
        onEvent: (payload) => {
            setNewPostsCount(prev => prev + 1);
        }
    });

    const refresh = () => {
        setNewPostsCount(0);
        refetchInitial();
    };

    return {
        posts,
        loading: initialLoading || moreLoading,
        error: initialError,
        hasMore,
        loadMore,
        refresh,
        newPostsCount,
        setPosts // Exposed for optimistic updates
    };
};

/**
 * useFocuslyPresence.js
 * =====================
 * Tracks user inactivity and triggers Focusly's "Concerned" mode
 * If user hasn't posted or interacted in 2+ days ΓåÆ Focusly appears worried
 * Generates motivational voice note and sends push notification
 *
 * H2 Innovative ΓÇö Focusly AI: The Living Soul
 */

import { useState, useEffect, useCallback, useRef } from 'react';
import { supabase } from '../lib/supabase';
import { useAuth } from './useAuth';

const INACTIVITY_THRESHOLD_HOURS = 48; // 2 days
const PRESENCE_UPDATE_INTERVAL_MS = 5 * 60 * 1000; // Every 5 mins

export const useFocuslyPresence = () => {
  const { user } = useAuth();
  const [isInactive, setIsInactive] = useState(false);
  const [inactivityHours, setInactivityHours] = useState(0);
  const [nudgeSent, setNudgeSent] = useState(false);
  const [focuslyMood, setFocuslyMood] = useState('neutral'); // reactive Focusly emotion
  const intervalRef = useRef(null);

  // ΓöÇΓöÇ Record user interaction (call this on any meaningful action) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const recordInteraction = useCallback(async () => {
    if (!user?.id) return;
    try {
      await supabase
        .from('focusly_presence')
        .upsert({
          user_id: user.id,
          last_interaction_at: new Date().toISOString(),
          inactivity_nudge_sent: false,
          updated_at: new Date().toISOString(),
        }, { onConflict: 'user_id' });

      setIsInactive(false);
      setFocuslyMood('neutral');
    } catch (err) {
      // Non-blocking
    }
  }, [user?.id]);

  // ΓöÇΓöÇ Record when user makes a post ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const recordPost = useCallback(async () => {
    if (!user?.id) return;
    try {
      await supabase
        .from('focusly_presence')
        .upsert({
          user_id: user.id,
          last_post_at: new Date().toISOString(),
          last_interaction_at: new Date().toISOString(),
          inactivity_nudge_sent: false,
          updated_at: new Date().toISOString(),
        }, { onConflict: 'user_id' });
    } catch (err) { /* non-blocking */ }
  }, [user?.id]);

  // ΓöÇΓöÇ Check inactivity status ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const checkInactivity = useCallback(async () => {
    if (!user?.id) return;
    try {
      const { data, error } = await supabase
        .from('focusly_presence')
        .select('last_interaction_at, last_post_at, inactivity_nudge_sent, nudge_sent_at')
        .eq('user_id', user.id)
        .single();

      if (error || !data) {
        // No presence record ΓÇö user is new, create one
        await recordInteraction();
        return;
      }

      const lastInteraction = new Date(data.last_interaction_at || data.last_post_at || Date.now());
      const hoursSince = (Date.now() - lastInteraction.getTime()) / (1000 * 60 * 60);

      setInactivityHours(Math.round(hoursSince));

      if (hoursSince >= INACTIVITY_THRESHOLD_HOURS) {
        setIsInactive(true);

        // Determine Focusly emotion based on how long they've been away
        if (hoursSince >= 72) {
          setFocuslyMood('idle_nervous'); // 3+ days
        } else {
          setFocuslyMood('sad'); // 2 days ΓÇö concerned
        }

        // Send nudge notification if not already sent
        if (!data.inactivity_nudge_sent) {
          await sendInactivityNudge(hoursSince);

          // Mark nudge as sent
          await supabase
            .from('focusly_presence')
            .update({
              inactivity_nudge_sent: true,
              nudge_sent_at: new Date().toISOString(),
            })
            .eq('user_id', user.id);

          setNudgeSent(true);
        }
      } else {
        setIsInactive(false);
        // Graduated mood ΓÇö slightly concerned if > 24h
        if (hoursSince >= 24) {
          setFocuslyMood('thinking_focus');
        } else {
          setFocuslyMood('neutral');
        }
      }
    } catch (err) {
      // Non-blocking
    }
  }, [user?.id, recordInteraction]);

  // ΓöÇΓöÇ Send inactivity nudge notification ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const sendInactivityNudge = useCallback(async (hoursSince) => {
    if (!user?.id) return;
    try {
      const days = Math.floor(hoursSince / 24);
      const message = days >= 3
        ? `Macha, ${days} days? Focusly has been searching for you ≡ƒªü Your story isn't finished yet.`
        : `Hey! Focusly misses you. It's been ${days > 1 ? `${days} days` : 'over a day'} ΓÇö come share something real. ≡ƒÆ£`;

      // Insert notification
      await supabase.from('notifications').insert({
        user_id: user.id,
        type: 'focusly_nudge',
        title: 'Focusly misses you ≡ƒªü',
        message,
        actor_id: null,
        read: false,
      });
    } catch (err) { /* non-blocking */ }
  }, [user?.id]);

  // ΓöÇΓöÇ Get motivational message based on inactivity duration ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const getMotivationalMessage = useCallback(() => {
    if (inactivityHours >= 72) {
      return {
        title: "Focusly has been worried about you ≡ƒªü",
        message: `It's been ${Math.floor(inactivityHours / 24)} days. Your transformation doesn't pause ΓÇö but we do pause for you. How are you doing today?`,
        cta: "Tell Focusly how you're doing",
        emotion: 'idle_nervous',
      };
    }
    if (inactivityHours >= 48) {
      return {
        title: "Focusly is thinking of you ≡ƒÆ£",
        message: "2 days away... that's okay. Growth happens offline too. But your Focus family is waiting. What's on your mind?",
        cta: "Share something real",
        emotion: 'sad',
      };
    }
    return null;
  }, [inactivityHours]);

