import { useState, useEffect } from 'react';
import { supabase, supabaseUrl, supabaseAnonKey } from '../lib/supabase';
import { useAuth } from './useAuth';

/**
 * Global hook to listen for incoming calls from anywhere in the app
 */
export const useGlobalCallListener = () => {
    const { user, session } = useAuth();
    const [incomingCall, setIncomingCall] = useState(null);

    useEffect(() => {
        if (!user?.id) return;

        console.log('≡ƒîì Setting up GLOBAL call listener for user:', user.id);

        // 1. Realtime Subscription
        const subscription = supabase
            .channel(`global-calls-${user.id}`)
            .on('postgres_changes',
                {
                    event: 'INSERT',
                    schema: 'public',
                    table: 'calls',
                    filter: `receiver_id=eq.${user.id}`
                },
                (payload) => handleIncomingCall(payload.new)
            )
            .subscribe((status) => {
                console.log('≡ƒîì Global call listener status:', status);
            });

        // 2. Polling Fallback (Every 5s)
        const pollInterval = setInterval(async () => {
            try {
                // Check for any 'ringing' calls for me created in the last 10 seconds
                // (To avoid picking up old stuck calls)
                const tenSecondsAgo = new Date(Date.now() - 10000).toISOString();

                const { data, error } = await supabase
                    .from('calls')
                    .select('*')
                    .eq('receiver_id', user.id)
                    .eq('status', 'ringing')
                    .gt('created_at', tenSecondsAgo)
                    .order('created_at', { ascending: false })
                    .limit(1);

                if (data && data.length > 0) {
                    const call = data[0];
                    // Only trigger if we aren't already ringing for this call
                    setIncomingCall(prev => {
                        if (prev && prev.id === call.id) return prev;
                        console.log('≡ƒöä Polling found incoming call:', call);
                        handleIncomingCall(call);
                        return call; // This doesn't actually set state, handleIncomingCall does
                    });
                }
            } catch (err) {
                // Silent error for polling
            }
        }, 5000);

        return () => {
            console.log('≡ƒîì Cleaning up global call listener');
            subscription.unsubscribe();
            clearInterval(pollInterval);
            stopRingtone();
        };
    }, [user?.id, session]);

    const handleIncomingCall = async (callRecord) => {
        try {
            console.log('≡ƒöö GLOBAL: Incoming call detected!', callRecord);

            // Check if we already have this call
            // (Prevent duplicate processing from Realtime + Polling)
            if (incomingCall && incomingCall.id === callRecord.id) return;

            // Fetch caller details using direct REST API
            console.log('≡ƒöì GLOBAL: Fetching caller profile via REST API...');

            let caller = null;

            try {
                const controller = new AbortController();
                const timeoutId = setTimeout(() => controller.abort(), 3000);

                const response = await fetch(
                    `${supabaseUrl}/rest/v1/profiles?id=eq.${callRecord.caller_id}&select=id,username,full_name,avatar_url`,
                    {
                        headers: {
                            'apikey': supabaseAnonKey,
                            'Authorization': `Bearer ${session?.access_token || supabaseAnonKey}`,
                            'Content-Type': 'application/json'
                        },
                        signal: controller.signal
                    }
                );

                clearTimeout(timeoutId);

                if (response.ok) {
                    const data = await response.json();
                    if (data && data.length > 0) {
                        caller = data[0];
                        console.log('Γ£à GLOBAL: Profile fetched successfully:', caller);
                    }
                }
            } catch (fetchError) {
                console.warn('ΓÜá∩╕Å GLOBAL: Profile fetch failed:', fetchError.message);
            }

            // Use fetched caller or fallback
            const callData = {
                ...callRecord,
                caller: caller || {
                    id: callRecord.caller_id,
                    username: 'Unknown User',
                    full_name: 'Unknown User',
                    avatar_url: null
                }
            };

            console.log('≡ƒô▓ GLOBAL: Setting incoming call:', callData);
            setIncomingCall(callData);
            playRingtone();
        } catch (err) {
            console.error('Γ¥î GLOBAL: Error in call listener:', err);
        }
    };

    const acceptCall = async () => {
        console.log('≡ƒöÿ ACCEPT BUTTON CLICKED!');

        if (!incomingCall) {
            console.error('Γ¥î No incoming call!');
            return null;
        }

        console.log('≡ƒô₧ Accepting call:', incomingCall.id);
        console.log('≡ƒô₧ Conversation:', incomingCall.conversation_id);

        try {
            console.log('≡ƒÆ╛ Updating call status...');

            const response = await fetch(
                `${supabaseUrl}/rest/v1/calls?id=eq.${incomingCall.id}`,
                {
                    method: 'PATCH',
                    headers: {
                        'apikey': supabaseAnonKey,
                        'Authorization': `Bearer ${session?.access_token || supabaseAnonKey}`,
                        'Content-Type': 'application/json'
                    },
                    body: JSON.stringify({ status: 'answered' })
                }
            );

            console.log('≡ƒôÑ Update response:', response.status);

            if (response.ok) {
                console.log('Γ£à Call status updated!');
            } else {
                const errorText = await response.text();
                console.error('Γ¥î Update failed:', response.status, errorText);
            }
        } catch (err) {
            console.error('Γ¥î Error updating call:', err);
        }

        const callData = { ...incomingCall };

        // Store call data in localStorage so ChatPane can pick it up
        console.log('≡ƒÆ╛ Storing call data in localStorage...');
        localStorage.setItem('pendingCall', JSON.stringify({
            ...callData,
            role: 'receiver',
            timestamp: Date.now()
        }));

        setIncomingCall(null);
        stopRingtone();

        // Navigate to conversation
        if (incomingCall.conversation_id) {
            console.log('≡ƒº¡ Navigating to:', `/messages/${incomingCall.conversation_id}`);
            window.location.href = `/messages/${incomingCall.conversation_id}`;
        } else {
            console.warn('ΓÜá∩╕Å No conversation_id!');
        }

        return callData;
    };

    const declineCall = async () => {
        console.log('≡ƒöÿ DECLINE BUTTON CLICKED!');

        if (!incomingCall) return;

        console.log('Γ¥î Declining call:', incomingCall.id);

        try {
            const response = await fetch(
                `${supabaseUrl}/rest/v1/calls?id=eq.${incomingCall.id}`,
                {
                    method: 'PATCH',
                    headers: {
                        'apikey': supabaseAnonKey,
                        'Authorization': `Bearer ${session?.access_token || supabaseAnonKey}`,
                        'Content-Type': 'application/json'
                    },
                    body: JSON.stringify({
                        status: 'rejected',
                        ended_at: new Date().toISOString()
                    })
                }
            );

            if (response.ok) {
                console.log('Γ£à Call declined successfully');
            } else {
                const errorText = await response.text();
                console.error('Γ¥î Decline failed:', response.status, errorText);
            }
        } catch (err) {
            console.error('Γ¥î Error declining call:', err);
        }

        setIncomingCall(null);
        stopRingtone();
    };

    return {
        incomingCall,
        acceptCall,
        declineCall
    };
};

// Ringtone helpers
const playRingtone = () => {
    try {
        if (window.globalRingtone) {
            window.globalRingtone.play();
            return;
        }

        const audio = new Audio('/sounds/ringtone.mp3');
        audio.loop = true;
        audio.volume = 0.5;
        audio.play().catch(err => console.log('Ringtone play failed:', err));
        window.globalRingtone = audio;
    } catch (err) {
        console.error('Error playing ringtone:', err);
    }
};

const stopRingtone = () => {
    if (window.globalRingtone) {
        window.globalRingtone.pause();
        window.globalRingtone.currentTime = 0;
        window.globalRingtone = null;
    }
};

import { useState, useCallback } from 'react';
import { supabase } from '../lib/supabase';
import { focusToast } from '../utils/focusToast';

/**
 * Hook for creating and managing events in group chats
 * WhatsApp-style events with RSVP tracking
 */
export const useGroupEvents = (groupId) => {
    const [loading, setLoading] = useState(false);
    const [events, setEvents] = useState([]);

    // Create an event
    const createEvent = useCallback(async (eventData, creatorId) => {
        if (!eventData.title || !eventData.date) {
            focusToast.error('Event must have a title and date');
            return null;
        }

        setLoading(true);
        try {
            const event = {
                group_id: groupId,
                sender_id: creatorId,
                message_type: 'event',
                content: eventData.title,
                event_data: {
                    title: eventData.title,
                    description: eventData.description || '',
                    date: eventData.date,
                    time: eventData.time || null,
                    location: eventData.location || null,
                    created_by: creatorId,
                    created_at: new Date().toISOString(),
                    rsvp: {
                        going: [],
                        maybe: [],
                        not_going: []
                    }
                }
            };

            const { data, error } = await supabase
                .from('group_messages')
                .insert(event)
                .select()
                .single();

            if (error) throw error;

            focusToast.success('Event created');
            return data;
        } catch (error) {
            console.error('Error creating event:', error);
            focusToast.error('Failed to create event');
            return null;
        } finally {
            setLoading(false);
        }
    }, [groupId]);

    // RSVP to an event
    const rsvpEvent = useCallback(async (messageId, userId, response) => {
        setLoading(true);
        try {
            // Get current event data
            const { data: message, error: fetchError } = await supabase
                .from('group_messages')
                .select('event_data')
                .eq('id', messageId)
                .single();

            if (fetchError) throw fetchError;

            const eventData = message.event_data;

            // Remove user from all RSVP lists
            eventData.rsvp.going = eventData.rsvp.going.filter(id => id !== userId);
            eventData.rsvp.maybe = eventData.rsvp.maybe.filter(id => id !== userId);
            eventData.rsvp.not_going = eventData.rsvp.not_going.filter(id => id !== userId);

            // Add to selected list
            if (response === 'going') {
                eventData.rsvp.going.push(userId);
            } else if (response === 'maybe') {
                eventData.rsvp.maybe.push(userId);
            } else if (response === 'not_going') {
                eventData.rsvp.not_going.push(userId);
            }

            // Update event
            const { error: updateError } = await supabase
                .from('group_messages')
                .update({ event_data: eventData })
                .eq('id', messageId);

            if (updateError) throw updateError;

            focusToast.success('RSVP updated');
            return true;
        } catch (error) {
            console.error('Error RSVP to event:', error);
            focusToast.error('Failed to RSVP');
            return false;
        } finally {
            setLoading(false);
        }
    }, []);

    // Get event summary
    const getEventSummary = useCallback((eventData) => {
        const total = eventData.rsvp.going.length +
            eventData.rsvp.maybe.length +
            eventData.rsvp.not_going.length;

        return {
            going: eventData.rsvp.going.length,
            maybe: eventData.rsvp.maybe.length,
            not_going: eventData.rsvp.not_going.length,
            total,
            percentage: total > 0 ? (eventData.rsvp.going.length / total) * 100 : 0
        };
    }, []);

    // Check user's RSVP status
    const getUserRSVP = useCallback((eventData, userId) => {
        if (eventData.rsvp.going.includes(userId)) return 'going';
        if (eventData.rsvp.maybe.includes(userId)) return 'maybe';
        if (eventData.rsvp.not_going.includes(userId)) return 'not_going';
        return null;
    }, []);

    // Format event date
    const formatEventDate = useCallback((date, time) => {
        const eventDate = new Date(date);
        const options = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
        let formatted = eventDate.toLocaleDateString('en-US', options);

        if (time) {
            formatted += ` at ${time}`;
        }

        return formatted;
    }, []);

    return {
        loading,
        events,
        createEvent,
        rsvpEvent,
        getEventSummary,
        getUserRSVP,
        formatEventDate
    };
};

import { useState, useCallback, useEffect } from 'react';
import { supabase } from '../lib/supabase';
import { focusToast } from '../utils/focusToast';

/**
 * Hook for creating and managing polls in group chats
 * WhatsApp-style polls with multiple options
 */
export const useGroupPolls = (groupId) => {
    const [polls, setPolls] = useState([]);
    const [loading, setLoading] = useState(false);

    // Create a poll
    const createPoll = useCallback(async (question, options, senderId) => {
        if (!question || !options || options.length < 2) {
            focusToast.error('Poll must have a question and at least 2 options');
            return null;
        }

        setLoading(true);
        try {
            // Create poll message
            const pollData = {
                group_id: groupId,
                sender_id: senderId,
                message_type: 'poll',
                content: question,
                poll_data: {
                    question,
                    options: options.map((opt, index) => ({
                        id: index,
                        text: opt,
                        votes: []
                    })),
                    created_at: new Date().toISOString(),
                    multiple_answers: false
                }
            };

            const { data, error } = await supabase
                .from('group_messages')
                .insert(pollData)
                .select()
                .single();

            if (error) throw error;

            focusToast.success('Poll created');
            return data;
        } catch (error) {
            console.error('Error creating poll:', error);
            focusToast.error('Failed to create poll');
            return null;
        } finally {
            setLoading(false);
        }
    }, [groupId]);

    // Vote on a poll
    const votePoll = useCallback(async (messageId, optionId, userId) => {
        setLoading(true);
        try {
            // Get current poll data
            const { data: message, error: fetchError } = await supabase
                .from('group_messages')
                .select('poll_data')
                .eq('id', messageId)
                .single();

            if (fetchError) throw fetchError;

            const pollData = message.poll_data;

            // Remove user's previous votes if not multiple choice
            if (!pollData.multiple_answers) {
                pollData.options.forEach(option => {
                    option.votes = option.votes.filter(v => v !== userId);
                });
            }

            // Add new vote
            const option = pollData.options.find(opt => opt.id === optionId);
            if (option && !option.votes.includes(userId)) {
                option.votes.push(userId);
            }

            // Update poll
            const { error: updateError } = await supabase
                .from('group_messages')
                .update({ poll_data: pollData })
                .eq('id', messageId);

            if (updateError) throw updateError;

            focusToast.success('Vote recorded');
            return true;
        } catch (error) {
            console.error('Error voting on poll:', error);
            focusToast.error('Failed to vote');
            return false;
        } finally {
            setLoading(false);
        }
    }, []);

    // Get poll results
    const getPollResults = useCallback((pollData) => {
        const totalVotes = pollData.options.reduce((sum, opt) => sum + opt.votes.length, 0);

        return pollData.options.map(option => ({
            ...option,
            voteCount: option.votes.length,
            percentage: totalVotes > 0 ? (option.votes.length / totalVotes) * 100 : 0
        }));
    }, []);

    // Check if user has voted
    const hasUserVoted = useCallback((pollData, userId) => {
        return pollData.options.some(option => option.votes.includes(userId));
    }, []);

    return {
        polls,
        loading,
        createPoll,
        votePoll,
        getPollResults,
        hasUserVoted
    };
};

/**
 * useGuardianship Hook
 * Manages guardian-teen relationships
 */

import { useState, useEffect } from 'react';
import { supabase } from '../lib/supabase';
import { useAuth } from './useAuth';

export const useGuardianship = () => {
    const { user } = useAuth();
    const [guardians, setGuardians] = useState([]);
    const [teens, setTeens] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    // Fetch guardians (if current user is a teen)
    const fetchGuardians = async () => {
        if (!user) return;

        try {
            const { data, error: fetchError } = await supabase
                .from('guardian_relationships')
                .select(`
          *,
          parent:parent_id (
            id,
            email,
            username,
            full_name,
            avatar_url
          )
        `)
                .eq('teen_id', user.id)
                .eq('status', 'active');

            if (fetchError) throw fetchError;
            setGuardians(data || []);
        } catch (err) {
            console.error('Error fetching guardians:', err);
            setError(err.message);
        }
    };

    // Fetch teens (if current user is a guardian)
    const fetchTeens = async () => {
        if (!user) {
            console.log('ΓÜá∩╕Å useGuardianship: No user found');
            setTeens([]);
            return;
        }

        try {
            console.log('≡ƒöì Fetching teens for guardian:', user.id);
            const { data, error: fetchError } = await supabase
                .from('guardian_relationships')
                .select(`
          *,
          teen:teen_id (
            id,
            email,
            username,
            full_name,
            avatar_url,
            age_verification (
              birth_date,
              is_coppa_mode,
              is_teen_mode
            )
          )
        `)
                .eq('parent_id', user.id)
                .in('status', ['active', 'pending']);

            if (fetchError) {
                console.error('Γ¥î Error fetching teens:', fetchError);
                throw fetchError;
            }

            console.log('Γ£à Teens fetched:', data?.length || 0, data);
            setTeens(data || []);
        } catch (err) {
            console.error('Γ¥î Error fetching teens:', err);
            setError(err.message);
            setTeens([]);
        }
    };

    // Send guardian invitation
    const sendInvitation = async (teenEmail, relationshipType = 'parent') => {
        if (!user) throw new Error('Not authenticated');

        try {
            // Generate invitation code
            const invitationCode = `INV-${Math.random().toString(36).substring(2, 15)}`;
            const expiresAt = new Date();
            expiresAt.setDate(expiresAt.getDate() + 7); // 7 days expiry

            // Find teen by email
            const { data: teenData, error: teenError } = await supabase
                .from('users')
                .select('id')
                .eq('email', teenEmail)
                .single();

            if (teenError) throw new Error('Teen not found with this email');

            // Create pending relationship
            const { data, error: insertError } = await supabase
                .from('guardian_relationships')
                .insert({
                    parent_id: user.id,
                    teen_id: teenData.id,
                    relationship_type: relationshipType,
                    status: 'pending',
                    invitation_code: invitationCode,
                    invitation_sent_at: new Date().toISOString(),
                    invitation_expires_at: expiresAt.toISOString()
                })
                .select()
                .single();

            if (insertError) throw insertError;

            // TODO: Send email notification to teen with invitation
            // await sendInvitationEmail(teenEmail, invitationCode);

            return { success: true, data };
        } catch (err) {
            console.error('Error sending invitation:', err);
            throw err;
        }
    };

    // Accept guardian invitation
    const acceptInvitation = async (relationshipId) => {
        if (!user) throw new Error('Not authenticated');

        try {
            const { data, error: updateError } = await supabase
                .from('guardian_relationships')
                .update({
                    status: 'active',
                    approved_at: new Date().toISOString()
                })
                .eq('id', relationshipId)
                .eq('teen_id', user.id)
                .eq('status', 'pending')
                .select()
                .single();

            if (updateError) throw updateError;

            // Log consent
            await supabase.from('consent_log').insert({
                user_id: user.id,
                consent_type: 'guardian_linking',
                consented_by: user.id,
                consent_given: true
            });

            await fetchGuardians();
            return { success: true, data };
        } catch (err) {
            console.error('Error accepting invitation:', err);
            throw err;
        }
    };

    // Reject guardian invitation
    const rejectInvitation = async (relationshipId) => {
        if (!user) throw new Error('Not authenticated');

        try {
            const { error: updateError } = await supabase
                .from('guardian_relationships')
                .update({ status: 'revoked' })
                .eq('id', relationshipId)
                .eq('teen_id', user.id);

            if (updateError) throw updateError;

            await fetchGuardians();
            return { success: true };
        } catch (err) {
            console.error('Error rejecting invitation:', err);
            throw err;
        }
    };

    // Remove guardian (teen removes guardian at 18+)
    const removeGuardian = async (relationshipId) => {
        if (!user) throw new Error('Not authenticated');

        try {
            // Check if user is 18+
            const { data: ageData } = await supabase
                .from('age_verification')
                .select('is_adult')
                .eq('user_id', user.id)
                .single();

            if (!ageData?.is_adult) {
                throw new Error('Only adults (18+) can remove guardians');
            }

            const { error: updateError } = await supabase
                .from('guardian_relationships')
                .update({
                    status: 'revoked',
                    revoked_at: new Date().toISOString(),
                    revoked_by: user.id,
                    revoke_reason: 'Removed by user (18+)'
                })
                .eq('id', relationshipId)
                .eq('teen_id', user.id);

            if (updateError) throw updateError;

            await fetchGuardians();
            return { success: true };
        } catch (err) {
            console.error('Error removing guardian:', err);
            throw err;
        }
    };

    // Check if user has permission
    const hasPermission = (relationship, permission) => {
        if (!relationship?.permissions) return false;
        return relationship.permissions[permission] === true;
    };

    // Update guardian permissions (guardian can modify)
    const updatePermissions = async (relationshipId, newPermissions) => {
        if (!user) throw new Error('Not authenticated');

        try {
            const { data, error: updateError } = await supabase
                .from('guardian_relationships')
                .update({ permissions: newPermissions })
                .eq('id', relationshipId)
                .eq('parent_id', user.id)
                .select()
                .single();

            if (updateError) throw updateError;

            await fetchTeens();
            return { success: true, data };
        } catch (err) {
            console.error('Error updating permissions:', err);
            throw err;
        }
    };

    // Subscribe to realtime changes
    useEffect(() => {
        if (!user) return;

        const fetchData = async () => {
            setLoading(true);
            await Promise.all([fetchGuardians(), fetchTeens()]);
            setLoading(false);
        };

        fetchData();

        // Realtime subscription
        const subscription = supabase
            .channel('guardian_relationships_changes')
            .on(
                'postgres_changes',
                {
                    event: '*',
                    schema: 'public',
                    table: 'guardian_relationships',
                    filter: `teen_id=eq.${user.id},parent_id=eq.${user.id}`
                },
                () => {
                    fetchData();
                }
            )
            .subscribe();

        return () => {
            subscription.unsubscribe();
        };
    }, [user]);

    return {
        guardians,
        teens,
        loading,
        error,
        sendInvitation,
        acceptInvitation,
        rejectInvitation,
        removeGuardian,
        hasPermission,
        updatePermissions,
        refetch: () => Promise.all([fetchGuardians(), fetchTeens()])
    };
};

import { useState, useEffect } from 'react';
import { supabase } from '../lib/supabase';
import { useAuth } from './useAuth';

/**
 * Hook to fetch and manage linked OAuth accounts
 * @returns {Object} { linkedAccounts, loading, unlinkAccount }
 */
export const useLinkedAccounts = () => {
    const { user } = useAuth();
    const [linkedAccounts, setLinkedAccounts] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    useEffect(() => {
        if (!user) {
            setLinkedAccounts([]);
            setLoading(false);
            return;
        }

        fetchLinkedAccounts();

        // Subscribe to real-time changes
        const channel = supabase
            .channel(`linked-accounts-${user.id}`)
            .on('postgres_changes', {
                event: '*',
                schema: 'public',
                table: 'linked_accounts',
                filter: `user_id=eq.${user.id}`
            }, (payload) => {
                console.log('≡ƒöù Linked accounts updated:', payload);
                fetchLinkedAccounts();
            })
            .subscribe();

        return () => {
            channel.unsubscribe();
        };
    }, [user]);

    const fetchLinkedAccounts = async () => {
        try {
            setLoading(true);
            console.log('≡ƒöù Fetching linked accounts...');

            const { data, error: fetchError } = await supabase
                .from('linked_accounts')
                .select('*')
                .eq('user_id', user.id)
                .order('connected_at', { ascending: false });

            if (fetchError) throw fetchError;

            console.log('Γ£à Linked accounts fetched:', data?.length || 0);
            setLinkedAccounts(data || []);
            setError(null);
        } catch (err) {
            console.error('Γ¥î Error fetching linked accounts:', err);
            setError(err.message);
            setLinkedAccounts([]);
        } finally {
            setLoading(false);
        }
    };

    const unlinkAccount = async (provider) => {
        try {
            const { error } = await supabase
                .from('linked_accounts')
                .delete()
                .eq('user_id', user.id)
                .eq('provider', provider);

            if (error) throw error;

            console.log('Γ£à Account unlinked successfully');
            setLinkedAccounts(prev => prev.filter(a => a.provider !== provider));
            return { success: true };
        } catch (err) {
            console.error('Γ¥î Error unlinking account:', err);
            return { success: false, error: err.message };
        }
    };

    return { linkedAccounts, loading, error, unlinkAccount, refetch: fetchLinkedAccounts };
};

import { useState, useCallback, useEffect } from 'react';
import { supabase } from '../lib/supabase';
import { focusToast } from '../utils/focusToast';

/**
 * Hook for locking chats with biometric/PIN
 * WhatsApp-style chat locking
 */
export const useLockedChats = (userId) => {
    const [lockedChats, setLockedChats] = useState([]);
    const [masterPin, setMasterPin] = useState(null);
    const [isUnlocked, setIsUnlocked] = useState(false);

    // Load locked chats
    useEffect(() => {
        if (userId) {
            loadLockedChats();
        }
    }, [userId]);

    const loadLockedChats = useCallback(async () => {
        try {
            const { data, error } = await supabase
                .from('profiles')
                .select('locked_chats, chat_lock_pin')
                .eq('id', userId)
                .single();

            if (error) throw error;

            setLockedChats(data.locked_chats || []);
            setMasterPin(data.chat_lock_pin);
        } catch (error) {
            console.error('Error loading locked chats:', error);
        }
    }, [userId]);

    // Set master PIN
    const setPin = useCallback(async (pin) => {
        try {
            const { error } = await supabase
                .from('profiles')
                .update({ chat_lock_pin: pin })
                .eq('id', userId);

            if (error) throw error;

            setMasterPin(pin);
            focusToast.success('PIN set successfully');
            return true;
        } catch (error) {
            console.error('Error setting PIN:', error);
            focusToast.error('Failed to set PIN');
            return false;
        }
    }, [userId]);

    // Lock a chat
    const lockChat = useCallback(async (chatId) => {
        if (!masterPin) {
            focusToast.error('Please set a PIN first');
            return false;
        }

        try {
            const newLocked = [...lockedChats, chatId];

            const { error } = await supabase
                .from('profiles')
                .update({ locked_chats: newLocked })
                .eq('id', userId);

            if (error) throw error;

            setLockedChats(newLocked);
            focusToast.success('Chat locked');
            return true;
        } catch (error) {
            console.error('Error locking chat:', error);
            focusToast.error('Failed to lock chat');
            return false;
        }
    }, [lockedChats, masterPin, userId]);

    // Unlock a chat
    const unlockChat = useCallback(async (chatId) => {
        try {
            const newLocked = lockedChats.filter(id => id !== chatId);

            const { error } = await supabase
                .from('profiles')
                .update({ locked_chats: newLocked })
                .eq('id', userId);

            if (error) throw error;

            setLockedChats(newLocked);
            focusToast.success('Chat unlocked');
            return true;
        } catch (error) {
            console.error('Error unlocking chat:', error);
            focusToast.error('Failed to unlock chat');
            return false;
        }
    }, [lockedChats, userId]);

    // Verify PIN
    const verifyPin = useCallback((inputPin) => {
        if (inputPin === masterPin) {
            setIsUnlocked(true);
            return true;
        }
        focusToast.error('Incorrect PIN');
        return false;
    }, [masterPin]);

    // Check if chat is locked
    const isLocked = useCallback((chatId) => {
        return lockedChats.includes(chatId);
    }, [lockedChats]);

    // Request biometric authentication
    const requestBiometric = useCallback(async () => {
        // This would integrate with browser's Web Authentication API
        // For now, we'll use PIN as fallback
        return new Promise((resolve) => {
            // Simulated biometric check
            resolve(isUnlocked);
        });
    }, [isUnlocked]);

    return {
        lockedChats,
        masterPin,
        isUnlocked,
        setPin,
        lockChat,
        unlockChat,
        verifyPin,
        isLocked,
        requestBiometric
    };
};

import { useState, useCallback } from 'react';
import { supabase } from '../lib/supabase';
import { focusToast } from '../utils/focusToast';

/**
 * Hook for editing messages
 * Supports 15-minute edit window like Instagram
 * Tracks edit history in database
 */
export const useMessageEdit = () => {
    const [editing, setEditing] = useState(false);

    // Check if message can be edited (within 15 minutes)
    const canEdit = useCallback((message, currentUserId) => {
        if (!message || message.sender_id !== currentUserId) return false;
        if (message.is_deleted) return false;

        const messageTime = new Date(message.created_at);
        const now = new Date();
        const diffMinutes = (now - messageTime) / 1000 / 60;

        return diffMinutes <= 15; // 15-minute edit window
    }, []);

    // Edit a message
    const editMessage = useCallback(async (messageId, newContent, originalContent) => {
        if (!messageId || !newContent || !newContent.trim()) {
            focusToast.error('Message content cannot be empty');
            return false;
        }

        if (newContent.trim() === originalContent?.trim()) {
            focusToast.info('No changes made');
            return false;
        }

        setEditing(true);
        try {
            // Save to edit history first
            const { error: historyError } = await supabase
                .from('message_edit_history')
                .insert({
                    message_id: messageId,
                    previous_content: originalContent,
                    edited_at: new Date().toISOString()
                });

            if (historyError) {
                console.error('Failed to save edit history:', historyError);
                // Continue anyway - edit history is optional
            }

            // Update the message
            const { data, error } = await supabase
                .from('messages')
                .update({
                    content: newContent.trim(),
                    is_edited: true,
                    edited_at: new Date().toISOString()
                })
                .eq('id', messageId)
                .select()
                .single();

            if (error) throw error;

            focusToast.success('Message edited successfully');
            return true;
        } catch (error) {
            console.error('Error editing message:', error);
            focusToast.error('Failed to edit message');
            return false;
        } finally {
            setEditing(false);
        }
    }, []);

    // Edit a group message
    const editGroupMessage = useCallback(async (messageId, newContent, originalContent) => {
        if (!messageId || !newContent || !newContent.trim()) {
            focusToast.error('Message content cannot be empty');
            return false;
        }

        if (newContent.trim() === originalContent?.trim()) {
            focusToast.info('No changes made');
            return false;
        }

        setEditing(true);
        try {
            // Save to edit history
            const { error: historyError } = await supabase
                .from('message_edit_history')
                .insert({
                    group_message_id: messageId,
                    previous_content: originalContent,
                    edited_at: new Date().toISOString()
                });

            if (historyError) {
                console.error('Failed to save edit history:', historyError);
            }

            // Update the group message
            const { data, error } = await supabase
                .from('group_messages')
                .update({
                    content: newContent.trim(),
                    is_edited: true,
                    edited_at: new Date().toISOString()
                })
                .eq('id', messageId)
                .select()
                .single();

            if (error) throw error;

            focusToast.success('Message edited successfully');
            return true;
        } catch (error) {
            console.error('Error editing group message:', error);
            focusToast.error('Failed to edit message');
            return false;
        } finally {
            setEditing(false);
        }
    }, []);

    // Get edit history for a message
    const getEditHistory = useCallback(async (messageId, isGroupMessage = false) => {
        try {
            const column = isGroupMessage ? 'group_message_id' : 'message_id';
            const { data, error } = await supabase
                .from('message_edit_history')
                .select('*')
                .eq(column, messageId)
                .order('edited_at', { ascending: false });

            if (error) throw error;
            return data || [];
        } catch (error) {
            console.error('Error fetching edit history:', error);
            return [];
        }
    }, []);

    return {
        editing,
        canEdit,
        editMessage,
        editGroupMessage,
        getEditHistory
    };
};

import { useState, useCallback } from 'react';
import { supabase } from '../lib/supabase';
import { focusToast } from '../utils/focusToast';

/**
 * Hook for forwarding messages
 * Supports forwarding to multiple chats (1-on-1 and groups)
 * Tracks forward count like WhatsApp
 */
export const useMessageForward = () => {
    const [forwarding, setForwarding] = useState(false);

    // Forward message to 1-on-1 conversation
    const forwardToConversation = useCallback(async (originalMessage, recipientId, currentUserId) => {
        if (!originalMessage || !recipientId || !currentUserId) return false;

        try {
            // Create new message with forwarded flag
            const { data, error } = await supabase
                .from('messages')
                .insert({
                    sender_id: currentUserId,
                    receiver_id: recipientId,
                    content: originalMessage.content || '',
                    message_type: originalMessage.message_type || 'text',
                    attachments: originalMessage.attachments || [],
                    forwarded_from: originalMessage.id,
                    forward_count: (originalMessage.forward_count || 0) + 1
                })
                .select()
                .single();

            if (error) throw error;

            // Update original message forward count
            await supabase
                .from('messages')
                .update({
                    forward_count: (originalMessage.forward_count || 0) + 1
                })
                .eq('id', originalMessage.id);

            return true;
        } catch (error) {
            console.error('Error forwarding to conversation:', error);
            throw error;
        }
    }, []);

    // Forward message to group
    const forwardToGroup = useCallback(async (originalMessage, groupId, currentUserId) => {
        if (!originalMessage || !groupId || !currentUserId) return false;

        try {
            // Create new group message with forwarded flag
            const { data, error } = await supabase
                .from('group_messages')
                .insert({
                    group_id: groupId,
                    sender_id: currentUserId,
                    content: originalMessage.content || '',
                    message_type: originalMessage.message_type || 'text',
                    attachments: originalMessage.attachments || [],
                    forwarded_from: originalMessage.id
                })
                .select()
                .single();

            if (error) throw error;

            // Update original message forward count
            const tableName = originalMessage.group_id ? 'group_messages' : 'messages';
            await supabase
                .from(tableName)
                .update({
                    forward_count: (originalMessage.forward_count || 0) + 1
                })
                .eq('id', originalMessage.id);

            return true;
        } catch (error) {
            console.error('Error forwarding to group:', error);
            throw error;
        }
    }, []);

    // Forward to multiple recipients
    const forwardToMultiple = useCallback(async (originalMessage, recipients, currentUserId) => {
        if (!originalMessage || !recipients || recipients.length === 0) {
            focusToast.error('Please select at least one recipient');
            return false;
        }

        setForwarding(true);
        let successCount = 0;
        let failCount = 0;

        try {
            for (const recipient of recipients) {
                try {
                    if (recipient.type === 'user') {
                        await forwardToConversation(originalMessage, recipient.id, currentUserId);
                        successCount++;
                    } else if (recipient.type === 'group') {
                        await forwardToGroup(originalMessage, recipient.id, currentUserId);
                        successCount++;
                    }
                } catch (error) {
                    console.error(`Failed to forward to ${recipient.type} ${recipient.id}:`, error);
                    failCount++;
                }
            }

            if (successCount > 0) {
                focusToast.success(`Message forwarded to ${successCount} ${successCount === 1 ? 'chat' : 'chats'}`);
            }
            if (failCount > 0) {
                focusToast.error(`Failed to forward to ${failCount} ${failCount === 1 ? 'chat' : 'chats'}`);
            }

            return successCount > 0;
        } catch (error) {
            console.error('Error forwarding messages:', error);
            focusToast.error('Failed to forward message');
            return false;
        } finally {
            setForwarding(false);
        }
    }, [forwardToConversation, forwardToGroup]);

    // Get list of conversations for forwarding
    const getForwardableChats = useCallback(async (currentUserId) => {
        if (!currentUserId) return [];

        try {
            // Get 1-on-1 conversations
            const { data: conversations, error: convError } = await supabase
                .from('conversations')
                .select(`
                    id,
                    user1_id,
                    user2_id,
                    profiles!conversations_user1_id_fkey (
                        id,
                        username,
                        full_name,
                        avatar_url
                    )
                `)
                .or(`user1_id.eq.${currentUserId},user2_id.eq.${currentUserId}`)
                .order('updated_at', { ascending: false });

            if (convError) throw convError;

            // Get group conversations
            const { data: groups, error: groupError } = await supabase
                .from('group_participants')
                .select(`
                    group_conversations (
                        id,
                        name,
                        avatar_url,
                        description
                    )
                `)
                .eq('user_id', currentUserId)
                .order('joined_at', { ascending: false });

            if (groupError) throw groupError;

            // Format conversations
            const formattedConvs = (conversations || []).map(conv => {
                const otherUserId = conv.user1_id === currentUserId ? conv.user2_id : conv.user1_id;
                return {
                    id: otherUserId,
                    type: 'user',
                    name: conv.profiles?.full_name || conv.profiles?.username || 'Unknown',
                    username: conv.profiles?.username,
                    avatar: conv.profiles?.avatar_url,
                    conversationId: conv.id
                };
            });

            // Format groups
            const formattedGroups = (groups || [])
                .filter(g => g.group_conversations)
                .map(g => ({
                    id: g.group_conversations.id,
                    type: 'group',
                    name: g.group_conversations.name,
                    avatar: g.group_conversations.avatar_url,
                    description: g.group_conversations.description
                }));

            return [...formattedConvs, ...formattedGroups];
        } catch (error) {
            console.error('Error fetching forwardable chats:', error);
            return [];
        }
    }, []);

    return {
        forwarding,
        forwardToConversation,
        forwardToGroup,
        forwardToMultiple,
        getForwardableChats
    };
};

import { useState, useEffect, useCallback } from 'react';
import { supabase } from '../lib/supabase';

/**
 * Hook for managing message delivery and read status
 * Implements WhatsApp/Instagram-style message ticks:
 * - Single gray tick: Sent
 * - Double gray ticks: Delivered
 * - Double blue ticks: Read
 */
export const useMessageStatus = (conversationId, currentUserId) => {
    const [messageStatuses, setMessageStatuses] = useState({});

    // Mark message as delivered
    const markAsDelivered = useCallback(async (messageId) => {
        if (!messageId || !currentUserId) return;

        try {
            const { error } = await supabase
                .from('messages')
                .update({
                    is_delivered: true,
                    delivered_at: new Date().toISOString()
                })
                .eq('id', messageId)
                .neq('sender_id', currentUserId); // Don't mark own messages

            if (error) throw error;
            await supabase.channel(`message-status:${conversationId}`).send({
                type: 'broadcast',
                event: 'message_read',
                payload: { messageId, readerId: currentUserId, readAt: new Date().toISOString() }
            });

            // Update local state
            setMessageStatuses(prev => ({
                ...prev,
                [messageId]: { ...prev[messageId], is_delivered: true }
            }));
        } catch (error) {
            console.error('Error marking message as delivered:', error);
        }
    }, [currentUserId]);

    // Mark message as read
    const markAsRead = useCallback(async (messageId) => {
        if (!messageId || !currentUserId) return;

        try {
            const { error } = await supabase
                .from('messages')
                .update({
                    is_read: true,
                    is_delivered: true, // Auto-mark as delivered when read
                    read_at: new Date().toISOString(),
                    delivered_at: new Date().toISOString()
                })
                .eq('id', messageId)
                .neq('sender_id', currentUserId); // Don't mark own messages

            if (error) throw error;

            // Update local state
            setMessageStatuses(prev => ({
                ...prev,
                [messageId]: { is_delivered: true, is_read: true }
            }));
        } catch (error) {
            console.error('Error marking message as read:', error);
        }
    }, [currentUserId]);

    // Mark all messages in conversation as read
    const markAllAsRead = useCallback(async () => {
        if (!conversationId || !currentUserId) return;

        try {
            const { error } = await supabase
                .from('messages')
                .update({
                    is_read: true,
                    is_delivered: true,
                    read_at: new Date().toISOString(),
                    delivered_at: new Date().toISOString()
                })
                .eq('conversation_id', conversationId)
                .eq('is_read', false)
                .neq('sender_id', currentUserId);

            if (error) throw error;
            await supabase.channel(`message-status:${conversationId}`).send({
                type: 'broadcast',
                event: 'conversation_read',
                payload: { conversationId, readerId: currentUserId, readAt: new Date().toISOString() }
            });
        } catch (error) {
            console.error('Error marking all messages as read:', error);
        }
    }, [conversationId, currentUserId]);

    // Subscribe to real-time status updates
    useEffect(() => {
        if (!conversationId) return;

        const channel = supabase
            .channel(`message-status:${conversationId}`)
            .on(
                'postgres_changes',
                {
                    event: 'UPDATE',
                    schema: 'public',
                    table: 'messages',
                    filter: `conversation_id=eq.${conversationId}`
                },
                (payload) => {
                    const { id, is_delivered, is_read } = payload.new;
                    setMessageStatuses(prev => ({
                        ...prev,
                        [id]: { is_delivered, is_read }
                    }));
                }
            )
            .on('broadcast', { event: 'message_read' }, ({ payload }) => {
                if (!payload?.messageId) return;
                setMessageStatuses(prev => ({
                    ...prev,
                    [payload.messageId]: { ...(prev[payload.messageId] || {}), is_read: true, is_delivered: true }
                }));
            })
            .on('broadcast', { event: 'conversation_read' }, () => {
                setMessageStatuses(prev => {
                    const next = { ...prev };
                    Object.keys(next).forEach((messageId) => {
                        next[messageId] = { ...(next[messageId] || {}), is_read: true, is_delivered: true };
                    });
                    return next;
                });
            })
            .subscribe();

        return () => {
            supabase.removeChannel(channel);
        };
    }, [conversationId]);

    return {
        messageStatuses,
        markAsDelivered,
        markAsRead,
        markAllAsRead
    };
};

/**
 * Hook for group message read receipts
 * Tracks which users have read each message in a group
 */
export const useGroupMessageStatus = (groupId, currentUserId) => {
    const [readReceipts, setReadReceipts] = useState({});

    // Mark group message as read
    const markGroupMessageAsRead = useCallback(async (messageId) => {
        if (!messageId || !currentUserId) return;

        try {
            // Insert read receipt
            const { error } = await supabase
                .from('message_read_receipts')
                .upsert({
                    group_message_id: messageId,
                    user_id: currentUserId,
                    read_at: new Date().toISOString()
                }, {
                    onConflict: 'group_message_id,user_id'
                });

            if (error) throw error;
        } catch (error) {
            console.error('Error marking group message as read:', error);
        }
    }, [currentUserId]);

    // Get read receipts for a message
    const getReadReceipts = useCallback(async (messageId) => {
        if (!messageId) return [];

        try {
            const { data, error } = await supabase
                .from('message_read_receipts')
                .select(`
                    user_id,
                    read_at,
                    profiles:user_id (
                        id,
                        username,
                        avatar_url
                    )
                `)
                .eq('group_message_id', messageId);

            if (error) throw error;
            return data || [];
        } catch (error) {
            console.error('Error fetching read receipts:', error);
            return [];
        }
    }, []);

    // Subscribe to real-time read receipt updates
    useEffect(() => {
        if (!groupId) return;

        const channel = supabase
            .channel(`group-receipts:${groupId}`)
            .on(
                'postgres_changes',
                {
                    event: 'INSERT',
                    schema: 'public',
                    table: 'message_read_receipts',
                    filter: `group_message_id=in.(SELECT id FROM group_messages WHERE group_id='${groupId}')`
                },
                (payload) => {
                    const { group_message_id, user_id } = payload.new;
                    setReadReceipts(prev => ({
                        ...prev,
                        [group_message_id]: [
                            ...(prev[group_message_id] || []),
                            user_id
                        ]
                    }));
                }
            )
            .subscribe();

        return () => {
            supabase.removeChannel(channel);
        };
    }, [groupId]);

    return {
        readReceipts,
        markGroupMessageAsRead,
        getReadReceipts
    };
};

import { useState, useEffect, useRef, useCallback } from 'react';
import { supabase } from '../lib/supabase';

/**
 * Modern WebRTC hook using Native RTCPeerConnection
 * Uses Hybrid Signaling: Database (Persistent) + Realtime Broadcast (Instant)
 */
export const useModernCall = (userId, callId) => {
    const [localStream, setLocalStream] = useState(null);
    const [remoteStream, setRemoteStream] = useState(null);
    const [isConnected, setIsConnected] = useState(false);
    const [isConnecting, setIsConnecting] = useState(false);
    const [error, setError] = useState(null);
    const [isMuted, setIsMuted] = useState(false);
    const [isVideoOff, setIsVideoOff] = useState(false);
    const [remoteEnded, setRemoteEnded] = useState(false);

    const peerRef = useRef(null);
    const localStreamRef = useRef(null);
    const iceCandidatesQueue = useRef([]);
    const channelRef = useRef(null);

    // ICE Servers configuration
    const rtcConfig = {
        iceServers: [
            { urls: 'stun:stun.l.google.com:19302' },
            { urls: 'stun:stun1.l.google.com:19302' }
        ]
    };

    // Initialize media
    const initMedia = useCallback(async (audioOnly = true) => {
        try {
            console.log('≡ƒÄñ Requesting media...', audioOnly ? 'Audio only' : 'Audio + Video');

            const constraints = {
                audio: {
                    echoCancellation: true,
                    noiseSuppression: true,
                    autoGainControl: true
                },
                video: audioOnly ? false : {
                    width: { ideal: 1280 },
                    height: { ideal: 720 },
                    facingMode: 'user'
                }
            };

            const stream = await navigator.mediaDevices.getUserMedia(constraints);
            console.log('Γ£à Media granted');

            setLocalStream(stream);
            localStreamRef.current = stream;
            return stream;
        } catch (err) {
            console.error('Γ¥î Media error:', err);

            if (!audioOnly && (err.name === 'NotReadableError' || err.name === 'NotAllowedError')) {
                console.log('ΓÜá∩╕Å Video failed, falling back to audio only...');
                try {
                    const audioStream = await navigator.mediaDevices.getUserMedia({ audio: true });
                    setLocalStream(audioStream);
                    localStreamRef.current = audioStream;
                    return audioStream;
                } catch (audioErr) {
                    setError('Could not access microphone');
                    throw audioErr;
                }
            }

            setError('Could not access camera/microphone');
            throw err;
        }
    }, []);

    // Helper to send signals via BOTH DB and Broadcast
    const sendSignal = useCallback(async (type, payload) => {
        if (!callId || !userId) return;

        const signalData = { type, ...payload };
        console.log(`≡ƒôñ Sending signal (${type}) via Hybrid Channel...`);

        // 1. Send via Broadcast (Fast, Ephemeral)
        if (channelRef.current) {
            channelRef.current.send({
                type: 'broadcast',
                event: 'signal',
                payload: { ...signalData, from_user: userId }
            }).catch(err => console.warn('ΓÜá∩╕Å Broadcast failed:', err));
        }

        // 2. Send via Database (Persistent, Reliable)
        // Don't await this if it's just a candidate or ready signal to avoid blocking
        const dbPromise = supabase.from('webrtc_signals').insert({
            call_id: callId,
            from_user: userId,
            signal: JSON.stringify(signalData)
        });

        if (type === 'offer' || type === 'answer') {
            // For critical signals, we log errors but don't block execution
            dbPromise.then(({ error }) => {
                if (error) console.error(`Γ¥î DB Insert Error (${type}):`, error);
                else console.log(`Γ£à DB Insert Success (${type})`);
            });
        }
    }, [callId, userId]);

    // Create Peer Connection
    const createPeerConnection = useCallback((userId, callId) => {
        const pc = new RTCPeerConnection(rtcConfig);

        pc.onicecandidate = (event) => {
            if (event.candidate) {
                console.log('Γ¥ä∩╕Å New ICE candidate generated');
                sendSignal('candidate', { candidate: event.candidate });
            }
        };

        pc.onconnectionstatechange = () => {
            console.log('≡ƒöä Connection state:', pc.connectionState);
            if (pc.connectionState === 'connected') {
                setIsConnected(true);
                setIsConnecting(false);
            } else if (pc.connectionState === 'failed' || pc.connectionState === 'disconnected') {
                setIsConnected(false);
                setIsConnecting(false);
            }
        };

        pc.ontrack = (event) => {
            console.log('≡ƒô║ Received remote track');
            setRemoteStream(event.streams[0]);
        };

        return pc;
    }, [sendSignal]);

    // Start call as initiator
    const startCall = useCallback(async (audioOnly = true) => {
        if (!callId || !userId) return;

        try {
            setIsConnecting(true);
            console.log('≡ƒô₧ Starting call as initiator...');

            const stream = await initMedia(audioOnly);
            const pc = createPeerConnection(userId, callId);

            stream.getTracks().forEach(track => pc.addTrack(track, stream));

            const offer = await pc.createOffer();
            await pc.setLocalDescription(offer);

            console.log('≡ƒôí Sending offer...');
            sendSignal('offer', { sdp: offer });

            peerRef.current = pc;
        } catch (err) {
            console.error('Γ¥î Start call error:', err);
            setIsConnecting(false);
        }
    }, [callId, userId, initMedia, createPeerConnection, sendSignal]);

    // Answer call as receiver
    const answerCall = useCallback(async (audioOnly = true) => {
        if (!callId || !userId) return;

        try {
            setIsConnecting(true);
            console.log('≡ƒô₧ Answering call...');

            const stream = await initMedia(audioOnly);
            const pc = createPeerConnection(userId, callId);

            stream.getTracks().forEach(track => pc.addTrack(track, stream));

            peerRef.current = pc;

            if (iceCandidatesQueue.current.length > 0) {
                console.log('Γ¥ä∩╕Å Processing queued candidates:', iceCandidatesQueue.current.length);
                for (const candidate of iceCandidatesQueue.current) {
                    await pc.addIceCandidate(candidate);
                }
                iceCandidatesQueue.current = [];
            }

            console.log('≡ƒæï Sending READY signal...');
            sendSignal('ready', {});

            // Start Polling for Offer (Backup)
            console.log('≡ƒöä Starting offer polling...');
            const pollInterval = setInterval(async () => {
                if (peerRef.current && peerRef.current.remoteDescription) {
                    clearInterval(pollInterval);
                    return;
                }

                try {
                    const { data: offers } = await supabase
                        .from('webrtc_signals')
                        .select('signal, from_user')
                        .eq('call_id', callId)
                        .order('created_at', { ascending: true });

                    if (offers && offers.length > 0) {
                        for (const row of offers) {
                            if (row.from_user === userId) continue;
                            const signal = JSON.parse(row.signal);
                            if (signal.type === 'offer') {
                                console.log('≡ƒô£ Polling found OFFER:', signal);
                                if (peerRef.current && !peerRef.current.remoteDescription) {
                                    await pc.setRemoteDescription(new RTCSessionDescription(signal.sdp));
                                    const answer = await pc.createAnswer();
                                    await pc.setLocalDescription(answer);
                                    sendSignal('answer', { sdp: answer });
                                    clearInterval(pollInterval);
                                }
                                break;
                            }
                        }
                    }
                } catch (err) {
                    // Ignore polling errors
                }
            }, 2000);

            setTimeout(() => clearInterval(pollInterval), 30000);

        } catch (err) {
            console.error('Γ¥î Answer call error:', err);
            setIsConnecting(false);
        }
    }, [callId, userId, initMedia, createPeerConnection, sendSignal]);

    // Listen for signals (Broadcast + DB)
    useEffect(() => {
        if (!callId || !userId) return;

        console.log('≡ƒæé Listening for signals...', callId);

        const handleSignal = async (signal, fromUser) => {
            if (fromUser === userId) return;
            console.log('≡ƒô¿ Received signal:', signal.type);

            try {
                const pc = peerRef.current;

                if (signal.type === 'offer') {
                    if (!pc) {
                        console.log('ΓÜá∩╕Å Received offer but peer not ready');
                        return;
                    }
                    if (pc.remoteDescription) return; // Already handled

                    await pc.setRemoteDescription(new RTCSessionDescription(signal.sdp));
                    const answer = await pc.createAnswer();
                    await pc.setLocalDescription(answer);
                    sendSignal('answer', { sdp: answer });
                }
                else if (signal.type === 'answer') {
                    if (pc && !pc.remoteDescription) {
                        await pc.setRemoteDescription(new RTCSessionDescription(signal.sdp));
                    }
                }
                else if (signal.type === 'candidate') {
                    if (pc && pc.remoteDescription) {
                        await pc.addIceCandidate(new RTCIceCandidate(signal.candidate));
                    } else {
                        iceCandidatesQueue.current.push(new RTCIceCandidate(signal.candidate));
                    }
                }
                else if (signal.type === 'ready') {
                    console.log('≡ƒæï Peer is ready, re-sending offer...');
                    if (pc && pc.localDescription && pc.localDescription.type === 'offer') {
                        console.log('≡ƒôí Re-sending offer to ready peer...');
                        sendSignal('offer', { sdp: pc.localDescription });
                    }
                }
                else if (signal.type === 'end') {
                    console.log('≡ƒæï Peer ended the call');
                    setRemoteEnded(true);

                    if (peerRef.current) {
                        peerRef.current.close();
                        peerRef.current = null;
                    }
                    setIsConnected(false);
                }
            } catch (err) {
                console.error('Γ¥î Signal processing error:', err);
            }
        };

        const channel = supabase.channel(`webrtc-${callId}`, {
            config: {
                broadcast: { self: false }
            }
        });

        channel
            .on('broadcast', { event: 'signal' }, ({ payload }) => {
                handleSignal(payload, payload.from_user);
            })
            .on('postgres_changes', {
                event: 'INSERT',
                schema: 'public',
                table: 'webrtc_signals',
                filter: `call_id=eq.${callId}`
            }, (payload) => {
                const signal = JSON.parse(payload.new.signal);
                handleSignal(signal, payload.new.from_user);
            })
            .subscribe((status) => {
                console.log('≡ƒôí Channel status:', status);
                if (status === 'SUBSCRIBED') {
                    channelRef.current = channel;
                }
            });

        // Listen for Call Status Changes (e.g. Rejected, Ended)
        const statusChannel = supabase.channel(`call-status-${callId}`)
            .on('postgres_changes', {
                event: 'UPDATE',
                schema: 'public',
                table: 'calls',
                filter: `id=eq.${callId}`
            }, (payload) => {
                const newStatus = payload.new.status;
                console.log('≡ƒô₧ Call status changed:', newStatus);

                if (newStatus === 'rejected' || newStatus === 'ended') {
                    console.log('≡ƒÜ½ Call was rejected or ended remotely');
                    setRemoteEnded(true);
                }
            })
            .subscribe();

        return () => {
            channel.unsubscribe();
            statusChannel.unsubscribe();
            channelRef.current = null;
        };
    }, [callId, userId, sendSignal]);

    // End call
    const endCall = useCallback(async () => {
        console.log('≡ƒô┤ Ending call...');

        // Send end signal if we are connected or connecting
        if (isConnected || isConnecting) {
            console.log('≡ƒôñ Sending END signal...');
            await sendSignal('end', {});
        }

        if (peerRef.current) {
            peerRef.current.close();
            peerRef.current = null;
        }
        if (localStreamRef.current) {
            localStreamRef.current.getTracks().forEach(track => track.stop());
            localStreamRef.current = null;
        }
        setLocalStream(null);
        setRemoteStream(null);
        setIsConnected(false);
        setIsConnecting(false);
    }, [isConnected, isConnecting, sendSignal]);

    const toggleMute = useCallback(() => {
        if (localStreamRef.current) {
            const audioTrack = localStreamRef.current.getAudioTracks()[0];
            if (audioTrack) {
                audioTrack.enabled = !audioTrack.enabled;
                setIsMuted(!audioTrack.enabled);
                return !audioTrack.enabled;
            }
        }
        return false;
    }, []);

    const toggleVideo = useCallback(() => {
        if (localStreamRef.current) {
            const videoTrack = localStreamRef.current.getVideoTracks()[0];
            if (videoTrack) {
                videoTrack.enabled = !videoTrack.enabled;
                setIsVideoOff(!videoTrack.enabled);
                return !videoTrack.enabled;
            }
        }
        return false;
    }, []);

    return {
        localStream,
        remoteStream,
        isConnected,
        isConnecting,
        isMuted,
        isVideoOff,
        error,
        remoteEnded,
        startCall,
        answerCall,
        endCall,
        toggleMute,
        toggleVideo
    };
};

import { useState, useEffect, useCallback } from 'react';
import { fetchNotifications, markNotificationRead, supabaseFetch } from '../utils/supabaseRest';
import { focusToast } from '../utils/focusToast';
import { useRobustQuery } from './useRobustQuery';
import { useRealtimeSubscription } from './useRealtimeSubscription';
import { useAudio } from '../context/AudioProvider';
import { playNotification } from '../utils/audioFX';

export const useNotifications = (userId, filter = 'all', pageSize = 20) => {
    const { play } = useAudio();
    const normalizeNotification = useCallback((n) => ({
        ...n,
        is_read: Boolean(n.is_read ?? n.read),
        read: Boolean(n.read ?? n.is_read),
    }), []);

    const groupNotifications = useCallback((notifs) => {
        const grouped = [];
        const seen = new Map();

        notifs.forEach(n => {
            const key = (n.type === 'like' || n.type === 'comment') && n.post_id 
                ? `${n.type}-${n.post_id}` 
                : n.id;

            if (seen.has(key) && key !== n.id) {
                const existing = seen.get(key);
                existing.group_count = (existing.group_count || 1) + 1;
                existing.latest_actor = existing.latest_actor || [existing.actor];
                if (!existing.latest_actor.find(a => a?.id === n.actor?.id)) {
                    existing.latest_actor.push(n.actor);
                }
                existing.is_read = existing.is_read && n.is_read;
                existing.read = existing.read && n.read;
            } else {
                const item = { ...n, group_count: 1, latest_actor: [n.actor] };
                seen.set(key, item);
                grouped.push(item);
            }
        });
        return grouped;
    }, []);

    const [notifications, setNotifications] = useState([]);
    const [hasMore, setHasMore] = useState(true);
    const [page, setPage] = useState(0);
    const [unreadCount, setUnreadCount] = useState(0);
    const [moreLoading, setMoreLoading] = useState(false);

    // Play unified premium notification sound.
    const playNotificationSound = useCallback(async () => {
        playNotification();
    }, []);

    // Show browser notification
    const showBrowserNotification = useCallback((notification) => {
        if (!('Notification' in window)) return;

        if (Notification.permission === 'granted') {
            const title = getNotificationTitle(notification);
            const body = getNotificationBody(notification);

            new Notification(title, {
                body,
                icon: notification.actor?.avatar_url || '/logo192.png',
                badge: '/logo192.png',
                tag: notification.id
            });
        } else if (Notification.permission !== 'denied') {
            Notification.requestPermission();
        }
    }, []);

    const getNotificationTitle = (notification) => {
        const actors = notification.latest_actor || [notification.actor];
        const actorName = actors[0]?.full_name || actors[0]?.username || 'Someone';
        const count = notification.group_count > 1 ? ` and ${notification.group_count - 1} others` : '';

        switch (notification.type) {
            case 'follow': return `${actorName}${count} started following you`;
            case 'like': return `${actorName}${count} liked your post`;
            case 'comment': return `${actorName}${count} commented on your post`;
            case 'mention': return `${actorName}${count} mentioned you`;
            case 'message': return `New message from ${actorName}`;
            default: return 'New notification';
        }
    };

    const getNotificationBody = (notification) => {
        return (notification.type === 'comment' || notification.type === 'message')
            ? (notification.body || 'Tap to view')
            : '';
    };

    // 1. Initial Fetch with Robust Query (using REST API)
    const fetchInitialNotifications = useCallback(async () => {
        if (!userId) return [];

        console.log('≡ƒöö Fetching notifications via REST API...');

        try {
            const notifs = await fetchNotifications(userId, {
                limit: pageSize,
                offset: 0,
                unreadOnly: filter === 'unread'
            });

            console.log(`Γ£à Fetched ${notifs.length} notifications`);
            return notifs;
        } catch (error) {
            console.error('Γ¥î Error fetching notifications:', error);
            throw error;
        }
    }, [userId, filter, pageSize]);

    const {
        data: initialData,
        loading: initialLoading,
        error: initialError,
        refetch: refetchInitial
    } = useRobustQuery(fetchInitialNotifications, {
        enabled: !!userId,
        retries: 3,
        onSuccess: (data) => {
            console.log('Γ£à Notifications loaded:', data?.length);
            const normalized = (data || []).map(normalizeNotification);
            setNotifications(groupNotifications(normalized));
            setPage(0);
            setHasMore((data || []).length === pageSize);

            // Count unread
            const unread = (data || []).filter(n => !(n.is_read ?? n.read)).length;
            setUnreadCount(unread);
        }
    });

    // 2. Load More
    const loadMore = async () => {
        if (moreLoading || !hasMore || initialLoading) return;
        setMoreLoading(true);

        try {
            const nextPage = page + 1;
            console.log('≡ƒöö Loading more notifications, page:', nextPage);

            const newNotifs = await fetchNotifications(userId, {
                limit: pageSize,
                offset: nextPage * pageSize,
                unreadOnly: filter === 'unread'
            });

            const normalized = (newNotifs || []).map(normalizeNotification);
            setNotifications(prev => groupNotifications([...prev, ...normalized]));
            setPage(nextPage);
            setHasMore(newNotifs.length === pageSize);
            console.log(`Γ£à Loaded ${newNotifs.length} more notifications`);
        } catch (error) {
            console.error('Γ¥î Error loading more notifications:', error);
        } finally {
            setMoreLoading(false);
        }
    };

    // 3. Mark as Read
    const markAsRead = async (notificationId) => {
        try {
            await markNotificationRead(notificationId);

            setNotifications(prev =>
                prev.map(n => n.id === notificationId ? { ...n, read: true, is_read: true } : n)
            );

            setUnreadCount(prev => Math.max(0, prev - 1));
        } catch (error) {
            console.error('Error marking notification as read:', error);
        }
    };

    // 4. Mark All as Read
    const markAllAsRead = async () => {
        try {
            // Update all unread notifications
            await supabaseFetch(`/notifications?user_id=eq.${userId}&read=eq.false`, {
                method: 'PATCH',
                body: JSON.stringify({ read: true })
            });

            setNotifications(prev => prev.map(n => ({ ...n, read: true, is_read: true })));
            setUnreadCount(0);
            focusToast.success('All notifications marked as read');
        } catch (error) {
            console.error('Error marking all as read:', error);
            focusToast.error('Failed to mark all as read');
        }
    };

    // 5. Realtime Subscription
    useRealtimeSubscription({
        channelName: `notifications-${userId}`,
        table: 'notifications',
        event: 'INSERT',
        enabled: !!userId,
        filter: `user_id=eq.${userId}`,
        onEvent: (payload) => {
            console.log('≡ƒöö New notification received');
            const newNotif = normalizeNotification(payload.new);

            setNotifications(prev => groupNotifications([newNotif, ...prev]));
            setUnreadCount(prev => prev + 1);

            playNotificationSound();
            play('notification');
            showBrowserNotification(newNotif);

            focusToast.info(getNotificationTitle(newNotif));
        }
    });

    return {
        notifications,
        setNotifications,
        loading: initialLoading || moreLoading,
        error: initialError,
        hasMore,
        unreadCount,
        loadMore,
        markAsRead,
        markAllAsRead,
        refresh: refetchInitial,
    };
};

/**
 * useOCRScanner.js
 * ================
 * Real ID text extraction using Tesseract.js
 * Supports: Aadhaar Card, Student ID, Passport
 * Extracts: Name, Date of Birth, ID Number
 *
 * H2 Innovative ΓÇö Focus Trust Shield
 */

import { useState, useCallback, useRef } from 'react';
import { createWorker } from 'tesseract.js';

// ΓöÇΓöÇ Text Parsers ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

// Aadhaar: 12-digit number in groups of 4
const AADHAAR_REGEX = /\b\d{4}\s?\d{4}\s?\d{4}\b/;

// Date patterns: DD/MM/YYYY, DD-MM-YYYY, YYYY-MM-DD
const DOB_REGEX = /\b(\d{4}[\/\-\.](?:0?[1-9]|1[0-2])[\/\-\.](?:0?[1-9]|[12]\d|3[01])|(?:0?[1-9]|[12]\d|3[01])[\/\-\.](?:0?[1-9]|1[0-2])[\/\-\.]\d{4})\b/;

// Year of birth (fallback)
const YEAR_REGEX = /(?:Year of Birth|DOB|YOB)\s*[:\-]?\s*(\d{4})/i;

// Name patterns ΓÇö look for lines after "Name:" or "αñ¿αñ╛αñ«" (Hindi)
const NAME_PATTERNS = [
  /(?:Name|αñ¿αñ╛αñ«)\s*[:\-]?\s*([A-Z][A-Za-z\s\.]{2,40})/i,
  /^([A-Z][A-Za-z\.]+(?:\s+[A-Z][A-Za-z\.]+){1,2})$/, // 2-3 words, Title case
  /^([A-Z][A-Z\s\.]{4,35})$/ // ALL CAPS line (common in govt IDs)
];

/**
 * Parse extracted OCR text into structured data
 */
const parseIDText = (text) => {
  const result = {
    raw: text,
    name: null,
    dob: null,
    idNumber: null,
    idType: 'unknown',
    confidence: 0,
  };

  if (!text) return result;

  // Detect Aadhaar
  const aadhaarMatch = text.match(AADHAAR_REGEX);
  if (aadhaarMatch) {
    result.idNumber = aadhaarMatch[0].replace(/\s/g, '');
    result.idType = 'aadhaar';
  }

  // Extract DOB
  const dobMatch = text.match(DOB_REGEX);
  if (dobMatch) {
    const rawDate = dobMatch[1] || dobMatch[0];
    if (/^\d{4}/.test(rawDate)) {
        const parts = rawDate.split(/[\/\-\.]/);
        result.dob = `${parts[0]}-${parts[1].padStart(2, '0')}-${parts[2].padStart(2, '0')}`;
    } else {
        const parts = rawDate.split(/[\/\-\.]/);
        result.dob = `${parts[2]}-${parts[1].padStart(2, '0')}-${parts[0].padStart(2, '0')}`;
    }
  } else {
    // Try year of birth fallback
    const yearMatch = text.match(YEAR_REGEX);
    if (yearMatch) {
      result.dob = `${yearMatch[1]}-01-01`; // approximate
    }
  }

  // Extract Name line by line to support filtering
  const lines = text.split('\n').map(l => l.trim()).filter(Boolean);
  let matchedName = null;

  for (const line of lines) {
    const lower = line.toLowerCase();
    if (lower.includes('.png') || lower.includes('.jpg') || lower.includes('jpeg') || lower.includes('www.') || lower.includes('screenshot')) {
      continue;
    }

    for (const pattern of NAME_PATTERNS) {
      const match = line.match(pattern);
      if (match) {
        const candidate = match[1].trim();
        // Reject if it looks like a label or too short
        if (candidate.length > 3 && !/^\d+$/.test(candidate) && !/(?:dob|year of birth|father)/i.test(candidate)) {
          matchedName = candidate;
          break;
        }
      }
    }
    if (matchedName) break;
  }

  if (matchedName) {
    result.name = toTitleCase(matchedName);
  }

  // Confidence: how many fields did we extract?
  const fields = [result.name, result.dob, result.idNumber].filter(Boolean).length;
  result.confidence = parseFloat((fields / 3).toFixed(2));

  return result;
};

const toTitleCase = (str) =>
  str.toLowerCase().replace(/\b\w/g, (c) => c.toUpperCase());

// ΓöÇΓöÇ Hook ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export const useOCRScanner = () => {
  const [scanning, setScanning] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusMessage, setStatusMessage] = useState('');
  const [result, setResult] = useState(null);
  const [error, setError] = useState(null);

  const workerRef = useRef(null);

  /**
   * Scan an image file for ID text
   * @param {File|string} imageSource ΓÇö File object or image URL
   * @returns {Object} Parsed ID data
   */
  const scanID = useCallback(async (imageSource) => {
    setScanning(true);
    setProgress(0);
    setError(null);
    setResult(null);

    try {
      setStatusMessage('Initializing OCR engine...');

      // Create fresh worker
      const worker = await createWorker('eng', 1, {
        logger: (m) => {
          if (m.status === 'recognizing text') {
            setProgress(Math.round(m.progress * 100));
          }
        },
      });

      workerRef.current = worker;

      setStatusMessage('Reading ID document...');

      // Set parameters for better ID card recognition
      await worker.setParameters({
        tessedit_char_whitelist: 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789 /-.',
        preserve_interword_spaces: '1',
      });

      const { data } = await worker.recognize(imageSource);
      await worker.terminate();
      workerRef.current = null;

      const text = data.text;
      const avgConf = data.confidence;

      if (avgConf < 30) {
        throw new Error('Image quality too low. Please upload a clearer photo of your ID in good lighting.');
      }

      setStatusMessage('Parsing identity data...');
      const parsed = parseIDText(text);

      if (parsed.confidence === 0) {
        throw new Error('Could not extract identity data. Please ensure the text on your ID is clearly visible and not blurred.');
      }

      setResult(parsed);
      setStatusMessage('ID scanned successfully.');
      return { ok: true, ...parsed };
    } catch (err) {
      const message = err.message || 'OCR scan failed. Please try again.';
      setError(message);
      setStatusMessage(message);

      // Terminate worker if still running
      if (workerRef.current) {
        try { await workerRef.current.terminate(); } catch (_) {}
        workerRef.current = null;
      }

      return { ok: false, reason: message };
    } finally {
      setScanning(false);
      setProgress(0);
    }
  }, []);

  /**
   * Verify name from ID matches profile name
   * @param {string} idName     - Name extracted from ID
   * @param {string} profileName - Name from user's Focus profile
   * @returns {boolean}
   */
  const verifyNameMatch = useCallback((idName, profileName) => {
    if (!idName || !profileName) return false;
    const normalize = (s) =>
      s.toLowerCase().replace(/[^a-z\s]/g, '').trim();
    const id = normalize(idName);
    const profile = normalize(profileName);

    // Full match
    if (id === profile) return true;

    // First name match (at least first word must match)
    const idFirst = id.split(' ')[0];
    const profileFirst = profile.split(' ')[0];
    return idFirst === profileFirst && idFirst.length > 2;
  }, []);

  /**
   * Calculate age from DOB string (YYYY-MM-DD or DD/MM/YYYY)
   */
  const calculateAgeFromDOB = useCallback((dob) => {
    if (!dob) return null;
    try {
      let year, month, day;
      if (dob.includes('-') && /^\d{4}-/.test(dob)) {
          [year, month, day] = dob.split('-').map(Number);
      } else {
          [day, month, year] = dob.split('/').map(Number);
      }
      const birth = new Date(year, month - 1, day);
      const today = new Date();
      let age = today.getFullYear() - birth.getFullYear();
      const monthDiff = today.getMonth() - birth.getMonth();
      if (monthDiff < 0 || (monthDiff === 0 && today.getDate() < birth.getDate())) {
        age--;
      }
      return age;
    } catch {
      return null;
    }
  }, []);

  /**
   * Determine ID tier based on age
   * 13-17 ΓåÆ Student ID required
   * 18+   ΓåÆ Govt ID required
   */
  const getRequiredIDTier = useCallback((age) => {
    if (!age) return 'govt';
    if (age >= 13 && age <= 17) return 'student';
    if (age >= 18) return 'govt';
    return null; // Under 13 ΓÇö not allowed
  }, []);

  return {
    scanning,
    progress,
    statusMessage,
    result,
    error,
    scanID,
    verifyNameMatch,
    calculateAgeFromDOB,
    getRequiredIDTier,
  };
};

export default useOCRScanner;

/**
 * useOfflineQueue Hook
 * React hook for offline queue management
 */

import { useState, useEffect, useCallback } from 'react';
import { offlineQueue } from '../utils/OfflineQueue';
import { toast } from 'react-toastify';

export const useOfflineQueue = () => {
    const [isOnline, setIsOnline] = useState(navigator.onLine);
    const [queueSize, setQueueSize] = useState(offlineQueue.getQueueSize());
    const [isSyncing, setIsSyncing] = useState(false);

    // Monitor online/offline status
    useEffect(() => {
        const handleOnline = () => {
            setIsOnline(true);
            toast.success('Back online! Syncing queued actions...');
            syncQueue();
        };

        const handleOffline = () => {
            setIsOnline(false);
            toast.warning('You are offline. Actions will be queued for sync.');
        };

        window.addEventListener('online', handleOnline);
        window.addEventListener('offline', handleOffline);

        return () => {
            window.removeEventListener('online', handleOnline);
            window.removeEventListener('offline', handleOffline);
        };
    }, []);

    /**
     * Queue an action for offline execution
     */
    const queueAction = useCallback((type, payload) => {
        if (offlineQueue.isFull()) {
            toast.error('Too many pending actions. Please connect to internet.');
            return false;
        }

        const success = offlineQueue.enqueue({ type, payload });
        if (success) {
            setQueueSize(offlineQueue.getQueueSize());
            if (!isOnline) {
                toast.info('Action queued for sync');
            }
        }
        return success;
    }, [isOnline]);

    /**
     * Sync queued actions
     */
    const syncQueue = useCallback(async () => {
        if (!isOnline || isSyncing) return;

        setIsSyncing(true);
        try {
            const result = await offlineQueue.syncQueue();
            setQueueSize(offlineQueue.getQueueSize());

            if (result.successCount > 0) {
                toast.success(`Synced ${result.successCount} actions`);
            }
            if (result.failedCount > 0) {
                toast.error(`${result.failedCount} actions failed to sync`);
            }
        } catch (error) {
            console.error('Sync failed:', error);
            toast.error('Failed to sync actions');
        } finally {
            setIsSyncing(false);
        }
    }, [isOnline, isSyncing]);

    /**
     * Clear queue
     */
    const clearQueue = useCallback(() => {
        offlineQueue.clear();
        setQueueSize(0);
        toast.success('Queue cleared');
    }, []);

    return {
        isOnline,
        queueSize,
        isSyncing,
        queueAction,
        syncQueue,
        clearQueue,
        isFull: offlineQueue.isFull()
    };
};

import { useState, useCallback, useEffect } from 'react';
import { supabase } from '../lib/supabase';
import { focusToast } from '../utils/focusToast';

/**
 * Hook for pinning conversations
 * Pin up to 3 favorite chats to the top
 */
export const usePinnedChats = (userId) => {
    const [pinnedChats, setPinnedChats] = useState([]);
    const [loading, setLoading] = useState(false);

    const MAX_PINNED = 3;

    // Load pinned chats
    useEffect(() => {
        if (userId) {
            loadPinnedChats();
        }
    }, [userId]);

    const loadPinnedChats = useCallback(async () => {
        try {
            const { data, error } = await supabase
                .from('profiles')
                .select('pinned_chats')
                .eq('id', userId)
                .single();

            if (error) throw error;

            setPinnedChats(data.pinned_chats || []);
        } catch (error) {
            console.error('Error loading pinned chats:', error);
        }
    }, [userId]);

    // Pin a chat
    const pinChat = useCallback(async (chatId, chatType = 'conversation') => {
        if (pinnedChats.length >= MAX_PINNED) {
            focusToast.error(`You can only pin up to ${MAX_PINNED} chats`);
            return false;
        }

        setLoading(true);
        try {
            const newPinned = [...pinnedChats, { id: chatId, type: chatType, pinned_at: new Date().toISOString() }];

            const { error } = await supabase
                .from('profiles')
                .update({ pinned_chats: newPinned })
                .eq('id', userId);

            if (error) throw error;

            setPinnedChats(newPinned);
            focusToast.success('Chat pinned');
            return true;
        } catch (error) {
            console.error('Error pinning chat:', error);
            focusToast.error('Failed to pin chat');
            return false;
        } finally {
            setLoading(false);
        }
    }, [pinnedChats, userId]);

    // Unpin a chat
    const unpinChat = useCallback(async (chatId) => {
        setLoading(true);
        try {
            const newPinned = pinnedChats.filter(chat => chat.id !== chatId);

            const { error } = await supabase
                .from('profiles')
                .update({ pinned_chats: newPinned })
                .eq('id', userId);

            if (error) throw error;

            setPinnedChats(newPinned);
            focusToast.success('Chat unpinned');
            return true;
        } catch (error) {
            console.error('Error unpinning chat:', error);
            focusToast.error('Failed to unpin chat');
            return false;
        } finally {
            setLoading(false);
        }
    }, [pinnedChats, userId]);

    // Check if chat is pinned
    const isPinned = useCallback((chatId) => {
        return pinnedChats.some(chat => chat.id === chatId);
    }, [pinnedChats]);

    return {
        pinnedChats,
        loading,
        pinChat,
        unpinChat,
        isPinned,
        canPinMore: pinnedChats.length < MAX_PINNED
    };
};

import { useState, useCallback, useEffect } from 'react';
import { supabase } from '../lib/supabase';
import { focusToast } from '../utils/focusToast';

/**
 * Hook for managing pinned messages
 * Supports up to 3 pinned messages per conversation (WhatsApp-style)
 * Auto-expires after 30 days (optional)
 */
export const usePinnedMessages = (conversationId, groupId = null) => {
    const [pinnedMessages, setPinnedMessages] = useState([]);
    const [loading, setLoading] = useState(false);

    const MAX_PINNED = 3; // WhatsApp allows 3 pinned messages

    // Fetch pinned messages
    const fetchPinnedMessages = useCallback(async () => {
        if (!conversationId && !groupId) return;

        try {
            const query = supabase
                .from('pinned_messages')
                .select(`
                    *,
                    messages (*),
                    group_messages (*)
                `)
                .order('pinned_at', { ascending: false });

            if (conversationId) {
                query.eq('conversation_id', conversationId);
            } else if (groupId) {
                query.eq('group_id', groupId);
            }

            const { data, error } = await query;

            if (error) throw error;

            // Filter out expired pins (30 days old)
            const now = new Date();
            const validPins = (data || []).filter(pin => {
                const pinnedDate = new Date(pin.pinned_at);
                const daysDiff = (now - pinnedDate) / (1000 * 60 * 60 * 24);
                return daysDiff <= 30; // 30-day expiry
            });

            setPinnedMessages(validPins);
        } catch (error) {
            console.error('Error fetching pinned messages:', error);
        }
    }, [conversationId, groupId]);

    // Pin a message
    const pinMessage = useCallback(async (messageId, userId, isGroupMessage = false) => {
        if (!messageId || !userId) return false;

        // Check if already at max pins
        if (pinnedMessages.length >= MAX_PINNED) {
            focusToast.error(`You can only pin up to ${MAX_PINNED} messages`);
            return false;
        }

        setLoading(true);
        try {
            const pinData = {
                pinned_by: userId,
                pinned_at: new Date().toISOString()
            };

            if (isGroupMessage) {
                pinData.group_message_id = messageId;
                pinData.group_id = groupId;
            } else {
                pinData.message_id = messageId;
                pinData.conversation_id = conversationId;
            }

            const { data, error } = await supabase
                .from('pinned_messages')
                .insert(pinData)
                .select()
                .single();

            if (error) throw error;

            focusToast.success('Message pinned');
            await fetchPinnedMessages();
            return true;
        } catch (error) {
            console.error('Error pinning message:', error);
            focusToast.error('Failed to pin message');
            return false;
        } finally {
            setLoading(false);
        }
    }, [conversationId, groupId, pinnedMessages.length, fetchPinnedMessages]);

    // Unpin a message
    const unpinMessage = useCallback(async (pinnedMessageId) => {
        if (!pinnedMessageId) return false;

        setLoading(true);
        try {
            const { error } = await supabase
                .from('pinned_messages')
                .delete()
                .eq('id', pinnedMessageId);

            if (error) throw error;

            focusToast.success('Message unpinned');
            await fetchPinnedMessages();
            return true;
        } catch (error) {
            console.error('Error unpinning message:', error);
            focusToast.error('Failed to unpin message');
            return false;
        } finally {
            setLoading(false);
        }
    }, [fetchPinnedMessages]);

    // Check if a message is pinned
    const isPinned = useCallback((messageId) => {
        return pinnedMessages.some(pin =>
            pin.message_id === messageId || pin.group_message_id === messageId
        );
    }, [pinnedMessages]);

    // Get pinned message by ID
    const getPinnedMessage = useCallback((messageId) => {
        return pinnedMessages.find(pin =>
            pin.message_id === messageId || pin.group_message_id === messageId
        );
    }, [pinnedMessages]);

    // Unpin all messages
    const unpinAll = useCallback(async () => {
        setLoading(true);
        try {
            const query = supabase.from('pinned_messages').delete();

            if (conversationId) {
                query.eq('conversation_id', conversationId);
            } else if (groupId) {
                query.eq('group_id', groupId);
            }

            const { error } = await query;

            if (error) throw error;

            focusToast.success('All messages unpinned');
            setPinnedMessages([]);
            return true;
        } catch (error) {
            console.error('Error unpinning all messages:', error);
            focusToast.error('Failed to unpin messages');
            return false;
        } finally {
            setLoading(false);
        }
    }, [conversationId, groupId]);

    // Auto-fetch on mount and when IDs change
    useEffect(() => {
        fetchPinnedMessages();
    }, [fetchPinnedMessages]);

    return {
        pinnedMessages,
        loading,
        pinMessage,
        unpinMessage,
        unpinAll,
        isPinned,
        getPinnedMessage,
        fetchPinnedMessages,
        canPinMore: pinnedMessages.length < MAX_PINNED,
        pinnedCount: pinnedMessages.length,
        maxPinned: MAX_PINNED
    };
};

import { useState, useCallback, useRef } from 'react';
import { supabase, supabaseUrl, supabaseAnonKey } from '../lib/supabase';
import { useAuth } from './useAuth';
import { useRobustQuery } from './useRobustQuery';
import { useRealtimeSubscription } from './useRealtimeSubscription';

export const useProfile = (username) => {
    const { user: currentUser, profile: authProfile } = useAuth();
    const [profile, setProfile] = useState(null);
    const [currentUserRelation, setCurrentUserRelation] = useState({
        isFollowing: false,
        isBlocked: false,
        isMuted: false
    });

    const isMounted = useRef(true);
    const usernameRef = useRef(username);

    // 1. Fetch Profile Logic
    const fetchProfileData = useCallback(async () => {
        if (!username) throw new Error('No username provided');

        const isOwnProfile =
            Boolean(currentUser) &&
            (username === currentUser.id ||
                (authProfile?.username && username === authProfile.username));

        // A. Own Profile
        if (isOwnProfile && authProfile) {
            // Fetch real counts
            const [followers, following, posts] = await Promise.all([
                supabase.from('follows').select('id', { count: 'exact', head: true }).eq('following_id', currentUser.id),
                supabase.from('follows').select('id', { count: 'exact', head: true }).eq('follower_id', currentUser.id),
                supabase.from('posts').select('id', { count: 'exact', head: true }).eq('user_id', currentUser.id)
            ]);

            return {
                ...authProfile,
                posts_count: posts.count || 0,
                followers_count: followers.count || 0,
                following_count: following.count || 0
            };
        }

        // B. Other Profile
        const isUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(username);
        
        let query = supabase.from('profiles').select('*');
        if (isUuid) {
            query = query.eq('id', username);
        } else {
            query = query.eq('username', username);
        }

        const { data: rows, error: fetchError } = await query;
        
        if (fetchError) throw fetchError;
        const data = rows?.[0];
        if (!data) throw new Error('Profile not found');

        // Fetch counts & relation
        const promises = [
            supabase.from('follows').select('id', { count: 'exact', head: true }).eq('following_id', data.id),
            supabase.from('follows').select('id', { count: 'exact', head: true }).eq('follower_id', data.id),
            supabase.from('posts').select('id', { count: 'exact', head: true }).eq('user_id', data.id)
        ];

        if (currentUser) {
            promises.push(
                supabase.from('follows').select('id').eq('follower_id', currentUser.id).eq('following_id', data.id).single()
            );
        }

        const results = await Promise.all(promises);
        const [followers, following, posts] = results;
        const followStatus = currentUser ? results[3] : { data: null };

        return {
            profile: {
                ...data,
                posts_count: posts.count || 0,
                followers_count: followers.count || 0,
                following_count: following.count || 0
            },
            relation: {
                isFollowing: !!followStatus.data,
                isBlocked: false, // TODO
                isMuted: false // TODO
            }
        };
    }, [username, currentUser, authProfile]);

    const {
        data: fetchedData,
        loading,
        error,
        refetch
    } = useRobustQuery(fetchProfileData, {
        enabled: !!username,
        retries: 3,
        onSuccess: (result) => {
            if (result.profile) {
                setProfile(result.profile);
                setCurrentUserRelation(result.relation);
            } else {
                // Own profile case
                setProfile(result);
            }
        }
    });

    // 2. Realtime Subscription for Follows
    useRealtimeSubscription({
        channelName: `profile-follows-${username}`,
        table: 'follows',
        event: '*',
        enabled: !!profile,
        onEvent: (payload) => {
            // Check if relevant to this profile
            if (payload.new.following_id === profile?.id || payload.old?.following_id === profile?.id) {
                console.log('≡ƒöö Follower change detected, refreshing...');
                refetch();
            }
        }
    });

    const updateFollowStatus = useCallback((isFollowing) => {
        setCurrentUserRelation(prev => ({ ...prev, isFollowing }));
        refetch();
    }, [refetch]);

    return {
        profile,
        loading,
        error,
        currentUserRelation,
        updateFollowStatus,
        refresh: refetch
    };
};

import { useState, useCallback, useEffect } from 'react';
import { supabase } from '../lib/supabase';
import { focusToast } from '../utils/focusToast';

/**
 * Hook for managing read receipt settings
 * Allows users to control read receipt visibility
 */
export const useReadReceiptSettings = (userId) => {
    const [globalSetting, setGlobalSetting] = useState(true);
    const [conversationSettings, setConversationSettings] = useState({});
    const [loading, setLoading] = useState(false);

    // Load settings on mount
    useEffect(() => {
        if (userId) {
            loadSettings();
        }
    }, [userId]);

    // Load user's read receipt settings
    const loadSettings = useCallback(async () => {
        try {
            const { data, error } = await supabase
                .from('profiles')
                .select('read_receipts_enabled, read_receipt_settings')
                .eq('id', userId)
                .single();

            if (error) throw error;

            setGlobalSetting(data.read_receipts_enabled !== false);
            setConversationSettings(data.read_receipt_settings || {});
        } catch (error) {
            console.error('Error loading settings:', error);
        }
    }, [userId]);

    // Toggle global read receipts
    const toggleGlobalReadReceipts = useCallback(async () => {
        setLoading(true);
        try {
            const newSetting = !globalSetting;

            const { error } = await supabase
                .from('profiles')
                .update({ read_receipts_enabled: newSetting })
                .eq('id', userId);

            if (error) throw error;

            setGlobalSetting(newSetting);
            focusToast.success(
                newSetting
                    ? 'Read receipts enabled'
                    : 'Read receipts disabled'
            );
            return true;
        } catch (error) {
            console.error('Error toggling read receipts:', error);
            focusToast.error('Failed to update settings');
            return false;
        } finally {
            setLoading(false);
        }
    }, [globalSetting, userId]);

    // Set read receipt for specific conversation
    const setConversationReadReceipt = useCallback(async (conversationId, enabled) => {
        setLoading(true);
        try {
            const newSettings = {
                ...conversationSettings,
                [conversationId]: enabled
            };

            const { error } = await supabase
                .from('profiles')
                .update({ read_receipt_settings: newSettings })
                .eq('id', userId);

            if (error) throw error;

            setConversationSettings(newSettings);
            focusToast.success(
                enabled
                    ? 'Read receipts enabled for this chat'
                    : 'Read receipts disabled for this chat'
            );
            return true;
        } catch (error) {
            console.error('Error updating conversation setting:', error);
            focusToast.error('Failed to update settings');
            return false;
        } finally {
            setLoading(false);
        }
    }, [conversationSettings, userId]);

    // Check if read receipts are enabled for a conversation
    const areReadReceiptsEnabled = useCallback((conversationId) => {
        // Check conversation-specific setting first
        if (conversationSettings.hasOwnProperty(conversationId)) {
            return conversationSettings[conversationId];
        }
        // Fall back to global setting
        return globalSetting;
    }, [conversationSettings, globalSetting]);

    return {
        globalSetting,
        conversationSettings,
        loading,
        toggleGlobalReadReceipts,
        setConversationReadReceipt,
        areReadReceiptsEnabled
    };
};

import { useState, useEffect, useCallback, useRef } from 'react';

/**
 * A hook for robust data fetching with retries, timeouts, and error handling.
 * @param {Function} fetchFn - Async function to fetch data
 * @param {Object} options - Configuration options
 * @returns {Object} { data, loading, error, refetch, retryCount }
 */
export const useRobustQuery = (fetchFn, options = {}) => {
    const {
        enabled = true,
        retries = 3,
        retryDelay = 2000,
        timeout = 10000,
        onSuccess,
        onError,
        dependencies = []
    } = options;

    const [data, setData] = useState(null);
    const [loading, setLoading] = useState(enabled);
    const [error, setError] = useState(null);
    const [retryCount, setRetryCount] = useState(0);

    // Track mount for Strict Mode: cleanup sets false; we must reset true on each mount
    // or the second mount's fetch will never call setLoading(false).
    const isMounted = useRef(true);

    useEffect(() => {
        isMounted.current = true;
        return () => {
            isMounted.current = false;
        };
    }, []);

    const execute = useCallback(async (resetState = true) => {
        if (resetState) {
            setLoading(true);
            setError(null);
        }

        let attempt = 0;
        let success = false;

        while (attempt <= retries && !success) {
            if (!isMounted.current) return;

            try {
                // Create a timeout promise
                const timeoutPromise = new Promise((_, reject) =>
                    setTimeout(() => reject(new Error('Request timed out')), timeout)
                );

                // Race the fetch function against the timeout
                const result = await Promise.race([fetchFn(), timeoutPromise]);

                if (isMounted.current) {
                    setData(result);
                    setLoading(false);
                    success = true;
                    if (onSuccess) onSuccess(result);
                }

            } catch (err) {
                attempt++;
                console.warn(`ΓÜá∩╕Å Query failed (Attempt ${attempt}/${retries + 1}):`, err.message);

                if (attempt > retries) {
                    if (isMounted.current) {
                        setError(err);
                        setLoading(false);
                        if (onError) onError(err);
                    }
                } else {
                    // Wait before retrying
                    if (isMounted.current) {
                        setRetryCount(attempt);
                        await new Promise(resolve => setTimeout(resolve, retryDelay));
                    }
                }
            }
        }
    }, [fetchFn, retries, retryDelay, timeout, ...dependencies]);

    useEffect(() => {
        if (enabled) {
            execute();
        }
    }, [enabled, execute]);

    return { data, loading, error, refetch: () => execute(true), retryCount };
};

import { useState, useEffect, useCallback, useRef } from 'react';
import { supabase } from '../lib/supabase';
import { useAuth } from './useAuth';

/**
 * Hook for managing screen time tracking and limits
 */
export const useScreenTime = () => {
    const { user } = useAuth();
    const [loading, setLoading] = useState(true);
    const [limits, setLimits] = useState(null);
    const [todayUsage, setTodayUsage] = useState(0);
    const [isLimitExceeded, setIsLimitExceeded] = useState(false);
    const [isTimeBlocked, setIsTimeBlocked] = useState(false);
    const [currentBlock, setCurrentBlock] = useState(null);
    const [remainingMinutes, setRemainingMinutes] = useState(null);
    const [graceActive, setGraceActive] = useState(false);

    const sessionStart = useRef(null);
    const trackingInterval = useRef(null);

    // Check if current time is in a blocked period
    const checkTimeBlocks = useCallback((blocks) => {
        if (!blocks || blocks.length === 0) return null;

        const now = new Date();
        const currentDay = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'][now.getDay()];
        const currentTime = now.getHours() * 60 + now.getMinutes(); // Minutes since midnight

        for (const block of blocks) {
            if (!block.days.includes(currentDay)) continue;

            const [startHour, startMin] = block.start.split(':').map(Number);
            const [endHour, endMin] = block.end.split(':').map(Number);
            const startMinutes = startHour * 60 + startMin;
            let endMinutes = endHour * 60 + endMin;

            // Handle overnight blocks (e.g., 22:00 to 07:00)
            if (endMinutes < startMinutes) {
                if (currentTime >= startMinutes || currentTime < endMinutes) {
                    return block;
                }
            } else {
                if (currentTime >= startMinutes && currentTime < endMinutes) {
                    return block;
                }
            }
        }

        return null;
    }, []);

    // Fetch screen time data
    const fetchScreenTimeData = useCallback(async () => {
        if (!user?.id) return;

        try {
            setLoading(true);

            // Get limits
            const { data: limitsData } = await supabase
                .from('screen_time_limits')
                .select('*')
                .eq('teen_id', user.id)
                .eq('enabled', true)
                .single();

            setLimits(limitsData);

            // Get today's usage
            const today = new Date().toISOString().split('T')[0];
            const { data: usageData } = await supabase
                .from('screen_time_usage')
                .select('*')
                .eq('teen_id', user.id)
                .eq('date', today)
                .single();

            const usedMinutes = usageData?.total_minutes || 0;
            setTodayUsage(usedMinutes);

            // Check limits
            if (limitsData) {
                const isWeekend = [0, 6].includes(new Date().getDay());
                const dailyLimit = isWeekend
                    ? (limitsData.weekend_limit_minutes || limitsData.daily_limit_minutes)
                    : limitsData.daily_limit_minutes;

                const remaining = dailyLimit - usedMinutes;
                setRemainingMinutes(Math.max(0, remaining));

                // Check if in grace period
                if (remaining <= 0) {
                    if (remaining > -limitsData.grace_period_minutes) {
                        setGraceActive(true);
                        setIsLimitExceeded(false);
                    } else {
                        setGraceActive(false);
                        setIsLimitExceeded(true);
                    }
                } else if (remaining <= limitsData.grace_period_minutes) {
                    setGraceActive(true);
                    setIsLimitExceeded(false);
                } else {
                    setGraceActive(false);
                    setIsLimitExceeded(false);
                }

                // Check time blocks
                const blocked = checkTimeBlocks(limitsData.time_blocks);
                setIsTimeBlocked(!!blocked);
                setCurrentBlock(blocked);
            }
        } catch (err) {
            console.error('Error fetching screen time data:', err);
        } finally {
            setLoading(false);
        }
    }, [user?.id, checkTimeBlocks]);

    // Start tracking session
    const startSession = useCallback(() => {
        if (sessionStart.current) return;

        sessionStart.current = new Date();

        // Update usage every minute
        trackingInterval.current = setInterval(() => {
            const elapsed = Math.floor((Date.now() - sessionStart.current.getTime()) / 60000);
            updateUsage(elapsed);
        }, 60000); // Every minute
    }, []);

    // End tracking session
    const endSession = useCallback(async () => {
        if (!sessionStart.current) return;

        const elapsed = Math.floor((Date.now() - sessionStart.current.getTime()) / 60000);

        if (trackingInterval.current) {
            clearInterval(trackingInterval.current);
            trackingInterval.current = null;
        }

        sessionStart.current = null;

        await updateUsage(elapsed);
    }, []);

    // Update usage in database
    const updateUsage = useCallback(async (additionalMinutes = 0) => {
        if (!user?.id) return;

        const today = new Date().toISOString().split('T')[0];

        try {
            // Get current usage
            const { data: current } = await supabase
                .from('screen_time_usage')
                .select('total_minutes')
                .eq('teen_id', user.id)
                .eq('date', today)
                .single();

            const newTotal = (current?.total_minutes || 0) + additionalMinutes;

            await supabase
                .from('screen_time_usage')
                .upsert({
                    teen_id: user.id,
                    date: today,
                    total_minutes: newTotal
                }, {
                    onConflict: 'teen_id,date'
                });

            setTodayUsage(newTotal);

            // Check if limit exceeded
            if (limits) {
                const isWeekend = [0, 6].includes(new Date().getDay());
                const dailyLimit = isWeekend
                    ? (limits.weekend_limit_minutes || limits.daily_limit_minutes)
                    : limits.daily_limit_minutes;

                if (newTotal >= dailyLimit) {
                    setIsLimitExceeded(true);
                    setRemainingMinutes(0);
                } else {
                    setRemainingMinutes(dailyLimit - newTotal);
                }
            }
        } catch (err) {
            console.error('Error updating screen time:', err);
        }
    }, [user?.id, limits]);

    // Format time display
    const formatTime = useCallback((minutes) => {
        if (minutes < 60) return `${minutes}m`;
        const hours = Math.floor(minutes / 60);
        const mins = minutes % 60;
        return mins > 0 ? `${hours}h ${mins}m` : `${hours}h`;
    }, []);

    // Get status message
    const getStatusMessage = useCallback(() => {
        if (isTimeBlocked && currentBlock) {
            return {
                type: 'blocked',
                title: currentBlock.name || 'Blocked Time',
                message: `App is blocked until ${currentBlock.end}`
            };
        }

        if (isLimitExceeded) {
            return {
                type: 'exceeded',
                title: "Time's Up!",
                message: "You've reached your daily screen time limit"
            };
        }

        if (graceActive) {
            return {
                type: 'grace',
                title: 'Almost Time',
                message: `${formatTime(remainingMinutes)} remaining in grace period`
            };
        }

        if (remainingMinutes !== null && remainingMinutes <= 15) {
            return {
                type: 'warning',
                title: 'Time Running Low',
                message: `Only ${formatTime(remainingMinutes)} left today`
            };
        }

        return null;
    }, [isTimeBlocked, currentBlock, isLimitExceeded, graceActive, remainingMinutes, formatTime]);

    // Initialize
    useEffect(() => {
        fetchScreenTimeData();

        // Refresh every 5 minutes
        const refreshInterval = setInterval(fetchScreenTimeData, 300000);

        return () => {
            clearInterval(refreshInterval);
            if (trackingInterval.current) {
                clearInterval(trackingInterval.current);
            }
        };
    }, [fetchScreenTimeData]);

    // Track visibility changes
    useEffect(() => {
        const handleVisibilityChange = () => {
            if (document.hidden) {
                endSession();
            } else {
                startSession();
            }
        };

        document.addEventListener('visibilitychange', handleVisibilityChange);

        // Start session on mount
        if (!document.hidden) {
            startSession();
        }

        return () => {
            document.removeEventListener('visibilitychange', handleVisibilityChange);
            endSession();
        };
    }, [startSession, endSession]);

    return {
        loading,
        limits,
        todayUsage,
        remainingMinutes,
        isLimitExceeded,
        isTimeBlocked,
        currentBlock,
        graceActive,
        formatTime,
        getStatusMessage,
        refresh: fetchScreenTimeData
    };
};

export default useScreenTime;

import { useState, useEffect, useCallback } from 'react';
import { supabase } from '../lib/supabase';
import useDebounce from './useDebounce';

const HISTORY_KEY = 'focus_search_history';
const scoreSimilarity = (value, term) => {
    const a = (value || '').toLowerCase();
    const b = (term || '').toLowerCase();
    if (!a || !b) return 0;
    if (a === b) return 1;
    if (a.startsWith(b)) return 0.9;
    if (a.includes(b)) return 0.7;
    const chars = b.split('');
    let hits = 0;
    chars.forEach((ch) => {
        if (a.includes(ch)) hits += 1;
    });
    return hits / chars.length * 0.5;
};

export const useSearch = () => {
    const [query, setQuery] = useState('');
    const [results, setResults] = useState({ users: [], hashtags: [], posts: [] });
    const [loading, setLoading] = useState(false);
    const [history, setHistory] = useState([]);

    const debouncedQuery = useDebounce(query, 300);

    // Load history on mount
    useEffect(() => {
        const savedHistory = localStorage.getItem(HISTORY_KEY);
        if (savedHistory) {
            setHistory(JSON.parse(savedHistory));
        }
    }, []);

    // Perform search
    useEffect(() => {
        const performSearch = async () => {
            if (!debouncedQuery || debouncedQuery.length < 2) {
                setResults({ users: [], hashtags: [], posts: [] });
                return;
            }

            setLoading(true);
            try {
                // Parallel search requests
                const [usersRes, hashtagsRes, postsRes] = await Promise.all([
                    supabase
                        .from('profiles')
                        .select('id, username, full_name, avatar_url, is_verified, trust_tier')
                        .or(`username.ilike.%${debouncedQuery}%,full_name.ilike.%${debouncedQuery}%`)
                        .limit(25),
                    supabase
                        .from('hashtags') // Assuming table exists
                        .select('id, name, count')
                        .ilike('name', `%${debouncedQuery}%`)
                        .limit(5),
                    supabase
                        .from('posts')
                        .select('id, media, type, caption')
                        .ilike('caption', `%${debouncedQuery}%`)
                        .limit(9)
                ]);

                const users = (usersRes.data || [])
                    .map((user) => ({
                        ...user,
                        verified: Boolean(user.is_verified || (user.trust_tier || 0) >= 4),
                        _score: Math.max(
                            scoreSimilarity(user.username, debouncedQuery),
                            scoreSimilarity(user.full_name, debouncedQuery)
                        )
                    }))
                    .sort((a, b) => b._score - a._score)
                    .slice(0, 8);

                setResults({
                    users,
                    hashtags: hashtagsRes.data || [],
                    posts: postsRes.data || []
                });
            } catch (error) {
                console.error('Search error:', error);
            } finally {
                setLoading(false);
            }
        };

        performSearch();
    }, [debouncedQuery]);

    const addToHistory = (term) => {
        const newHistory = [term, ...history.filter(h => h !== term)].slice(0, 10);
        setHistory(newHistory);
        localStorage.setItem(HISTORY_KEY, JSON.stringify(newHistory));
    };

    const clearHistory = () => {
        setHistory([]);
        localStorage.removeItem(HISTORY_KEY);
    };

    const removeFromHistory = (term) => {
        const newHistory = history.filter(h => h !== term);
        setHistory(newHistory);
        localStorage.setItem(HISTORY_KEY, JSON.stringify(newHistory));
    };

    return {
        query,
        setQuery,
        results,
        loading,
        history,
        addToHistory,
        clearHistory,
        removeFromHistory
    };
};

import { useState, useEffect } from 'react';
import { supabase } from '../lib/supabase';
import { useAuth } from './useAuth';

/**
 * Hook to fetch and manage user sessions
 * @returns {Object} { sessions, loading, endSession, endAllOtherSessions }
 */
export const useSessions = () => {
    const { user } = useAuth();
    const [sessions, setSessions] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    useEffect(() => {
        if (!user) {
            setSessions([]);
            setLoading(false);
            return;
        }

        fetchSessions();

        // Subscribe to real-time changes
        const channel = supabase
            .channel(`user-sessions-${user.id}`)
            .on('postgres_changes', {
                event: '*',
                schema: 'public',
                table: 'user_sessions',
                filter: `user_id=eq.${user.id}`
            }, (payload) => {
                console.log('≡ƒÆ╗ Sessions updated:', payload);
                fetchSessions();
            })
            .subscribe();

        return () => {
            channel.unsubscribe();
        };
    }, [user]);

    const fetchSessions = async () => {
        try {
            setLoading(true);
            console.log('≡ƒÆ╗ Fetching user sessions...');

            const { data, error: fetchError } = await supabase
                .from('user_sessions')
                .select('*')
                .eq('user_id', user.id)
                .order('last_active_at', { ascending: false });

            if (fetchError) throw fetchError;

            console.log('Γ£à Sessions fetched:', data?.length || 0);
            setSessions(data || []);
            setError(null);
        } catch (err) {
            console.error('Γ¥î Error fetching sessions:', err);
            setError(err.message);
            setSessions([]);
        } finally {
            setLoading(false);
        }
    };

    const endSession = async (sessionId) => {
        try {
            const { error } = await supabase
                .from('user_sessions')
                .delete()
                .eq('id', sessionId)
                .eq('user_id', user.id);

            if (error) throw error;

            console.log('Γ£à Session ended successfully');
            setSessions(prev => prev.filter(s => s.id !== sessionId));
            return { success: true };
        } catch (err) {
            console.error('Γ¥î Error ending session:', err);
            return { success: false, error: err.message };
        }
    };

    const endAllOtherSessions = async () => {
        try {
            const { error } = await supabase
                .from('user_sessions')
                .delete()
                .eq('user_id', user.id)
                .eq('is_current', false);

            if (error) throw error;

            console.log('Γ£à All other sessions ended successfully');
            await fetchSessions();
            return { success: true };
        } catch (err) {
            console.error('Γ¥î Error ending sessions:', err);
            return { success: false, error: err.message };
        }
    };

    return { sessions, loading, error, endSession, endAllOtherSessions, refetch: fetchSessions };
};

import { useState, useCallback } from 'react';
import { supabase } from '../lib/supabase';
import { useAuth } from './useAuth';
import { useRobustQuery } from './useRobustQuery';
import { useRealtimeSubscription } from './useRealtimeSubscription';
import { focusToast } from '../utils/focusToast';

const DEFAULT_SETTINGS = {
    theme: 'dark',
    font_size: 'medium',
    glassmorphism_enabled: true,
    high_contrast_mode: false,
    account_visibility: 'public',
    two_factor_enabled: false,
    show_activity_status: true,
    who_can_view_profile: 'everyone',
    who_can_view_posts: 'everyone',
    who_can_view_stories: 'everyone',
    who_can_view_boltz: 'everyone',
    push_notifications: true,
    email_notifications: true,
    in_app_notifications: true,
    notify_likes: true,
    notify_comments: true,
    notify_followers: true,
    notify_mentions: true,
    notify_messages: true,
    notify_boltz: true,
    notify_flash: true,
    notification_sound: 'default',
    quiet_hours_enabled: false,
    quiet_hours_start: null,
    quiet_hours_end: null
};

export const useSettings = () => {
    const { user } = useAuth();
    const [settings, setSettings] = useState(null);
    const [saving, setSaving] = useState(false);

    // 1. Fetch Settings Logic
    const fetchSettingsData = useCallback(async () => {
        if (!user) return null;

        // Try cache first
        const cached = localStorage.getItem(`settings_${user.id}`);
        if (cached && !settings) {
            try {
                setSettings(JSON.parse(cached));
            } catch (e) { }
        }

        const { data, error } = await supabase
            .from('user_settings')
            .select('*')
            .eq('user_id', user.id)
            .single();

        if (error) {
            if (error.code === 'PGRST116') {
                // Create default settings
                const newSettings = { ...DEFAULT_SETTINGS, user_id: user.id };
                const { data: created, error: createError } = await supabase
                    .from('user_settings')
                    .insert([newSettings])
                    .select()
                    .single();
                if (createError) throw createError;
                return created;
            }
            throw error;
        }

        return data || { ...DEFAULT_SETTINGS, user_id: user.id };
    }, [user, settings]);

    const {
        data: fetchedSettings,
        loading,
        error,
        refetch
    } = useRobustQuery(fetchSettingsData, {
        enabled: !!user,
        retries: 3,
        onSuccess: (data) => {
            if (data) {
                setSettings(data);
                localStorage.setItem(`settings_${user.id}`, JSON.stringify(data));
            }
        }
    });

    // 2. Realtime Subscription
    useRealtimeSubscription({
        channelName: `settings-${user?.id}`,
        table: 'user_settings',
        event: 'UPDATE',
        filter: `user_id=eq.${user?.id}`,
        enabled: !!user,
        onEvent: (payload) => {
            console.log('Γ£à Settings updated from another device');
            setSettings(payload.new);
            localStorage.setItem(`settings_${user.id}`, JSON.stringify(payload.new));
            focusToast.info('Settings synced from another device');
        }
    });

    // 3. Update Settings Function - CRITICAL FOR SAVING
    const updateSettings = useCallback(async (newSettings) => {
        if (!user) {
            focusToast.error('You must be logged in to change settings');
            return { success: false, error: 'Not logged in' };
        }

        // Store previous settings for rollback
        const previousSettings = settings;

        // Optimistic update - immediately show change in UI
        const updatedSettings = { ...settings, ...newSettings };
        setSettings(updatedSettings);

        setSaving(true);
        try {
            const { data, error: updateError } = await supabase
                .from('user_settings')
                .upsert({
                    user_id: user.id,
                    ...updatedSettings,
                    updated_at: new Date().toISOString()
                }, {
                    onConflict: 'user_id'
                })
                .select()
                .single();

            if (updateError) throw updateError;

            // Update cache
            localStorage.setItem(`settings_${user.id}`, JSON.stringify(data));
            focusToast.success('Settings saved!');
            console.log('Γ£à Settings saved successfully:', data);
            return { success: true, data };
        } catch (err) {
            // Revert to previous settings on error
            setSettings(previousSettings);
            console.error('Γ¥î Settings update error:', err);
            focusToast.error('Failed to save settings. Changes were rolled back.');
            return { success: false, error: err.message };
        } finally {
            setSaving(false);
        }
    }, [user, settings]);

    // 4. Update Single Setting - convenience function
    const updateSetting = useCallback(async (key, value) => {
        return updateSettings({ [key]: value });
    }, [updateSettings]);

    return {
        settings: settings || DEFAULT_SETTINGS,
        loading,
        error,
        refetch,
        updateSettings,
        updateSetting,
        saving
    };
};

/**
 * useStrikeSystem.js
 * ==================
 * Automated 3-strike enforcement system
 * Strike 1 ΓåÆ Warning
 * Strike 2 ΓåÆ 24h Ghost Protocol (shadow-ban)
 * Strike 3 ΓåÆ Permanent Quarantine
 *
 * H2 Innovative ΓÇö Content Constitution
 */

import { useState, useCallback } from 'react';
import { supabase } from '../lib/supabase';
import { useAuth } from './useAuth';
import { toast } from 'react-toastify';

const STRIKE_ACTIONS = {
  1: 'warning',
  2: 'shadow_ban',
  3: 'quarantine',
};

const SHADOW_BAN_DURATION_HOURS = 24;

export const useStrikeSystem = () => {
  const { user } = useAuth();
  const [processing, setProcessing] = useState(false);

  /**
   * Get current strike count for a user
   */
  const getStrikeCount = useCallback(async (userId = user?.id) => {
    if (!userId) return 0;
    const { data, error } = await supabase
      .from('content_strikes')
      .select('id')
      .eq('user_id', userId);
    if (error) return 0;
    return data?.length || 0;
  }, [user?.id]);

  /**
   * Record a strike and enforce action
   * @param {Object} params
   * @param {string} params.userId
   * @param {string} params.reason           - Human-readable reason
   * @param {string} params.violationType    - 'nsfw', 'hate_speech', 'violence', etc.
   * @param {string} params.contentSnapshot  - Truncated offending content
   * @param {string} params.geminiExplanation- AI-generated educational explanation
   * @param {string} [params.contentId]      - ID of the blocked content
   * @param {string} [params.contentType]    - 'post', 'comment', 'boltz'
   */
  const recordStrike = useCallback(async ({
    userId,
    reason,
    violationType,
    contentSnapshot = '',
    geminiExplanation = '',
    contentId = null,
    contentType = 'post',
  }) => {
    if (!userId) return { success: false, error: 'No user ID' };

    setProcessing(true);
    try {
      // 1. Count existing strikes
      const existingCount = await getStrikeCount(userId);
      const newStrikeNumber = existingCount + 1;
      const action = STRIKE_ACTIONS[Math.min(newStrikeNumber, 3)];

      // 2. Determine shadow ban expiry if applicable
      const shadowBanUntil = action === 'shadow_ban'
        ? new Date(Date.now() + SHADOW_BAN_DURATION_HOURS * 60 * 60 * 1000).toISOString()
        : null;

      // 3. Insert strike record
      const { error: strikeError } = await supabase
        .from('content_strikes')
        .insert({
          user_id: userId,
          strike_number: newStrikeNumber,
          reason,
          violation_type: violationType,
          content_id: contentId,
          content_type: contentType,
          content_snapshot: contentSnapshot.slice(0, 500),
          action_taken: action,
          shadow_ban_until: shadowBanUntil,
          gemini_explanation: geminiExplanation,
        });

      if (strikeError) throw strikeError;

      // 4. Enforce on user profile
      const profileUpdates = {
        strike_count: newStrikeNumber,
        updated_at: new Date().toISOString(),
      };

      if (action === 'shadow_ban') {
        profileUpdates.account_status = 'SHADOW_BANNED';
        profileUpdates.shadow_banned_until = shadowBanUntil;
      } else if (action === 'quarantine') {
        profileUpdates.account_status = 'QUARANTINED';
        profileUpdates.shadow_banned_until = null;
      }

      await supabase
        .from('profiles')
        .update(profileUpdates)
        .eq('id', userId);

      // 5. Return result with action details
      return {
        success: true,
        strikeNumber: newStrikeNumber,
        action,
        shadowBanUntil,
        isQuarantined: action === 'quarantine',
        isShadowBanned: action === 'shadow_ban',
      };
    } catch (err) {
      console.error('[StrikeSystem] Error recording strike:', err);
      return { success: false, error: err.message };
    } finally {
      setProcessing(false);
    }
  }, [user?.id, getStrikeCount]);

  /**
   * Check if the current user can post (not shadow-banned or quarantined)
   * Returns { canPost, reason, accountStatus }
   */
  const checkPostPermission = useCallback(async (userId = user?.id) => {
    if (!userId) return { canPost: false, reason: 'Not authenticated' };

    const { data, error } = await supabase
      .from('profiles')
      .select('account_status, shadow_banned_until, strike_count')
      .eq('id', userId)
      .single();

    if (error || !data) return { canPost: true, accountStatus: 'ACTIVE' };

    const status = data.account_status || 'ACTIVE';

    if (status === 'QUARANTINED') {
      return {
        canPost: false,
        accountStatus: status,
        reason: 'Your account has been permanently quarantined due to repeated violations of the Focus Constitution.',
      };
    }

    if (status === 'SHADOW_BANNED') {
      const banUntil = new Date(data.shadow_banned_until);
      const now = new Date();
      if (now < banUntil) {
        const hoursLeft = Math.ceil((banUntil - now) / (1000 * 60 * 60));
        // Ghost Protocol: user can "post" but content is invisible
        // We still allow the API call to succeed ΓÇö just mark content as ghost
        return {
          canPost: true,
          isGhost: true,   // ΓåÉ Content saved but invisible to others
          accountStatus: status,
          shadowBanExpiresAt: data.shadow_banned_until,
          reason: `Ghost Protocol active. Your content is not visible to others. Lifts in ${hoursLeft}h.`,
        };
      } else {
        // Ban expired ΓÇö lift it
        await supabase
          .from('profiles')
          .update({ account_status: 'ACTIVE', shadow_banned_until: null })
          .eq('id', userId);
        return { canPost: true, accountStatus: 'ACTIVE', isGhost: false };
      }
    }

    return { canPost: true, accountStatus: status, strikeCount: data.strike_count };
  }, [user?.id]);

  /**
   * Acknowledge a strike's educational content
   */
  const acknowledgeStrike = useCallback(async (strikeId) => {
    await supabase
      .from('content_strikes')
      .update({ educational_acknowledged: true, acknowledged_at: new Date().toISOString() })
      .eq('id', strikeId);
  }, []);

  return {
    processing,
    recordStrike,
    getStrikeCount,
    checkPostPermission,
    acknowledgeStrike,
  };
};

export default useStrikeSystem;

import { useState } from 'react';
import { supabase } from '../lib/supabase';
import { v4 as uuidv4 } from 'uuid';

export const useUploadMedia = () => {
    const [uploading, setUploading] = useState(false);
    const [progress, setProgress] = useState(0);
    const [error, setError] = useState(null);

    const uploadFile = async (file, bucket = 'posts') => {
        setUploading(true);
        setProgress(0);
        setError(null);

        try {
            const fileExt = file.name.split('.').pop();
            const fileName = `${uuidv4()}.${fileExt}`;
            const filePath = `${fileName}`;

            const { data, error: uploadError } = await supabase.storage
                .from(bucket)
                .upload(filePath, file, {
                    cacheControl: '3600',
                    upsert: false
                });

            if (uploadError) throw uploadError;

            // Get public URL
            const { data: { publicUrl } } = supabase.storage
                .from(bucket)
                .getPublicUrl(filePath);

            setProgress(100);
            return publicUrl;

        } catch (err) {
            console.error('Upload error:', err);
            setError(err.message);
            return null;
        } finally {
            setUploading(false);
        }
    };

    const uploadMultipleFiles = async (files, bucket = 'posts') => {
        setUploading(true);
        setProgress(0);
        setError(null);

        const urls = [];
        let completed = 0;

        try {
            for (const file of files) {
                const url = await uploadFile(file, bucket);
                if (url) {
                    urls.push(url);
                    completed++;
                    setProgress((completed / files.length) * 100);
                } else {
                    throw new Error(`Failed to upload ${file.name}`);
                }
            }
            return urls;
        } catch (err) {
            setError(err.message);
            return null;
        } finally {
            setUploading(false);
        }
    };

    return { uploadFile, uploadMultipleFiles, uploading, progress, error };
};

import { useState, useEffect } from 'react';
import { useAuth } from './useAuth';
import { supabase } from '../lib/supabase';

export const useVerifications = () => {
    const { user } = useAuth();
    const [verifications, setVerifications] = useState({
        email: false,
        profile: false,
        oauth: false,
        biometric: false
    });
    const [loading, setLoading] = useState({});

    const checkVerifications = () => {
        const hasEmail = !!user.email_confirmed_at;

        // Check profile completeness
        const meta = user.user_metadata || {};
        const hasProfile = !!(meta.avatar_url && meta.bio && meta.full_name);

        // Check OAuth (identities array)
        const identities = user.identities || [];
        const hasOAuth = identities.some(id => id.provider !== 'email');

        // Check Biometric (stored in metadata or local preference for now)
        const hasBiometric = localStorage.getItem('biometric_lock_enabled') === 'true';

        setVerifications({
            email: hasEmail,
            profile: hasProfile,
            oauth: hasOAuth,
            biometric: hasBiometric
        });
    };

    useEffect(() => {
        if (user) {
            checkVerifications();
        }
    }, [user]);

    const verifyStep = async (stepId, params = {}) => {
        if (!user) {
            return { success: false, error: 'User not authenticated' };
        }
        setLoading(prev => ({ ...prev, [stepId]: true }));

        try {
            switch (stepId) {
                case 'email':
                    // Trigger email verification resend
                    if (!user.email_confirmed_at) {
                        const { error } = await supabase.auth.resend({
                            type: 'signup',
                            email: user.email,
                        });
                        if (error) throw error;
                        return { success: true, message: 'Verification email sent!' };
                    }
                    break;

                case 'oauth':
                    // Initiate OAuth flow
                    const { data, error } = await supabase.auth.signInWithOAuth({
                        provider: params.provider,
                        options: {
                            redirectTo: window.location.origin + '/verification-center'
                        }
                    });
                    if (error) throw error;
                    break;

                case 'biometric':
                    // Register WebAuthn credential
                    if (!window.PublicKeyCredential) {
                        throw new Error('Biometrics not supported');
                    }

                    // Create challenge
                    const challenge = new Uint8Array(32);
                    window.crypto.getRandomValues(challenge);

                    const credential = await navigator.credentials.create({
                        publicKey: {
                            challenge,
                            rp: { name: 'Focus App' },
                            user: {
                                id: Uint8Array.from(user.id.split('').map(c => c.charCodeAt(0))),
                                name: user.email,
                                displayName: user.user_metadata?.full_name || user.email
                            },
                            pubKeyCredParams: [{ alg: -7, type: 'public-key' }],
                            authenticatorSelection: {
                                authenticatorAttachment: 'platform',
                                userVerification: 'required'
                            },
                            timeout: 60000
                        }
                    });

                    if (credential) {
                        localStorage.setItem('biometric_lock_enabled', 'true');
                        // Also update user metadata to reflect this for trust score
                        await supabase.auth.updateUser({
                            data: { biometric_enabled: true }
                        });
                        checkVerifications();
                        return { success: true, message: 'Biometric lock enabled!' };
                    }
                    break;

                default:
                    break;
            }
        } catch (error) {
            console.error('Verification error:', error);
            return { success: false, error: error.message };
        } finally {
            setLoading(prev => ({ ...prev, [stepId]: false }));
        }
    };

    return { verifications, verifyStep, loading };
};

import { useState, useCallback } from 'react';
import { supabase } from '../lib/supabase';
import { focusToast } from '../utils/focusToast';

/**
 * Hook for recording and sending video notes
 * WhatsApp-style short video messages (up to 60 seconds)
 */
export const useVideoNotes = () => {
    const [recording, setRecording] = useState(false);
    const [mediaRecorder, setMediaRecorder] = useState(null);
    const [recordedChunks, setRecordedChunks] = useState([]);
    const [duration, setDuration] = useState(0);

    const MAX_DURATION = 60; // 60 seconds

    // Start recording
    const startRecording = useCallback(async () => {
        try {
            const stream = await navigator.mediaDevices.getUserMedia({
                video: { facingMode: 'user', width: 720, height: 720 },
                audio: true
            });

            const recorder = new MediaRecorder(stream, {
                mimeType: 'video/webm;codecs=vp9'
            });

            const chunks = [];
            recorder.ondataavailable = (e) => {
                if (e.data.size > 0) {
                    chunks.push(e.data);
                }
            };

            recorder.onstop = () => {
                setRecordedChunks(chunks);
                stream.getTracks().forEach(track => track.stop());
            };

            setMediaRecorder(recorder);
            setRecordedChunks([]);
            setDuration(0);
            recorder.start();
            setRecording(true);

            // Auto-stop after max duration
            setTimeout(() => {
                if (recorder.state === 'recording') {
                    stopRecording();
                }
            }, MAX_DURATION * 1000);

        } catch (error) {
            console.error('Error starting video recording:', error);
            focusToast.error('Failed to start recording');
        }
    }, []);

    // Stop recording
    const stopRecording = useCallback(() => {
        if (mediaRecorder && mediaRecorder.state === 'recording') {
            mediaRecorder.stop();
            setRecording(false);
        }
    }, [mediaRecorder]);

    // Send video note
    const sendVideoNote = useCallback(async (conversationId, senderId, receiverId) => {
        if (recordedChunks.length === 0) {
            focusToast.error('No video recorded');
            return null;
        }

        try {
            const blob = new Blob(recordedChunks, { type: 'video/webm' });
            const fileName = `video-note-${Date.now()}.webm`;

            // Upload to Supabase Storage
            const { data: uploadData, error: uploadError } = await supabase.storage
                .from('messages')
                .upload(`video-notes/${senderId}/${fileName}`, blob);

            if (uploadError) throw uploadError;

            // Get public URL
            const { data: { publicUrl } } = supabase.storage
                .from('messages')
                .getPublicUrl(uploadData.path);

            // Create message
            const { data, error } = await supabase
                .from('messages')
                .insert({
                    sender_id: senderId,
                    receiver_id: receiverId,
                    conversation_id: conversationId,
                    message_type: 'video_note',
                    content: 'Video note',
                    attachments: [{
                        type: 'video_note',
                        url: publicUrl,
                        duration: duration
                    }]
                })
                .select()
                .single();

            if (error) throw error;

            focusToast.success('Video note sent');
            setRecordedChunks([]);
            return data;
        } catch (error) {
            console.error('Error sending video note:', error);
            focusToast.error('Failed to send video note');
            return null;
        }
    }, [recordedChunks, duration]);

    return {
        recording,
        duration,
        startRecording,
        stopRecording,
        sendVideoNote,
        maxDuration: MAX_DURATION
    };
};

import { useEffect, useRef } from 'react';

export const useVideoPlayer = (currentIndex, videos, playing, muted) => {
    const videoRefs = useRef([]);

    useEffect(() => {
        // Pause all videos except current
        videoRefs.current.forEach((video, index) => {
            if (video) {
                if (index === currentIndex && playing) {
                    video.play().catch(err => {
                        if (err.name !== 'AbortError') {
                            console.error('Play error:', err);
                        }
                    });
                } else {
                    video.pause();
                }
                video.muted = muted;
            }
        });
    }, [currentIndex, playing, muted]);

    // Cleanup on unmount
    useEffect(() => {
        return () => {
            videoRefs.current.forEach(video => {
                if (video) {
                    video.pause();
                    video.src = '';
                }
            });
        };
    }, []);

    const setVideoRef = (index) => (ref) => {
        videoRefs.current[index] = ref;
    };

    return { setVideoRef, videoRefs };
};

import { useState, useEffect, useRef, useCallback } from 'react';
import { supabase } from '../lib/supabase';

/**
 * Custom hook for WebRTC peer-to-peer connections
 * Handles signaling via Supabase Realtime
 */
export const useWebRTC = (localUserId, remoteUserId, conversationId) => {
    const [localStream, setLocalStream] = useState(null);
    const [remoteStream, setRemoteStream] = useState(null);
    const [isConnected, setIsConnected] = useState(false);
    const [error, setError] = useState(null);

    const peerConnection = useRef(null);
    const signalingChannel = useRef(null);

    // ICE servers configuration (using free STUN/TURN servers)
    const iceServers = {
        iceServers: [
            // Google STUN servers
            { urls: 'stun:stun.l.google.com:19302' },
            { urls: 'stun:stun1.l.google.com:19302' },
            // Free TURN server from Metered (no auth required for testing)
            {
                urls: 'turn:openrelay.metered.ca:80',
                username: 'openrelayproject',
                credential: 'openrelayproject'
            },
            {
                urls: 'turn:openrelay.metered.ca:443',
                username: 'openrelayproject',
                credential: 'openrelayproject'
            },
            {
                urls: 'turn:openrelay.metered.ca:443?transport=tcp',
                username: 'openrelayproject',
                credential: 'openrelayproject'
            }
        ]
    };

    // Send signaling message via Supabase Realtime
    const sendSignal = useCallback(async (signal) => {
        try {
            const { error } = await supabase
                .from('call_signals')
                .insert({
                    conversation_id: conversationId,
                    from_user_id: signal.from,
                    to_user_id: signal.to,
                    signal_type: signal.type,
                    signal_data: signal
                });

            if (error) throw error;
            console.log('≡ƒôñ Signal sent:', signal.type);
        } catch (err) {
            console.error('Γ¥î Error sending signal:', err);
        }
    }, [conversationId]);

    // Initialize peer connection
    const initializePeerConnection = useCallback(() => {
        try {
            peerConnection.current = new RTCPeerConnection(iceServers);

            // Handle ICE candidates
            peerConnection.current.onicecandidate = (event) => {
                if (event.candidate) {
                    console.log('≡ƒôí Sending ICE candidate:', event.candidate);
                    sendSignal({
                        type: 'ice-candidate',
                        candidate: event.candidate,
                        from: localUserId,
                        to: remoteUserId
                    });
                }
            };

            // Handle remote stream
            peerConnection.current.ontrack = (event) => {
                console.log('≡ƒôÑ Received remote track:', event.streams[0]);
                setRemoteStream(event.streams[0]);
            };

            // Handle connection state changes
            peerConnection.current.onconnectionstatechange = () => {
                const state = peerConnection.current.connectionState;
                console.log('≡ƒöù Connection state:', state);
                setIsConnected(state === 'connected');

                if (state === 'failed' || state === 'disconnected') {
                    setError('Connection failed or disconnected');
                }
            };

            console.log('Γ£à Peer connection initialized');
        } catch (err) {
            console.error('Γ¥î Error initializing peer connection:', err);
            setError(err.message);
        }
    }, [localUserId, remoteUserId, sendSignal]);

    // Handle incoming signaling messages
    const handleSignal = useCallback(async (signal) => {
        console.log('≡ƒô¿ Received signal:', signal.type);

        try {
            switch (signal.type) {
                case 'offer':
                    await peerConnection.current.setRemoteDescription(
                        new RTCSessionDescription(signal.offer)
                    );
                    const answer = await peerConnection.current.createAnswer();
                    await peerConnection.current.setLocalDescription(answer);
                    sendSignal({
                        type: 'answer',
                        answer: answer,
                        from: localUserId,
                        to: remoteUserId
                    });
                    break;

                case 'answer':
                    await peerConnection.current.setRemoteDescription(
                        new RTCSessionDescription(signal.answer)
                    );
                    break;

                case 'ice-candidate':
                    await peerConnection.current.addIceCandidate(
                        new RTCIceCandidate(signal.candidate)
                    );
                    break;

                default:
                    console.warn('Unknown signal type:', signal.type);
            }
        } catch (err) {
            console.error('Γ¥î Error handling signal:', err);
            setError(err.message);
        }
    }, [localUserId, remoteUserId, sendSignal]);

    // Start call (initiator)
    const startCall = useCallback(async (audioOnly = false) => {
        try {
            console.log('≡ƒô₧ Starting call...', audioOnly ? 'Audio only' : 'Audio + Video');

            // Get local media stream
            const stream = await navigator.mediaDevices.getUserMedia({
                audio: true,
                video: !audioOnly
            });

            setLocalStream(stream);

            // Initialize peer connection
            initializePeerConnection();

            // Add local tracks to peer connection
            stream.getTracks().forEach(track => {
                peerConnection.current.addTrack(track, stream);
            });

            // Create and send offer
            const offer = await peerConnection.current.createOffer();
            await peerConnection.current.setLocalDescription(offer);

            sendSignal({
                type: 'offer',
                offer: offer,
                from: localUserId,
                to: remoteUserId
            });

            console.log('Γ£à Call started');
        } catch (err) {
            console.error('Γ¥î Error starting call:', err);
            setError(err.message);
        }
    }, [localUserId, remoteUserId, initializePeerConnection, sendSignal]);

    // Answer call (receiver)
    const answerCall = useCallback(async (audioOnly = false) => {
        try {
            console.log('≡ƒô₧ Answering call...');

            // Initialize peer connection if not already done
            if (!peerConnection.current) {
                initializePeerConnection();
            }

            // Get local media stream
            const stream = await navigator.mediaDevices.getUserMedia({
                audio: true,
                video: !audioOnly
            });

            setLocalStream(stream);

            // Add local tracks to peer connection
            stream.getTracks().forEach(track => {
                peerConnection.current.addTrack(track, stream);
            });

            console.log('Γ£à Call answered, waiting for offer');
        } catch (err) {
            console.error('Γ¥î Error answering call:', err);
            setError(err.message);
        }
    }, [initializePeerConnection]);

    // End call
    const endCall = useCallback(() => {
        console.log('≡ƒô┤ Ending call...');

        // Stop local stream
        if (localStream) {
            localStream.getTracks().forEach(track => track.stop());
            setLocalStream(null);
        }

        // Close peer connection
        if (peerConnection.current) {
            peerConnection.current.close();
            peerConnection.current = null;
        }

        setRemoteStream(null);
        setIsConnected(false);
        console.log('Γ£à Call ended');
    }, [localStream]);

    // Toggle audio
    const toggleAudio = useCallback(() => {
        if (localStream) {
            const audioTrack = localStream.getAudioTracks()[0];
            if (audioTrack) {
                audioTrack.enabled = !audioTrack.enabled;
                return audioTrack.enabled;
            }
        }
        return false;
    }, [localStream]);

    // Toggle video
    const toggleVideo = useCallback(() => {
        if (localStream) {
            const videoTrack = localStream.getVideoTracks()[0];
            if (videoTrack) {
                videoTrack.enabled = !videoTrack.enabled;
                return videoTrack.enabled;
            }
        }
        return false;
    }, [localStream]);

    // Set up signaling channel
    useEffect(() => {
        if (!conversationId || !localUserId) return;

        console.log('≡ƒöî Setting up signaling channel...');

        try {
            // Subscribe to call signals
            signalingChannel.current = supabase
                .channel(`call_${conversationId}`)
                .on('postgres_changes', {
                    event: 'INSERT',
                    schema: 'public',
                    table: 'call_signals',
                    filter: `to_user_id=eq.${localUserId}`
                }, (payload) => {
                    console.log('≡ƒô¿ Signal received via Realtime');
                    handleSignal(payload.new.signal_data);
                })
                .subscribe((status) => {
                    console.log('≡ƒôí Signaling channel status:', status);
                    if (status === 'SUBSCRIBED') {
                        console.log('Γ£à Signaling channel ready');
                    } else if (status === 'CHANNEL_ERROR') {
                        console.error('Γ¥î Signaling channel error - table may not exist. Run create_calls_tables.sql migration.');
                    }
                });

            return () => {
                if (signalingChannel.current) {
                    console.log('≡ƒöî Unsubscribing from signaling channel');
                    signalingChannel.current.unsubscribe();
                }
            };
        } catch (err) {
            console.error('Γ¥î Error setting up signaling channel:', err);
            console.error('≡ƒÆí Make sure to run create_calls_tables.sql migration in Supabase');
        }
    }, [conversationId, localUserId, handleSignal]);

    // Cleanup on unmount
    useEffect(() => {
        return () => {
            endCall();
        };
    }, [endCall]);

    return {
        localStream,
        remoteStream,
        isConnected,
        error,
        startCall,
        answerCall,
        endCall,
        toggleAudio,
        toggleVideo
    };
};

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import MainLayout from '../components/layout/MainLayout';
import BadgeDisplay from '../components/badge/BadgeDisplay';
import BadgeProgress from '../components/badge/BadgeProgress';
import BadgeApplication from '../components/badge/BadgeApplication';
import BadgeCount from '../components/shared/BadgeCount';
import { useUserBadges } from '../hooks/useUserBadges';
import { useBadgeCriteria } from '../hooks/useBadgeCriteria';
import { useBadgeProgress } from '../hooks/useBadgeProgress';
import { useAuth } from '../hooks/useAuth';
import { BADGE_DEFINITIONS, getAllBadgeDefinitions } from '../utils/badgeRules';
import { formatDateAwarded, groupBadgesByCategory } from '../utils/badgeFormatter';
import styles from './BadgeCenter.module.css';

/**
 * BadgeCenter Page
 * Main badge center showing all badges, progress, and application options
 */
const BadgeCenter = () => {
    const navigate = useNavigate();
    const { user, loading: authLoading } = useAuth();
    const { badges, badgeCount, loading: badgesLoading } = useUserBadges();
    const { eligibleBadges, loading: criteriaLoading } = useBadgeCriteria();
    const { progress, nextBadge, loading: progressLoading } = useBadgeProgress();

    const [selectedBadge, setSelectedBadge] = useState(null);
    const [showApplication, setShowApplication] = useState(false);
    const [activeTab, setActiveTab] = useState('all'); // all, earned, locked

    const loading = authLoading || badgesLoading || criteriaLoading || progressLoading;

    if (authLoading) {
        return (
            <MainLayout>
                <div className={styles.loading}>Loading...</div>
            </MainLayout>
        );
    }

    if (!user) {
        navigate('/auth');
        return null;
    }

    const allBadgeDefinitions = getAllBadgeDefinitions();
    const earnedBadgeNames = badges.map(b => b.badge?.name);
    const categorizedBadges = groupBadgesByCategory(badges);

    const handleBadgeClick = (badgeName) => {
        const definition = BADGE_DEFINITIONS[badgeName];
        setSelectedBadge({ name: badgeName, ...definition });
    };

    const handleApply = (badgeName) => {
        const definition = BADGE_DEFINITIONS[badgeName];
        setSelectedBadge({ name: badgeName, ...definition });
        setShowApplication(true);
    };

    return (
        <MainLayout>
            <div className={styles.badgeCenter}>
                {/* Header */}
                <div className={styles.header}>
                    <div>
                        <h1 className={styles.title}>Badge Center</h1>
                        <p className={styles.subtitle}>Earn badges by completing achievements and verifications</p>
                    </div>
                    <BadgeCount count={badgeCount} size="lg" />
                </div>

                {/* Next Badge to Earn */}
                {nextBadge && (
                    <div className={styles.nextBadge}>
                        <div className={styles.nextBadgeIcon}>
                            <BadgeDisplay badge={nextBadge} size="xl" showTooltip={false} />
                        </div>
                        <div className={styles.nextBadgeInfo}>
                            <div className={styles.nextBadgeLabel}>Next Badge</div>
                            <div className={styles.nextBadgeName}>{nextBadge.name}</div>
                            <div className={styles.nextBadgeProgress}>
                                {nextBadge.progressPercent}% complete
                            </div>
                        </div>
                        {nextBadge.requiresApplication && nextBadge.progressPercent === 100 && (
                            <button
                                className={styles.applyButton}
                                onClick={() => handleApply(nextBadge.badgeType)}
                            >
                                Apply Now
                            </button>
                        )}
                    </div>
                )}

                {/* Tabs */}
                <div className={styles.tabs}>
                    <button
                        className={`${styles.tab} ${activeTab === 'all' ? styles.active : ''}`}
                        onClick={() => setActiveTab('all')}
                    >
                        All Badges
                    </button>
                    <button
                        className={`${styles.tab} ${activeTab === 'earned' ? styles.active : ''}`}
                        onClick={() => setActiveTab('earned')}
                    >
                        Earned ({badgeCount})
                    </button>
                    <button
                        className={`${styles.tab} ${activeTab === 'locked' ? styles.active : ''}`}
                        onClick={() => setActiveTab('locked')}
                    >
                        Locked ({allBadgeDefinitions.length - badgeCount})
                    </button>
                </div>

                {/* Content */}
                <div className={styles.content}>
                    {activeTab === 'all' && (
                        <div className={styles.badgeGrid}>
                            {allBadgeDefinitions.map(definition => {
                                const isEarned = earnedBadgeNames.includes(definition.name);
                                const badge = badges.find(b => b.badge?.name === definition.name);

                                return (
                                    <div
                                        key={definition.name}
                                        className={`${styles.badgeCard} ${isEarned ? styles.earned : styles.locked}`}
                                        onClick={() => handleBadgeClick(definition.name)}
                                    >
                                        <BadgeDisplay badge={definition} size="lg" showTooltip={false} />
                                        <div className={styles.badgeCardName}>{definition.name}</div>
                                        <div className={styles.badgeCardDescription}>{definition.description}</div>
                                        {isEarned && badge && (
                                            <div className={styles.earnedDate}>
                                                Earned {formatDateAwarded(badge.date_awarded)}
                                            </div>
                                        )}
                                        {!isEarned && definition.requiresApplication && (
                                            <button
                                                className={styles.cardApplyButton}
                                                onClick={(e) => {
                                                    e.stopPropagation();
                                                    handleApply(definition.name);
                                                }}
                                            >
                                                Apply
                                            </button>
                                        )}
                                    </div>
                                );
                            })}
                        </div>
                    )}

                    {activeTab === 'earned' && (
                        <div className={styles.earnedSection}>
                            {Object.entries(categorizedBadges).map(([category, categoryBadges]) => {
                                if (categoryBadges.length === 0) return null;

                                return (
                                    <div key={category} className={styles.category}>
                                        <h3 className={styles.categoryTitle}>
                                            {category.charAt(0).toUpperCase() + category.slice(1)}
                                        </h3>
                                        <div className={styles.badgeGrid}>
                                            {categoryBadges.map(badge => {
                                                const definition = BADGE_DEFINITIONS[badge.badge?.name];
                                                return (
                                                    <div
                                                        key={badge.id}
                                                        className={`${styles.badgeCard} ${styles.earned}`}
                                                        onClick={() => handleBadgeClick(badge.badge?.name)}
                                                    >
                                                        <BadgeDisplay badge={definition} size="lg" showTooltip={false} />
                                                        <div className={styles.badgeCardName}>{definition?.name}</div>
                                                        <div className={styles.earnedDate}>
                                                            {formatDateAwarded(badge.date_awarded)}
                                                        </div>
                                                    </div>
                                                );
                                            })}
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    )}

                    {activeTab === 'locked' && (
                        <BadgeProgress progressData={progress} earnedBadges={badges} />
                    )}
                </div>

                {/* Badge Application Modal */}
                {showApplication && selectedBadge && (
                    <BadgeApplication
                        isOpen={showApplication}
                        onClose={() => {
                            setShowApplication(false);
                            setSelectedBadge(null);
                        }}
                        badgeName={selectedBadge.name}
                        badgeDefinition={selectedBadge}
                    />
                )}
            </div>
        </MainLayout>
    );
};

export default BadgeCenter;

import React, { useState, useRef, useEffect } from 'react';
import styles from './EditMedia.module.css';
import FilterGallery, { FILTERS } from '../../components/create/FilterGallery';
import AdjustmentPanel from '../../components/create/AdjustmentPanel';
import VideoEditor from '../../components/create/VideoEditor';
import Button from '../../components/ui/Button';
import { ArrowLeft, ArrowRight, Wand2, Sliders, Crop, Type, Smile } from 'lucide-react';

const TABS = [
    { id: 'filter', icon: Wand2, label: 'Filter' },
    { id: 'adjust', icon: Sliders, label: 'Adjust' },
];

const EditMedia = ({ mode, mediaFiles, onUpdateMedia, onNext, onBack }) => {
    const [activeTab, setActiveTab] = useState('filter');
    const [currentMediaIndex, setCurrentMediaIndex] = useState(0);
    const canvasRef = useRef(null);

    const currentMedia = mediaFiles[currentMediaIndex];
    const edits = currentMedia.edits;

    useEffect(() => {
        if (!currentMedia || currentMedia.type === 'video') return;

        const canvas = canvasRef.current;
        const ctx = canvas.getContext('2d');
        const img = new Image();
        img.src = currentMedia.preview;

        img.onload = () => {
            canvas.width = img.width;
            canvas.height = img.height;

            const filterStyle = FILTERS.find(f => f.id === edits.filter)?.style || '';
            const brightness = `brightness(${edits.brightness}%)`;
            const contrast = `contrast(${edits.contrast}%)`;
            const saturate = `saturate(${edits.saturation}%)`;

            ctx.filter = `${filterStyle} ${brightness} ${contrast} ${saturate}`;

            ctx.drawImage(img, 0, 0);
        };
    }, [currentMedia, edits]);

    const handleEditChange = (key, value) => {
        onUpdateMedia(currentMedia.id, { [key]: value });
    };

    const handleVideoSave = (result) => {
        // Update all video metadata
        onUpdateMedia(currentMedia.id, {
            trim: result.trimRange,
            crop: result.crop,
            filters: result.filters,
            textOverlays: result.textOverlays,
            stickers: result.stickers,
            thumbnail: result.thumbnail,
            file: result.file, // If exported, this is the new file
            isEdited: true
        });
    };

    return (
        <div className={styles.container}>
            <div className={styles.header}>
                <Button variant="ghost" onClick={onBack}>
                    <ArrowLeft size={16} /> Back
                </Button>
                <h2>Edit {mode === 'flash' ? 'Media' : mode === 'boltz' ? 'Video' : 'Photo'}</h2>
                <Button onClick={onNext}>
                    Next <ArrowRight size={16} />
                </Button>
            </div>

            <div className={styles.workspace}>
                {currentMedia.type === 'video' ? (
                    <div className={styles.videoEditorWrapper}>
                        <VideoEditor
                            file={currentMedia.file}
                            onSave={handleVideoSave}
                            onCancel={() => { }} // No cancel needed in this flow
                            initialTrim={edits.trim}
                        />
                    </div>
                ) : (
                    <>
                        <div className={styles.previewArea}>
                            <canvas ref={canvasRef} className={styles.mediaPreview} />

                            {mediaFiles.length > 1 && (
                                <div className={styles.dots}>
                                    {mediaFiles.map((_, idx) => (
                                        <button
                                            key={idx}
                                            className={`${styles.dot} ${idx === currentMediaIndex ? styles.activeDot : ''}`}
                                            onClick={() => setCurrentMediaIndex(idx)}
                                        />
                                    ))}
                                </div>
                            )}
                        </div>

                        <div className={styles.toolsPanel}>
                            <div className={styles.tabs}>
                                {TABS.map(tab => (
                                    <button
                                        key={tab.id}
                                        className={`${styles.tab} ${activeTab === tab.id ? styles.activeTab : ''}`}
                                        onClick={() => setActiveTab(tab.id)}
                                    >
                                        <tab.icon size={20} />
                                        <span>{tab.label}</span>
                                    </button>
                                ))}
                            </div>

                            <div className={styles.toolContent}>
                                {activeTab === 'filter' && (
                                    <FilterGallery
                                        activeFilter={edits.filter}
                                        onSelect={(id) => handleEditChange('filter', id)}
                                        previewImage={currentMedia.preview}
                                    />
                                )}
                                {activeTab === 'adjust' && (
                                    <AdjustmentPanel
                                        values={edits}
                                        onChange={handleEditChange}
                                    />
                                )}
                            </div>
                        </div>
                    </>
                )}
            </div>
        </div>
    );
};

export default EditMedia;

import React, { useState, useRef, useEffect } from 'react';
import styles from './PreviewPost.module.css';
import Button from '../../components/ui/Button';
import { ArrowLeft, Calendar, Music, Play, Pause } from 'lucide-react';
import { usePublish } from '../../hooks/usePublish';
import { useNavigate } from 'react-router-dom';

const PreviewPost = ({ mediaFiles, details, music, createMode, onBack, onUpdateDetails }) => {
    const navigate = useNavigate();
    const { publish, loading, error } = usePublish();
    const [showConfetti, setShowConfetti] = useState(false);
    const [isPlaying, setIsPlaying] = useState(false);
    const [videoError, setVideoError] = useState(null);
    const videoRef = useRef(null);
    const audioRef = useRef(null);

    const currentMedia = mediaFiles[0];
    const isVideo = currentMedia?.type === 'video';
    const edits = currentMedia?.edits || {};

    // Cleanup audio/video on unmount
    useEffect(() => {
        return () => {
            try {
                if (videoRef.current) {
                    videoRef.current.pause();
                    videoRef.current.currentTime = 0;
                }
                if (audioRef.current) {
                    audioRef.current.pause();
                    audioRef.current.currentTime = 0;
                }
            } catch (err) {
                console.log('Cleanup error:', err);
            }
        };
    }, []);

    // Sync audio with video time (only while playing)
    useEffect(() => {
        if (!videoRef.current || !audioRef.current || !music || !isPlaying) return;

        let syncTimeout;

        const handleTimeUpdate = () => {
            if (audioRef.current && videoRef.current && isPlaying) {
                const timeDiff = Math.abs(audioRef.current.currentTime - videoRef.current.currentTime);
                // Resync if drift is more than 1 second
                if (timeDiff > 1) {
                    try {
                        audioRef.current.currentTime = videoRef.current.currentTime;
                    } catch (err) {
                        // Ignore sync errors
                    }
                }
            }
        };

        videoRef.current.addEventListener('timeupdate', handleTimeUpdate);

        return () => {
            if (videoRef.current) {
                videoRef.current.removeEventListener('timeupdate', handleTimeUpdate);
            }
            if (syncTimeout) {
                clearTimeout(syncTimeout);
            }
        };
    }, [music?.id, isPlaying]);

    // Handle video loading
    useEffect(() => {
        if (videoRef.current && isVideo) {
            const video = videoRef.current;

            const handleLoadedData = () => {
                console.log('Video loaded successfully');
                console.log('Video duration:', video.duration);
                console.log('Video dimensions:', video.videoWidth, 'x', video.videoHeight);
            };

            const handleError = (e) => {
                console.error('Video loading error:', e);
                console.error('Video error details:', video.error);
                setVideoError('Failed to load video. The exported file may be corrupted.');
            };

            const handleCanPlay = () => {
                console.log('Video can play');
            };

            video.addEventListener('loadeddata', handleLoadedData);
            video.addEventListener('error', handleError);
            video.addEventListener('canplay', handleCanPlay);

            return () => {
                video.removeEventListener('loadeddata', handleLoadedData);
                video.removeEventListener('error', handleError);
                video.removeEventListener('canplay', handleCanPlay);
            };
        }
    }, [currentMedia, edits.file, isVideo]);

    // Check if video has been exported (edits baked in)
    const hasExportedFile = edits.file && edits.isEdited;

    // Get the video source - use edited file if available, otherwise original preview
    const getVideoSource = () => {
        if (edits.file) {
            console.log('Using exported file:', edits.file);
            const url = URL.createObjectURL(edits.file);
            console.log('Generated URL:', url);
            return url;
        }
        console.log('Using original preview:', currentMedia.preview);
        return currentMedia.preview;
    };

    // Build filter string from edits (only apply if not already baked into exported file)
    const getFilterStyle = () => {
        if (hasExportedFile || !edits.filters) return 'none';
        const { brightness = 100, contrast = 100, saturate = 100, hueRotate = 0, sepia = 0, blur = 0 } = edits.filters;
        return `brightness(${brightness}%) contrast(${contrast}%) saturate(${saturate}%) hue-rotate(${hueRotate}deg) sepia(${sepia}%) blur(${blur}px)`;
    };

    // Build crop clip-path from edits (only apply if not already baked into exported file)
    const getCropStyle = () => {
        if (hasExportedFile || !edits.crop) return 'none';
        const { x = 0, y = 0, width = 100, height = 100 } = edits.crop;
        return `inset(${y}% ${100 - x - width}% ${100 - y - height}% ${x}%)`;
    };

    const togglePlay = () => {
        if (!videoRef.current) {
            console.log('No video reference');
            return;
        }

        console.log('Toggle play - current state:', isPlaying);
        console.log('Video element:', videoRef.current);
        console.log('Video src:', videoRef.current.src);

        try {
            if (isPlaying) {
                // Pause both
                console.log('Pausing video and audio');
                videoRef.current.pause();
                if (audioRef.current) {
                    audioRef.current.pause();
                }
                setIsPlaying(false);
            } else {
                // Play both - with minimal delay
                console.log('Starting video playback');
                const videoPromise = videoRef.current.play();

                if (videoPromise) {
                    videoPromise.then(() => {
                        console.log('Video started playing successfully');
                        setIsPlaying(true);
                    }).catch(err => {
                        console.error('Video play failed:', err);
                        setIsPlaying(false);
                    });
                }

                if (audioRef.current && music) {
                    console.log('Starting audio playback');
                    audioRef.current.currentTime = 0;
                    audioRef.current.play().catch(err => {
                        console.log('Audio play error:', err);
                    });
                }
            }
        } catch (err) {
            console.error('Toggle play error:', err);
        }
    };

    const handlePublish = async () => {
        const success = await publish(mediaFiles, details, music, createMode);
        if (success) {
            setShowConfetti(true);
            setTimeout(() => {
                navigate('/');
            }, 2000);
        }
    };

    return (
        <div className={styles.container}>
            <div className={styles.header}>
                <Button variant="ghost" onClick={onBack}>
                    <ArrowLeft size={16} /> Back
                </Button>
                <h2>Preview & Share ({createMode || 'unknown'})</h2>
                <Button onClick={handlePublish} disabled={loading}>
                    {loading ? 'Sharing...' : 'Share'}
                </Button>
            </div>

            <div className={styles.content}>
                <div className={styles.previewCard}>
                    <div className={styles.cardHeader}>
                        <div className={styles.avatar} />
                        <div className={styles.headerInfo}>
                            <span className={styles.username}>You</span>
                            {music && (
                                <div className={styles.musicTag}>
                                    <Music size={12} />
                                    <span>{music.name} ΓÇó {music.artist_name}</span>
                                </div>
                            )}
                        </div>
                    </div>

                    <div className={styles.mediaWrapper}>
                        {videoError ? (
                            <div className={styles.errorContainer}>
                                <p className={styles.errorText}>{videoError}</p>
                                <button
                                    className={styles.retryBtn}
                                    onClick={() => {
                                        setVideoError(null);
                                        if (videoRef.current) {
                                            videoRef.current.load();
                                        }
                                    }}
                                >
                                    Retry
                                </button>
                            </div>
                        ) : isVideo ? (
                            <div className={styles.videoContainer}>
                                <video
                                    ref={videoRef}
                                    src={getVideoSource()}
                                    className={styles.media}
                                    style={{
                                        filter: getFilterStyle(),
                                        clipPath: getCropStyle()
                                    }}
                                    onEnded={() => {
                                        console.log('Video ended');
                                        setIsPlaying(false);
                                        if (audioRef.current) {
                                            audioRef.current.pause();
                                        }
                                    }}
                                    onPlay={() => {
                                        console.log('Video play event');
                                        setIsPlaying(true);
                                    }}
                                    onPause={() => {
                                        console.log('Video pause event');
                                        setIsPlaying(false);
                                    }}
                                    onError={(e) => {
                                        console.error('Video element error:', e);
                                    }}
                                    onLoadStart={() => {
                                        console.log('Video load start');
                                    }}
                                    preload="metadata"
                                    playsInline
                                    muted={!music} // Only mute if no music
                                />
                                <div className={styles.playOverlay} onClick={togglePlay}>
                                    {isPlaying ? <Pause size={48} /> : <Play size={48} fill="white" />}
                                </div>
                                {music && (
                                    <audio
                                        ref={audioRef}
                                        src={music.audio}
                                        loop
                                        crossOrigin="anonymous"
                                    />
                                )}
                            </div>
                        ) : (
                            <img
                                src={currentMedia.preview}
                                className={styles.media}
                                style={{
                                    filter: edits.filter !== 'none'
                                        ? `url(#${edits.filter})`
                                        : 'none'
                                }}
                                alt="Preview"
                            />
                        )}
                    </div>

                    <div className={styles.captionInput}>
                        <textarea
                            className={styles.captionTextarea}
                            placeholder="Write a caption..."
                            value={details.caption || ''}
                            onChange={(e) => {
                                onUpdateDetails({ ...details, caption: e.target.value });
                            }}
                            maxLength={2200}
                            rows={3}
                        />
                        <div className={styles.captionCount}>
                            {(details.caption || '').length}/2200
                        </div>
                    </div>

                    <div className={styles.cardFooter}>
                        {details.caption && (
                            <p className={styles.caption}>
                                <span className={styles.username}>You</span> {details.caption}
                            </p>
                        )}
                    </div>
                </div>

                <div className={styles.actions}>
                    <Button variant="secondary" className={styles.actionBtn}>
                        <Calendar size={18} /> Schedule
                    </Button>
                    <Button variant="secondary" className={styles.actionBtn}>
                        Save Draft
                    </Button>
                </div>

                {error && <p className={styles.error}>{error}</p>}
            </div>
        </div>
    );
};

export default PreviewPost;

