// COMPLETE CHAT WINDOW - All 13 Features Integrated
// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ
// This is a REFERENCE IMPLEMENTATION showing how to integrate all features.
// Use this as a guide to update your existing ChatPane/ChatWindow component.
// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ

import React, { useState, useEffect, useRef } from 'react';
import { useRealtimeMessages } from '../../hooks/useRealtimeMessages';
import { useTypingIndicator } from '../../hooks/useTypingIndicator';
import { usePresence } from '../../hooks/usePresence';
import EnhancedMessageInput from './EnhancedMessageInput';
import EnhancedMessageBubble from './EnhancedMessageBubble';
import { formatDistanceToNow } from 'date-fns';
import styles from './CompleteChatWindow.module.css';

const CompleteChatWindow = ({
    conversationId,
    currentUserId,
    otherUserId,
    otherUserData,
    onBack,
    onCall, // Audio call handler
    onVideoCall // Video call handler
}) => {
    const [replyTo, setReplyTo] = useState(null);
    const [forwardMessage, setForwardMessage] = useState(null);
    const [showScrollButton, setShowScrollButton] = useState(false);

    const messagesEndRef = useRef(null);
    const messagesContainerRef = useRef(null);

    // Real-time messages
    const {
        messages,
        loading,
        sending,
        hasMore,
        sendMessage,
        markAsSeen,
        deleteMessage,
        loadMore
    } = useRealtimeMessages(conversationId, currentUserId);

    // Typing indicator
    const {
        typingUsers,
        setTyping
    } = useTypingIndicator(conversationId, currentUserId);

    // Online presence
    const {
        isOnline,
        lastSeen
    } = usePresence(otherUserId);

    // Auto-scroll to bottom on new messages
    useEffect(() => {
        if (messages.length > 0) {
            const lastMessage = messages[messages.length - 1];

            // Scroll if it's our message or if we're near bottom
            if (lastMessage.sender_id === currentUserId || isNearBottom()) {
                scrollToBottom();
            }

            // Mark as seen if not our message
            if (lastMessage.sender_id !== currentUserId) {
                markAsSeen(lastMessage.id);
            }
        }
    }, [messages, currentUserId, markAsSeen]);

    // Scroll to bottom
    const scrollToBottom = (smooth = true) => {
        messagesEndRef.current?.scrollIntoView({
            behavior: smooth ? 'smooth' : 'auto'
        });
    };

    // Check if near bottom
    const isNearBottom = () => {
        if (!messagesContainerRef.current) return true;
        const { scrollTop, scrollHeight, clientHeight } = messagesContainerRef.current;
        return scrollHeight - scrollTop - clientHeight < 100;
    };

    // Handle scroll for "scroll to bottom" button
    const handleScroll = () => {
        setShowScrollButton(!isNearBottom());

        // Load more messages when scrolling to top
        if (messagesContainerRef.current?.scrollTop === 0 && hasMore) {
            loadMore();
        }
    };

    // Handle typing change
    const handleTypingChange = (isTyping) => {
        setTyping(isTyping);
    };

    // Handle reply
    const handleReply = (message) => {
        setReplyTo(message);
    };

    // Handle delete
    const handleDelete = async (messageId, deleteForEveryone) => {
        try {
            await deleteMessage(messageId, deleteForEveryone);
        } catch (error) {
            alert('Failed to delete message: ' + error.message);
        }
    };

    // Handle forward
    const handleForward = (message) => {
        setForwardMessage(message);
        // TODO: Open forward modal
    };

    // Group messages by date
    const groupMessagesByDate = (messages) => {
        const groups = [];
        let currentDate = null;

        messages.forEach(message => {
            const messageDate = new Date(message.created_at).toDateString();

            if (messageDate !== currentDate) {
                currentDate = messageDate;
                groups.push({
                    type: 'date',
                    date: messageDate,
                    label: formatDateLabel(new Date(message.created_at))
                });
            }

            groups.push({
                type: 'message',
                data: message
            });
        });

        return groups;
    };

    // Format date label
    const formatDateLabel = (date) => {
        const today = new Date();
        const yesterday = new Date(today);
        yesterday.setDate(yesterday.getDate() - 1);

        if (date.toDateString() === today.toDateString()) {
            return 'Today';
        } else if (date.toDateString() === yesterday.toDateString()) {
            return 'Yesterday';
        } else {
            return date.toLocaleDateString('en-US', {
                month: 'short',
                day: 'numeric',
                year: date.getFullYear() !== today.getFullYear() ? 'numeric' : undefined
            });
        }
    };

    const groupedMessages = groupMessagesByDate(messages);

    return (
        <div className={styles.chatWindow}>
            {/* Header */}
            <div className={styles.header}>
                <button className={styles.backBtn} onClick={onBack}>
                    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                        <path d="M19 12H5M12 19l-7-7 7-7" />
                    </svg>
                </button>

                <div className={styles.userInfo} onClick={() => {/* Navigate to profile */ }}>
                    <div className={styles.avatarContainer}>
                        <img
                            src={otherUserData?.avatar_url || '/default-avatar.png'}
                            alt={otherUserData?.username}
                            className={styles.avatar}
                        />
                        {isOnline && <div className={styles.onlineIndicator}></div>}
                    </div>
                    <div className={styles.userDetails}>
                        <div className={styles.username}>{otherUserData?.username}</div>
                        <div className={styles.status}>
                            {isOnline ? (
                                'Online'
                            ) : lastSeen ? (
                                `Last seen ${formatDistanceToNow(new Date(lastSeen), { addSuffix: true })}`
                            ) : (
                                'Offline'
                            )}
                        </div>
                    </div>
                </div>

                <div className={styles.headerActions}>
                    {/* Audio Call */}
                    <button
                        className={styles.headerBtn}
                        onClick={() => onCall?.(otherUserId)}
                        title="Audio call"
                    >
                        <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                            <path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.79 19.79 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6 19.79 19.79 0 0 1-3.07-8.67A2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72 12.84 12.84 0 0 0 .7 2.81 2 2 0 0 1-.45 2.11L8.09 9.91a16 16 0 0 0 6 6l1.27-1.27a2 2 0 0 1 2.11-.45 12.84 12.84 0 0 0 2.81.7A2 2 0 0 1 22 16.92z" />
                        </svg>
                    </button>

                    {/* Video Call */}
                    <button
                        className={styles.headerBtn}
                        onClick={() => onVideoCall?.(otherUserId)}
                        title="Video call"
                    >
                        <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                            <polygon points="23 7 16 12 23 17 23 7" />
                            <rect x="1" y="5" width="15" height="14" rx="2" ry="2" />
                        </svg>
                    </button>

                    {/* Menu */}
                    <button className={styles.headerBtn} title="More options">
                        <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                            <circle cx="12" cy="12" r="1" />
                            <circle cx="12" cy="5" r="1" />
                            <circle cx="12" cy="19" r="1" />
                        </svg>
                    </button>
                </div>
            </div>

            {/* Messages Container */}
            <div
                className={styles.messagesContainer}
                ref={messagesContainerRef}
                onScroll={handleScroll}
            >
                {loading && messages.length === 0 ? (
                    <div className={styles.loadingState}>
                        <div className={styles.spinner}></div>
                        <p>Loading messages...</p>
                    </div>
                ) : messages.length === 0 ? (
                    <div className={styles.emptyState}>
                        <div className={styles.emptyIcon}>≡ƒÆ¼</div>
                        <h3>No messages yet</h3>
                        <p>Send a message to start the conversation!</p>
                    </div>
                ) : (
                    <>
                        {hasMore && (
                            <div className={styles.loadMoreContainer}>
                                <button className={styles.loadMoreBtn} onClick={loadMore}>
                                    Load older messages
                                </button>
                            </div>
                        )}

                        {groupedMessages.map((item, index) => (
                            item.type === 'date' ? (
                                <div key={`date-${index}`} className={styles.dateSeparator}>
                                    <span>{item.label}</span>
                                </div>
                            ) : (
                                <EnhancedMessageBubble
                                    key={item.data.id}
                                    message={item.data}
                                    currentUserId={currentUserId}
                                    onReply={handleReply}
                                    onDelete={handleDelete}
                                    onForward={handleForward}
                                    showAvatar={true}
                                />
                            )
                        ))}

                        <div ref={messagesEndRef} />
                    </>
                )}
            </div>

            {/* Scroll to Bottom Button */}
            {showScrollButton && (
                <button
                    className={styles.scrollToBottomBtn}
                    onClick={() => scrollToBottom()}
                >
                    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                        <path d="M12 5v14M19 12l-7 7-7-7" />
                    </svg>
                </button>
            )}

            {/* Message Input */}
            <EnhancedMessageInput
                conversationId={conversationId}
                currentUserId={currentUserId}
                replyTo={replyTo}
                onClearReply={() => setReplyTo(null)}
                onSendMessage={sendMessage}
                typingUsers={typingUsers}
                onTypingChange={handleTypingChange}
            />
        </div>
    );
};

export default CompleteChatWindow;

// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ
// ENHANCED MESSAGE BUBBLE - Reactions, Delete, Reply, Share, All Features
// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ

import React, { useState, useRef, useEffect } from 'react';
import { formatDistanceToNow } from 'date-fns';
import { useMessageReactions } from '../../hooks/useMessageReactions';
import styles from './MessageBubble.module.css';

const EnhancedMessageBubble = ({
    message,
    currentUserId,
    onReply,
    onDelete,
    onForward,
    showAvatar = true
}) => {
    const [showActions, setShowActions] = useState(false);
    const [showReactionPicker, setShowReactionPicker] = useState(false);
    const [showDeleteModal, setShowDeleteModal] = useState(false);
    const actionsRef = useRef(null);

    const {
        groupedReactions,
        userReaction,
        addReaction,
        availableEmojis
    } = useMessageReactions(message.id, currentUserId);

    const isOwn = message.sender_id === currentUserId;
    const isDeleted = message.deleted_for_everyone;

    // Close actions menu when clicking outside
    useEffect(() => {
        const handleClickOutside = (event) => {
            if (actionsRef.current && !actionsRef.current.contains(event.target)) {
                setShowActions(false);
                setShowReactionPicker(false);
            }
        };

        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    // Handle long press for mobile
    const longPressTimer = useRef(null);
    const handleTouchStart = () => {
        longPressTimer.current = setTimeout(() => {
            setShowReactionPicker(true);
        }, 500);
    };

    const handleTouchEnd = () => {
        if (longPressTimer.current) {
            clearTimeout(longPressTimer.current);
        }
    };

    // Render message content based on type
    const renderContent = () => {
        if (isDeleted) {
            return (
                <div className={styles.deletedMessage}>
                    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                        <polyline points="3 6 5 6 21 6" />
                        <path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2" />
                    </svg>
                    <span>Message was deleted</span>
                </div>
            );
        }

        switch (message.type) {
            case 'text':
                return <div className={styles.messageText}>{message.content}</div>;

            case 'image':
                const imageAttachment = message.attachments?.[0];
                return (
                    <div className={styles.imageMessage}>
                        <img
                            src={imageAttachment?.url}
                            alt="Shared image"
                            className={styles.messageImage}
                            loading="lazy"
                        />
                        {message.content && (
                            <div className={styles.imageCaption}>{message.content}</div>
                        )}
                    </div>
                );

            case 'video':
                const videoAttachment = message.attachments?.[0];
                return (
                    <div className={styles.videoMessage}>
                        <video
                            src={videoAttachment?.url}
                            poster={videoAttachment?.thumbnail_url}
                            controls
                            className={styles.messageVideo}
                        />
                        {message.content && (
                            <div className={styles.videoCaption}>{message.content}</div>
                        )}
                    </div>
                );

            case 'gif':
                return (
                    <div className={styles.gifMessage}>
                        <img
                            src={message.metadata?.url}
                            alt={message.content || 'GIF'}
                            className={styles.messageGif}
                            loading="lazy"
                        />
                    </div>
                );

            case 'sticker':
                return (
                    <div className={styles.stickerMessage}>
                        <img
                            src={message.metadata?.url}
                            alt={message.content || 'Sticker'}
                            className={styles.messageSticker}
                        />
                    </div>
                );

            case 'voice':
                const voiceAttachment = message.attachments?.[0];
                return (
                    <div className={styles.voiceMessage}>
                        <audio src={voiceAttachment?.url} controls className={styles.messageAudio} />
                        <span className={styles.voiceDuration}>
                            {formatDuration(voiceAttachment?.duration)}
                        </span>
                    </div>
                );

            case 'shared_post':
            case 'shared_flash':
            case 'shared_boltz':
                return (
                    <div className={styles.sharedContent}>
                        <div className={styles.sharedHeader}>
                            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                                <circle cx="18" cy="5" r="3" />
                                <circle cx="6" cy="12" r="3" />
                                <circle cx="18" cy="19" r="3" />
                                <line x1="8.59" y1="13.51" x2="15.42" y2="17.49" />
                                <line x1="15.41" y1="6.51" x2="8.59" y2="10.49" />
                            </svg>
                            <span>Shared {message.type.replace('shared_', '')}</span>
                        </div>
                        <div className={styles.sharedPreview}>
                            {message.metadata?.thumbnail && (
                                <img src={message.metadata.thumbnail} alt="Preview" />
                            )}
                            <div className={styles.sharedInfo}>
                                <div className={styles.sharedTitle}>{message.metadata?.title}</div>
                                <div className={styles.sharedAuthor}>@{message.metadata?.author}</div>
                            </div>
                        </div>
                    </div>
                );

            default:
                return <div className={styles.messageText}>{message.content || '[Unsupported message type]'}</div>;
        }
    };

    // Format duration (seconds to mm:ss)
    const formatDuration = (seconds) => {
        if (!seconds) return '0:00';
        const mins = Math.floor(seconds / 60);
        const secs = seconds % 60;
        return `${mins}:${secs.toString().padStart(2, '0')}`;
    };

    // Handle delete with modal
    const handleDeleteClick = () => {
        setShowDeleteModal(true);
        setShowActions(false);
    };

    const handleDeleteConfirm = (deleteForEveryone) => {
        onDelete(message.id, deleteForEveryone);
        setShowDeleteModal(false);
    };

    // Check if can delete for everyone (within 5 minutes)
    const canDeleteForEveryone = () => {
        const messageTime = new Date(message.created_at);
        const now = new Date();
        const diffMinutes = (now - messageTime) / 1000 / 60;
        return diffMinutes <= 5;
    };

    return (
        <div
            className={`${styles.messageBubble} ${isOwn ? styles.own : styles.other}`}
            onTouchStart={handleTouchStart}
            onTouchEnd={handleTouchEnd}
        >
            {/* Avatar (for other user's messages) */}
            {!isOwn && showAvatar && (
                <div className={styles.avatar}>
                    <img
                        src={message.sender?.avatar_url || '/default-avatar.png'}
                        alt={message.sender?.username}
                    />
                </div>
            )}

            <div className={styles.bubbleContent}>
                {/* Reply Preview */}
                {message.reply_to && (
                    <div className={styles.replyPreview}>
                        <div className={styles.replyBar}></div>
                        <div className={styles.replyContent}>
                            <div className={styles.replyAuthor}>
                                {message.reply_to.sender?.username}
                            </div>
                            <div className={styles.replyText}>
                                {message.reply_to.content || `[${message.reply_to.type}]`}
                            </div>
                        </div>
                    </div>
                )}

                {/* Message Content */}
                <div className={styles.messageContent}>
                    {renderContent()}

                    {/* Message Status (for own messages) */}
                    {isOwn && !isDeleted && (
                        <div className={styles.messageStatus}>
                            {message.status === 'sent' && (
                                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                                    <polyline points="20 6 9 17 4 12" />
                                </svg>
                            )}
                            {message.status === 'delivered' && (
                                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                                    <polyline points="20 6 9 17 4 12" />
                                    <polyline points="20 6 9 17 4 12" transform="translate(3, 0)" />
                                </svg>
                            )}
                            {message.status === 'seen' && (
                                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#8B5CF6" strokeWidth="2">
                                    <polyline points="20 6 9 17 4 12" />
                                    <polyline points="20 6 9 17 4 12" transform="translate(3, 0)" />
                                </svg>
                            )}
                        </div>
                    )}

                    {/* Timestamp */}
                    <div className={styles.timestamp}>
                        {formatDistanceToNow(new Date(message.created_at), { addSuffix: true })}
                    </div>
                </div>

                {/* Reactions */}
                {groupedReactions.length > 0 && (
                    <div className={styles.reactions}>
                        {groupedReactions.map(reaction => (
                            <div
                                key={reaction.emoji}
                                className={`${styles.reactionBadge} ${userReaction === reaction.emoji ? styles.userReacted : ''
                                    }`}
                                onClick={() => addReaction(reaction.emoji)}
                            >
                                <span className={styles.reactionEmoji}>{reaction.emoji}</span>
                                <span className={styles.reactionCount}>{reaction.count}</span>
                            </div>
                        ))}
                    </div>
                )}

                {/* Actions Menu Button */}
                {!isDeleted && (
                    <button
                        className={styles.actionsButton}
                        onClick={() => setShowActions(!showActions)}
                    >
                        <svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor">
                            <circle cx="12" cy="5" r="2" />
                            <circle cx="12" cy="12" r="2" />
                            <circle cx="12" cy="19" r="2" />
                        </svg>
                    </button>
                )}

                {/* Actions Menu */}
                {showActions && (
                    <div ref={actionsRef} className={`${styles.actionsMenu} ${isOwn ? styles.ownActions : ''}`}>
                        <button onClick={() => {
                            setShowReactionPicker(true);
                            setShowActions(false);
                        }}>
                            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                                <circle cx="12" cy="12" r="10" />
                                <path d="M8 14s1.5 2 4 2 4-2 4-2" />
                                <line x1="9" y1="9" x2="9.01" y2="9" />
                                <line x1="15" y1="9" x2="15.01" y2="9" />
                            </svg>
                            React
                        </button>
                        <button onClick={() => {
                            onReply(message);
                            setShowActions(false);
                        }}>
                            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                                <polyline points="9 14 4 9 9 4" />
                                <path d="M20 20v-7a4 4 0 0 0-4-4H4" />
                            </svg>
                            Reply
                        </button>
                        <button onClick={() => {
                            onForward(message);
                            setShowActions(false);
                        }}>
                            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                                <polyline points="15 10 20 15 15 20" />
                                <path d="M4 4v7a4 4 0 0 0 4 4h12" />
                            </svg>
                            Forward
                        </button>
                        {isOwn && (
                            <button onClick={handleDeleteClick} className={styles.deleteAction}>
                                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                                    <polyline points="3 6 5 6 21 6" />
                                    <path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2" />
                                </svg>
                                Delete
                            </button>
                        )}
                    </div>
                )}

                {/* Reaction Picker */}
                {showReactionPicker && (
                    <div className={styles.reactionPicker}>
                        {availableEmojis.map(emoji => (
                            <button
                                key={emoji}
                                className={`${styles.reactionOption} ${userReaction === emoji ? styles.selected : ''}`}
                                onClick={() => {
                                    addReaction(emoji);
                                    setShowReactionPicker(false);
                                }}
                            >
                                {emoji}
                            </button>
                        ))}
                    </div>
                )}

                {/* Delete Modal */}
                {showDeleteModal && (
                    <div className={styles.deleteModal}>
                        <div className={styles.deleteModalContent}>
                            <h3>Delete Message?</h3>
                            <div className={styles.deleteOptions}>
                                <button
                                    className={styles.deleteOption}
                                    onClick={() => handleDeleteConfirm(false)}
                                >
                                    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                                        <path d="M3 3h18v18H3zM15 9l-6 6m0-6l6 6" />
                                    </svg>
                                    <div>
                                        <div className={styles.optionTitle}>Delete for me</div>
                                        <div className={styles.optionDesc}>Message removed from your view only</div>
                                    </div>
                                </button>
                                {canDeleteForEveryone() && (
                                    <button
                                        className={styles.deleteOption}
                                        onClick={() => handleDeleteConfirm(true)}
                                    >
                                        <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                                            <polyline points="3 6 5 6 21 6" />
                                            <path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2" />
                                        </svg>
                                        <div>
                                            <div className={styles.optionTitle}>Delete for everyone</div>
                                            <div className={styles.optionDesc}>Message removed for both users</div>
                                        </div>
                                    </button>
                                )}
                            </div>
                            <button
                                className={styles.cancelDelete}
                                onClick={() => setShowDeleteModal(false)}
                            >
                                Cancel
                            </button>
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

