// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ
// MESSAGE BUBBLE COMPONENT - All message types with delivery states
// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ

import React, { useState } from 'react';
import { formatDistanceToNow } from 'date-fns';
import styles from './MessageBubble.module.css';

const MessageBubble = ({
    message,
    isSent,
    currentUserId,
    onReply,
    onDelete,
    onUnsend,
    onJumpToMessage,
    showAvatar = true
}) => {
    const [showMenu, setShowMenu] = useState(false);
    const [isPlaying, setIsPlaying] = useState(false);

    // Check if message can be unsent (within 15 minutes)
    const canUnsend = () => {
        if (!isSent) return false;
        const messageTime = new Date(message.created_at);
        const now = new Date();
        const diffMinutes = (now - messageTime) / 1000 / 60;
        return diffMinutes <= 15;
    };

    // Render delivery status icons
    const renderDeliveryStatus = () => {
        if (!isSent) return null;

        const { status } = message;

        if (status === 'seen') {
            return (
                <div className={`${styles.statusIcon} ${styles.seen}`}>
                    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                        <path d="M1 12l5 5L23 1M8 12l5 5L30 1" />
                    </svg>
                </div>
            );
        } else if (status === 'delivered') {
            return (
                <div className={`${styles.statusIcon} ${styles.delivered}`}>
                    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                        <path d="M1 12l5 5L23 1M8 12l5 5L30 1" />
                    </svg>
                </div>
            );
        } else if (status === 'sent') {
            return (
                <div className={`${styles.statusIcon} ${styles.delivered}`}>
                    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                        <path d="M5 12l5 5L20 7" />
                    </svg>
                </div>
            );
        } else {
            return (
                <div className={`${styles.statusIcon} ${styles.pending}`}>
                    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                        <circle cx="12" cy="12" r="10" />
                    </svg>
                </div>
            );
        }
    };

    // Render message content based on type
    const renderContent = () => {
        if (message.deleted_for_everyone) {
            return (
                <div className={styles.deletedMessage}>
                    {isSent ? 'You unsent this message' : 'This message was unsent'}
                </div>
            );
        }

        switch (message.type) {
            case 'text':
                return <div className={styles.textContent}>{message.content}</div>;

            case 'image':
                return (
                    <div className={styles.mediaContent}>
                        {message.attachments?.[0] && (
                            <img
                                src={message.attachments[0].url}
                                alt="Shared image"
                                loading="lazy"
                            />
                        )}
                        {message.content && (
                            <div className={styles.textContent} style={{ marginTop: '8px' }}>
                                {message.content}
                            </div>
                        )}
                    </div>
                );

            case 'video':
                return (
                    <div className={styles.mediaContent}>
                        {message.attachments?.[0] && (
                            <video
                                src={message.attachments[0].url}
                                poster={message.attachments[0].thumbnail_url}
                                controls
                            />
                        )}
                        {message.content && (
                            <div className={styles.textContent} style={{ marginTop: '8px' }}>
                                {message.content}
                            </div>
                        )}
                    </div>
                );

            case 'voice':
                return (
                    <div className={styles.voiceMessage}>
                        <button
                            className={styles.playButton}
                            onClick={() => setIsPlaying(!isPlaying)}
                        >
                            {isPlaying ? (
                                <svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor">
                                    <rect x="6" y="4" width="4" height="16" />
                                    <rect x="14" y="4" width="4" height="16" />
                                </svg>
                            ) : (
                                <svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor">
                                    <path d="M8 5v14l11-7z" />
                                </svg>
                            )}
                        </button>
                        <div className={styles.waveform}>
                            {[...Array(20)].map((_, i) => (
                                <div
                                    key={i}
                                    className={`${styles.waveBar} ${isPlaying && i < 10 ? styles.active : ''}`}
                                    style={{ height: `${Math.random() * 100}%` }}
                                />
                            ))}
                        </div>
                        <div className={styles.duration}>
                            {message.attachments?.[0]?.duration || 0}s
                        </div>
                    </div>
                );

            case 'gif':
            case 'sticker':
                return (
                    <div className={message.type === 'gif' ? styles.gifContent : styles.stickerContent}>
                        {message.attachments?.[0] && (
                            <img src={message.attachments[0].url} alt={message.type} />
                        )}
                    </div>
                );

            case 'shared_post':
            case 'shared_flash':
            case 'shared_boltz':
                const contentType = message.type.replace('shared_', '');
                return (
                    <div className={styles.sharedContent}>
                        <div className={styles.sharedThumbnail}>
                            <img src="/placeholder-content.jpg" alt="Shared content" />
                        </div>
                        <div className={styles.sharedInfo}>
                            <div className={styles.sharedType}>{contentType}</div>
                            <div className={styles.sharedTitle}>Shared Content</div>
                            <div className={styles.sharedAuthor}>@username</div>
                        </div>
                        {message.content && (
                            <div className={styles.textContent} style={{ marginTop: '8px' }}>
                                {message.content}
                            </div>
                        )}
                    </div>
                );

            default:
                return <div className={styles.textContent}>{message.content}</div>;
        }
    };

    return (
        <div className={`${styles.messageBubble} ${isSent ? styles.sent : styles.received}`}>
            {showAvatar && !isSent && (
                <div className={styles.avatar}>
                    {message.sender?.avatar_url ? (
                        <img src={message.sender.avatar_url} alt={message.sender.username} />
                    ) : (
                        message.sender?.username?.[0]?.toUpperCase() || '?'
                    )}
                </div>
            )}

            <div className={styles.bubbleContainer}>
                {message.reply_to && (
                    <div
                        className={styles.replyPreview}
                        onClick={() => onJumpToMessage?.(message.reply_to_message_id)}
                    >
                        <div className={styles.replyAuthor}>
                            {message.reply_to.sender_id === currentUserId ? 'You' : 'Them'}
                        </div>
                        <div className={styles.replyContent}>
                            {message.reply_to.content || `[${message.reply_to.type}]`}
                        </div>
                    </div>
                )}

                <div
                    className={styles.bubble}
                    onContextMenu={(e) => {
                        e.preventDefault();
                        setShowMenu(true);
                    }}
                    onClick={() => setShowMenu(false)}
                >
                    {renderContent()}

                    {showMenu && (
                        <div className={styles.contextMenu}>
                            <div className={styles.menuItem} onClick={() => onReply?.(message)}>
                                <svg className={styles.menuIcon} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                                    <path d="M9 14L4 9l5-5M4 9h10.5a5.5 5.5 0 0 1 5.5 5.5v0a5.5 5.5 0 0 1-5.5 5.5H11" />
                                </svg>
                                Reply
                            </div>
                            {isSent && canUnsend() && (
                                <div className={`${styles.menuItem} ${styles.danger}`} onClick={() => onUnsend?.(message.id)}>
                                    <svg className={styles.menuIcon} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                                        <path d="M3 6h18M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2" />
                                    </svg>
                                    Unsend
                                </div>
                            )}
                            <div className={`${styles.menuItem} ${styles.danger}`} onClick={() => onDelete?.(message.id)}>
                                <svg className={styles.menuIcon} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                                    <path d="M3 6h18M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2" />
                                </svg>
                                Delete for me
                            </div>
                        </div>
                    )}
                </div>

                <div className={styles.metadata}>
                    <span className={styles.timestamp}>
                        {formatDistanceToNow(new Date(message.created_at), { addSuffix: true })}
                    </span>
                    {renderDeliveryStatus()}
                </div>
            </div>
        </div>
    );
};

export default MessageBubble;

/* ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ
   SHARED CONTENT PREVIEW - Rich preview for shared posts/boltz/flash
   Phase 3: Social Integration
   ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ */

import React, { useState, useEffect } from 'react';
import { supabase } from '../../../../lib/supabase';
import styles from './SharedContentPreview.module.css';

const SharedContentPreview = ({ contentContext, onTap }) => {
    const [content, setContent] = useState(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        if (contentContext) {
            fetchContent();
        }
    }, [contentContext]);

    const fetchContent = async () => {
        try {
            const { type, id } = contentContext;
            let tableName = type === 'post' ? 'posts' : type === 'boltz' ? 'boltz' : 'stories';

            const { data } = await supabase
                .from(tableName)
                .select('*, profiles(*)')
                .eq('id', id)
                .single();

            setContent(data);
        } catch (error) {
            console.error('Error fetching shared content:', error);
        } finally {
            setLoading(false);
        }
    };

    if (loading) {
        return <div className={styles.loading}>Loading...</div>;
    }

    if (!content) {
        return <div className={styles.error}>Content unavailable</div>;
    }

    const { type } = contentContext;

    return (
        <div className={styles.preview} onClick={onTap}>
            <div className={styles.previewHeader}>
                <div className={styles.typeIcon}>
                    {type === 'post' ? '≡ƒô¥' : type === 'boltz' ? 'ΓÜí' : 'Γ£¿'}
                </div>
                <div className={styles.typeLabel}>
                    {type === 'post' ? 'Post' : type === 'boltz' ? 'Boltz' : 'Flash'}
                </div>
            </div>

            <div className={styles.previewContent}>
                {/* Author */}
                <div className={styles.author}>
                    <img
                        src={content.profiles?.avatar_url || '/default-avatar.png'}
                        alt={content.profiles?.username}
                        className={styles.authorAvatar}
                    />
                    <span className={styles.authorName}>
                        {content.profiles?.username || 'Unknown'}
                    </span>
                </div>

                {/* Content */}
                <div className={styles.contentText}>
                    {content.content || content.caption || 'No caption'}
                </div>

                {/* Media Preview */}
                {content.media_url && (
                    <div className={styles.mediaPreview}>
                        <img src={content.media_url} alt="Preview" className={styles.previewImage} />
                    </div>
                )}

                {/* Stats */}
                <div className={styles.stats}>
                    <span>Γ¥ñ∩╕Å {content.likes_count || 0}</span>
                    {type === 'post' && <span>≡ƒÆ¼ {content.comments_count || 0}</span>}
                    {type === 'boltz' && <span>ΓÜí {content.reactions_count || 0}</span>}
                </div>
            </div>

            <div className={styles.tapHint}>Tap to view</div>
        </div>
    );
};

export default SharedContentPreview;

/* ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ
   CONVERSATION CARD - Individual conversation in the list
   Visual-first design with rich previews
   ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ */

import React, { useState, useEffect } from 'react';
import { supabase } from '../../../../lib/supabase';
import { formatMessageTime, getMessagePreview, getUnreadCount } from '../../utils/messageHelpers';
import styles from './ConversationCard.module.css';

const ConversationCard = ({ conversation, isSelected, onClick, currentUserId }) => {
    const [otherUser, setOtherUser] = useState(null);
    const [lastMessage, setLastMessage] = useState(null);
    const [unreadCount, setUnreadCount] = useState(0);
    const [isOnline, setIsOnline] = useState(false);

    // Fetch other user data for direct chats
    useEffect(() => {
        const fetchUserData = async () => {
            if (conversation.type === 'direct') {
                const otherUserId = conversation.participants.find(id => id !== currentUserId);

                if (otherUserId) {
                    const { data } = await supabase
                        .from('profiles')
                        .select('*')
                        .eq('id', otherUserId)
                        .single();

                    setOtherUser(data);
                }
            }
        };

        fetchUserData();
    }, [conversation, currentUserId]);

    // Fetch last message
    useEffect(() => {
        const fetchLastMessage = async () => {
            if (conversation.last_message_id) {
                const { data } = await supabase
                    .from('messages')
                    .select('*')
                    .eq('id', conversation.last_message_id)
                    .single();

                setLastMessage(data);
            }
        };

        fetchLastMessage();
    }, [conversation.last_message_id]);

    // Calculate unread count
    useEffect(() => {
        const fetchUnreadCount = async () => {
            const { data } = await supabase
                .from('messages')
                .select('id')
                .eq('conversation_id', conversation.id)
                .neq('sender_id', currentUserId)
                .not('read_by', 'cs', `{${currentUserId}}`);

            setUnreadCount(data?.length || 0);
        };

        fetchUnreadCount();
    }, [conversation.id, currentUserId]);

    const displayName = conversation.type === 'group'
        ? conversation.group_name
        : otherUser?.full_name || otherUser?.username || 'Unknown User';

    const avatarUrl = conversation.type === 'group'
        ? conversation.group_avatar
        : otherUser?.avatar_url;

    return (
        <div
            className={`${styles.card} ${isSelected ? styles.selected : ''}`}
            onClick={onClick}
        >
            {/* Avatar with online indicator */}
            <div className={styles.avatarContainer}>
                <img
                    src={avatarUrl || '/default-avatar.png'}
                    alt={displayName}
                    className={styles.avatar}
                />
                {conversation.type === 'direct' && isOnline && (
                    <div className={styles.onlineIndicator}></div>
                )}
            </div>

            {/* Content */}
            <div className={styles.content}>
                <div className={styles.header}>
                    <div className={styles.nameContainer}>
                        <span className={styles.name}>{displayName}</span>
                        {otherUser?.verified && (
                            <svg className={styles.verifiedBadge} width="16" height="16" viewBox="0 0 24 24" fill="none">
                                <path d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" stroke="#8b5cf6" strokeWidth="2" fill="#8b5cf6" />
                            </svg>
                        )}
                    </div>
                    {lastMessage && (
                        <span className={styles.time}>
                            {formatMessageTime(lastMessage.created_at)}
                        </span>
                    )}
                </div>

                <div className={styles.preview}>
                    <span className={styles.previewText}>
                        {lastMessage ? getMessagePreview(lastMessage) : 'No messages yet'}
                    </span>
                    {unreadCount > 0 && (
                        <div className={styles.unreadBadge}>{unreadCount}</div>
                    )}
                </div>
            </div>

            {/* Pin indicator */}
            {conversation.pinned && (
                <div className={styles.pinIndicator}>
                    <svg width="16" height="16" viewBox="0 0 24 24" fill="none">
                        <path d="M16 4v6l3 3v2h-6v5l-1 1-1-1v-5H5v-2l3-3V4h8z" fill="currentColor" />
                    </svg>
                </div>
            )}
        </div>
    );
};

export default ConversationCard;

/* ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ
   CONVERSATION SETTINGS MODAL - Pin, mute, archive, disappearing messages
   Phase 4: Advanced Features
