import React, { useState, useEffect } from 'react';
import { supabase } from '../../../../lib/supabase';
import styles from './ConversationSettingsModal.module.css';

const ConversationSettingsModal = ({ onClose, conversationId, currentUserId }) => {
    const [settings, setSettings] = useState({
        pinned: false,
        muted: false,
        disappearing_messages: false,
        read_receipts_enabled: false
    });
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);

    useEffect(() => {
        fetchSettings();
    }, [conversationId, currentUserId]);

    const fetchSettings = async () => {
        try {
            const { data } = await supabase
                .from('conversation_settings')
                .select('*')
                .eq('conversation_id', conversationId)
                .eq('user_id', currentUserId)
                .single();

            if (data) {
                setSettings(data);
            }
        } catch (error) {
            console.error('Error fetching settings:', error);
        } finally {
            setLoading(false);
        }
    };

    const updateSetting = async (key, value) => {
        try {
            setSaving(true);

            const { error } = await supabase
                .from('conversation_settings')
                .upsert({
                    conversation_id: conversationId,
                    user_id: currentUserId,
                    [key]: value,
                    [`${key}_at`]: key === 'pinned' && value ? new Date().toISOString() : null
                }, {
                    onConflict: 'conversation_id,user_id'
                });

            if (error) throw error;

            setSettings(prev => ({ ...prev, [key]: value }));
        } catch (error) {
            console.error('Error updating setting:', error);
            alert('Failed to update setting');
        } finally {
            setSaving(false);
        }
    };

    const handleArchive = async () => {
        // Archive conversation (hide from list)
        if (window.confirm('Archive this conversation?')) {
            await updateSetting('archived', true);
            onClose();
        }
    };

    const handleBlock = async () => {
        if (window.confirm('Block this user? You won\'t receive messages from them.')) {
            // Implement block functionality
            alert('Block feature coming soon!');
        }
    };

    const handleReport = async () => {
        if (window.confirm('Report this conversation?')) {
            // Implement report functionality
            alert('Report feature coming soon!');
        }
    };

    if (loading) {
        return (
            <div className={styles.overlay} onClick={onClose}>
                <div className={styles.modal} onClick={(e) => e.stopPropagation()}>
                    <div className={styles.loading}>Loading settings...</div>
                </div>
            </div>
        );
    }

    return (
        <div className={styles.overlay} onClick={onClose}>
            <div className={styles.modal} onClick={(e) => e.stopPropagation()}>
                <div className={styles.header}>
                    <h2>Conversation Settings</h2>
                    <button onClick={onClose} className={styles.closeButton}>
                        <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
                            <path d="M18 6L6 18M6 6l12 12" stroke="currentColor" strokeWidth="2" />
                        </svg>
                    </button>
                </div>

                <div className={styles.settingsList}>
                    {/* Pin Conversation */}
                    <div className={styles.settingItem}>
                        <div className={styles.settingInfo}>
                            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" className={styles.settingIcon}>
                                <path d="M16 4v6l3 3v2h-6v5l-1 1-1-1v-5H5v-2l3-3V4h8z" fill="currentColor" />
                            </svg>
                            <div>
                                <h3>Pin Conversation</h3>
                                <p>Keep this chat at the top</p>
                            </div>
                        </div>
                        <label className={styles.toggle}>
                            <input
                                type="checkbox"
                                checked={settings.pinned}
                                onChange={(e) => updateSetting('pinned', e.target.checked)}
                                disabled={saving}
                            />
                            <span className={styles.slider}></span>
                        </label>
                    </div>

                    {/* Mute Notifications */}
                    <div className={styles.settingItem}>
                        <div className={styles.settingInfo}>
                            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" className={styles.settingIcon}>
                                <path d="M17.5 12c0 1.77-1.02 3.29-2.5 4.03v2.21c2.89-.86 5-3.54 5-6.74s-2.11-5.88-5-6.74v2.21c1.48.74 2.5 2.26 2.5 4.03zM11 4.07V3c0-.55-.45-1-1-1s-1 .45-1 1v1.07c-2.39.49-4.16 2.58-4.16 5.1 0 2.52 1.77 4.61 4.16 5.1v6.17c0 .55.45 1 1 1s1-.45 1-1v-6.17c2.39-.49 4.16-2.58 4.16-5.1 0-2.52-1.77-4.61-4.16-5.1z" fill="currentColor" />
                            </svg>
                            <div>
                                <h3>Mute Notifications</h3>
                                <p>Stop receiving notifications</p>
                            </div>
                        </div>
                        <label className={styles.toggle}>
                            <input
                                type="checkbox"
                                checked={settings.muted}
                                onChange={(e) => updateSetting('muted', e.target.checked)}
                                disabled={saving}
                            />
                            <span className={styles.slider}></span>
                        </label>
                    </div>

                    {/* Disappearing Messages */}
                    <div className={styles.settingItem}>
                        <div className={styles.settingInfo}>
                            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" className={styles.settingIcon}>
                                <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 18c-4.41 0-8-3.59-8-8s3.59-8 8-8 8 3.59 8 8-3.59 8-8 8zm.5-13H11v6l5.25 3.15.75-1.23-4.5-2.67z" fill="currentColor" />
                            </svg>
                            <div>
                                <h3>Disappearing Messages</h3>
                                <p>Messages auto-delete after 24h</p>
                            </div>
                        </div>
                        <label className={styles.toggle}>
                            <input
                                type="checkbox"
                                checked={settings.disappearing_messages}
                                onChange={(e) => updateSetting('disappearing_messages', e.target.checked)}
                                disabled={saving}
                            />
                            <span className={styles.slider}></span>
                        </label>
                    </div>

                    {/* Read Receipts */}
                    <div className={styles.settingItem}>
                        <div className={styles.settingInfo}>
                            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" className={styles.settingIcon}>
                                <path d="M9 16.17L4.83 12l-1.42 1.41L9 19 21 7l-1.41-1.41z" fill="currentColor" />
                            </svg>
                            <div>
                                <h3>Read Receipts</h3>
                                <p>Show when you've read messages</p>
                            </div>
                        </div>
                        <label className={styles.toggle}>
                            <input
                                type="checkbox"
                                checked={settings.read_receipts_enabled}
                                onChange={(e) => updateSetting('read_receipts_enabled', e.target.checked)}
                                disabled={saving}
                            />
                            <span className={styles.slider}></span>
                        </label>
                    </div>

                    {/* Divider */}
                    <div className={styles.divider}></div>

                    {/* Archive */}
                    <button onClick={handleArchive} className={styles.actionButton}>
                        <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
                            <path d="M20.54 5.23l-1.39-1.68C18.88 3.21 18.47 3 18 3H6c-.47 0-.88.21-1.16.55L3.46 5.23C3.17 5.57 3 6.02 3 6.5V19c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2V6.5c0-.48-.17-.93-.46-1.27zM12 17.5L6.5 12H10v-2h4v2h3.5L12 17.5zM5.12 5l.81-1h12l.94 1H5.12z" fill="currentColor" />
                        </svg>
                        <span>Archive Conversation</span>
                    </button>

                    {/* Block */}
                    <button onClick={handleBlock} className={`${styles.actionButton} ${styles.danger}`}>
                        <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
                            <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zM4 12c0-4.42 3.58-8 8-8 1.85 0 3.55.63 4.9 1.69L5.69 16.9C4.63 15.55 4 13.85 4 12zm8 8c-1.85 0-3.55-.63-4.9-1.69L18.31 7.1C19.37 8.45 20 10.15 20 12c0 4.42-3.58 8-8 8z" fill="currentColor" />
                        </svg>
                        <span>Block User</span>
                    </button>

                    {/* Report */}
                    <button onClick={handleReport} className={`${styles.actionButton} ${styles.danger}`}>
                        <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
                            <path d="M15.73 3H8.27L3 8.27v7.46L8.27 21h7.46L21 15.73V8.27L15.73 3zM12 17.3c-.72 0-1.3-.58-1.3-1.3 0-.72.58-1.3 1.3-1.3.72 0 1.3.58 1.3 1.3 0 .72-.58 1.3-1.3 1.3zm1-4.3h-2V7h2v6z" fill="currentColor" />
                        </svg>
                        <span>Report Conversation</span>
                    </button>
                </div>
            </div>
        </div>
    );
};

export default ConversationSettingsModal;

/* ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ
   FORWARD MESSAGE MODAL - Forward messages to other conversations
   Phase 4: Advanced Features
   ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ */

import React, { useState, useEffect } from 'react';
import { supabase } from '../../../../lib/supabase';
import styles from './ForwardMessageModal.module.css';

const ForwardMessageModal = ({ onClose, message, currentUserId, onForward }) => {
    const [conversations, setConversations] = useState([]);
    const [selectedConversations, setSelectedConversations] = useState([]);
    const [loading, setLoading] = useState(true);
    const [forwarding, setForwarding] = useState(false);

    useEffect(() => {
        fetchConversations();
    }, [currentUserId]);

    const fetchConversations = async () => {
        try {
            const { data } = await supabase
                .from('conversations')
                .select('*')
                .contains('participants', [currentUserId])
                .order('last_message_at', { ascending: false });

            setConversations(data || []);
        } catch (error) {
            console.error('Error fetching conversations:', error);
        } finally {
            setLoading(false);
        }
    };

    const toggleConversation = (convId) => {
        setSelectedConversations(prev =>
            prev.includes(convId)
                ? prev.filter(id => id !== convId)
                : [...prev, convId]
        );
    };

    const handleForward = async () => {
        if (selectedConversations.length === 0) return;

        try {
            setForwarding(true);

            for (const convId of selectedConversations) {
                await onForward(message, convId);
            }

            onClose();
        } catch (error) {
            console.error('Error forwarding message:', error);
            alert('Failed to forward message');
        } finally {
            setForwarding(false);
        }
    };

    return (
        <div className={styles.overlay} onClick={onClose}>
            <div className={styles.modal} onClick={(e) => e.stopPropagation()}>
                <div className={styles.header}>
                    <h2>Forward Message</h2>
                    <button onClick={onClose} className={styles.closeButton}>
                        <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
                            <path d="M18 6L6 18M6 6l12 12" stroke="currentColor" strokeWidth="2" />
                        </svg>
                    </button>
                </div>

                <div className={styles.messagePreview}>
                    <div className={styles.previewLabel}>Forwarding:</div>
                    <div className={styles.previewContent}>
                        {message.content || '≡ƒô╖ Media'}
                    </div>
                </div>

                <div className={styles.conversationsList}>
                    {loading ? (
                        <div className={styles.loading}>Loading conversations...</div>
                    ) : conversations.length === 0 ? (
                        <div className={styles.empty}>No conversations available</div>
                    ) : (
                        conversations.map(conv => (
                            <div
                                key={conv.id}
                                className={`${styles.conversationCard} ${selectedConversations.includes(conv.id) ? styles.selected : ''}`}
                                onClick={() => toggleConversation(conv.id)}
                            >
                                <div className={styles.checkbox}>
                                    {selectedConversations.includes(conv.id) && (
                                        <svg width="16" height="16" viewBox="0 0 24 24" fill="none">
                                            <path d="M20 6L9 17l-5-5" stroke="currentColor" strokeWidth="3" />
                                        </svg>
                                    )}
                                </div>
                                <div className={styles.conversationInfo}>
                                    <span className={styles.name}>
                                        {conv.type === 'group' ? conv.group_name : 'Direct Chat'}
                                    </span>
                                </div>
                            </div>
                        ))
                    )}
                </div>

                <div className={styles.actions}>
                    <button onClick={onClose} className={styles.cancelButton} disabled={forwarding}>
                        Cancel
                    </button>
                    <button
                        onClick={handleForward}
                        className={styles.forwardButton}
                        disabled={forwarding || selectedConversations.length === 0}
                    >
                        {forwarding ? 'Forwarding...' : `Forward to ${selectedConversations.length} chat${selectedConversations.length !== 1 ? 's' : ''}`}
                    </button>
                </div>
            </div>
        </div>
    );
};

export default ForwardMessageModal;

// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ
// NEW MESSAGE MODAL - Instagram-inspired (Focus Lavender Theme)
// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { supabase } from '../../../../lib/supabase';
import styles from './NewMessageModal.module.css';

const NewMessageModal = ({ onClose, currentUserId }) => {
    const navigate = useNavigate();
    const [searchQuery, setSearchQuery] = useState('');
    const [users, setUsers] = useState([]);
    const [suggestedUsers, setSuggestedUsers] = useState([]);
    const [selectedUsers, setSelectedUsers] = useState([]);
    const [loading, setLoading] = useState(true);

    // Fetch suggested users on mount
    useEffect(() => {
        fetchSuggestedUsers();
    }, []);

    // Search users when query changes
    useEffect(() => {
        if (searchQuery.trim()) {
            searchUsers(searchQuery);
        } else {
            setUsers([]);
        }
    }, [searchQuery]);

    const fetchSuggestedUsers = async () => {
        try {
            console.log('≡ƒæÑ Fetching suggested users...');
            console.log('≡ƒæÑ Current user ID:', currentUserId);

            // Set timeout to stop loading after 3 seconds
            const timeoutId = setTimeout(() => {
                console.log('ΓÅ▒∩╕Å Suggested users fetch timeout');
                setLoading(false);
            }, 3000);

            const { data, error } = await supabase
                .from('profiles')
                .select('id, username, full_name, avatar_url')
                .neq('id', currentUserId)
                .limit(20);

            clearTimeout(timeoutId);

            console.log('≡ƒæÑ Suggested users response:', { data, error, count: data?.length });

            if (error) {
                console.error('Γ¥î Error fetching suggested users:', error);
                setSuggestedUsers([]);
            } else {
                console.log(`Γ£à Loaded ${data?.length || 0} suggested users`);
                setSuggestedUsers(data || []);
            }
        } catch (err) {
            console.error('Γ¥î Error fetching suggested users:', err);
            setSuggestedUsers([]);
        } finally {
            setLoading(false);
        }
    };

    const searchUsers = async (query) => {
        try {
            console.log('≡ƒöì Searching for users with query:', query);
            console.log('≡ƒöì Current user ID:', currentUserId);

            const searchPattern = `%${query}%`;
            const { data, error } = await supabase
                .from('profiles')
                .select('id, username, full_name, avatar_url')
                .neq('id', currentUserId)
                .or(`username.ilike.${searchPattern},full_name.ilike.${searchPattern}`)
                .limit(20);

            console.log('≡ƒöì Search results:', { data, error });

            if (error) {
                console.error('Γ¥î Search error:', error);
                throw error;
            }

            console.log(`Γ£à Found ${data?.length || 0} users`);
            setUsers(data || []);
        } catch (err) {
            console.error('Γ¥î Error searching users:', err);
            setUsers([]); // Clear users on error
        }
    };

    const toggleUserSelection = (user) => {
        setSelectedUsers(prev => {
            const isSelected = prev.find(u => u.id === user.id);
            if (isSelected) {
                return prev.filter(u => u.id !== user.id);
            } else {
                return [...prev, user];
            }
        });
    };

    const handleChat = async () => {
        if (selectedUsers.length === 0) return;

        try {
            console.log('≡ƒÆ¼ Starting chat with users:', selectedUsers);

            // For single user, get or create conversation
            if (selectedUsers.length === 1) {
                const otherUserId = selectedUsers[0].id;
                const otherUsername = selectedUsers[0].username;

                console.log('≡ƒÆ¼ Creating/getting conversation with:', { otherUserId, otherUsername });
                console.log('≡ƒÆ¼ Current user ID:', currentUserId);

                // Call RPC function to get or create conversation
                const { data: conversationId, error: convError } = await supabase
                    .rpc('get_or_create_conversation', {
                        user1_id: currentUserId,
                        user2_id: otherUserId
                    });

                console.log('≡ƒÆ¼ RPC response:', { conversationId, convError });

                if (convError) {
                    console.error('Γ¥î Error from RPC:', convError);
                    throw convError;
                }

                if (!conversationId) {
                    throw new Error('No conversation ID returned from RPC');
                }

                console.log('Γ£à Got conversation ID:', conversationId);
                console.log('≡ƒöÇ Navigating to:', `/messages/${conversationId}`);

                // Close modal first
                onClose();

                // Navigate to conversation
                navigate(`/messages/${conversationId}`);

            } else {
                // For multiple users, create group chat (implement later)
                console.log('≡ƒæÑ Group chat requested with:', selectedUsers.length, 'users');
                alert('Group chats coming soon!');
            }
        } catch (err) {
            console.error('Γ¥î Error in handleChat:', err);
            console.error('Γ¥î Error details:', {
                message: err.message,
                code: err.code,
                details: err.details,
                hint: err.hint
            });
            alert(`Failed to start chat: ${err.message || 'Unknown error'}`);
        }
    };

    const displayUsers = searchQuery.trim() ? users : suggestedUsers;

    return (
        <div className={styles.modalOverlay} onClick={onClose}>
            <div className={styles.modal} onClick={(e) => e.stopPropagation()}>
                {/* Header */}
                <div className={styles.header}>
                    <h2 className={styles.title}>New message</h2>
                    <button className={styles.closeBtn} onClick={onClose}>
                        <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                            <line x1="18" y1="6" x2="6" y2="18" />
                            <line x1="6" y1="6" x2="18" y2="18" />
                        </svg>
                    </button>
                </div>

                {/* Search Input */}
                <div className={styles.searchContainer}>
                    <label className={styles.searchLabel}>To:</label>
                    <input
                        type="text"
                        placeholder="Search..."
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        className={styles.searchInput}
                        autoFocus
                    />
                </div>

                {/* Selected Users Pills */}
                {selectedUsers.length > 0 && (
                    <div className={styles.selectedUsers}>
                        {selectedUsers.map(user => (
                            <div key={user.id} className={styles.userPill}>
                                <span>{user.username}</span>
                                <button onClick={() => toggleUserSelection(user)}>
                                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                                        <line x1="18" y1="6" x2="6" y2="18" />
                                        <line x1="6" y1="6" x2="18" y2="18" />
                                    </svg>
                                </button>
                            </div>
                        ))}
                    </div>
                )}

                {/* Suggested Label */}
                {!searchQuery && (
                    <div className={styles.sectionLabel}>Suggested</div>
                )}

                {/* Users List */}
                <div className={styles.usersList}>
                    {loading ? (
                        <div className={styles.loading}>
