// USE PRESENCE HOOK - Real-time user presence tracking
// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ

import { useState, useEffect, useCallback, useRef } from 'react';
import { supabase } from '../../../lib/supabase';
import { updatePresence, fetchPresence } from '../../../utils/supabaseRest';

export const usePresence = (currentUserId) => {
    const [presenceMap, setPresenceMap] = useState(new Map());
    const heartbeatIntervalRef = useRef(null);
    const subscriptionRef = useRef(null);
    const realtimePresenceRef = useRef(null);

    // Update own presence
    const setOnline = useCallback(async (isOnline) => {
        if (!currentUserId) return;

        try {
            await updatePresence(currentUserId, isOnline);
        } catch (err) {
            console.error('Error updating presence:', err);
        }
    }, [currentUserId]);

    // Heartbeat to keep presence alive
    useEffect(() => {
        if (!currentUserId) return;

        // Set online on mount
        setOnline(true);

        // Heartbeat every 30 seconds
        heartbeatIntervalRef.current = setInterval(() => {
            setOnline(true);
        }, 30000);

        // Handle visibility change
        const handleVisibilityChange = () => {
            if (document.hidden) {
                setOnline(false);
            } else {
                setOnline(true);
            }
        };

        document.addEventListener('visibilitychange', handleVisibilityChange);

        // Set offline on unmount
        return () => {
            if (heartbeatIntervalRef.current) {
                clearInterval(heartbeatIntervalRef.current);
            }
            document.removeEventListener('visibilitychange', handleVisibilityChange);
            setOnline(false);
        };
    }, [currentUserId, setOnline]);

    // Subscribe to presence updates
    useEffect(() => {
        const realtimeChannel = supabase.channel('focus-messages-presence', {
            config: { presence: { key: currentUserId || 'anonymous' } }
        });
        realtimePresenceRef.current = realtimeChannel;
        realtimeChannel
            .on('presence', { event: 'sync' }, () => {
                const state = realtimeChannel.presenceState();
                setPresenceMap((prev) => {
                    const next = new Map(prev);
                    Object.keys(state).forEach((userId) => {
                        if (!userId) return;
                        const rows = state[userId];
                        const latest = rows?.[rows.length - 1];
                        next.set(userId, {
                            isOnline: true,
                            lastSeenAt: latest?.last_seen_at || new Date().toISOString(),
                        });
                    });
                    return next;
                });
            })
            .subscribe(async (status) => {
                if (status === 'SUBSCRIBED' && currentUserId) {
                    await realtimeChannel.track({
                        user_id: currentUserId,
                        last_seen_at: new Date().toISOString(),
                    });
                }
            });

        subscriptionRef.current = supabase
            .channel('user_presence')
            .on('postgres_changes', {
                event: '*',
                schema: 'public',
                table: 'user_presence'
            }, (payload) => {
                if (payload.new) {
                    setPresenceMap(prev => {
                        const newMap = new Map(prev);
                        newMap.set(payload.new.user_id, {
                            isOnline: payload.new.is_online,
                            lastSeenAt: payload.new.last_seen_at
                        });
                        return newMap;
                    });
                }
            })
            .subscribe();

        return () => {
            if (realtimePresenceRef.current) {
                realtimePresenceRef.current.untrack();
                supabase.removeChannel(realtimePresenceRef.current);
            }
            if (subscriptionRef.current) {
                subscriptionRef.current.unsubscribe();
            }
        };
    }, []);

    // Fetch presence for specific users
    const fetchUserPresence = useCallback(async (userIds) => {
        if (!userIds || userIds.length === 0) return;

        try {
            const data = await fetchPresence(userIds);
            setPresenceMap(prev => {
                const newMap = new Map(prev);
                data.forEach(p => {
                    newMap.set(p.user_id, {
                        isOnline: p.is_online,
                        lastSeenAt: p.last_seen_at
                    });
                });
                return newMap;
            });
        } catch (err) {
            console.error('Error fetching presence:', err);
        }
    }, []);

    // Get presence for a user
    const getUserPresence = useCallback((userId) => {
        return presenceMap.get(userId) || { isOnline: false, lastSeenAt: null };
    }, [presenceMap]);

    return {
        getUserPresence,
        fetchUserPresence,
        setOnline
    };
};

// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ
// REAL-TIME MESSAGES HOOK - Production-ready with all features
// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ

import { useState, useEffect, useCallback, useRef } from 'react';
import { supabase } from '../../../lib/supabase';

export const useRealtimeMessages = (conversationId, currentUserId) => {
    const [messages, setMessages] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [hasMore, setHasMore] = useState(true);
    const [sending, setSending] = useState(false);

    const subscriptionRef = useRef(null);
    const PAGE_SIZE = 50;

    // Fetch initial messages
    const fetchMessages = useCallback(async (offset = 0) => {
        if (!conversationId) return [];

        try {
            const { data, error: fetchError } = await supabase
                .from('messages')
                .select(`
                    *,
                    sender:profiles!sender_id(id, username, full_name, avatar_url),
                    reply_to:messages!reply_to_message_id(
                        id,
                        content,
                        type,
                        sender:profiles!sender_id(id, username)
                    ),
                    attachments:message_attachments(*)
                `)
                .eq('conversation_id', conversationId)
                .eq('deleted_for_everyone', false)
                .order('created_at', { ascending: false })
                .range(offset, offset + PAGE_SIZE - 1);

            if (fetchError) throw fetchError;

            // Filter out messages deleted for current user
            const visibleMessages = (data || []).filter(msg => {
                if (msg.sender_id === currentUserId) {
                    return !msg.deleted_for_sender;
                }
                return true;
            });

            return visibleMessages.reverse(); // Oldest first for display
        } catch (err) {
            console.error('Error fetching messages:', err);
            setError(err.message);
            return [];
        }
    }, [conversationId, currentUserId]);

    // Load initial messages
    useEffect(() => {
        if (!conversationId) {
            setMessages([]);
            setLoading(false);
            return;
        }

        const loadMessages = async () => {
            setLoading(true);
            const initialMessages = await fetchMessages(0);
            setMessages(initialMessages);
            setHasMore(initialMessages.length >= PAGE_SIZE);
            setLoading(false);
        };

        loadMessages();
    }, [conversationId, fetchMessages]);

    // Real-time subscription
    useEffect(() => {
        if (!conversationId) return;

        // Subscribe to new messages
        const channel = supabase
            .channel(`messages:${conversationId}`)
            .on(
                'postgres_changes',
                {
                    event: 'INSERT',
                    schema: 'public',
                    table: 'messages',
                    filter: `conversation_id=eq.${conversationId}`
                },
                async (payload) => {
                    console.log('≡ƒô¿ New message received:', payload.new);

                    // Fetch full message with relations
                    const { data } = await supabase
                        .from('messages')
                        .select(`
                            *,
                            sender:profiles!sender_id(id, username, full_name, avatar_url),
                            reply_to:messages!reply_to_message_id(
                                id,
                                content,
                                type,
                                sender:profiles!sender_id(id, username)
                            ),
                            attachments:message_attachments(*)
                        `)
                        .eq('id', payload.new.id)
                        .single();

                    if (data) {
                        setMessages(prev => {
                            // Prevent duplicates
                            if (prev.some(m => m.id === data.id)) return prev;
                            return [...prev, data];
                        });

                        // Auto-mark as delivered if not sender
                        if (data.sender_id !== currentUserId) {
                            await markAsDelivered(data.id);
                        }
                    }
                }
            )
            .on(
                'postgres_changes',
                {
                    event: 'UPDATE',
                    schema: 'public',
                    table: 'messages',
                    filter: `conversation_id=eq.${conversationId}`
                },
                (payload) => {
                    console.log('≡ƒô¥ Message updated:', payload.new);
                    setMessages(prev => prev.map(msg =>
                        msg.id === payload.new.id ? { ...msg, ...payload.new } : msg
                    ));
                }
            )
            .on(
                'postgres_changes',
                {
                    event: 'DELETE',
                    schema: 'public',
                    table: 'messages',
                    filter: `conversation_id=eq.${conversationId}`
                },
                (payload) => {
                    console.log('≡ƒùæ∩╕Å Message deleted:', payload.old);
                    setMessages(prev => prev.filter(msg => msg.id !== payload.old.id));
                }
            )
            .subscribe();

        subscriptionRef.current = channel;

        return () => {
            channel.unsubscribe();
        };
    }, [conversationId, currentUserId]);

    // Send message
    const sendMessage = useCallback(async (messageData) => {
        if (!conversationId || !currentUserId) {
            throw new Error('Missing conversation or user ID');
        }

        setSending(true);
        try {
            const messagePayload = {
                conversation_id: conversationId,
                sender_id: currentUserId,
                type: messageData.type || 'text',
                content: messageData.content || null,
                reply_to_message_id: messageData.replyToId || null,
                status: 'sent',
                metadata: messageData.metadata || {}
            };

            // Insert message
            const { data: newMessage, error: messageError } = await supabase
                .from('messages')
                .insert(messagePayload)
                .select(`
                    *,
                    sender:profiles!sender_id(id, username, full_name, avatar_url),
                    reply_to:messages!reply_to_message_id(
                        id,
                        content,
                        type,
                        sender:profiles!sender_id(id, username)
                    )
                `)
                .single();

            if (messageError) throw messageError;

            // Handle attachments if present
            if (messageData.attachmentData) {
                const attachmentPayload = {
                    message_id: newMessage.id,
                    type: messageData.type,
                    url: messageData.attachmentData.url,
                    thumbnail_url: messageData.attachmentData.thumbnailUrl,
                    width: messageData.attachmentData.width,
                    height: messageData.attachmentData.height,
                    size: messageData.attachmentData.size,
                    duration: messageData.attachmentData.duration,
                    mime_type: messageData.attachmentData.mimeType
                };

                const { data: attachment, error: attachmentError } = await supabase
                    .from('message_attachments')
                    .insert(attachmentPayload)
                    .select()
                    .single();

                if (attachmentError) {
                    console.error('Attachment error:', attachmentError);
                } else {
                    newMessage.attachments = [attachment];
                }
            }

            return newMessage;
        } catch (err) {
            console.error('Error sending message:', err);
            throw err;
        } finally {
            setSending(false);
        }
    }, [conversationId, currentUserId]);

    // Mark message as delivered
    const markAsDelivered = useCallback(async (messageId) => {
        try {
            await supabase
                .from('messages')
                .update({
                    status: 'delivered',
                    delivered_at: new Date().toISOString()
                })
                .eq('id', messageId)
                .neq('sender_id', currentUserId);
        } catch (err) {
            console.error('Error marking as delivered:', err);
        }
    }, [currentUserId]);

    // Mark messages as seen
    const markAsSeen = useCallback(async (messageId) => {
        if (!conversationId || !currentUserId) return;

        try {
            // Use the database function
            await supabase.rpc('mark_messages_as_read', {
                p_conversation_id: conversationId,
                p_user_id: currentUserId,
                p_message_id: messageId
            });
        } catch (err) {
            console.error('Error marking as seen:', err);
        }
    }, [conversationId, currentUserId]);

    // Delete message
    const deleteMessage = useCallback(async (messageId, deleteForEveryone = false) => {
        try {
            if (deleteForEveryone) {
                // Check if within time limit
                const { data: canUnsend } = await supabase
                    .rpc('can_unsend_message', { p_message_id: messageId });

                if (!canUnsend) {
                    throw new Error('Time limit exceeded for deleting for everyone');
                }

                await supabase
                    .from('messages')
                    .update({
                        deleted_for_everyone: true,
                        deleted_at: new Date().toISOString(),
                        content: null
                    })
                    .eq('id', messageId)
                    .eq('sender_id', currentUserId);
            } else {
                // Delete for me only
                await supabase
                    .from('messages')
                    .update({
                        deleted_for_sender: true,
                        deleted_at: new Date().toISOString()
                    })
                    .eq('id', messageId)
                    .eq('sender_id', currentUserId);
            }
        } catch (err) {
            console.error('Error deleting message:', err);
            throw err;
        }
    }, [currentUserId]);

    // Load more messages (pagination)
    const loadMore = useCallback(async () => {
        if (!hasMore || loading) return;

        const moreMessages = await fetchMessages(messages.length);
        if (moreMessages.length < PAGE_SIZE) {
            setHasMore(false);
        }
        setMessages(prev => [...moreMessages, ...prev]);
    }, [hasMore, loading, messages.length, fetchMessages]);

    return {
        messages,
        loading,
        error,
        sending,
        hasMore,
        sendMessage,
        markAsSeen,
        deleteMessage,
        loadMore
    };
};

/* ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ
   MESSAGE SCHEDULING HOOK - Schedule messages for later
   Phase 5: Future Enhancements
   ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ */

import { useState, useEffect } from 'react';
import { supabase } from '../../../lib/supabase';

export const useScheduledMessages = (userId) => {
    const [scheduledMessages, setScheduledMessages] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        if (userId) {
            fetchScheduledMessages();

            // Check every minute for messages to send
            const interval = setInterval(checkAndSendScheduled, 60000);
            return () => clearInterval(interval);
        }
    }, [userId]);

    const fetchScheduledMessages = async () => {
        try {
            const { data } = await supabase
                .from('scheduled_messages')
                .select('*')
                .eq('sender_id', userId)
                .eq('sent', false)
                .order('scheduled_for', { ascending: true });

            setScheduledMessages(data || []);
        } catch (error) {
            console.error('Error fetching scheduled messages:', error);
        } finally {
            setLoading(false);
        }
    };

    const scheduleMessage = async (conversationId, content, scheduledFor, messageData = {}) => {
        try {
            const { data, error } = await supabase
                .from('scheduled_messages')
                .insert({
                    sender_id: userId,
                    conversation_id: conversationId,
                    content,
                    scheduled_for: scheduledFor,
                    message_data: messageData,
                    sent: false
                })
                .select()
                .single();

            if (error) throw error;

            await fetchScheduledMessages();
            return data;
        } catch (error) {
            console.error('Error scheduling message:', error);
            return null;
        }
    };

    const cancelScheduled = async (scheduledId) => {
        try {
            await supabase
                .from('scheduled_messages')
                .delete()
                .eq('id', scheduledId);

            await fetchScheduledMessages();
            return true;
        } catch (error) {
            console.error('Error canceling scheduled message:', error);
            return false;
        }
    };

    const checkAndSendScheduled = async () => {
        try {
            const now = new Date().toISOString();

            const { data: dueMessages } = await supabase
                .from('scheduled_messages')
                .select('*')
                .eq('sender_id', userId)
                .eq('sent', false)
                .lte('scheduled_for', now);

            for (const scheduled of dueMessages || []) {
                // Send the message
                await supabase
                    .from('messages')
                    .insert({
                        conversation_id: scheduled.conversation_id,
                        sender_id: scheduled.sender_id,
                        content: scheduled.content,
                        ...scheduled.message_data
                    });

                // Mark as sent
                await supabase
                    .from('scheduled_messages')
                    .update({ sent: true })
                    .eq('id', scheduled.id);
            }

            if (dueMessages?.length > 0) {
                await fetchScheduledMessages();
            }
        } catch (error) {
            console.error('Error sending scheduled messages:', error);
        }
    };

    return {
        scheduledMessages,
        loading,
        scheduleMessage,
        cancelScheduled
    };
};

/* ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ
   STAR MESSAGES HOOK - Bookmark important messages
   Phase 4: Advanced Features
   ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ */

import { useState, useEffect } from 'react';
import { supabase } from '../../../lib/supabase';

export const useStarredMessages = (userId) => {
    const [starredMessages, setStarredMessages] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        if (userId) {
            fetchStarredMessages();
        }
    }, [userId]);

    const fetchStarredMessages = async () => {
        try {
            // Get starred message IDs from user settings
            const { data: settings } = await supabase
                .from('user_settings')
                .select('starred_messages')
                .eq('user_id', userId)
                .single();

            if (settings?.starred_messages) {
                // Fetch actual messages
                const { data: messages } = await supabase
                    .from('messages')
                    .select('*, conversations(*)')
                    .in('id', settings.starred_messages)
                    .order('created_at', { ascending: false });

                setStarredMessages(messages || []);
            }
        } catch (error) {
            console.error('Error fetching starred messages:', error);
        } finally {
            setLoading(false);
        }
    };

    const toggleStar = async (messageId) => {
        try {
            // Get current starred messages
            const { data: settings } = await supabase
                .from('user_settings')
                .select('starred_messages')
                .eq('user_id', userId)
                .single();

            let starred = settings?.starred_messages || [];

            // Toggle star
            if (starred.includes(messageId)) {
                starred = starred.filter(id => id !== messageId);
            } else {
                starred = [...starred, messageId];
            }

            // Update database
            await supabase
                .from('user_settings')
                .upsert({
                    user_id: userId,
                    starred_messages: starred
                }, {
                    onConflict: 'user_id'
                });

            // Update local state
            await fetchStarredMessages();

            return true;
        } catch (error) {
            console.error('Error toggling star:', error);
            return false;
        }
    };

    const isStarred = (messageId) => {
        return starredMessages.some(msg => msg.id === messageId);
    };

    return {
        starredMessages,
        loading,
        toggleStar,
        isStarred
    };
};

