    try {
        const { data, error } = await supabase
            .from('teen_activity_logs')
            .select('activity_type, details, created_at')
            .eq('teen_id', teenId)
            .gte('created_at', startDate)
            .lte('created_at', endDate)
            .order('created_at', { ascending: false });

        if (error) throw error;

        // Aggregate by type
        const summary = {
            posts_created: 0,
            posts_deleted: 0,
            users_followed: 0,
            users_unfollowed: 0,
            new_followers: 0,
            content_reported: 0,
            accounts_blocked: 0,
            messages_sent: 0,
            profile_updates: 0,
            location_shares: 0,
            total_activities: data?.length || 0,
            detailed_activities: data || []
        };

        data?.forEach(activity => {
            switch (activity.activity_type) {
                case 'post_created':
                    summary.posts_created++;
                    break;
                case 'post_deleted':
                    summary.posts_deleted++;
                    break;
                case 'followed_user':
                    summary.users_followed++;
                    break;
                case 'unfollowed_user':
                    summary.users_unfollowed++;
                    break;
                case 'new_follower':
                    summary.new_followers++;
                    break;
                case 'content_reported':
                    summary.content_reported++;
                    break;
                case 'account_blocked':
                    summary.accounts_blocked++;
                    break;
                case 'message_sent':
                    summary.messages_sent++;
                    break;
                case 'profile_updated':
                    summary.profile_updates++;
                    break;
                case 'location_shared':
                    summary.location_shares++;
                    break;
                default:
                    break;
            }
        });

        return summary;
    } catch (error) {
        console.error('Error getting activity summary:', error);
        throw error;
    }
};

